    public static int bfs(long w, int n) {
        Queue<Long> q = new ArrayDeque<>();
        q.add(w);
        HashMap<Long, Integer> h = new HashMap<>();
        h.put(w, 0);
        int min = Integer.MAX_VALUE;
        while (!q.isEmpty()) {
            long s = q.poll();
            if (n == String.valueOf(s).length()) {
                return h.get(s);
            }
            TreeSet<Integer> t = new TreeSet<>();
            String e = s + "";
            for (int i = 0; i < e.length(); i++) {
                t.add(e.charAt(i) - '0');
            }
            for (Integer x : t) {
                long v = (long) x * s;
                if (String.valueOf(v).length() > n) {
                    continue;
                }
                if (h.get(v) == null) {
                    h.put(v, h.get(s) + 1);
                    q.add(v);
                }
            }
        }
        return min == Integer.MAX_VALUE ? -1 : min;
    }

