        distances[node] = 0;
        while (!q.isEmpty()) {
            int parent = q.poll();
            ArrayList<Integer> nodes = a[parent];

            int cost = distances[parent];
            for (Integer node1 : nodes) {
                if (distances[node1] == -1) {

                    q.add(node1);
                    distances[node1] = cost + 1;
                }
            }
        }
        return distances;
    }

