    static class TaskB {
        private char[][] grid = new char[10][10];

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            for (int i = 0; i < 10; i++) {
                String s = in.readLine();
                for (int j = 0; j < 10; j++) {
                    grid[i][j] = s.charAt(j);
                }
            }

            for (int i = 0; i < 10; i++)
                for (int j = 0; j < 10; j++)
                    if (ok(i, j)) {
                        out.print("YES");
                        return;
                    }

            out.print("NO");
        }

        private boolean isOk(int x, int y) {
            return x >= 0 && x < 10 && y >= 0 && y < 10;
        }

        private boolean okD1(int x, int y) {
            for (int i = 1; i <= 4; i++) {
                if (!isOk(x - i, y + i)) return false;
            }
            int cX = 0, cE = 0;
            for (int i = 0; i <= 4; i++) {
                if (grid[x - i][y + i] == 'X') cX++;
                if (grid[x - i][y + i] == '.') cE++;
            }
            return cX == 4 && cE == 1;
        }

        private boolean okD2(int x, int y) {
            for (int i = 1; i <= 4; i++) {
                if (!isOk(x + i, y + i)) return false;
            }
            int cX = 0, cE = 0;
            for (int i = 0; i <= 4; i++) {
                if (grid[x + i][y + i] == 'X') cX++;
                if (grid[x + i][y + i] == '.') cE++;
            }
            return cX == 4 && cE == 1;
        }

        private boolean okD3(int x, int y) {
            for (int i = 1; i <= 4; i++) {
                if (!isOk(x + i, y - i)) return false;
            }
            int cX = 0, cE = 0;
            for (int i = 0; i <= 4; i++) {
                if (grid[x + i][y - i] == 'X') cX++;
                if (grid[x + i][y - i] == '.') cE++;
            }
            return cX == 4 && cE == 1;
        }

        private boolean okD4(int x, int y) {
            for (int i = 1; i <= 4; i++) {
                if (!isOk(x - i, y - i)) return false;
            }
            int cX = 0, cE = 0;
            for (int i = 0; i <= 4; i++) {
                if (grid[x - i][y - i] == 'X') cX++;
                if (grid[x - i][y - i] == '.') cE++;
            }
            return cX == 4 && cE == 1;
        }

        private boolean okV1(int x, int y) {
            for (int i = 1; i <= 4; i++) {
                if (!isOk(x - i, y)) return false;
            }
            int cX = 0, cE = 0;
            for (int i = 0; i <= 4; i++) {
                if (grid[x - i][y] == 'X') cX++;
                if (grid[x - i][y] == '.') cE++;
            }
            return cX == 4 && cE == 1;
        }

        private boolean okV2(int x, int y) {
            for (int i = 1; i <= 4; i++) {
                if (!isOk(x + i, y)) return false;
            }
            int cX = 0, cE = 0;
            for (int i = 0; i <= 4; i++) {
                if (grid[x + i][y] == 'X') cX++;
                if (grid[x + i][y] == '.') cE++;
            }
            return cX == 4 && cE == 1;
        }

        private boolean okH1(int x, int y) {
            for (int i = 1; i <= 4; i++) {
                if (!isOk(x, y - i)) return false;
            }
            int cX = 0, cE = 0;
            for (int i = 0; i <= 4; i++) {
                if (grid[x][y - i] == 'X') cX++;
                if (grid[x][y - i] == '.') cE++;
            }
            return cX == 4 && cE == 1;
        }

        private boolean okH2(int x, int y) {
            for (int i = 1; i <= 4; i++) {
                if (!isOk(x, y + i)) return false;
            }
            int cX = 0, cE = 0;
            for (int i = 0; i <= 4; i++) {
                if (grid[x][y + i] == 'X') cX++;
                if (grid[x][y + i] == '.') cE++;
            }
            return cX == 4 && cE == 1;
        }

        private boolean ok(int x, int y) {
            return okD1(x, y) || okD2(x, y) || okD3(x, y) || okD4(x, y) || okV1(x, y) || okV2(x, y) || okH1(x, y) || okH2(x, y);
        }

    }

