    public void solve() throws IOException
    {
        int people = in.nextInt();
        int totalBear = in.nextInt() * in.nextInt();
        int totalLimes = in.nextInt() * in.nextInt();
        int totalSalt = in.nextInt();

        int toastBear = in.nextInt();
