        int toastSalt = in.nextInt() * people;

        int count = 0;
        while (true)
        {
            if (totalBear < totalToastBear || totalSalt < toastSalt || totalLimes < people)
            {
                break;
            }
            totalBear -= totalToastBear;
            totalSalt -= toastSalt;
            totalLimes -= people;
            count++;
        }
        System.out.println(count);

