import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.io.PrintStream;
import java.util.InputMismatchException;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author Nirav
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scan in = new Scan(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskC {
        public void solve(int testNumber, Scan in, PrintWriter out) {
            long nuber = in.scanLong();
            String str = Long.toString(nuber);
            long length = (long) Math.log10(nuber) + 1;
            long totalbit = length;
            long combination = 0;
            while (length > 0) {
                combination = combination | (1 << (length - 1));
                length--;
            }
            long result = -1;
            while (combination > 0) {
                long totalones = 0;
                long ot = 0;
                for (int i = 0; i < totalbit; i++) {
                    if ((combination & (1 << i)) != 0) {
                        if (ot == 0 && str.charAt(i) == '0') {
                            break;
                        }
                        ot = ot * 10 + str.charAt(i) - '0';
                        totalones++;
                    }
                }
                if (ot > 0 && Math.sqrt(ot) == (long) Math.sqrt(ot)) {
                    if (result < totalones) {
                        result = totalones;
                    }
                }
                combination--;
            }
            if (result == -1) {
                totalbit = result - 1;
            }
            out.println(totalbit - result);

        }

    }

    static class Scan {
        private byte[] buf = new byte[1024];
        private int index;
        private InputStream in;
        private int total;

        public Scan() {
            in = System.in;
        }

        public Scan(InputStream inputStream) {
            in = inputStream;
        }

        public int scan() {
            if (total < 0) {
                return 0;
            }
            if (index >= total) {
                index = 0;
                try {
                    total = in.read(buf);
                } catch (Exception e) {
                    System.out.println(e);
                }
                if (total <= 0)
                    return -1;

            }
            return buf[index++];
        }

        public long scanLong() {
            long lng = 0;
            int n = scan();
            while (isWhiteSpace(n))
                n = scan();
            int neg = 1;
            if (n == '-') {
                neg = -1;
                n = scan();
            }
            while (!isWhiteSpace(n) && n != '.') {
                if (n >= '0' && n <= '9') {
                    lng *= 10;
                    lng += n - '0';
                    n = scan();
                } else throw new InputMismatchException();
            }
            if (n == '.') {
                n = scan();
                long temp = 1;
                while (!isWhiteSpace(n)) {
                    if (n >= '0' && n <= '9') {
                        temp /= 10;
                        lng += (n - '0') * temp;
                        n = scan();
                    } else throw new InputMismatchException();
                }
            }
            return neg * lng;
        }

        private boolean isWhiteSpace(int n) {
            if (n == ' ' || n == '\n' || n == '\r' || n == '\t' || n == -1)
                return true;
            return false;
        }

    }
}

