import java.util.*;

public class DigitalRoot
{
	public Scanner in = new Scanner(System.in);
	public PrintStream out = System.out;

	public int N;

	public void main()
	{
		N = in.nextInt();

		int x, y, z;
		long res = 0;

		long A, B, C;
		int a, b;

		for(z=1;z<=9;++z) for(x=1;x<=9;++x) for(y=1;y<=9;++y) if(z == d(x*y))
		{
			C = count(9, z);
			A = count(9, x);
			B = count(9, y);

			res += A * B * C;

			for(int k=0; k*9+x <=N;++k)
			{
				a = k*9*9 + 9*x;
				b = k*9*y + x*y;
				res -= count(a, b);
			}
		}

		out.println(res);
	}//end public void main()

	public int d(int x)
	{
		if(x%9 == 0) return 9;
		return x%9;
	}

	public int count(int a, int b)
	{
		if(N < b) return 0;
		return (N - b)/a + 1;
	}

	public static void main(String[] args)
	{
		(new DigitalRoot()).main();
	}
}

