public class CFC {
    BufferedReader br;
    PrintWriter out;
    StringTokenizer st;
    boolean eof;
    final long MOD = 1000L * 1000L * 1000L + 7;

    void solve() throws IOException {
        int n = 24;
        int[] arr = nextIntArr(n);
        int[][] idx = {{1, 3, 5, 7, 9, 11, 22, 24},
        {2, 4, 6, 8, 10, 12, 21, 23},
        {13, 14, 5, 6, 17, 18, 21, 22},
        {15, 16, 7, 8, 19, 20, 23, 24},
        {1, 2, 18, 20, 12, 11, 15, 13},
        {3, 4, 17, 19, 10, 9, 16, 14}};

        for (int[] cand : idx) {
            int[] candArr = Arrays.copyOf(cand, cand.length);
            int[] fix = Arrays.copyOf(arr, arr.length);

            int[] left = shiftLeft(candArr);
            boolean flag = check(fix, candArr, left);
            if (flag) {
                out("YES");
                return;
            }

            int[] right = shiftRight(candArr);
            flag = check(fix, candArr, right);
            if (flag) {
                out("YES");
                return;
            }
        }

        out("NO");
    }

    boolean check(int[] mat, int[] old, int[] index) {
//        for (int i = 0; i < old.length; i++) {
//            swap(mat, old[i] - 1, index[i] - 1);
//        }

        int[] newMat = Arrays.copyOf(mat, mat.length);
        for (int i = 0; i < old.length; i++) {
            newMat[index[i] - 1] = mat[old[i] - 1];
        }
        return isValid(newMat);
    }

    int[] shiftRight(int[] ind) {
        int[] res = new int[8];
        for (int i = 2; i < 8; i++) {
            res[i] = ind[i - 2];
        }

        res[0] = ind[6];
        res[1] = ind[7];
        return res;
    }

    int[] shiftLeft(int[] ind) {
        int[] res = new int[8];
        for (int i = 0; i < 6; i++) {
            res[i] = ind[i + 2];
        }
        res[6] = ind[0];
        res[7] = ind[1];
        return res;
    }

    boolean isValid(int[] arr) {
        for (int i = 0; i < 6; i++) {
            int cnt1 = arr[4 * i];
            for (int j = 1; j < 4; j++) {
                if (arr[4 * i + j] != cnt1) {
                    return false;
                }
            }
        }

        return true;
    }

    void swap(int[] arr, int i, int j) {
        int tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }

    void shuffle(int[] a) {
        int n = a.length;
        for(int i = 0; i < n; i++) {
            int r = i + (int) (Math.random() * (n - i));
            int tmp = a[i];
            a[i] = a[r];
            a[r] = tmp;
        }
    }
    private void outln(Object o) {
        out.println(o);
    }
    private void out(Object o) {
        out.print(o);
    }
    public CFC() throws IOException {
        br = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(System.out);
        solve();
        out.close();
    }
    public static void main(String[] args) throws IOException {
        new CFC();
    }

    public long[] nextLongArr(int n) throws IOException{
        long[] res = new long[n];
        for(int i = 0; i < n; i++)
            res[i] = nextLong();
        return res;
    }
    public int[] nextIntArr(int n) throws IOException {
        int[] res = new int[n];
        for(int i = 0; i < n; i++)
            res[i] = nextInt();
        return res;
    }
    public String nextToken() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                st = new StringTokenizer(br.readLine());
            } catch (Exception e) {
                eof = true;
                return null;
            }
        }
        return st.nextToken();
    }
    public String nextString() {
        try {
            return br.readLine();
        } catch (IOException e) {
            eof = true;
            return null;
        }
    }
    public int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }
    public long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }
    public double nextDouble() throws IOException {
        return Double.parseDouble(nextToken());
    }
}

