class TaskB2 {
    public void solve(int testNumber, InputReader in, OutputWriter out) {
        int n = in.readInt();
        int m = in.readInt();

        int[] dp = new int[n + 1];
        dp[0] = dp[1] = 1;

        for (int i = 2; i <= n; i++) {
            for (int j = 0; j < i; j++) {
                dp[i] += dp[j];
            }
        }

        int[] a = new int[n];
        boolean[] used = new boolean[n + 1];

        int add = 0;
        int last = 0;
        for (int i = 0; i < n; i++) {
            for (int j = last + 1; j <= n; j++) {
                if(used[j]) continue;

                int grt = 0;
                for (int k = j + 1; k <= n; k++) {
                    if (!used[k])   grt++;
                }
                if (add + dp[grt] >= m) {
                    a[i] = j;
                    used[j] = true;
                    last = j;
                    break;
                } else {
                    add += dp[grt];
                }
            }
        }

        for (int i = n - 1; i >= 0; i--) {
            if (a[i] == 0) {
                for (int j = 1; j <= n; j++) {
                    if (!used[j]) {
                        a[i] = j;
                        used[j] = true;
                        break;
                    }
                }
            }
        }

        for (int i = 0; i < n; i++) {
            out.print(a[i] + " ");
        }
    }
}

class InputReader {
    private InputStream stream;
    private byte[] buf = new byte[1024];
    private int curChar;
    private int numChars;
    private SpaceCharFilter filter;

    public InputReader(InputStream stream) {
        this.stream = stream;
    }

    public int read() {
        if (numChars == -1)
            throw new InputMismatchException();
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0)
                return -1;
        }
        return buf[curChar++];
    }

    public int readInt() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9')
                throw new InputMismatchException();
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    public boolean isSpaceChar(int c) {
        if (filter != null)
            return filter.isSpaceChar(c);
        return isWhitespace(c);
    }

    public static boolean isWhitespace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    public interface SpaceCharFilter {
        public boolean isSpaceChar(int ch);
    }
}

