	public static boolean clock (int h, int m, int s, int t1, int t2) {
		int t1_s = t1 * 5;
		if (t1_s >= 60)
			t1_s -= 60;
		boolean solution_s = false;
		int t2_s = t2 * 5;
		if (t2_s >= 60)
			t2_s -= 60;
		while (t1_s != s) {
			if (t1_s == t2_s) {
				solution_s = true;
				break;
			}
			t1_s++;
			if (t1_s > 59)
				t1_s -= 60;
		}
		if (!solution_s)
			return false;

		double t1_m = (double)t1 * (double)5;
		if (t1_m >= 60)
			t1_m -= 60;
		double m1 = (double)m;
		boolean solution_m = false;
		if (s > 0)
			m1 += 0.5;
		if (m1 >= 60)
			m1 -= 60;
		double t2_m = (double)t2 * (double)5;
		if (t2_m >= 60)
			t2_m -= 60;
		while (t1_m != (double)m1) {
			if (t1_m == t2_m) {
				solution_m = true;
				break;
			}
			t1_m += 0.5;
			if (t1_m >= 60)
				t1_m -= 60;
		}
		if (!solution_m)
			return false;

		double t1_h = (double)t1;
		double h1 = (double)h;
                boolean solution_h = false;
                if (m > 0 || s > 0)
                        h1 += 0.5;
		if (h1 > 12)
			h1 -= 12;
                while (t1_h != (double)h1) {
                        if (t1_h == (double)t2) {
                                solution_h = true;
                                break;
                        }
                        t1_h += 0.5;
                        if (t1_h > 12)
                                t1_h -= 12;
                }
                if (!solution_h)
                        return false;
		return true;
	}

	public static boolean anti (int h, int m, int s, int t1, int t2) {
                int t1_s = t1 * 5;
		if (t1_s >= 60)
			t1_s -= 60;
                boolean solution_s = false;
		int t2_s = t2 * 5;
		if (t2_s >= 60)
			t2_s -= 60;
                while (t1_s != s) {
                        if (t1_s == t2_s) {
                                solution_s = true;
                                break;
                        }
                        t1_s--;
                        if (t1_s < 0)
                                t1_s += 60;
                }
                if (!solution_s)
                        return false;

                double t1_m = (double)t1 * (double)5;
		if (t1_m >= 60)
			t1_m -= 60;
                double m1 = (double)m;
                boolean solution_m = false;
                if (s > 0)
                        m1 += 0.5;
                if (m1 >= 60)
                        m1 -= 60;
		double t2_m = (double)t2 * (double)5;
		if (t2_m >= 60)
			t2_m -= 60;
                while (t1_m != (double)m1) {
                        if (t1_m == t2_m) {
                                solution_m = true;
                                break;
                        }
                        t1_m -= 0.5;
                        if (t1_m < 0)
                                t1_m += 60;
                }
                if (!solution_m)
                        return false;

                double t1_h = (double)t1;
                double h1 = (double)h;
                boolean solution_h = false;
                if (m > 0 || s > 0)
                        h1 += 0.5;
                if (h1 > 12)
                        h1 -= 12;
                while (t1_h != (double)h1) {
                        if (t1_h == (double)t2) {
	                        solution_h = true;
                                break;
                        }
                        t1_h -= 0.5;
                        if (t1_h < 0.5)
                                t1_h += 12;
                }
                if (!solution_h)
                        return false;
                return true;
        }

