	void solve() {
		int x = scn.nextInt(), y = scn.nextInt(), mod = (int) 1e9 + 7;
		if (y % x != 0) {
			out.println(0);
			return;
		}
		int k = y / x;

		HashMap<Integer, Long> map = new HashMap<>();
		map.put(1, 1L);

		out.println(func(k, map, mod));
	}

	long func(int k, HashMap<Integer, Long> map, int mod) {
		if (map.containsKey(k)) {
			return map.get(k);
		}
		long rv = 1;
		for (int i = 2; i * i <= k; i++) {
			if (k % i != 0) {
				continue;
			}
			rv += func(i, map, mod);
			if (i * i != k) {
				rv += func(k / i, map, mod);
			}
		}

		rv %= mod;
		rv = (power(2, k - 1, mod) - rv + mod) % mod;
		map.put(k, rv);

		return rv;
	}

	long power(long a, long x, long mod) {
		if (x == 0) {
			return 1;
		}
		long p = power(a, x / 2, mod);
		p *= p;
		p %= mod;
		if (x % 2 == 1) {
			p *= a;
			p %= mod;
		}
		return p;
	}

