        final FastScanner scanner = new FastScanner();
        int n = scanner.nextInt(), l = scanner.nextInt(), r = scanner.nextInt();
        System.out.println(min(n, l) + " " + max(n, r));
    }


    static int max(int n, int r) {
        int sum = 0;
        int start = 1, curr = 1, unique = 0;
        for (int i = 0; i < n; i++) {
            if (unique < r) {
                sum += start;
                curr = start;
                start *= 2;
                unique ++;
            } else {
                sum += curr;
            }
//            System.out.println(sum);
        }
        return sum;
    }

    static int min(int n, int l) {
        int start = 1;
        int sum = 0;
        for (int i = 0; i < l; i++) {
            sum += start;
            start *= 2;
        }

        for (int i = l; i < n; i++) {
            sum += 1;
        }
        return sum;
    }


