		/*---------------------------------*/

		while (a > 0) {
			boxesNumber++;
			if (b > 0) {
				a -= v*(Math.min(b, k-1) + 1);
				b -= Math.min(b, k-1);
			} else {
				a -= v;
			}
		}

		System.out.println(boxesNumber);
	}
