public class lolat {
	static int n;

	static long[][] memo;

	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		while (in.hasNext()) {
			n = in.nextInt();
			int k = in.nextInt();
			memo = new long[n + 1][k + 1];
			for (int i = 0; i <= n; i++) {
				Arrays.fill(memo[i], -1);
			}
			System.out
					.println(callRecusive(1, k) % 1000000007);
		}
	}

	private static long callRecusive(int num, int len) {
		// TODO Auto-generated method stub
		if (len == 0) {
			return 1;
		}
		if (memo[num][len] != -1)
			return memo[num][len];
		long s = 0;
		for (int i = num; i <= n; i += num) {
			s += callRecusive(i, len - 1);
		}
		return (memo[num][len] = s % 1000000007);
	}

}

