public class CFProblemC {
	static long mod;

	public static void main(String[] args) {
		FastScanner input = new FastScanner();
		mod = input.nextInt();
		int h1 = input.nextInt(); // start
		int a1 = input.nextInt(); // goal
		int x1 = input.nextInt(); // x1*h1+y1 -> h1
		int y1 = input.nextInt();

		int h2 = input.nextInt();
		int a2 = input.nextInt(); // goal
		int x2 = input.nextInt();
		int y2 = input.nextInt();
		ArrayList<Long> values1 = evaluateTimes(h1, a1, x1, y1);
		ArrayList<Long> values2 = evaluateTimes(h2, a2, x2, y2);
		int index1 = 0;
		int index2 = 0;
		while (index1 < values1.size() && index2 < values2.size()) {
			if (values1.get(index1).equals(values2.get(index2))) {
				break;
			}
			if (values1.get(index1).compareTo(values2.get(index2)) < 0) {
				index1++;
			} else {
				index2++;
			}
		}
		if (values1.size() > 0 && values2.size() > 0 && index1 < values1.size()
				&& index2 < values2.size()
				&& values1.get(index1).equals(values2.get(index2))) {
			System.out.println(values1.get(index1));
		} else {
			System.out.println(-1);
		}
	}

	private static ArrayList<Long> evaluateTimes(long h1, long a1, long x1,
			long y1) {
		long start = h1;
		long count = 0;
		ArrayList<Long> output = new ArrayList<Long>();
		while (count < 2 * mod + 2) {
			if (start == a1) {
				output.add(count);
			}
			count++;
			start = (start * x1 + y1) % mod;
		}
		if (output.size() == 0) {
			return output;
		} else {
			if (output.size() > 1) {
				long diff = output.get(1) - output.get(0);
				long startVal = output.get(output.size() - 1);
				for (int a = 1; a < mod + .1 * mod; a++) {
					output.add(startVal + diff * a);
				}
			}
		}
		return output;
	}

