		int a = in.nextInt();
		int b = in.nextInt();
		int[][] dp = new int[201][201];
		for (int sum = 2; sum <= 200; sum++) {
			for (int i = 1; i <= sum; i++) {
				int j = sum - i;

				if (i - 2 >= 0 && j > 0) {
					dp[i][j] = Math.max(dp[i][j], dp[i - 2][j + 1] + 1);
				}
				if (j - 2 >= 0 && i > 0) {
					dp[i][j] = Math.max(dp[i][j], dp[i + 1][j - 2] + 1);
				}
			}
		}

		out.print(dp[a][b]);
	}

