		long b = in.nextInt();
		long T = in.nextLong();
		char[] s = in.next().toCharArray();
		long[] right = new long[n];
		long[] left = new long[n];
		right[0] = 1 + (s[0] == 'w' ? b : 0);
		left[0] = 0;

		for (int i = 1; i < n; i++) {
			long changeCost = (s[i] == 'w' ? b : 0);
			right[i] = right[i - 1] + a + changeCost + 1;
		}
		for (int i = 1; i < n; i++) {
			int pos = n - i;
			long changeCost = (s[pos] == 'w' ? b : 0);
			left[pos] = left[(pos + 1) % n] + a + changeCost + 1;
		}

		long best = 0;
		int bestL = n - 1;
		for (int i = n - 1; i >= 0; i--) { // right
			long time = right[i];
			if (time <= T) {
				best = Math.max(best, i + 1);
				long rem = T - time;
				rem -= a * i; // back time
				while (bestL > i && rem >= left[bestL]) {
					best = Math.max(best, i + 1 + (n - bestL));
					bestL--;
				}
			}
		}

		char[] tmp = new char[s.length];
		tmp[0] = s[0];
		for (int i = 1; i < n; i++) {
			tmp[i] = s[n - i];
		}
		for (int i = 0; i < n; i++) {
			s[i] = tmp[i];
		}

		// **** left
		right = new long[n];
		left = new long[n];
		right[0] = 1 + (s[0] == 'w' ? b : 0);
		left[0] = 0;

		for (int i = 1; i < n; i++) {
			long changeCost = (s[i] == 'w' ? b : 0);
			right[i] = right[i - 1] + a + changeCost + 1;
		}
		for (int i = 1; i < n; i++) {
			int pos = n - i;
			long changeCost = (s[pos] == 'w' ? b : 0);
			left[pos] = left[(pos + 1) % n] + a + changeCost + 1;
		}

		bestL = n - 1;
		for (int i = n - 1; i >= 0; i--) { // right
			long time = right[i];
			if (time <= T) {
				best = Math.max(best, i + 1);
				long rem = T - time;
				rem -= a * i; // back time
				while (bestL > i && rem >= left[bestL]) {
					best = Math.max(best, i + 1 + (n - bestL));
					bestL--;
				}
			}
		}
		out.print(best);
	}

