public class P910B {

  int n;
  TreeMap<Integer, Integer> m;

  void use(int l) {
    Integer pl = m.ceilingKey(l);

    int c = m.get(pl) - 1;
    if (c > 0) {
      m.put(pl, c);
    } else {
      m.remove(pl);
    }

    if (pl != l) {
      m.put(pl - l, m.getOrDefault(pl - l, 0) + 1);
    }
  }

  public void run() throws Exception {
    n = nextInt();
    int a = nextInt(), b = nextInt(), k = Integer.MAX_VALUE;

    for (int mm = (1 << 6) - 1; mm > 0; mm--) {
      if (Integer.bitCount(mm) != 2) { continue; }

      m = new TreeMap();
      m.put(n, 6);
      for (int mi = 1 << 5; mi > 0; mi >>= 1) {
        if ((mm & mi) == 0) {
          use(a);
        } else {
          use(b);
        }
      }

      k = Math.min(k, 6 - m.getOrDefault(n, 0));
    }

    println(k);
  }

