               pow[i] = (pow[i-1]*p)%MOD;
            long[][] dp = new long[cnt+1][T+1];
            for(int i=0; i <= cnt; i++)
               dp[i][0] = pow[i];
            for(int t=1; t <= T; t++)
            {
               long sum = 0L;
               for(int i=0; i <= cnt; i++)
               {
                  sum = (sum+dp[i][t-1])%MOD;
                  dp[i][t] = (sum*power(i+1, MOD-2, MOD))%MOD;  
               }
            }
            long num = dp[cnt][T];
            //long denom = power(cnt+1, T, MOD);
            P = (P*num)%MOD;

         }
         }
         long res = (P*power(Q, MOD-2, MOD))%MOD;
         System.out.println((P+MOD)%MOD);
      }
      public static long power(long x, long y, long p) 
      { 
          long res = 1L;      
          x = x % p;  
          while (y > 0) 
          { 
              if((y & 1)==1) 
                  res = (res * x) % p; 
              y = y >> 1;  
              x = (x * x) % p;  
          } 
          return res; 
      }
   }

