    private static void solution() {
        long r = sc.nextLong();
        long g = sc.nextLong();
        long b = sc.nextLong();

        long bouketsCount = solutionWithParams(r, g, b);

        out.println(bouketsCount);
        out.close();

    }

    private static long solutionWithParams(long r, long g, long b) {
        long bouketsCount = 0;

        long minCount = r > g ? g : r;
        minCount = minCount > b ? b : minCount;

        long countToCut = minCount;
        if (countToCut > 2) {
            countToCut = 2;
        }

        minCount -= countToCut;
        if (minCount < 0) {
            minCount = 0;
        }

        long threeCeil = minCount - minCount % 3;
        bouketsCount += threeCeil;

        r -= threeCeil;
        g -= threeCeil;
        b -= threeCeil;

        if (r > 2 + countToCut) {
            long rThreeCeil = (r - countToCut) / 3;
            bouketsCount += rThreeCeil;
            r -= 3 * rThreeCeil;
        }

        if (g > 2 + countToCut) {
            long gThreeCeil = (g - countToCut) / 3;
            bouketsCount += gThreeCeil;
            g -= 3 * gThreeCeil;
        }

        if (b > 2 + countToCut) {
            long bThreeCeil = (b - countToCut) / 3;
            bouketsCount += bThreeCeil;
            b -= 3 * bThreeCeil;
        }

        while (r > countToCut && b > countToCut && g > countToCut) {
            bouketsCount++;
            r--;
            g--;
            b--;
        }

        //now all values are [2..4]
        if (r + g + b >= 10) {//442
            bouketsCount += 3;
        } else if (countToCut > 1) {
            bouketsCount += 2;
        } else if (countToCut > 0 && r + g + b >= 7) {
            bouketsCount += 2;
        } else if (countToCut > 0) {
            bouketsCount += 1;
        }

        return bouketsCount;
    }

