class Task{
    Scanner cin;
    PrintWriter cout;
    final int maxn = 400005;
    final int MOD = 1000000007;
    int []dp = new int[maxn];
    int r, g;
    public Task(Scanner cin, PrintWriter cout) {        
        // TODO Auto-generated constructor stub     
        this.cin = cin;
        this.cout = cout;
        r = cin.nextInt();
        g = cin.nextInt();
    }
    public void read() {
        r = cin.nextInt();
        g = cin.nextInt();
    }
    int GetHeight(){
        for (int i = 1; ; i++){
            if (i * (i + 1) / 2 > r + g){
                return i-1;
            }
        }
    }
    public void solve(){
        int h = GetHeight();
        int res = 0;
        dp[0] = 1;
        for (int i = 1; i <= h; i++){
            for (int j = r; j >= 0; j--){
                dp[i+j] = (dp[i+j] + dp[j]) % MOD;
            }
        }
        for (int i = Math.max(h*(h+1)/2 - g, 0); i <= r; i++){
            res = (res + dp[i]) % MOD;
        }
        cout.println(res);
    }   
}

