public class EightEightEightB {
    byte inputCommNum;
    int answer = 0;
    String commands;

    public static void main (String[] args) {
        EightEightEightB c = new EightEightEightB();
        c.readParams();
        c.solve();

        System.out.println(c.getAnswer());
    }

    private void solve() {
        int ls = 0;
        int rs = 0;
        int us = 0;
        int ds = 0;
        for (byte i = 0; i < commands.length(); i++) {
            char c = commands.charAt(i);
            switch (c) {
                case 'U':
                    us++;
                    break;
                case 'D':
                    ds++;
                    break;
                case 'L':
                    ls++;
                    break;
                case 'R':
                    rs++;
                    break;
                default:
                    break;
            }
        }
        if (ls == 0 || rs == 0) {
            answer = 2 * Math.min(us, ds);
        } else if (us == 0 || rs == 0) {
            answer = 2 * Math.min(ls, rs);
        } else {
            answer = (byte) (2 * (Math.min(ls, rs) + Math.min(us, ds)));
        }
    }

    private void readParams() {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        try {
            inputCommNum = Byte.parseByte(br.readLine());
            commands = br.readLine();
        } catch (IOException e) {
            return;
        }
    }

    public int getAnswer() {
        return answer;
    }

}

