class TaskSolver {
    private InputReader in;
    private PrintWriter out;

    public TaskSolver(InputReader inputReader, PrintWriter printWriter) {
        in = inputReader;
        out = printWriter;
    }

    public void solve() {
        int a = in.nextInt();
        int b = in.nextInt();
        int m = in.nextInt();
        int r0 = in.nextInt();
        int[] r = new int[ (int) 1e+6];
        int[] check = new int[ (int) 1e+6];
        Arrays.fill(check, -1);
        r[0] = (a * r0 + b) % m;
        check[r[0]] = 0;
        int res = 0;
        for (int i = 1; ; i++) {
            r[i] = (a * r[i - 1] + b) % m;
            if (check[r[i]] == -1) {
                check[r[i]] = i;
            } else {
                res = i - check[r[i]];
                break;
            }
        }
        out.print(res);
    }
}

class InputReader {
