public class champion {
	static long n, m, k;
	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);
		n = scan.nextLong();
		m = scan.nextLong();
		k = scan.nextLong();
		long low = 1;
		long high = n * (m+1);

		while(low < high) {
			long x = (high+low) >> 1;
			if(works(x)) {
				low = x+1;
			} else {
				high = x;
			}
		}

		System.out.println(high-1);

	}

	public static boolean works(long attempt) {
		long num = 0;
	    attempt--;
	    for(int i=1; i<=n; ++i) {
	    	num += Math.min(m, attempt/i);
	    }
	    return num < k;
	}
}

