        int[] f = new int[m];
        int[] c = new int[m];
        for(int k = 2; k < m; k++)
            if(f[k] == 0) {
                long s = 1l * k * k;
                if(s < m)
                    for(int i = (int)s; i < m; i += k)
                        f[i] = k;
                f[k] = k;
            }
        c[1] = 1;
        for(int k = 2; k < m; k++) {
            int p = f[k];
            int r = c[k / p];
            if(k % (1l * p * p * r) == 0) 
                c[k] = p * p * r;
            else
                c[k] = r;
        }
        long ans = 0;
        for(int i = a; i < m; i++) {
