import java.io.PrintWriter;
import java.util.HashSet;
import java.util.Queue;
import java.util.Scanner;
import java.util.Set;
import java.util.concurrent.LinkedBlockingQueue;

public class C214 {
    int n;
    boolean room[][];
    boolean dep[][];
    int num[];
    int idx[];
    boolean visited[];
    int ans = Integer.MAX_VALUE;
    Set<Integer> zeros;
    static int [][] pay;
    static {
        pay = new int[3][3];
        for( int i =0; i<3 ; i ++){
            pay[i][i] = 0;
            pay[i][(i+1)%3] = 1;
            pay[i][(i+2)%3] = 2;
        }
    }

    public void solve(Scanner cin , PrintWriter cout ){
        n = cin.nextInt();
        room = new boolean[3][n];
        dep = new boolean[n][n];
        num = new int[n];
        idx = new int[n];
        visited = new boolean[n];
        for( int i=0 ;i <n ; i ++){
            idx[i] = cin.nextInt()-1;
            room[idx[i]][i] = true;
        }

        zeros = new HashSet<Integer>();
        for( int i= 0;i <n ; i ++){
            int k = cin.nextInt();
            num[i] = k;
            if( k ==0) {
                zeros.add(i);
            }
            for( int j=0;j <k ; j ++){
                int pre = cin.nextInt() - 1;
                dep[pre][i] = true;
            }
        }
        for( int r = 0; r < 3 ; r ++) {
            Set<Integer> bak_zeros = new HashSet<Integer>(zeros);
            visited = new boolean[n];
            int [] bak_num = new int[n];
            for( int i=0;i<n;i++){
                bak_num [i] = num[i];
            }
            search(r,0);
            zeros = bak_zeros;
            num = bak_num;
        }
        cout.println(ans);
    }

    private void search(int r,int cost){
        if( cost >= ans)
            return;
        if( zeros.size() == 0 ){
            if( cost < ans ) {
                ans = cost;
            }
            return;
        }
        Queue<Integer> zs = new LinkedBlockingQueue<Integer>();
        Set<Integer> bak_zeros = new HashSet<Integer>();

        for( int zero : zeros){
            if( idx[zero] == r) {
                zs.add(zero);
                bak_zeros.add(zero);
            }
        }
        while(!zs.isEmpty()) {
            int now = zs.poll();
            zeros.remove(now);
            cost ++ ;
            visited[now] = true;
            for( int i=0 ;i < n ; i ++) {
                if( !visited[i] && dep[now][i]  && num[i] > 0) {
                    num[i] -- ;
                    if( num[i] == 0) {
                        if( idx[i] == r ) {
                            zs.add(i);
                        } else{
                            zeros.add(i);
                        }
                    }
                }
            }
        }
        if( zeros.size() == 0 ){
            if( cost < ans ) {
                ans = cost;
            }
            return ;
        }
        search((r+1)%3,cost + pay[r][(r+1)%3]);
    }

    public static void main (String [] args){
        C214 solution = new C214();
        Scanner cin = new Scanner(System.in);
        PrintWriter cout = new PrintWriter(System.out);
        solution.solve(cin, cout);
        cin.close();
        cout.close();
    }
}

