public class Main {


    public static int[] pref_f(String s) {
        int n = s.length();
        int[] pf = new int[n];
        for(int i = 1; i < n; i++){
            int j = pf[i-1];
            while (j > 0 && s.charAt(i) != s.charAt(j)){
                j = pf[j-1];
            }
            if (s.charAt(i) == s.charAt(j)) j++;
            pf[i] = j;
        }
        return pf;
    }

    public static void shortestPaths(List<Edge>[] edges, int s, int[] d, int[] pred) {
        Arrays.fill(pred, -1);
        Arrays.fill(d, Integer.MAX_VALUE);
        d[s] = 0;
        PriorityQueue<Long> q = new PriorityQueue<>();
        q.add((long) s);
        while (!q.isEmpty()) {
            long cur = q.remove();
            int curu = (int) cur;
            if (cur >>> 32 != d[curu])
                continue;
            for (Edge e : edges[curu]) {
                int v = e.t;
                int nprio = d[curu] + e.cost;
                if (d[v] > nprio) {
                    d[v] = nprio;
                    pred[v] = curu;
                    q.add(((long) nprio << 32) + v);
                }
            }
        }
    }

    public static class Edge {
        int t;
        int cost;

        public Edge(int t, int cost) {
            this.t = t;
            this.cost = cost;
        }
    }


    public static void main(String[] args) throws IOException {
        FastScanner in = new FastScanner(System.in);
        FastPrinter out = new FastPrinter(System.out);
        //FastScanner in = new FastScanner(new InputStreamReader(new FileInputStream(new File("strings.in"))));
        //FastPrinter out = new FastPrinter(new OutputStreamWriter(new FileOutputStream(new File("strings.out"))));
        ArrayList<Integer> list = new ArrayList<>();
        int n = in.nextInt();
        int[] mas = new int[1000000];
        for(int i = 2; i < 1000000; i++){
            if(mas[i] == 0){
                list.add(i);
                long k = (long)i * (long)i;
                while (k < 1000000){
                    mas[(int)k] = 1;
                    k += i;
                }
            }
        }
        int r = n-1;
        int max = 0;
        for(int i = 0; i < list.size(); i++){
            if(list.get(i) > n) break;
            if(n % list.get(i) == 0){
                max = list.get(i);
            }
        }
        int l = (n-max) + 1;

        max = r;
        for(int i = l; i <= r; i++){
            if(mas[i] == 0) continue;
            int k1 = 0;
            int k2 = i;
            for(int j = 0; j < list.size(); j++){
                int p = list.get(j);

                if((long)p * p > k2) break;

                if(k2 % p == 0){
                    k1 = p;
                    while (k2 % p == 0) k2 /= p;
                }

                if(k2 == p) {k1 = 1; break;}
            }
            if(k2 > k1) k1 = k2;
            if((i - k1 + 1) < max) max = (i - k1 + 1);
        }
        System.out.println(max);
        out.close();
    }
}

