public class E {

    /*
        Runtime = O()
     */
    static int N, M, K;
    static String s;
    static StringTokenizer st;
    static int[] d;

    static long ans = 0;
    static long[] pre;

    static void dis(long N) {
        //System.out.println(N);
        if(N == 1){
            return;
        }
        long x = ((long)((Math.log(N-0.1))/Math.log(2)));
        //System.out.println(x);
        long low = (long)Math.pow(2, x);
        //System.out.println(low);
        ans += low;
        ans += pre[(int)x];
        dis(N-low);
    }

