    public static long dontcry(long n, long k, long A, long B, long count){
        if(n==1)
            return count;
        else{
            if(k==1 || n<k){
                count+=(n-1)*A;
                n=1;
            }
            else if(n>k && n%k!=0){
                count+=(n%k)*A;
                n=n-(n%k);
            }
            else if(n%k==0){
                if(B<(n-(n/k))*A){
                    count+=B;
                    n=n/k;
                }
                else{
                    count+=(n-1)*A;
                    n=1;
                }
            }
            return dontcry(n, k, A, B, count);
        }
    }
}

