public class TripForMeal {
    private Scanner read = new Scanner(System.in);

    public static void main(String[] args) {
        TripForMeal p = new TripForMeal();
        byte eatVisit = p.readByte();
        byte a = p.readByte();
        byte b = p.readByte();
        byte c = p.readByte();
        int answer = p.tripForMeal(eatVisit, a, b, c);
        System.out.println(answer);
    }

    private int tripForMeal(byte n, byte a, byte b, byte c) {
        int result = 0;
        byte count = 0;
        if(n != 1)
        {
            if(a < b)
            {
                result += a;
                count = a;
            }
            else
            {
                result+= b;
                count = b;
            }
        }

        n-=1;

        while(n > 1)
        {
            n--;
            if(count == a)
