import java.util.ArrayList;

public class CodeForces {

    ArrayList<Integer> num = new ArrayList<Integer>();

    private boolean search(int value, int begin, int end) {
        if (end - begin < 3) {
            if (num.get(begin) == value || num.get(end) == value) {
                return (true);
            } else {
                return (false);
            }
        } else {
            int middle = (end - begin) / 2 + begin;
            if (num.get(middle) == value) {
                return (true);
            } else {
                if (num.get(middle) < value) {
                    return (search(value, middle + 1, end));
                } else {
                    return (search(value, begin, middle - 1));
                }
            }
        }
    }

    public void run() throws IOException {
        MyScanner sc = new MyScanner(System.in);
        int n = sc.nextInt();
        int i = 1;
        boolean greater = false;
        while (!greater) {
            long number = i * (i + 1) / 2;
            if (number >= n) {
                greater = true;
            } else {
                num.add((int) number);
            }
            i++;
        }
        boolean exist = false;
        for (i = 0; i < num.size(); i++) {
            if (search(n - num.get(i), 0, num.size() - 1)) {
                exist = true;
                break;
            }
        }
        if (exist) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    public static void main(String[] args) throws FileNotFoundException, IOException {
        CodeForces cf = new CodeForces();
        cf.run();
    }
}

