        int d = scanner.nextInt();

        System.out.println(Path(fV,sV,t,d));

   }

    static int Path(int F,int S,int t,int d)
    {
        int Distance = F;
        for (int i = 1; i < t-1; i++) 
        {
            Distance += Math.min(F + i*d , S + (t-1)*d - i*d);
        }

        Distance += S;

        return Distance;
    }



}

