static int[] csum(int[] a)
{
    int n = a.length;
    int[] res = new int[n];
    res[0] = a[0];
    for(int i = 1; i<n; i++) res[i] = (a[i] + res[i-1])%mod;
    return res;
}
static int query(int[] csum, int a, int b)
{
    int res = csum[b];
    if(a > 0) res -= csum[a-1];
    if(res < 0) res += mod;
    return res;
}
static int mod = 1000000007;
