class TaskB {
    public void solve(int testNumber, InputReader in, OutputWriter out){
	    int velocityprincess = in.ri(), velocitydragon = in.ri(), thoursheadstart = in.ri(), fhoursstraightening = in.ri(), cmilestotravel = in.ri();
	    double t = -(1.0* thoursheadstart * velocitydragon) / (velocityprincess - velocitydragon);
	    double distanceprincess = velocityprincess * t;
	    if (distanceprincess >= cmilestotravel || velocityprincess >= velocitydragon){
		    out.print(0);
		    return;
	    }
	    for(int i = 0; i < 10000000; i++) {
