	public static void main(String[] args) throws IOException, FileNotFoundException {
		BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
		//BufferedReader in = new BufferedReader(new FileReader("FriendsandPresents"));

		StringTokenizer st = new StringTokenizer(in.readLine());
		cnt1 = Integer.parseInt(st.nextToken());
		cnt2 = Integer.parseInt(st.nextToken());
		x = Integer.parseInt(st.nextToken());
		y = Integer.parseInt(st.nextToken());

		long min = 1;
		long max = (long)(1e10);
		while (min < max) {
			long middle = (min  +max)/2;
			if (check(middle)) {
				max = middle;	
			}
			else min = middle+1;
		}

		System.out.println(min);

	}

	public static boolean check(long num) {
		long divnone = num - (num/x + num/y - num/(x*y));
		long divy = num/y - num/(x*y);
		long divx = num/x - num/(x*y);
		long c1_left = cnt1 - divy;
		if (c1_left<0) c1_left=0;
		long c2_left = cnt2 - divx;
		if (c2_left<0) c2_left=0;
		return c2_left + c1_left <= divnone;
	}
}

