public class Main {
	public static void main(String args[]) {new Main().work();}

	Scanner in = new Scanner(System.in);
	PrintWriter out = new PrintWriter(System.out);
	void work() {		
		int n=in.nextInt();
		String str=in.next();
		long[][] dp=new long[n][n];
		out.println(dfs(str,0,n-1,dp));
		out.flush();
	}

	long dfs(String str,int s,int e,long[][] dp){
	    if(s>e) return 0;
	    if(dp[s][e]>0) return dp[s][e];
	    dp[s][e]=1+dfs(str,s+1,e,dp);
        for(int i=s+1;i<=e;i++){
            if(str.charAt(i)==str.charAt(s)){
                dp[s][e]=Math.min(dfs(str,s+1,i-1,dp)+dfs(str,i,e,dp),dp[s][e]);
            }
        }	    
        return dp[s][e];
	}
}

