		while(true) {
			int x = q.poll();

			if(x>=orig) {
				q.add(x-1);
				orig++;
			}
			else
				break;

			bribes++;
		}
		System.out.println(bribes);
	}

	public static class reverseCompare implements Comparator<Integer>{

		@Override
		public int compare(Integer arg0, Integer arg1) {
			if(arg0 > arg1)
				return -1;
			if(arg0 < arg1)
				return 1;
			return 0;
		}
	}
}

