public class P2 {
	static int find (long x) {
		if (x < 2)
			return 0;
		int bc = 0, zc = 0, zp = -1;
		long b = x;
		while (b > 0) {
			bc++;
			if ((b & 1) == 0) {
				zc++;
				zp = bc;
			}
			b >>= 1;
		}
		long p = 0;
		if (zc == 0)
			p = x - 1;
		else if (zc == 1)
			p = x;
		else {
			for (int i = 1; i < bc - zp; i++) {
				p = p << 1;
				p = p | 1;
			}
			p = p << 1;
			for (int i = 0; i < zp; i++) {
				p = p << 1;
				p = p | 1;
			}
			if ((p & (p + 1)) == 0)
				p--;
		}
		bc = 0;
		zp = -1;
		b = p;
		while (b > 0) {
			bc++;
			if ((b & 1) == 0)
				zp = bc;
			b >>= 1;
		}
		int ans = 0;
		for (int i = 2; i < bc; i++)
			ans += (i - 1);
		ans += (bc - zp);
		return ans;
	}
	public static void main (String[] args) {
		Scanner sc = new Scanner (System.in);
		PrintStream op = System.out;
		long a = sc.nextLong();
		long b = sc.nextLong();
		if (a > b) {
			long t = a;
			a = b;
			b = t;
		}
		int av = find (a - 1);
		int bv = find (b);
		op.println(bv - av);
		sc.close();
		op.close();
	}
}

