	long[][][] dp = new long[36][36][36];
	void solve() throws IOException
	{
		StringTokenizer st = tokens();
		int n = nextInt(st), H = nextInt(st);
		this.H = H;
		for(long[][] t1 : dp) for(long[] t2 : t1) fill(t2, -1);
		long res = 0;
		for(int i = 1; i <= n; i++) 
			for(int h = H; h <= n; h++)
			{
				res += get(i - 1, n - i, h - 1);
				//print(i - 1, n - i, h - 1, get(i - 1, n - i, h - 1));
			}
		out.println(res);
	}
	int H;
	long get(int left, int right, int h)
	{
		if(h == 0)
		{
			if(left == 0 && right == 0) return 1;
			return 0;
		}
		if(dp[left][right][h] != -1) return dp[left][right][h];

		if(h > max(left, right))
		{
			dp[left][right][h] = 0;
			return 0;
		}	
		long res = 0;
		if(left > 0 && right > 0)
		{
			for(int i = 0; i < left; i++)
				for(int j = 0; j < right; j++)
				{
					for(int k = 0; k <= h - 2; k++)
					{
						res += get(i, left - i - 1, k) * get(j, right - j - 1, h - 1);
						res += get(i, left - i - 1, h - 1) * get(j, right - j - 1, k);	
					}
					res += get(i, left - i - 1, h - 1) * get(j, right - j - 1, h - 1);
				}

		}
		if(left > 0 && right == 0)
		{
			for(int i = 0; i < left; i++) res += get(i, left - i - 1, h - 1);
		}
		if(right > 0 && left == 0)
		{
			for(int i = 0; i < right; i++) res += get(i, right - i - 1, h - 1);
		}
		//print(left, right, h, res);
		return dp[left][right][h] = res;
	}

