    class Box{
        public Box(char color, int count, int idx){
            this.color = color == 'R' ? 0 : (color == 'G' ? 1 : 2);
            this.count = count;
            this.idx = idx;
        }
        public int color;
        public int count;
        public int idx;
    }

    public void solve() {
        int[] l = io.readIntArray();
        int n = l[0];
        int s = l[1] - 1;
        int k = l[2];
        int[] num = io.readIntArray();
        char[] col = io.readLine().toCharArray();
        Box[] all = new Box[n];
        int sum = 0;
        for(int i = 0;i<n;i++){
            all[i] = new Box(col[i], num[i], i);
            sum += num[i];
        }
        int maxCount = Math.max(k, sum);
        Arrays.sort(all, Comparator.comparingInt(a -> a.count));
        int[][] min = new int[n][maxCount+1];
        for(int i = 0;i<n;i++)
            for(int j = 0;j<=maxCount;j++)
                min[i][j] = Integer.MAX_VALUE / 3;
        for(int i = 0;i<n;i++) {
            Box b = all[i];
            min[i][b.count] = Math.min(min[i][b.count], Math.abs(s - b.idx));
            for (int j = 0; j < i; j++)
                if (b.count > all[j].count && b.color != all[j].color) {
                    for (int c = b.count; c <= maxCount; c++) {
                        min[i][c] = Math.min(min[i][c], min[j][c - b.count] + Math.abs(b.idx - all[j].idx));
                    }
                }
        }
        int res = Integer.MAX_VALUE/3;
        for(int i = 0;i<n;i++)
            for(int j = k; j<=maxCount;j++)
                res = Math.min(res, min[i][j]);
        io.writeLine((res==Integer.MAX_VALUE/3?-1:res)+"");
    }

}


