        else if (K == N) System.out.println(pow(M, (N + 1) / 2));
        else if (K % 2 == 0) System.out.println(M);
        else System.out.println(M * M);

        }

    private static int pow(long x, long y) {
        int[] put = new int[128];
        int k = 0;
        while (y != 0) {
            put[k++] = (int)y % 2;
            y /= 2;
        }

        long res = x;
        for (int i = k - 2; i >= 0; i--) {
            if (put[i] == 1) {
                res *= res;
                res %= MOD;
                res *= x;
                res %= MOD;
            } else {
                res *= res;
                res %= MOD;
            }
        }

        return (int)res;
    }
}

