        public void solve(int testNumber, MyReader in, PrintWriter out) {
            String str = in.next();
            long n = Long.parseLong(str.substring(0, str.length() - 1));
            char ch = str.charAt(str.length() - 1);
            int poz = getPoz(ch);
            BigInteger time = BigInteger.ZERO;
            if (n % 4 != 0) time = BigInteger.valueOf(n / 4).multiply(BigInteger.valueOf(16));
            else time = BigInteger.valueOf((n - 1) / 4).multiply(BigInteger.valueOf(16));

            if (n % 4 == 0) {
                time = time.add(BigInteger.valueOf(poz + 7));
            } else if (n % 4 == 1) {
                time = time.add(BigInteger.valueOf(poz));
            } else if (n % 4 == 2) {
                time = time.add(BigInteger.valueOf(poz + 7));
            } else if (n % 4 == 3) {
                time = time.add(BigInteger.valueOf(poz));
            }
            out.println(time);
