		for(int i=0;i<n;i++)
			R[i]=new Rectangle(in.readInt(),in.readInt(),in.readInt(),in.readInt());

		for(int i=(1<<n)-1;i<(1<<n);i++)
			{
			LinkedList<Rectangle> L=new LinkedList<Rectangle>();
			for(int j=0;j<n;j++)
				{
