	private static boolean check(Rectangle[] RT)
		{
		/*System.out.println("For ");
		for(Rectangle r:RT)
			System.out.println("\t"+r.x1+" "+r.y1+" "+r.x2+" "+r.y2);*/
		long totArea=0;
		for(Rectangle r:RT)
			totArea+=(r.x2-r.x1)*(r.y2-r.y1);
		int upperCornerIndex=-1,lowerCornerIndex=-1;
		int N=RT.length;

		//upper right
		for(int i=0;i<N;i++)
			{
			boolean valid=true;
			for(int j=0;j<N;j++)
				{
				if(RT[i].x2>=RT[j].x2&&RT[i].y2>=RT[j].y2)
					continue;
				else
					valid=false;
				}
			if(valid)
				upperCornerIndex=i;
			}

		//bottom left
		for(int i=0;i<N;i++)
			{
			boolean valid=true;
			for(int j=0;j<N;j++)
				{
				if(RT[i].x1<=RT[j].x1&&RT[i].y1<=RT[j].y1)
					continue;
				else
					valid=false;
				}
			if(valid)
				lowerCornerIndex=i;
			}
		if(upperCornerIndex==-1||lowerCornerIndex==-1)
			return false;
		//System.out.println("\tIndices: "+upperCornerIndex+" "+lowerCornerIndex);
		long yLen=RT[upperCornerIndex].y2-RT[lowerCornerIndex].y1;
		long xLen=RT[upperCornerIndex].x2-RT[lowerCornerIndex].x1;
		if(xLen != yLen)
			return false;
		if(xLen*yLen!=totArea)
			return false;
		/*System.out.println("True for ");
		for(Rectangle r:RT)
			System.out.println("\t"+r.x1+" "+r.y1+" "+r.x2+" "+r.y2);*/
		return true;
		}
