public class C {
	FastReader scn;
	PrintWriter out;
	String INPUT = "";

	void solve() {
		int n = scn.nextInt();
		char[] arr = scn.next().toCharArray();
		int sum = 0;
		boolean allZero = true;
		for(char ch : arr) {
			sum += ch - '0';
			if(ch != '0') {
				allZero = false;
			}
		}
		if(allZero) {
			out.println("YES");
			return;
		}
		boolean yes = false;
		for (int i = 0; i < sum; i++) {
			boolean fail = false;
			int curr = 0;
			for (int j = 0; j < n; j++) {
				int val = curr + arr[j] - '0';
				if (val > i) {
					fail = true;
					break;
				} else {
					curr += arr[j] - '0';
					j++;
					while(j < n && arr[j] == '0') {
						j++;
					}
					j--;
					if(curr == i) {
						curr = 0;
					} else if(j == n - 1) {
						fail = true;
					}
				}
			}
			if (!fail) {
				yes = true;
				break;
			}
		}

		if (yes) {
			out.println("YES");
		} else {
			out.println("NO");
		}
	}

