public class ProblemC {
    static final long MOD = 1000000007;
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int l = sc.nextInt();
		int r = sc.nextInt();
		sc.close();
		long[][] dp = new long[n + 1][3];
		int []k = new int[3];
		for(int i = 0; i < 3; i++) {
			k[i] = (r - i + 3) / 3 - (l - i + 2) / 3;
		}
		dp[1][0] = k[0];
		dp[1][1] = k[1];
		dp[1][2] = k[2];
		for(int i = 2; i <= n; i++) {
			dp[i][0] = dp[i-1][0] * k[0] + dp[i-1][1] * k[2] + dp[i-1][2] * k[1];
			dp[i][1] = dp[i-1][0] * k[1] + dp[i-1][1] * k[0] + dp[i-1][2] * k[2];
			dp[i][2] = dp[i-1][0] * k[2] + dp[i-1][1] * k[1] + dp[i-1][2] * k[0];
			dp[i][0] %= MOD;
			dp[i][1] %= MOD;
			dp[i][2] %= MOD;
		}
		System.out.println(dp[n][0]);
	}
}

