public class ETry implements Runnable {

    BufferedReader in;
    PrintWriter out;
    StringTokenizer tok;

    public static void main(String[] args) {
        new ETry().run();
    }

    @Override
    public void run() {
        try {
            in = new BufferedReader(new InputStreamReader(System.in));
            out = new PrintWriter(System.out);

            Locale.setDefault(Locale.US);
            tok = new StringTokenizer("");
            solve();
            in.close();
            out.close();
        } catch (Throwable t) {
            t.printStackTrace(System.err);
            System.exit(-1);
        }
    }

    String readString() throws IOException {
        while (!tok.hasMoreTokens()) {
            tok = new StringTokenizer(in.readLine());
        }
        return tok.nextToken();
    }

    int readInt() throws IOException {
        return Integer.parseInt(readString());
    }

    long readLong() throws IOException {
        return Long.parseLong(readString());
    }

    double readDouble() throws IOException {
        return Double.parseDouble(readString());
    }


    // solution

    class Point {
        long x, y;
        int i;

        public Point(long x, long y, int i) {
            this.x = x;
            this.y = y;
            this.i = i;
        }

        @Override
        public String toString() {
            return String.format("[(%d %d) %d]", x, y, i);
        }

    }

    class PointComparator implements Comparator<Point> {
        Point root;

        public PointComparator(Point root) {
            this.root = root;
        }

        @Override
        public int compare(Point a, Point b) {
            long wp = (a.x - root.x) * (b.y - root.y) - (a.y - root.y) * (b.x - root.x);
            if (wp < 0)
                return -1;
            if (wp > 0)
                return 1;
            return 0;
        }

    }

    int n;
    List<Integer>[] graph;
    int[] size;
    int[] parent;
    Point[] points;
    int[] ans;

    void solve() throws IOException {
        n = readInt();
        // читаем граф
        graph = new List[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<Integer>();
        }
        for (int i = 0; i < n - 1; i++) {
            int x = readInt() - 1;
            int y = readInt() - 1;
            graph[x].add(y);
            graph[y].add(x);
        }

        // читаем точки
        points = new Point[n];
        for (int i = 0; i < n; i++) {
            points[i] = new Point(readLong(), readLong(), i);
        }

        // подвешиваем дерево и 
        size = new int[n];
        parent = new int[n];
        dfs(0, -1);

        // считаем ответ
        ans = new int[n];
        Arrays.fill(ans, -1);

        // ищем самый левый
        int rootIndex = 0;
        for (int i = 1; i < n; i++) {
            if (points[i].x < points[rootIndex].x || points[i].x == points[rootIndex].x
                    && points[i].y < points[rootIndex].y) {
                rootIndex = i;
            }
        }

        // ставим самый левый первым
        Point tmp = points[0];
        points[0] = points[rootIndex];
        points[rootIndex] = tmp;


        // считаем
        rec(0, 0, n - 1);

        // ответ
        for (int i = 0; i < n; i++) {
            if (ans[i] == -1) {
                throw new RuntimeException("Answer is wrong");
            }
        }
        for (int i = 0; i < n; i++) {
            out.print(ans[i] + 1);
            if (i == n - 1) {
                out.println();
            } else {
                out.print(" ");
            }
        }
    }

    private void rec(int x, int left, int right) {
        ans[points[left].i] = x;
        Arrays.sort(points, left + 1, right + 1, new PointComparator(points[left]));
        int i = left + 1;
        for (int y : graph[x]) {
            if (y != parent[x]) {
                rec(y, i, i + size[y] - 1);
                i += size[y];
            }
        }
    }

    private void dfs(int x, int p) {
        parent[x] = p;
        size[x] = 1;
        for (int y : graph[x]) {
            if (y != p) {
                dfs(y, x);
                size[x] += size[y];
            }
        }
    }

}

