public class Main {

    public static void main(String[] args) {
        Scanner cin = new Scanner(System.in);

        int n = cin.nextInt();
        int k = cin.nextInt();

        String cell = cin.next();


        int tPos = 0, pPos = 0;
        for (int i = 0; i < cell.length(); i++) {

            if (cell.charAt(i) == 'T') {
                tPos = i;
            }
            if (cell.charAt(i) == 'G') {
                pPos = i;
            }
        }


        int minv = Math.min(tPos, pPos);
        boolean flag = true;
        while (flag) {
            minv += k;
            if (minv >= n) {
                break;
            }
            if (cell.charAt(minv) == '#') {
                break;
            }
            if (cell.charAt(minv) == 'T' || cell.charAt(minv) == 'G') {
                flag = false;
            }
        }
        if (flag) {
            System.out.println("NO");
        } else {
            System.out.println("YES");
        }
    }
}

