public class Permutation {

        int[] a;
        int n;

        public Permutation(int n){
            this.n=n;
            a=new int[n];
            for (int i=0; i<n; i++){
                a[i]=i;
            }
        }

        public boolean nextPermutation(){ //Пишется с do{}while(nextPermutation(a));
            int i=n-1;
            for (i=n-2; i>=0; i--){
                if (a[i]<a[i+1]){
                    break;
                }
            }
            if (i==-1){
                return false;
            }
            int jMin=i+1;
            for (int j=n-1; j>i; j--){
                if (a[i]<a[j]&&a[j]<a[jMin]){
                    jMin=j;
                }
            }
            swap(i, jMin);
            for (int j=1; j<=(n-i)/2; j++){
                swap(i+j, n-j);
            }
            return true;
        }


        public int get(int i){
            return a[i];
        }

        void swap(int i, int j){
            int r=a[i];
            a[i]=a[j];
            a[j]=r;
        }
    }

    void solve() throws IOException{
        Permutation per;
        int[] p = new int[4];
        for (int i = 0; i < 4; i++){
            p[i] = readInt();
        }
        int a = readInt();
        int b = readInt();
        int count = 0;
        for (int x = a; x <= b; x++){
            per = new Permutation(4);
            int pr = 0;
            do{
                int p1 = p[per.get(0)];
                int p2 = p[per.get(1)];
                int p3 = p[per.get(2)];
                int p4 = p[per.get(3)];
                if (x % p1 % p2 % p3 % p4 == x){
                    pr++;
                }
            }while(per.nextPermutation());
            if (pr >= 7){
                count++;
            }
        }
        out.print(count);
    }      
}

