class TaskA {
    public void solve(int testNumber, InputReader in, OutputWriter out) {
        long x = in.readLong();
        long y = in.readLong();
        long m = in.readLong();

        if (x >= m || y >= m) {
            out.printLine(0);
            return;
        }

        if (x <= 0 && y <= 0) {
            out.printLine(-1);
            return;
        }

        long answer = 0;

        if (x < 0) {
            answer += (Math.abs(x) + y) / y;
            x = x + answer * y;
        }

        if (y < 0) {
            answer += (Math.abs(y) + x) / x;
            y = y + answer * x;
        }

        Queue<Pair<Long, Long>> pairQueue = new ArrayDeque<Pair<Long, Long>>();

        pairQueue.add(Pair.makePair(x, y));

        while (true) {
            Pair<Long, Long>[] temp = new Pair[pairQueue.size()];
            pairQueue.toArray(temp);
            pairQueue = new ArrayDeque<Pair<Long, Long>>();
            for (Pair<Long, Long> cur : temp) {
                if (cur.first >= m || cur.second >= m) {
                    out.printLine(answer);
                    return;
                }
                if (cur.first > 0 && cur.first >= cur.second)
                    pairQueue.add(Pair.makePair(cur.first, cur.first + cur.second));
                if (cur.second > 0 && cur.second >= cur.first)
                    pairQueue.add(Pair.makePair(cur.first + cur.second, cur.second));
            }
            answer++;
        }
    }
}

class InputReader {
    private InputStream stream;
    private byte[] buf = new byte[1024];
    private int curChar;
    private int numChars;
    private SpaceCharFilter filter;

    public InputReader(InputStream stream) {
        this.stream = stream;
    }

    public int read() {
        if (numChars == -1)
            throw new InputMismatchException();
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0)
                return -1;
        }
        return buf[curChar++];
    }

    public boolean isSpaceChar(int c) {
        if (filter != null)
            return filter.isSpaceChar(c);
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    public long readLong() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        long res = 0;
        do {
            if (c < '0' || c > '9')
                throw new InputMismatchException();
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    public interface SpaceCharFilter {
        public boolean isSpaceChar(int ch);
    }

}

