            System.out.println(-1);
        else
            System.out.println(ans);
    }

    static void f(int a, int d) {
        if (weights.containsKey(a))
            return;

        weights.put(a, d);

        if (a % 2 == 0)
            f(a / 2, d + 1);
        if (a % 3 == 0)
            f(a / 3, d + 1);
        if (a % 5 == 0)
            f(a / 5, d + 1);
    }

    static void f2(int b, int d) {
        if (weights.containsKey(b)) {
            ans = Math.min(ans, d + weights.get(b));
            return;
        }

        if (b % 2 == 0)
            f2(b / 2, d + 1);
        if (b % 3 == 0)
            f2(b / 3, d + 1);
        if (b % 5 == 0)
            f2(b / 5, d + 1);
    }
}

