import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.regex.Pattern;

public class Solution {

	private static boolean check(String s) {
		if (s.split("@").length != 2)
			return false;

		if (s.charAt(0) == '@' || s.charAt(s.length() - 1) == '@')
			return false;

		String username = s.split("@")[0];
		String remains = s.split("@")[1];

		if (remains.split("/").length > 2)
			return false;
		if (remains.charAt(remains.length() - 1) == '/')
			return false;

		String hostname = remains.split("/")[0];

		if (hostname.length() < 1 || hostname.length() > 32)
			return false;

		Pattern p = Pattern.compile("[A-Za-z0-9_]{1,16}");

		String[] temp_hp = hostname.split("\\.");

		int cnt = temp_hp.length + (hostname.charAt(0) == '.' ? 1 : 0)
				+ (hostname.charAt(hostname.length() - 1) == '.' ? 1 : 0);

		String[] host_parts = new String[cnt];
		Arrays.fill(host_parts, "");
		for (int i = 0; i < temp_hp.length; ++i)
			host_parts[i] = temp_hp[i];

		// System.err.println("hostname = " + hostname);
		// System.err.println("host_parts.length = " + host_parts.length);

		if (!p.matcher(username).matches())
			return false;

		for (String hp : host_parts)
			if (!p.matcher(hp).matches())
				return false;

		if (remains.split("/").length == 2) {
			String resourse = remains.split("/")[1];
			return p.matcher(resourse).matches();
		}

		return true;
	}

	public static void main(String[] args) throws IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String s = br.readLine();
		if (check(s))
			System.out.println("YES");
		else
			System.out.println("NO");
	}

}

