public class Main {

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        long m = sc.nextLong();
        long lo = 0;
        long hi = (long) 1e16;
        long ans = -1;
        while (lo <= hi) {
            long mid = (lo + hi) /2;
            long ways = getNumberofways(mid);
            if (ways == m) ans = mid;
            if (ways >= m) hi=mid-1;
            else lo = mid+1;
        }
        out.println(ans);
        out.close();
        out.flush();
    }

    static long getNumberofways(long n) {
        long cnt = 0;
        for (long k = 2; 1l * k * k * k <= n; k++) {
            long mult = 1l * k * k * k;
            cnt += n / mult;
        }
        return cnt;
    }


    static class Scanner {
        StringTokenizer st;
        BufferedReader br;

        public Scanner(InputStream system) {
            br = new BufferedReader(new InputStreamReader(system));
