    public void solve(Scanner in, PrintWriter out) {
        int t = in.nextInt();
        int l = in.nextInt();
        int r = in.nextInt();

        long[] a = new long[r + 1];
        boolean[] prime = new boolean[r + 1];
        Arrays.fill(prime, true);
        prime[0] = prime[1] = false;
        for (int i = 2; i <= r; i++) {
            if (prime[i]) {
                if ((long)i * i <= (long)r) {
                    for (long j = (long)i*i; j <= r; j+=i) {
                        prime[(int)j] = false;
                    }
                }
            }
        }


        List<Integer> pr = new ArrayList<>();
        for (int i = 2; i <= r; i++) {
            if (prime[i]) {
                pr.add(i);
                a[i] = (long) i * (i - 1) / 2;
            } else {
                for (Integer p : pr) {
                    if (i % p == 0) {
                        int p1 = i / p;
                        int max = Math.max(p, p1);
                        int min = Math.min(p, p1);
                        a[i] = a[min] * max + a[max];
                        break;
                    }
                }
            }
        }

        long tt[] = new long[r];
        tt[0] = 1;
        long temp = 1;
        for (int i = 1; i <= r - l; i++) {
            temp *= (long)t;
            temp %= 1000000007;
            tt[i] = temp;
        }

        long res = 0;
        for (int i = 0; i <= r - l; i++) {
            res += (tt[i] * (a[i + l] % 1000000007)) % 1000000007;
            res %= 1000000007;
        }

        System.out.println(res);
    }


}

class Utils {

    public static int binarySearch(int[] a, int key) {
        int s = 0;
        int f = a.length;
        while (f > s) {
            int mid = (s + f) / 2;
            if (a[mid] > key) {
                f = mid - 1;
            } else if (a[mid] <= key) {
                s = mid + 1;
            }
        }
        return -1;
    }

    public static long gcd(long a, long b) {
        return b != 0 ? gcd(b, a % b) : a;
    }

    public static long lcm(long a, long b) {
        return a / gcd(a, b) * b;
    }

    static List<Integer> prime(int number) {
        List<Integer> a = new ArrayList<>();
        for (int i = 2; i * i <= number; i++) {
            if (number % i == 0) {
                a.add(i);
                number /= i;
                i = 1;
            }
        }
        a.add(number);
        return a;
    }
}

