class TaskB implements Task {

	boolean[] vis;
	int[] arr;
	List<Long> div;
	boolean[] sieve;

	public void solve(int testNumber, InputReader in, OutputWriter out) {
		int n=in.readInt(), m=in.readInt();
		arr=new int[n+1];
		vis=new boolean[n+1];
		sieve=IntegerUtils.generatePrimalityTable(n+1);
		while (m-->0) {
			char c=in.readCharacter();
			int x=in.readInt();
			div=IntegerUtils.getDivisors(x);
			if (c=='+') {
				if (vis[x]) {
					out.printLine("Already on");
					continue;
				}
				boolean val=true;
				for (long y: div) if (sieve[(int)y] && arr[(int)y]>0) {
					val=false;
					out.printLine("Conflict with", arr[(int)y]);
					break;
				}
				if (!val) continue;
				out.printLine("Success");
				vis[x]=true;
				for (long y: div) if (sieve[(int)y]) arr[(int)y]=x;
			}
			else if (vis[x]) {
				out.printLine("Success");
				vis[x]=false;
				for (long y: div) arr[(int)y]=0;
			}
			else out.printLine("Already off");
		}
	}

}

