import java.io.*; 
import java.util.*;

public class Main {

    static class FastScanner
    { 
        BufferedReader br; 
        StringTokenizer st; 

        public FastScanner() 
        { 
            br = new BufferedReader(new
                     InputStreamReader(System.in)); 
        } 

        String next() 
        { 
            while (st == null || !st.hasMoreElements()) 
            { 
                try
                { 
                    st = new StringTokenizer(br.readLine()); 
                } 
                catch (IOException  e) 
                { 
                    e.printStackTrace(); 
                } 
            } 
            return st.nextToken(); 
        } 

        int nextInt() 
        { 
            return Integer.parseInt(next()); 
        } 

        long nextLong() 
        { 
            return Long.parseLong(next()); 
        } 

        double nextDouble() 
        { 
            return Double.parseDouble(next()); 
        } 

        String nextLine() 
        { 
            String str = ""; 
            try
            { 
                str = br.readLine(); 
            } 
            catch (IOException e) 
            { 
                e.printStackTrace(); 
            } 
            return str; 
        } 
    } 

    public static void main(String[] args) throws IOException {
        FastScanner sc=new FastScanner();
        int N = sc.nextInt();
        int C = sc.nextInt();
        int[] p = new int[N];
        for (int i = 0; i < N; i++)
        	p[i] = sc.nextInt();
        int[] t = new int[N];
        for (int i = 0; i < N; i++)
        	t[i] = sc.nextInt();

        int score1 = 0;
        int time1 = 0;
        for (int i = 0; i < N; i++) {
        	time1 += t[i];
        	score1 += Math.max(0, p[i] - C*time1);
        }

        int score2 = 0;
        int time2 = 0;
        for (int i = N-1; i >= 0; i--) {
        	time2 += t[i];
        	score2 += Math.max(0, p[i] - C*time2);
        }

        if (score1 > score2) {
        	System.out.println("Limak");
        } else if (score2 > score1) {
        	System.out.println("Radewoosh");
        } else {
        	System.out.println("Tie");
        }
    }
}

import java.util.*;
public class MartianClock {
	public static void main(String[] args){
		Scanner reader = new Scanner(System.in);
		String in = reader.next();
		StringTokenizer st = new StringTokenizer(in, ":");
		String a = st.nextToken();
		String b = st.nextToken();

		LinkedList<Integer> q = new LinkedList<Integer>();
		//try all bases!
		for(int i = 2; i <= 70; i++){
			try{
				int A = parseInt(a,i);
				int B = parseInt(b,i);
				if(A <= 23 && B <= 59)
					q.add(i);
			}catch(Exception e){
				continue;
			}
		}

		if(q.size() == 0){
			System.out.println(0);
		}else if(q.getLast() == 70){
			System.out.println(-1);
		}else{
			while(!q.isEmpty())
				System.out.print(q.remove() + " ");
			System.out.println();
		}
	}

	public static int parseInt(String a, int b){
		if(b < 36)
			return Integer.parseInt(a,b);
		int sum = 0;
		for(int i = 0; i < a.length(); i++){
			sum *= b;
			sum += a.charAt(i)>='A'?(a.charAt(i)-'A'+10):(a.charAt(i)-'0');
		}
