		}
		for (int i = 0; i < a.length; i++) {
			for (int j = i; j < a.length; j++) {
				max = Math.max(max, count(i, j, a));
			}
		}
		System.out.println(max);
	}

	public static int count(int x, int y, int a[]) {
		int c = 0, co = 0;
		for (int i = x; i <= y; i++) {
			if (a[i] == 0) {
				c++;
			}
		}
		for (int i = 0; i < a.length; i++) {
			if (a[i] == 1 && i < x || a[i] == 1 && i > y) {
				co++;
			}
		}
		return co + c;
	}
}

