    private void rec( Long a, Long b){
        if(a==0 || b==0) {
            this.a = a;
            this.b = b;
            return;
        }
        else if(a >= 2*b) rec((a)%(b*2), b);
        else if(b >= 2*a) rec(a, b%(2*a));
        else{
            this.a = a;
            this.b = b;
        }
    }
