public class Hopscotch
{
    public static void main(String ar[])
    {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;

        BufferedReader in = new BufferedReader(new InputStreamReader(inputStream));
        PrintWriter out = new PrintWriter(outputStream);

        Hopscotch demo = new Hopscotch();
        demo.solve(in, out);

        out.close();
    }

    public void solve(BufferedReader in, PrintWriter out)
    {
        try
        {
            String tokens[] = in.readLine().split(" ");
            int side = Integer.parseInt(tokens[0]);
            int x = Integer.parseInt(tokens[1]);
            int y = Integer.parseInt(tokens[2]);
            out.println(taskB(side, x, y));
        } catch (IOException e)
        {
            e.printStackTrace();
        }
    }

    public long taskB(int side, int x, int y)
    {
        if (x == side || x == -side || y % side == 0)
        {
            return -1;
        }
        long yAbove = 0;
        long yBelow = 0;
        long iteration = 0;
        long stone = 0;
        while (true)
        {
            iteration++;
            stone = (iteration == 1 || iteration % 2 == 0) ? stone + 1 : stone + 2;
            yBelow = yAbove;
            yAbove += side;
            if ((y > yBelow && y < yAbove))
            {
                if (iteration == 1 || iteration % 2 == 0)
                {
                    if (x < side / 2.0 && x > -side / 2.0)
                    {
                        return stone;
                    }
                }
                else
                {
                    if (x == 0)
                    {
                        return -1;
                    }
                    else if (x < side && x > 0)
                    {
                        return stone;
                    }
                    else if (x > -side && x < 0)
                    {
                        return stone - 1;
                    }
                }
            }
            else if ((y < yBelow && y < yAbove) || y == yBelow || y == yAbove)
            {
                return -1;
            }
        }
    }
}

