import java.io.*;
import java.util.*;

public class E_1228 {

    static int n;
    static long k;
    static long[][] dp;
    static long[] kPow;
    static long[] k1Pow;
    static long[][] C;
    static long mod = (long) (1e9 + 7);

    static void prec() {
        kPow = new long[n + 1];
        k1Pow = new long[n + 1];
        kPow[0] = 1;
        k1Pow[0] = 1;
        for (int i = 1; i <= n; i++) {
            kPow[i] = (kPow[i - 1] * k) % mod;
            k1Pow[i] = (k1Pow[i - 1] * (k - 1)) % mod;
        }

        C = new long[n + 1][n + 1];
        C[0][0] = 1;
        for (int i = 1; i <= n; i++) {
            C[i][0] = C[i][i] = 1;
            for (int j = 1; j < i; j++) {
                C[i][j] = (C[i - 1][j] + C[i - 1][j - 1]) % mod;
            }
        }
    }

    static long mod(long x) {
        x %= mod;
        if (x < 0) x += mod;
        return x;
    }

    static void solve(FastReader in, PrintWriter out) {
        n = in.nextInt();
        k = in.nextInt();

        prec();

        dp = new long[n + 1][n + 1];
        dp[0][0] = 1;
        for (int r = 1; r <= n; r++) {
            dp[r][0] = dp[r - 1][0] * mod(kPow[n] - k1Pow[n]) % mod;
        }
        for (int c = 1; c <= n; c++) {
            dp[1][c] = kPow[n - c];
        }

        for (int r = 2; r <= n; r++) {
            for (int c = 1; c <= n; c++) {
                dp[r][c] = k1Pow[c] * mod(kPow[n - c] - k1Pow[n - c]) % mod * dp[r - 1][c] % mod;
                for (int c0 = 1; c0 <= c; c0++) {
                    dp[r][c] = (dp[r][c] + kPow[n - c] * C[c][c0] % mod * k1Pow[c - c0] % mod * dp[r - 1][c - c0] % mod) % mod;
                }
            }
        }

        out.println(dp[n][n]);
    }

    public static void main(String[] args) {
        FastReader in = new FastReader(System.in);
//        FastReader in = new FastReader(new FileInputStream("input.txt"));
        PrintWriter out = new PrintWriter(System.out);
//        PrintWriter out = new PrintWriter(new FileOutputStream("output.txt"));


        int q = 1;

        while (q-- > 0)
            solve(in, out);

        out.close();
    }

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        Integer nextInt() {
            return Integer.parseInt(next());
        }

        Long nextLong() {
            return Long.parseLong(next());
        }

        Double nextDouble() {
            return Double.parseDouble(next());
