public class d {

	static int n;
	static int k;
	static int m;

	static long[][] memo;

	public static void main(String[] args) 
	{
		Scanner in = new Scanner(System.in);

		n = in.nextInt();
		k = in.nextInt();
		m = in.nextInt();
		in.close();

		memo = new long[n+1][k];
		for(int curr = 0; curr < memo.length; ++curr)
		{
			Arrays.fill(memo[curr], -1);
		}

		System.out.println(go(1, 0, 1));
	}

	static long go(int place, int mod, int tens)
	{
		if(place == n+1) return 0;

		if(memo[place][mod] != -1)
			return memo[place][mod];

		long ret = 0;

		for(int curr = place == n?1:0; curr < 10; ++curr)
		{
			int nmod = (mod + curr*tens) %k;

			if(curr != 0 && nmod == 0)
			{
				//System.out.print(place +" " +curr +" " +mod +" ");
				long r = 1;
				for(int loc = place+1; loc < n; ++loc)
				{
					r = (r*10)%m;
				}
				if(place != n)
				{
					r = (r*9)%m;
				}
				//System.out.println(r);
				ret = (ret + r)%m;
			}
			else
			{
				ret = (ret + go(place+1, nmod, (tens*10)%k))%m;
			}
		}

		return memo[place][mod] = ret;
	}
}

