public class D {
	final long MOD = (long)(1e9+7);
	long p,k;
	void readInput() throws NumberFormatException, IOException{
		//BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		Scanner sc = new Scanner(System.in);
		p = sc.nextLong();
		k = sc.nextLong();
	}

	public static long powmod(long a, long x, long n){
		long res = 1;
		a = a % n;
		while(x>0){
			if ( x % 2 == 1)
				res = (res*a) %n;
			a = (a*a) %n;
			x = x >> 1;
		}
		return res;
	}	

	void solve(){
		long ssol = 0;
		if (k==0)
			ssol = powmod(p, p-1, MOD);
		else if (k==1)
			ssol = powmod(p, p, MOD);		
		else {		
			int ord = 1;
			long q = k;
			while(q!=1)
			{
				q = (q*k) % p;
				if (q<0) q+= p;
				ord++;
			}
			ssol = powmod(p, (p-1)/ord, MOD);		
		}		
		System.out.println(ssol);
	}

	public static void main(String[] args) throws NumberFormatException, IOException {
		D a = new D();
		a.readInput();
		a.solve();
	}

}

