                            for (int jj = j; jj <= j1; jj++) {
                                if (alt[ii][jj]) cnt++;
                            }
                        }
                        if (cnt >= k) {
                            ans++;
                        }
                    }
                }
            }
        }
        out.println(ans);

    }


