import java.util.Scanner;

public class Chess {
	static int[] shift = { -1, 2, 1, 2, -2, 1, 2, 1, -2, -1, 2, -1, 1, -2, -1,
			-2 };

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		boolean[][] board = new boolean[8][8];
		String rook = sc.next();
		int row = rook.charAt(0) - 'a';
		int col = rook.charAt(1) - '0' - 1;
		for (int i = 0; i < 8; i++)
			board[row][i] = true;
		for (int i = 0; i < 8; i++)
			board[i][col] = true;

		String knight = sc.next();
		int row1 = knight.charAt(0) - 'a';
		int col1 = knight.charAt(1) - '0' - 1;
		board[row1][col1] = true;
		for (int i = 0; i < shift.length - 1; i += 2) {
			int dx = row1 + shift[i];
			int dy = col1 + shift[i + 1];
			if (dx >= 0 && dx < 8 && dy < 8 && dy >= 0)
				board[dx][dy] = true;
		}
		int counter = 0;
		for (int i = 0; i < 8; i++)
			for (int j = 0; j < 8; j++)
				if (!board[i][j] && check(board, i, j, row, col))
					counter++;

		System.out.println(counter);

	}

	private static boolean check(boolean[][] board, int x, int y, int row,
			int col) {
		for (int i = 0; i < shift.length - 1; i += 2) {
			int dx = x + shift[i];
			int dy = y + shift[i + 1];
			if (dx == row && dy == col)
				return false;
		}
		return true;
	}
}

