public class Main {
	static class Reader
    {
        final private int BUFFER_SIZE = 1 << 16;
        private DataInputStream din;
        private byte[] buffer;
        private int bufferPointer, bytesRead;

        public Reader()
        {
            din = new DataInputStream(System.in);
            buffer = new byte[BUFFER_SIZE];
            bufferPointer = bytesRead = 0;
        }

        public Reader(String file_name) throws IOException
        {
            din = new DataInputStream(new FileInputStream(file_name));
            buffer = new byte[BUFFER_SIZE];
            bufferPointer = bytesRead = 0;
        }

        public String readLine() throws IOException
        {
            byte[] buf = new byte[64]; // line length
            int cnt = 0, c;
            while ((c = read()) != -1)
            {
                if (c == '\n')
                    break;
                buf[cnt++] = (byte) c;
            }
            return new String(buf, 0, cnt);
        }

        public int nextInt() throws IOException
        {
            int ret = 0;
            byte c = read();
            while (c <= ' ')
                c = read();
            boolean neg = (c == '-');
            if (neg)
                c = read();
            do
            {
                ret = ret * 10 + c - '0';
            }  while ((c = read()) >= '0' && c <= '9');

            if (neg)
                return -ret;
            return ret;
        }

        public long nextLong() throws IOException
        {
            long ret = 0;
            byte c = read();
            while (c <= ' ')
                c = read();
            boolean neg = (c == '-');
            if (neg)
                c = read();
            do {
                ret = ret * 10 + c - '0';
            }
            while ((c = read()) >= '0' && c <= '9');
            if (neg)
                return -ret;
            return ret;
        }

        public double nextDouble() throws IOException
        {
            double ret = 0, div = 1;
            byte c = read();
            while (c <= ' ')
                c = read();
            boolean neg = (c == '-');
            if (neg)
                c = read();

            do {
                ret = ret * 10 + c - '0';
            }
            while ((c = read()) >= '0' && c <= '9');

            if (c == '.')
            {
                while ((c = read()) >= '0' && c <= '9')
                {
                    ret += (c - '0') / (div *= 10);
                }
            }

            if (neg)
                return -ret;
            return ret;
        }

        private void fillBuffer() throws IOException
        {
            bytesRead = din.read(buffer, bufferPointer = 0, BUFFER_SIZE);
            if (bytesRead == -1)
                buffer[0] = -1;
        }

        private byte read() throws IOException
        {
            if (bufferPointer == bytesRead)
                fillBuffer();
            return buffer[bufferPointer++];
        }

        public void close() throws IOException
        {
            if (din == null)
                return;
            din.close();
        }
    }

	static class time implements Comparable<time>{
		int l,r;
		time(int x,int y){
			l=x;
			r=y;
		}
		@Override
		public int compareTo(time ob){
			int diff = this.l-ob.l;
			if(diff!=0)
				return diff;
			return this.r-ob.r;
		}
	}
	public static void main(String args[])throws IOException{
		Reader in=new Reader();
		long n=in.nextLong();
		long m=in.nextLong();
		if(m>=n){
			System.out.println(n);
			System.exit(0);
		}
		n -= m;
		long l = 0, r = (long)2e9;
		while (l < r) {
			long med = (l + r) / 2;
			long val = med * (med+1) / 2;
			if (val >= n) {
				r = med;
			} else {
				l = med+1;
			}
		}
		System.out.println(l+m);
	}
}

import java.io.*;
import java.util.*;
public class icpc
{
    public static void main(String[] args) throws IOException
    {
        Reader in = new Reader();
        //BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        long l = in.nextLong();
        long r = in.nextLong();
        System.out.println(giveAns(r) - giveAns(l - 1));
    }
    public static long giveAns(long x)
    {
        int numOfDigits = Long.toString(x).length();
        long ans = 0L;
        for (int i=2;i<numOfDigits;i++)
            ans += 9L * (long)Math.pow(10, i - 2);
        if (numOfDigits > 1)
            ans += 9;
        if (numOfDigits == 1)
            ans += x;
        else
        {
            int firstDigit = Long.toString(x).charAt(0) - '0';
            int lastDigit = Long.toString(x).charAt(numOfDigits - 1) - '0';
            ans += (firstDigit - 1) * (long)Math.pow(10, numOfDigits - 2);
            String s = Long.toString(x);
            for (int j=1;j<numOfDigits - 1;j++)
            {
                long val = 1L;
                int digit = s.charAt(j) - '0';
                val *= (1L * digit * (long)Math.pow(10, numOfDigits - j - 2));
                ans += val;
            }
            if (firstDigit <= lastDigit)
                ans++;
        }
        return ans;
    }
}
