import java.util.ArrayList;
import java.util.Arrays;
import java.util.Scanner;
public class Main{

	public static void main(String[] args) {

		Scanner kb = new Scanner(System.in);
		int rows = kb.nextInt();
		int columns = kb.nextInt();
		kb.nextLine();
		int[][] distances = new int[rows * columns][rows * columns];
		for (int i = 0; i < rows * columns; i++) {
			Arrays.fill(distances[i], 10000);
		}
		for (int i = 0; i < rows * columns; i++) {
			distances[i][i] = 0;
		}
		String rowLine = kb.nextLine();
		char[] rowLinesplit = rowLine.toCharArray();
		for (int i = 0; i < rows; i++) {
			if (rowLinesplit[i] == '<') {
				for (int j = columns - 1; j > 0; j --) {
					int from = i * columns + j;
					int to = i * columns + j - 1;
					distances[from][to] = 1;
				}
			} else if (rowLinesplit[i] == '>') {
				for (int j = 0; j < columns - 1; j++) {
					int from = i * columns + j;
					int to = i * columns + j + 1;
					distances[from][to] = 1;
				}
			}
		}
		String columnLine = kb.nextLine();
		char[] columnLineSplit = columnLine.toCharArray();
		for (int i = 0; i < columns; i++) {
			if (columnLineSplit[i] == 'v') {
				for (int j = 0; j < rows - 1; j++) {
					int from = j * columns + i;
					int to = (j + 1) * columns + i;
					distances[from][to] = 1;
				}
			} else if (columnLineSplit[i] == '^') {
				for (int j = rows - 1; j > 0; j--) {
					int from = j * columns + i;
					int to = (j - 1) * columns + i;
					distances[from][to] = 1;
				}
			}
		}

		for (int k = 0; k < rows * columns; k++) {
			for (int i = 0; i < rows * columns; i++) {
				for (int j = 0; j < rows * columns; j++) {
					distances[i][j] = Math.min(distances[i][j], distances[i][k] + distances[k][j]);
				}
			}
		}
		for (int i = 0; i < rows * columns; i++) {
			for (int j = 0; j < rows * columns; j++) {
				if (distances[i][j] == 10000) {
					System.out.println("NO");
					return;
				}
			}
		}
		System.out.println("YES");
	}

}

