			memo[idx][turn][1-turn]=0;
			return; 
		}
		if(memo[idx][turn][0]!=-1)
			return;
		dp(idx+1,turn);
		dp(idx+1,1-turn);
		//first case i leave it and give it to the other player
		int sc1 = memo[idx+1][turn][turn], sc2 = memo[idx+1][turn][1-turn]+elm[idx];
		int sc11 = memo[idx+1][1-turn][turn]+elm[idx], sc21 = memo[idx+1][1-turn][1-turn];
		if(sc1>sc11) {
			memo[idx][turn][turn]= sc1;
			memo[idx][turn][1-turn]=sc2;
		}else {
			memo[idx][turn][turn]= sc11;
			memo[idx][turn][1-turn]=sc21;
		}	

