			out.println(res);
		}

		static long inversions(int[] a, int low, int high) {
			if (high - low < 2)
				return 0;
			int mid = (low + high) >>> 1;
			long res = inversions(a, low, mid) + inversions(a, mid, high);
			int[] b = Arrays.copyOfRange(a, low, mid);
			for (int i = low, j = mid, k = 0; k < b.length; i++)
				if (j == high || b[k] <= a[j]) {
					a[i] = b[k++];
				} else {
					a[i] = a[j++];
					res += b.length - k;
				}
			return res;
		}

	}

	static class InputReader {
		final InputStream is;
		final byte[] buf = new byte[1024];
		int pos;
		int size;

		public InputReader(InputStream is) {
			this.is = is;
		}

		public int nextInt() {
			int c = read();
			while (isWhitespace(c))
				c = read();
			int sign = 1;
			if (c == '-') {
				sign = -1;
				c = read();
			}
			int res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = read();
			} while (!isWhitespace(c));
			return res * sign;
		}

		int read() {
			if (size == -1)
				throw new InputMismatchException();
			if (pos >= size) {
				pos = 0;
				try {
					size = is.read(buf);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (size <= 0)
					return -1;
			}
			return buf[pos++] & 255;
		}

		static boolean isWhitespace(int c) {
			return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
		}

	}
}

