class TaskC {
    public void solve(int testNumber, InputReader in, PrintWriter out) {
        long n = in.nextInt();
        if (n == 1) {
            out.println(1);
        } else if (n == 2) {
            out.println(2);
        } else {
            long ans = 0;
            int lower = (int) (n <= 100 ? 1 : n - 100);
            for (int i = lower; i <= n; i++) {
                for (int j = lower; j <= n; j++) {
                    for (int k = lower; k <= n; k++) {
                        ans = Math.max(lcm(lcm(i, j), k), ans);
                    }
                }
            }
            out.println(ans);
        }
    }

    public long gcd(long x, long y) {
        return y == 0 ? x : gcd(y, x % y);
    }

    public long lcm(long x, long y) {
        return x * y / gcd(x, y);
    }
}

