import java.util.Arrays;
import java.util.Scanner;

public class Main {

	public static void main(String[] args)
	{
		Scanner s=new Scanner(System.in);

		long m=1000000007;

		long x=s.nextLong();
		long n=s.nextLong();

		boolean[] prime=new boolean[500001];

		seive(prime,500000);

		ArrayList<Long> list=new ArrayList<>();

		for(long i=2;i<=500000;i++)
		{
			if(prime[(int)i]&&x%i==0)
			{
				list.add(i);

				while(x%i==0)
				{
					x=x/i;
				}
			}
		}

		if(x!=1)
		list.add(x);

		//System.out.println(list);

		long ans=1;



		for(int i=0;i<list.size();i++)
		{
			long count=0;

			for(long j=list.get(i);j<=n;j=j*list.get(i))
			{
				count=count+(n/j);
				if(Long.MAX_VALUE/j<list.get(i))
					break;
			}

			ans=(ans%m*power(list.get(i),count,m))%m;

		}

		System.out.println(ans);

	}

	public static long power(long a,long b,long m)
	{
		long res=1;

		while(b>0)
		{
			if(b%2!=0)
			{
				res=(res%m*a%m)%m;
			}

			b=b/2;
			a=(a%m*a%m)%m;
		}

		return res;
	}

	public static void seive(boolean[] prime,int n)
	{
		Arrays.fill(prime,true);

		prime[0]=false;
		prime[1]=false;

		for(int i=2;i<=Math.sqrt(n);i++)
		{
			if(prime[i])
			{
				for(int j=i*i;j<=n;j=j+i)
				{
					prime[j]=false;
				}
			}
		}
	}

}

