    private void solve() throws IOException {
        int a = nextInt();
        int b = nextInt();
        int c = nextInt();

        long result = 0;

        cache = new int[a * b * c + 1];

        for (int i = 1; i <= a; i++)
            for (int j = 1; j <= b; j++)
                for (int k = 1; k <= c; k++)
                    result += countD(i * j * k);

        out.print(result);
    }

    //70 70 70 = 14425864
    int[] cache;

    long countD(int n) {
        int result = 0;
        if (cache[n] != 0) return cache[n];
        for (int i = 1; i * i <= n; i++)
        {
            if (n % i == 0)
            {
                result++;
                if (i != n / i)
                {
                    result++;
                }
            }
        }
        cache[n] = result;
        return result;
    }

