public class Solution 
{
	static final int MOD = 1000000007;

	public static void main(String[] args) throws Exception
	{
		Scanner sc = new Scanner(System.in);
		int i , j;
		int T = 1;//sc.nextInt();
		outer : for(int tc = 1; tc <= T; tc++)
		{
			int A[][] = new int[6][2];
			for(i = 0; i < 6; i++)
			{
				A[i][0] = sc.nextInt();
				A[i][1] = sc.nextInt();
			}
			System.out.println(solve(A) ? "YES" : "NO");
		}
		sc.close();
    }

	static boolean solve(int A[][])
	{
		long a = area(A[0][0] , A[1][0] , A[0][1] , A[1][1]);

		int x1 = Math.max(A[0][0] , A[2][0]);
		int y1 = Math.max(A[0][1] , A[2][1]);

		int x2 = Math.min(A[1][0] , A[3][0]);
		int y2 = Math.min(A[1][1] , A[3][1]);

		long a1 = area(x1 , x2 , y1 , y2);
		if(x1 > x2 || y1 > y2)
			a1 = 0;

		int x3 = Math.max(A[0][0] , A[4][0]);
		int y3 = Math.max(A[0][1] , A[4][1]);

		int x4 = Math.min(A[1][0] , A[5][0]);
		int y4 = Math.min(A[1][1] , A[5][1]);

		long a2 = area(x3 , x4 , y3 , y4);
		if(x3 > x4 || y3 > y4)
			a2 = 0;

		x1 = Math.max(x1 , x3);
		y1 = Math.max(y1 , y3);

		x2 = Math.min(x2 , x4);
		y2 = Math.min(y2 , y4);

		long a3 = area(x1 , x2 , y1 , y2);
		if(x1 > x2 || y1 > y2)
			a3 = 0;

		if(a > a1 + a2 - a3)
			return true;
		return false;
	}

	static long area(int x1 , int x2 , int y1 , int y2)
	{
		return (1L * Math.abs(x1-x2) * Math.abs(y1-y2));
	}
}

