	{		
		in = new FastReader(System.in);
		out = new PrintWriter(System.out);
		solve();
		out.close();
	}

	void solve()
	{
		int h = in.nextInt();
		long n = in.nextLong();

		long tot = 0;
		long max = 1L << h;
		int cnt = 0;
		while (max >= 1)
		{			
			if (cnt % 2 == 0)
			{
				if (n > max / 2)
					tot += max;
				else {tot++; cnt++;}
			}
			else
			{
				if (n <= max / 2)
					tot += (max);
				else {tot++; cnt++;}
			}			
			max /= 2;
			if (n > max) n -= max;
		}

		out.println(tot - 1);		
	}

