public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        ScanReader in = new ScanReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        CGarland solver = new CGarland();
        solver.solve(1, in, out);
        out.close();
    }

    static class CGarland {
        int[] arr;
        int n;
        long[][][][] dp;

        long findIT(int index, int odd, int even, int parity) {
            if (odd < 0) return Integer.MAX_VALUE / 2;
            if (even < 0) return Integer.MAX_VALUE / 2;
            if (index == n) return 0;

            if (dp[index][odd][even][parity] != -1) return dp[index][odd][even][parity];
            if (arr[index] != 0) {
                int pp = (arr[index] % 2) == parity ? 0 : 1;
                return dp[index][odd][even][parity] = pp + findIT(index + 1, odd, even, arr[index] % 2);
            } else {
                long ans = Integer.MAX_VALUE / 2;
                {
                    int pp = (0) == parity ? 0 : 1;
                    ans = Math.min(ans, pp + findIT(index + 1, odd, even - 1, 0));
                }
                {
                    int pp = (1) == parity ? 0 : 1;
                    ans = Math.min(ans, pp + findIT(index + 1, odd - 1, even, 1));
                }
                return dp[index][odd][even][parity] = ans;
            }

        }

        public void solve(int testNumber, ScanReader in, PrintWriter out) {
            n = in.scanInt();
            arr = new int[n];
            in.scanInt(arr);
            boolean done[] = new boolean[n + 1];
            HashSet<Integer> remaining = new HashSet<>();


            for (int i = 0; i < n; i++) if (arr[i] != 0) done[arr[i]] = true;
            for (int i = 1; i <= n; i++) if (!done[i]) remaining.add(i);


            {
                dp = new long[n + 5][n + 5][n + 5][2];
                for (int i = 0; i < n + 5; i++) {
                    for (int j = 0; j < n + 5; j++) {
                        for (int k = 0; k < n + 5; k++) {
                            dp[i][j][k][0] = dp[i][j][k][1] = -1;
                        }
                    }
                }
            }

            int even = 0;
            int odd = 0;
            for (int e : remaining) {
                if (e % 2 == 0) even++;
                else odd++;
            }


            long ans;
            if (arr[0] == 0) {
                ans = Math.min(findIT(1, odd, even - 1, 0), findIT(1, odd - 1, even, 1));
            } else {
                ans = findIT(1, odd, even, arr[0] % 2);
            }


            out.println(ans);
        }

    }

    static class ScanReader {
        private byte[] buf = new byte[4 * 1024];
        private int INDEX;
        private BufferedInputStream in;
        private int TOTAL;

        public ScanReader(InputStream inputStream) {
            in = new BufferedInputStream(inputStream);
        }

        private int scan() {
            if (INDEX >= TOTAL) {
                INDEX = 0;
                try {
                    TOTAL = in.read(buf);
                } catch (Exception e) {
                    e.printStackTrace();
                }
                if (TOTAL <= 0) return -1;
            }
            return buf[INDEX++];
        }

        public int scanInt() {
            int I = 0;
            int n = scan();
            while (isWhiteSpace(n)) n = scan();
            int neg = 1;
            if (n == '-') {
                neg = -1;
                n = scan();
            }
            while (!isWhiteSpace(n)) {
                if (n >= '0' && n <= '9') {
                    I *= 10;
                    I += n - '0';
                    n = scan();
                }
            }
            return neg * I;
        }

        private boolean isWhiteSpace(int n) {
            if (n == ' ' || n == '\n' || n == '\r' || n == '\t' || n == -1) return true;
            else return false;
        }

        public void scanInt(int[] A) {
            for (int i = 0; i < A.length; i++) A[i] = scanInt();
        }

    }
}

