import java.util.Scanner;

public class BusGame {
    public enum Player {
        Ciel {
            @Override
            public Player nextPlayer() {
                return Hanako;
            }
        },
        Hanako {
            @Override 
            public Player nextPlayer() {
                return Ciel;
            }
        };

        public abstract Player nextPlayer();
    }


    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int hundredsCount = scanner.nextInt();
        int tensCount = scanner.nextInt();

        int hundreds = 100 * hundredsCount;
        int tens = 10 * tensCount;

        Player currentPlayer = Player.Ciel;
        Player currentWinner = Player.Hanako;

        boolean isLastTurn = false;

        do {
            int remainingAmount = 220;

            switch (currentPlayer) {
                case Ciel:

                if (hundreds >= 200) {
                    remainingAmount = remainingAmount - 200;
                    hundreds = hundreds - 200;
                } else if (hundreds >= 100) {
                    remainingAmount = remainingAmount - 100;
                    hundreds = hundreds - 100;
                }

                if (tens - remainingAmount >= 0) {
                    tens = tens - remainingAmount;
                    remainingAmount = 0;
                }

                break;

                case Hanako:
                if (tens >= 220) {
                    remainingAmount = 0;
                    tens = tens - 220;
                } else if ( hundreds >= 100 && tens >= 120 ) {
                    hundreds = hundreds - 100;
                    tens = tens - 120;
                    remainingAmount = 0;
                } else if ( hundreds >= 200 && tens >= 20 ) {
                    hundreds = hundreds - 200;
                    tens = tens - 20;
                    remainingAmount = 0;
                }

                break;
            }


            if (remainingAmount == 0) {
                currentWinner = currentPlayer;
                currentPlayer = currentPlayer.nextPlayer();
                remainingAmount = 220;
                isLastTurn = false;
            } else {
                isLastTurn = true;
            }


        } while( !isLastTurn );

        System.out.println(currentWinner.toString());
    }
}

