public class WordCorrection {
    public static void main(String [] args) {
        Scanner input = new Scanner(System.in);
        int n = input.nextInt();
        StringBuilder word = new StringBuilder(input.next());

        for(int i = 0; i < word.length(); i++) {
            if(isVowel(word.charAt(i)) && i != word.length() - 1 && isVowel(word.charAt(i + 1))) {
                word.deleteCharAt(i + 1);
                i = -1;
            }
        }

        System.out.println(word);
    }

    public static boolean isVowel(char character) {
        return "aeiouy".contains(String.valueOf(character));
    }
}

