class TaskA {
    public void solve(int testNumber, Scanner in, PrintWriter out) {
        long n = in.nextInt();
        long m = in.nextInt();
        long k = in.nextInt();
        if(n+m-2<k) out.print(-1);
        else{
            k++;
            out.print(Math.max(get_area(n,m,k),get_area(m,n,k)));
        }
    }
    public long get_area(long n,long m,long k){
        if(k<=n){
            return (n/k)*m;
        }
        else{
            k--;
            k-=(n-1);
            k++;
            return m/k;
        }
    }
}

