      int n = in.nextInt();
      int m = in.nextInt();

      Box[] bs = new Box[m];
      for (int i=0; i<m; i++)
         bs[i] = new Box(in.nextInt(), in.nextInt());

      Arrays.sort(bs);
      int i = m-1;
      long res = 0;
      while ((n > 0)&&(i >= 0))
