public class Solution {

    public static void solve(InputReader in, PrintWriter out, DebugWriter debug) throws IOException {
        long n = in.nextInt();
        long m = in.nextInt();
        long k = in.nextInt();

        long x = Math.max(0, m - (n - n % k) / k * (k-1) - n % k);

        long scoreNoSerial = m-x*k;
        long scoreSerial = ((pow2(x)-1)*k*2) % mod ;

        debug.println(x);
        debug.println(scoreNoSerial);
        debug.println(scoreSerial);

        out.println((scoreSerial+scoreNoSerial) % mod);
    }

    public static long mod = (long) Math.pow(10, 9)+9;


    public static long pow2(long x){
        long[] array2 = new long[64];
        array2[0] = 2;

        for (int i=1; i<array2.length; i++){
            array2[i] = (array2[i-1]*array2[i-1]) % mod;
            //System.out.println( i + ": " + array2[i]);
        }


        long ans = 1;
        String binary = Long.toBinaryString(x);
        //System.out.println("Bin: " + binary);
        for (int i=binary.length()-1; i>=0; i--){
            if (binary.charAt(i) == '1'){
                ans *= array2[binary.length()-1-i];
                ans %= mod;
            }
        }

        //System.out.println("2^" + x + "=" + ans);
        return ans;
    }


    public static void main(String[] args) throws IOException{
        InputReader in;
        PrintWriter out;
        DebugWriter debug;

