public class A {	
	BufferedReader reader;
    StringTokenizer tokenizer;
    PrintWriter out;

    int INF = Integer.MAX_VALUE/2;
    int STOP = 2000000;

    int N;
    int M;
    int I;
    int J;
    int A;
    int B;
	public void solve() throws IOException {				
		N = nextInt();
		M = nextInt();
		I = nextInt();
		J = nextInt();
		A = nextInt();
		B = nextInt();

		int ans = INF;
		ans = Math.min(ans, go(1, 1));
		ans = Math.min(ans, go(1, M));
		ans = Math.min(ans, go(N, 1));
		ans = Math.min(ans, go(N, M));

		if (ans == INF) {
			out.println("Poor Inna and pony!");
		} else {
			out.println(ans);
		}
	}

	public int go(int targetX, int targetY) {
		int curX = I;
		int curY = J;
		int ans = 0;
		while (true) {
			if (curX == targetX && curY == targetY) {
				return ans;
			}

			if (curX + A > N && curX - A < 1) {
				return INF;
			}
			if (curY + B > M && curY - B < 1) {
				return INF;
			}

			if (curX + A > N) {
				curX -= A;
			} else if(curX - A < 1) {
				curX += A;
			} else {
				if (curX <= targetX) {
					curX += A;
				} else {
					curX -= A;
				}
			}

			if (curY + B > M) {
				curY -= B;
			} else if(curY - B < 1) {
				curY += B;
			} else {
				if (curY <= targetY) {
					curY += B;
				} else {
					curY -= B;
				}
			}

			ans++;
			if (ans == STOP) {
				return INF;
			}
		}
	}


	/**
	 * @param args
	 */
	public static void main(String[] args) {
		new A().run();
	}

	public void run() {
        try {
            reader = new BufferedReader(new InputStreamReader(System.in));
            tokenizer = null;
            out = new PrintWriter(System.out);
            solve();
            reader.close();
            out.close();
        } catch (Exception e) {
            e.printStackTrace();
            System.exit(1);
        }
    }

