import java.io.*;
import java.util.Arrays;
import java.util.StringTokenizer;

public class StringPlay {
    public static final int UNREACHABLE = 1000;

    FastScanner in;
    PrintWriter out;

    public void solve() throws IOException {
        int n = in.nextInt();
        char[][] t = new char[n][n];
        for (int i = 0; i < n; i++) {
            t[i] = in.next().toCharArray();
        }

        int[] curr = new int[1 << n];
        Arrays.fill(curr, UNREACHABLE);
        curr[1 << (n - 1)] = 0;

        int[] next = new int[1 << n];
        Arrays.fill(next, UNREACHABLE);
        int[] nextMask = new int['z' - 'a' + 1];
        int[] charMasks = new int['z' - 'a' + 1];

        for (int layer = 2 * n - 2; layer > 0; layer--) {
            boolean first = layer % 2 == 0;

            Arrays.fill(charMasks, 0);
            for (int row = 0; row < n; row++) {
                int col = layer - row - 1;
                if (col >= 0 && col < n) {
                    int ch = t[row][col] - 'a';
                    charMasks[ch] += (1 << row);
                }
            }

            for (int charMask : charMasks) {
                for (int state = charMask; state > 0; state = (state - 1) & charMask) {
                    Arrays.fill(nextMask, 0);
                    char sel = 0;
                    for (int row = 0; row < n; row++) {
                        int bit = 1 << row;
                        if ((state & bit) == 0) {
                            continue;
                        }

                        int col = layer - row - 1;
                        if (col < 0 || col > n - 1) {
                            sel = 0;
                            break;
                        }

                        if (sel == 0) {
                            sel = t[row][col];
                        }
                        if (sel != t[row][col]) {
                            sel = 0;
                            break;
                        }

                        if (col < n - 1) {
                            int ch = t[row][col + 1] - 'a';
                            nextMask[ch] |= (1 << (row));
                        }
                        if (row < n - 1) {
                            int ch = t[row + 1][col] - 'a';
                            nextMask[ch] |= (1 << (row + 1));
                        }
                    }

                    if (sel == 0) {
                        continue;
                    }

                    int nonrelaxed = UNREACHABLE;
                    for (int i = 0; i < nextMask.length; i++) {
                        int mask = nextMask[i];
                        if (mask == 0) {
                            continue;
                        }

                        int add = getValue((char) ('a' + i));
                        int from = curr[mask];
                        if (from == UNREACHABLE) {
                            continue;
                        }

                        if (nonrelaxed == UNREACHABLE) {
                            nonrelaxed = from + add;
                        } else if (first) {
                            nonrelaxed = Math.max(nonrelaxed, from + add);
                        } else {
                            nonrelaxed = Math.min(nonrelaxed, from + add);
                        }
                    }
                    next[state] = nonrelaxed;
                }
            }

            int[] tmp = next;
            next = curr;
            curr = tmp;
        }

        int res = curr[1] + getValue(t[0][0]);
        if (res == 0) {
            out.println("DRAW");
        } else {
            out.println(res > 0 ? "FIRST" : "SECOND");
        }
    }

    private int getValue(char c) {
        return c != 'a' ? c == 'b' ? -1 : 0 : 1;
    }

    public void run() {
        try {
            in = new FastScanner(System.in);
            out = new PrintWriter(System.out);

            solve();

            out.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }


        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] arg) {
        new StringPlay().run();
    }
}

