class PreparingOlympiad {
    public void solve(int testNumber, InputReader in, PrintWriter out) {
        int n = in.nextInt();
        int l = in.nextInt();
        int r = in.nextInt();
        int x = in.nextInt();
        int[] c = new int[n];
        for (int i = 0; i < n; i++) c[i] = in.nextInt();
        Arrays.sort(c);
        int res = 0;
        for (int i = 1; i < (1 << n); i++) {
            int hi = Integer.highestOneBit(i);
            int lo = Integer.lowestOneBit(i);
            hi = (int)(Math.log(hi) / Math.log(2));
            lo = (int)(Math.log(lo) / Math.log(2));
            if (c[hi] - c[lo] < x) continue;
            int sum = 0;
            for (int j = 0; j < n; j++)
                if ((i & (1 << j)) != 0) sum += c[j];
            if (sum <= r && sum >= l) res ++;
        }
        out.println(res);
    }
}

