public class Main {

    static FastReader in;
    static PrintWriter out;
    static Random rand = new Random();
    static final int INF = (int) (1e9 + 10);
    static final int MOD = 998244353;
    static final int N = (int) (2e5 + 10);

    static long[] f, f1;

    static long pow(long a, long b) {
        long res = 1;
        while (b != 0) {
            if ((b & 1) == 1)
                res = (res * a) % MOD;
            a = (a * a) % MOD;
            b >>= 1;
        }
        return res;
    }

    static long C(int n, int k) {
        return f[n] * f1[k] % MOD * f1[n - k] % MOD;
    }

    static void precalc() {
        f = new long[N];
        f[0] = 1;
        for (int i = 1; i < N; i++)
            f[i] = (f[i - 1] * i) % MOD;

        f1 = new long[N];
        for (int i = 0; i < N; i++)
            f1[i] = pow(f[i], MOD - 2);
    }

    static void solve() {
        precalc();

        int n = in.nextInt();
        long k = in.nextLong();

        if (k > n - 1) {
            out.println(0);
            return;
        }
        if (k == 0) {
            out.println(f[n]);
            return;
        }

        int m = n - (int) k;

        long res = 0;
        for (int i = 0; i <= m - 1; i++) {
            long sign = i % 2 == 0 ? 1L : -1L;
            res += sign * C(m, i) * pow(m - i, n) % MOD;
            res %= MOD;
        }
        if (res < 0)
            res += MOD;

        long ans = 2L * res * C(n, m) % MOD;
        out.println(ans);
    }

