		for(int i=a+1;i<=n;i++) {
			ans=(ans*i+mod)%mod;
		}
		for(int i=1;i<=n-a;i++) {
			ans=(ans*fexp(i,mod-2)+mod)%mod;
		}
		if(k!=0) {
			ans*=2;
			ans%=mod;
		}
		out.println(ans);
		out.close();
	}
	public static long fexp(long a,long e)
	{
		if(e==0) return 1;
		long tmp = fexp(a,e/2);
		tmp = (tmp*((long)tmp))%mod;
		if(e%2==1) tmp = (tmp*((long)a))%mod;
		return tmp;
	}
}

