        int dist01 = (x[0] - x[1]) * (x[0] - x[1]) + (y[0] - y[1]) * (y[0] - y[1]),
                dist12 = (x[2] - x[1]) * (x[2] - x[1]) + (y[2] - y[1]) * (y[2] - y[1]),
                dist02 = (x[0] - x[2]) * (x[0] - x[2]) + (y[0] - y[2]) * (y[0] - y[2]);
        if (Math.min(Math.min(dist01, dist02), dist12) == 0) {
            return false;
        }
        if (dist01 * dist02 == square) {
            return true;
        }
        if (dist01 * dist12 == square) {
            return true;
        }
        if (dist02 * dist12 == square) {
            return true;
        }
        return false;
    }



