import java.lang.*;

public class Main {
    private static FastReader sc = new FastReader(System.in);
    private static OutputWriter out = new OutputWriter(System.out);

    public static void main(String[] args) {
        int n = sc.nextInt();
        int k = sc.nextInt();
        int m = sc.nextInt();
        int a = sc.nextInt();

        int[] votes = new int[n];
        int[] lastTime = new int[n];
        Arrays.fill(lastTime, -1);
        Vote[] voteInfo = new Vote[n];

        int[] arr = new int[a];
        for (int i = 0; i < a; i++) {
            arr[i] = sc.nextInt() - 1;
            votes[arr[i]]++;
            lastTime[arr[i]] = i;
        }

        for (int i = 0; i < n; i++) {
            voteInfo[i] = new Vote(votes[i], lastTime[i], i);
        }
        Arrays.sort(voteInfo);

        int[] ans = new int[n];

        if (m == a) {
            for (int i = 0; i < n; i++) {
                if (i < k && voteInfo[i].votes > 0) ans[voteInfo[i].idx] = 1;
                else ans[voteInfo[i].idx] = 3;
            }

            for (int i : ans) System.out.print(i + " ");
            System.exit(0);
        }

        for (int i = 0; i < n; i++) {
            int curr = votes[i] + (m - a);
            int more = 0;
            for (int j = 0; j < n; j++) {
                if (j != i && votes[j] >= curr) more++;
            }
            if (more >= k || curr == 0) {
                ans[i] = 3;
                continue;
            }

            int minNeeded = 0;
            curr = votes[i];
            HashSet<Integer> need = new HashSet<>();
            boolean bool = false;

            for (int j = 0; j <= Math.min(n - 1, k); j++) {
                if (voteInfo[j].idx == i) {
                    bool = true;
                    continue;
                }
                if (!bool && j == k) break;
                if (voteInfo[j].votes == curr && (voteInfo[j].lastTime > lastTime[i] || voteInfo[j].votes == 0)) {
                    minNeeded++;
                } else if (voteInfo[j].votes < curr) {
                    minNeeded += (curr - voteInfo[j].votes + 1);
                }
                need.add(j);
            }

            if (votes[i] > 0 && (minNeeded > m - a || need.size() < k)) {
                ans[i] = 1;
            } else {
                ans[i] = 2;
            }
        }

        for (int i : ans) out.print(i + " ");
        out.close();
    }
}

class Vote implements Comparable<Vote> {
    int votes, lastTime, idx;

    public Vote(int a, int b, int c) {
        votes = a;
        lastTime = b;
        idx = c;
    }

    public int compareTo(Vote that) {
        if (this.votes > that.votes) return -1;
        if (this.votes < that.votes) return +1;
        if (this.lastTime > that.lastTime) return +1;
        return -1;
    }
}

class FastReader {
    private boolean finished = false;

    private InputStream stream;
    private byte[] buf = new byte[1024];
    private int curChar;
    private int numChars;
    private SpaceCharFilter filter;

    public FastReader(InputStream stream) {
        this.stream = stream;
    }

    public int read() {
        if (numChars == -1) {
            throw new InputMismatchException();
        }
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0) {
                return -1;
            }
        }

        return buf[curChar++];
    }

    public int peek() {
        if (numChars == -1) {
            return -1;
        }
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buf);
            } catch (IOException e) {
                return -1;
            }
            if (numChars <= 0) {
                return -1;
            }
        }
        return buf[curChar];
    }

    public int nextInt() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        do {
            if (c == ',') {
                c = read();
            }
            if (c < '0' || c > '9') {
                throw new InputMismatchException();
            }
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    public long nextLong() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        long res = 0;
        do {
            if (c < '0' || c > '9') {
                throw new InputMismatchException();
            }
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    public String nextString() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        StringBuilder res = new StringBuilder();
        do {
            res.appendCodePoint(c);
            c = read();
        } while (!isSpaceChar(c));
        return res.toString();
    }

    public boolean isSpaceChar(int c) {
        if (filter != null) {
            return filter.isSpaceChar(c);
        }
        return isWhitespace(c);
    }

    public static boolean isWhitespace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    private String readLine0() {
        StringBuilder buf = new StringBuilder();
        int c = read();
        while (c != '\n' && c != -1) {
            if (c != '\r') {
                buf.appendCodePoint(c);
            }
            c = read();
        }
        return buf.toString();
    }

    public String nextLine() {
        String s = readLine0();
        while (s.trim().length() == 0)
            s = readLine0();
        return s;
    }

    public String nextLine(boolean ignoreEmptyLines) {
        if (ignoreEmptyLines) {
            return nextLine();
        } else {
            return readLine0();
        }
    }

    public BigInteger nextBigInteger() {
        try {
            return new BigInteger(nextString());
        } catch (NumberFormatException e) {
            throw new InputMismatchException();
        }
    }

    public char nextCharacter() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        return (char) c;
    }

    public double nextDouble() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        double res = 0;
        while (!isSpaceChar(c) && c != '.') {
            if (c == 'e' || c == 'E') {
                return res * Math.pow(10, nextInt());
            }
            if (c < '0' || c > '9') {
                throw new InputMismatchException();
            }
            res *= 10;
            res += c - '0';
            c = read();
        }
        if (c == '.') {
            c = read();
            double m = 1;
            while (!isSpaceChar(c)) {
                if (c == 'e' || c == 'E') {
                    return res * Math.pow(10, nextInt());
                }
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                m /= 10;
                res += (c - '0') * m;
                c = read();
            }
        }
        return res * sgn;
    }

    public boolean isExhausted() {
        int value;
        while (isSpaceChar(value = peek()) && value != -1)
            read();
        return value == -1;
    }

    public String next() {
        return nextString();
    }

    public SpaceCharFilter getFilter() {
        return filter;
    }

    public void setFilter(SpaceCharFilter filter) {
        this.filter = filter;
    }

    public interface SpaceCharFilter {
        public boolean isSpaceChar(int ch);
    }
}

class OutputWriter {
