class TaskA {
    public void solve(int testNumber, InputReader in, PrintWriter out) {
        long l = in.readInt();
        long r = in.readInt();
        long base = 1;
        while (base <= r) base *= 10;
        long m = base >> 1;
        if (m > r) m = r;
        if (m < l) m = l;
        out.println(m * reflection(m));
    }

    private long reflection(long a) {
        StringBuilder s = new StringBuilder();
        while (a > 0) {
            s.insert(0, String.valueOf(9 - a % 10));
            a /= 10;
        }
        return Long.parseLong(s.toString());
    }
}

