	boolean rcheck(int ir, int jr, int ik, int jk, int i, int j) {
		if (ir == i && jr == j)
			return false;
		if (ir == i)
			return ik != i || jk < Math.min(jr, j) || jk > Math.max(jr, j);
		if (jr == j)
			return jk != j || ik < Math.min(ir, i) || ik > Math.max(ir, i);
		return false;
	}
	boolean kcheck(int ik, int jk, int i, int j) {
		return Math.max(Math.abs(ik - i), Math.abs(jk - j)) == 1;
	}
