        long n=fr.l();
        long k=fr.l();
        long right=n;
        long left=1;
        while(left<right)
        {
            if(left/2 == right/2)
                break;
            long mid=(left+right)/2;
            long curK=0;
            long other=mid%2==0?mid-1:mid+1;
            long curK1=getK(mid,n);
            long curK2=getK(other,n);
            curK=Math.max(curK1,curK2);
            //System.err.println(mid+" "+curK);
            if(curK<k)
                right=mid-1;
            else
                left=mid+1;
        }
        //System.err.println("left="+left);
        left+=4;
        long k2=getK(left,n);
        while(k2<k || left>n) {
            --left;
            k2=getK(left,n);
        }
        pw.println(left);
        pw.flush();
        pw.close();
    }
    public static long getK(long num,long n)
    {
        long curK=0;
        long lowerBound=num;
        long upperBound=num%2==0?num+1:num;
        while(upperBound<n)
        {
            curK+=(upperBound-lowerBound)+1;
            lowerBound*=2;
            upperBound=2*upperBound+1;
        }
        curK+=Math.max((n-lowerBound)+1,0);
        return curK;
    }
}

