public class RobotSequence {
  public static void main(String[] args) {
    Scanner in = new Scanner(System.in);
	int n = in.nextInt();
	char[] commands = in.next().toCharArray();
	start(n, commands);
  }

  private static void start(int n, char[] commands) {
   	int toReturn = 0;
    int[] countsUDLR = new int[4];

    for (int i = 0; i < n - 1; i++) {
      countsUDLR = new int[4];
      countDir(commands[i], countsUDLR);

      for (int j = i + 1; j < n; j++) {
        countDir(commands[j], countsUDLR);
        if (atStart(countsUDLR)) {
          toReturn++;
        }
      }
    }

    System.out.println(toReturn);
  }

  private static void countDir(char dir, int[] counts) {
    if (dir == 'U') {
      counts[0]++;
    } else if (dir == 'D') {
      counts[1]++;
    } else if (dir == 'L') {
      counts[2]++;
    } else {
      counts[3]++;
    }
  }

  private static boolean atStart(int[] counts) {
    return counts[0] == counts[1] && counts[2] == counts[3];
  }
}

