		solve();
	}

	void solve(){
		int n=s.length();
		int[] a=new int[n];
		for(int i=0; i<n; i++){
			if(Character.isLetter(s.charAt(i))){
				a[i]=s.charAt(i)-'a';
			}else{
				a[i]=-1;
			}
		}
		LinkedList<Integer> indices=new LinkedList<Integer>();
		LinkedList<Integer> unused=new LinkedList<Integer>();
		for(int i=0; i<k; i++){
			unused.addFirst(i);
		}
		boolean ok=true;
		for(int i=0;; i++){
			int j=n-1-i;
			if(i>j){
				break;
			}
			if(a[i]==-1&&a[j]==-1){
				indices.addFirst(i);
			}else if(a[i]==-1^a[j]==-1){
				a[i]=a[j]=a[i]==-1?a[j]:a[i];
				unused.remove((Integer)a[i]);
			}else{
				ok&=a[i]==a[j];
				unused.remove((Integer)a[i]);
			}
		}
		ok&=indices.size()>=unused.size();

		for(int i : indices){
			int j=n-1-i;
			int v;
			if(unused.size()==0){
				v=0;
			}else{
				v=unused.removeFirst();
			}
			a[i]=a[j]=v;
		}
		String ans="";;
		for(int i=0; i<n; i++){
			ans+=(char)(a[i]+'a');
		}
		if(!ok){
			ans="IMPOSSIBLE";
		}
		println(ans);
	}

	void println(String s){
		System.out.println(s);
	}

	public static void main(String[] args){
		Locale.setDefault(Locale.US);
		new P059C().run();
	}
}

