    static class CTitle {
        public void solve(int testNumber, inputClass sc, PrintWriter out) {
            int n = sc.nextInt();
            StringBuilder s = new StringBuilder(sc.nextLine());
            boolean[] used = new boolean[n];
            int len = s.length();
            int nb = 0;
            for (int i = 0; i < s.length() / 2 + (len % 2 == 0 ? 0 : 1); i++) {
                if (s.charAt(i) == '?' && s.charAt(len - 1 - i) == '?') {
                    nb++;
                    continue;
                }
                if (s.charAt(i) == '?' || s.charAt(len - 1 - i) == '?') {
                    if (s.charAt(i) == '?') {
                        s.setCharAt(i, s.charAt(len - 1 - i));
                    } else {
                        s.setCharAt(len - 1 - i, s.charAt(i));
                    }
                }
                if (s.charAt(i) != s.charAt(len - 1 - i)) {
                    out.println("IMPOSSIBLE");
                    return;
                }
                used[s.charAt(i) - 'a'] = true;
            }
            int toadd = 0;
            for (int i = 0; i < n; i++) {
                if (!used[i])
                    toadd++;
            }
            if (toadd > nb) {
                out.println("IMPOSSIBLE");
                return;
            }
            int nxt = 0;
            for (; nxt < n; nxt++) {
                if (!used[nxt])
                    break;
            }
            for (int i = 0; i < s.length() / 2 + (len % 2 == 0 ? 0 : 1); i++) {
                if (s.charAt(i) == '?') {
                    if (nb > toadd) {
                        s.setCharAt(i, 'a');
                        s.setCharAt(len - 1 - i, 'a');
                        nb--;
                    } else {
                        s.setCharAt(i, (char) (nxt + 'a'));
                        s.setCharAt(len - 1 - i, (char) (nxt + 'a'));
                        nxt++;
                        while (nxt < n && used[nxt]) nxt++;
                    }
                }
            }
            out.println(s);
        }

    }

