public class B {
    static long n, k, total = 0;

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        n = in.nextLong();
        k = in.nextLong();

        total = (k - 1) * ((k - 1) + 1) / 2;
        if (n > total + 1) {
            System.out.println(-1);
        } else {
            if (n == 1) {
                System.out.println(0);
            } else if (n <= k) {
                System.out.println(1);
            } else {
                long high = k - 1, low = 1, mid = 0;
                for (int i = 0; i < 40; i++) {
                    mid = (high + low) / 2;
                    if (calculate(mid) >= n) {
                        high = mid;
                    } else {
                        low = mid;
                    }
                }

                System.out.println(high + 1);
            }
        }
    }

    private static long calculate(long x) {
        long m = (k - 1 - x);
        return (total - (m * (m + 1) / 2)) + k - x;
    }
}

