public class BPetrAndACombinationLock {
    static class Solution {
        int[]mat = {1, -1};
        //Boolean[][]dp;
        Map<String, Boolean> map;
        public void find(int[] arr) {
            map = new HashMap();
            boolean res = possible(arr, 0, 0);
            System.out.println(res==true? "YES" : "NO");
        }

        boolean possible(int[] arr, int index, int sum) {
            if(index == arr.length) {
                if(sum%360 == 0) {
                    return true;
                }
                return false;
            }

            String key = index + "/" + sum;

            if(map.containsKey(key)) return map.get(key);
            for(int i=0; i<2; i++) {
                if(possible(arr, index+1, sum+(arr[index]*mat[i]))) {
                    map.put(key, true);
                    return true;
                }
            }
            map.put(key, false);
            return false;
        }
    }

    public static void main(String[] args) {
        Solution sol = new Solution();
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] arr = new int[n];
        for(int i=0; i<n; i++) {
            arr[i] = sc.nextInt();
        }
        sol.find(arr);
    }
}

