import java.io.*;
import java.util.*;

public class Main {

	static int[][] h;

	static void getInput(Scanner sc, int n, int m) throws IOException {
		int[] g = new int[n * m + n];
		g[0] = sc.nextInt();
		h = new int[n][m];
		int x = sc.nextInt(), y = sc.nextInt(), z = sc.nextInt();
		for (int i = 1; i < g.length; i++) {
			g[i] = (int) ((g[i - 1] * 1L * x + y) % z);
		}
		for (int i = 1; i <= n; i++)
			for (int j = 1; j <= m; j++) {
				h[i - 1][j - 1] = g[(i - 1) * m + j - 1];
			}
	}

	public static void main(String[] args) throws IOException {
		Scanner sc = new Scanner();
		PrintWriter out = new PrintWriter(System.out);
		int n = sc.nextInt(), m = sc.nextInt(), a = sc.nextInt(), b = sc.nextInt();
		getInput(sc, n, m);
		int[][] mins = new int[n][m]; // mins[i][j] = min value from a[i][j] to a[i][j+b-1]
		for (int i = 0; i < n; i++) {
			SparseTable row = new SparseTable(h[i]);
			for (int j = 0; j + b <= m; j++) {
				mins[i][j] = row.query(j, j + b - 1);
			}
		}
		long ans = 0;
		for (int j = 0; j + b <= m; j++) {
			int[] x = new int[n];
			for (int i = 0; i < n; i++)
				x[i] = mins[i][j];
			SparseTable col = new SparseTable(x);
			for (int i = 0; i + a <= n; i++)
				ans += col.query(i, i + a - 1);
		}
		out.println(ans);

		out.close();

	}

	static class SparseTable {
		// table [i][j] = the index with the min value from a[j] to
		// a[j+(1<<i)-1];

		int[] log, a, table[];

		SparseTable(int[] a) {
			this.a = a;
			int n = a.length;
			log = new int[n + 1];
			for (int i = 2; i <= n; i++)
				log[i] = log[i / 2] + 1;
			table = new int[log[n] + 1][n];
			for (int i = 0; i < n; i++)
				table[0][i] = i;
			for (int i = 1, len = 2; len <= n; i++, len <<= 1)
				for (int j = 0; j + len <= n; j++) {
					int u = table[i - 1][j], v = table[i - 1][j + len / 2];
					table[i][j] = a[u] < a[v] ? u : v;
				}

		}

		int query(int l, int r) {
			int len = r - l + 1;
			int lg = log[len];
			int u = table[lg][l];
			int v = table[lg][r - (1 << lg) + 1];
			int bestIdx = a[u] < a[v] ? u : v;
			return a[bestIdx]; // return a[bestIdx] for value
		}

	}

	static class Scanner {
		BufferedReader br;
		StringTokenizer st;

		Scanner() {
			br = new BufferedReader(new InputStreamReader(System.in));
		}

		Scanner(String fileName) throws FileNotFoundException {
			br = new BufferedReader(new FileReader(fileName));
		}

		String next() throws IOException {
			while (st == null || !st.hasMoreTokens())
				st = new StringTokenizer(br.readLine());
			return st.nextToken();
		}

		String nextLine() throws IOException {
			return br.readLine();
		}

		int nextInt() throws IOException {
			return Integer.parseInt(next());
		}

		long nextLong() throws NumberFormatException, IOException {
			return Long.parseLong(next());
		}

		double nextDouble() throws NumberFormatException, IOException {
