public class CFD {

    BufferedReader br;
    PrintWriter out;
    StringTokenizer st;
    boolean eof;
    private static long MOD = 1000L * 1000L * 1000L + 7;
    private static final int[] dx = {0, -1, 0, 1};
    private static final int[] dy = {1, 0, -1, 0};
    private static final String yes = "Yes";
    private static final String no = "No";

    int n;
    int m;
    int a;
    int b;
    int LIMIT = 1000 * 1000 + 10;
    long[] fact;
    long[] invfact;
    long[] powN;
    long[] powM;
    void solve() throws IOException {
        n = nextInt();
        m = nextInt();
        a = nextInt();
        b = nextInt();

        fact = new long[LIMIT];
        invfact = new long[LIMIT];
        fact[0] = 1;
        for (int i = 1; i < LIMIT; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }

        invfact[LIMIT - 1] = powMod(fact[LIMIT - 1], MOD - 2, MOD);
        for (int i = LIMIT - 2; i >= 0; i--) {
            invfact[i] = invfact[i + 1] * (i + 1) % MOD;
        }

        powN = new long[LIMIT];
        powM = new long[LIMIT];
        powN[0] = 1;
        powM[0] = 1;
        for (int i = 1; i < LIMIT; i++) {
            powN[i] = n * powN[i - 1] % MOD;
            powM[i] = m * powM[i - 1] % MOD;
        }

        long res = 0;
        for (int i = 0; i <= Math.min(m - 1, n - 2); i++) {
            int left = n - (i + 2);
            // (n - i - 1) * (n - i) *...* (n - 2)
            long extra = fact[n - 2] * invfact[n - i - 2] % MOD;
            extra *= comb(m - 1, i);
            extra %= MOD;
            extra *= caley(n, i + 2);
            extra %= MOD;
            extra *= powM[left];
            extra %= MOD;
            res += extra;
            if (res >= MOD) {
                res -= MOD;
            }

            if (res >= MOD) {
                res -= MOD;
            }
        }

        outln(res % MOD);
    }

    long caley(int n, int k) {
        if (k >= n) {
            return 1;
        }
        return k * powN[n - k - 1] % MOD;
    }

    long comb(int n, int r) {
        long res = fact[n] * invfact[r] % MOD;
        res = res * invfact[n - r] % MOD;
        return res;
    }

    // return 1/a module MOD, which is a ^ (MOD - 2) % MOD
    long inverseMod(long a, long MOD) {
        return powMod(a, MOD - 2, MOD);
    }

    // Power Calculate N^M % MOD, N and M can be long (up to 2^64, ~10^18)
    public long powMod(long N, long M, long MOD){//N^M % MOD
        if(M == 0L)
            return 1L;
        long[] hp = new long[64];
        boolean[] bp = new boolean[64];
        hp[0] = N;
        for(int i = 1; i < hp.length; i++) {
            hp[i] = (hp[i - 1] * hp[i - 1]) % MOD;
        }
        for(int j = 0; j < hp.length; j++) {
            if((M & (1L << j)) != 0)
                bp[j] = true;
        }
        long res = 1;
        for(int i = 0;i < bp.length; i++){
            if(bp[i]) {
                res = (res * hp[i]) % MOD;
            }
        }
        return res;
    }

    void shuffle(int[] a) {
        int n = a.length;
        for(int i = 0; i < n; i++) {
            int r = i + (int) (Math.random() * (n - i));
            int tmp = a[i];
            a[i] = a[r];
            a[r] = tmp;
        }
    }
    long gcd(long a, long b) {
        while(a != 0 && b != 0) {
            long c = b;
            b = a % b;
            a = c;
        }
        return a + b;
    }
    private void outln(Object o) {
        out.println(o);
    }
    private void out(Object o) {
        out.print(o);
    }
    private void formatPrint(double val) {
        outln(String.format("%.9f%n", val));
    }
    public CFD() throws IOException {
        br = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(System.out);
        solve();
        out.close();
    }
    public static void main(String[] args) throws IOException {
        new CFD();
    }

