import java.util.Scanner;

public class C {
    static long factorial[] = new long[(int) 2e5 + 3];
    static long inverseFactorial[] = new long[(int) 2e5 + 3];
    static int MOD = (int) 1e9 + 7;

    public static void main(String[] args) {
        factorial[0] = 1;
        inverseFactorial[0] = 1;
        for (int i = 1; i <= (int) 2e5; i++) {
            factorial[i] = mul(factorial[i - 1], i);
            inverseFactorial[i] = binpow(factorial[i], MOD - 2);
        }
        Scanner scn = new Scanner(System.in);
        int test = scn.nextInt();
        while (test-- > 0) {
            int n = scn.nextInt();
            int k = scn.nextInt();
            long[] dp = new long[k + 1];
            dp[k] = 1;
            long equal = 0;
            long moreThan = 0;
            if (n % 2 != 0)
                equal = 1l;
            else moreThan = 1l;
            for (int i = 0; i < n; i += 2) {
                equal = add(equal, nCr(n, i));
            }

            for (int i = k - 1; i >= 0; i--) {
                dp[i] = mul(equal, dp[i + 1]);
                dp[i] = add(dp[i], mul(moreThan, binpow(2, 1l*n * (k - i - 1))));
            }
            System.out.println(dp[0]);
        }

    }

    static long add(long a, long b) {
        if ((a += b) >= MOD)
            a -= MOD;
        else if (a < 0)
            a += MOD;
        return a;
    }

    static long mul(long x, long y) {
        return (1L * x * y) % MOD;
    }

    static long nCr(int n, int r) {
        if (r > n)
            return 0;
        return mul(mul(factorial[n], inverseFactorial[r]), inverseFactorial[n - r]);
    }


    public static long binpow(long x, long n) {
        assert (n >= 0);
        x %= MOD;  // note: MOD * MOD must be less than 2^63 to avoid ll overflow
        long res = 1;
        while (n > 0) {
            if (n % 2 == 1)  // if n is odd
                res = res * x % MOD;
            x = x * x % MOD;
            n /= 2;  // divide by two
        }
        return res;
    }
}

