import static java.lang.Math.*;

public class Sol implements Runnable {
	final long MOD = 1000000007;
	long half = (MOD + 1) / 2;

	void solve() throws Exception {
		int L = nextInt(), R = nextInt();
		long ans = ((getGoodAll(R) - getGoodAll(L - 1) + MOD) * half) % MOD;
		out.println(ans);
	}

	long getAll(int R) {
		long res = get(1);
		if (R == 1) return res;
		res += 2 * getK(R) + 4 * getK(1);
		res %= MOD;
		long add1 = R >= 3 ? 6 * (mpow(3, (R - 1) / 2) - 1) : 0;
		long add2 = R >= 4 ? 3 * (mpow(3, R / 2) - 3) : 0;
		return (res + add1 + add2) % MOD;	
	}

	long getGoodAll(int R) {
		if (R == 0) return 0;
		long res = getAll(R);
		res += getAll((R + 1) / 2);
		return res % MOD;
	}

	long get(int n) {
		return 2 * getK(n) + 2 * getY(n);
	}

	long getY(int n) {
		return n == 1 ? 1 : 2 * getK(n - 1);
	}

	long getK(int n) {
		if (n % 2 == 0) {
			return (2 * mpow(3, n / 2 - 1)) % MOD;
		} else {
			return mpow(3, n / 2);
		}
	}

	long mpow(long a, long n) {
		if (n == 0) return 1;
		long ans = mpow(a, n / 2);
		ans = (ans * ans) % MOD;
		if (n % 2 == 1) {
			ans = (ans * a) % MOD;
		}
		return ans;
	}


	public static void main(String[] args) {
		new Thread(new Sol()).start();
	}

	public void run() {
		try {
			Locale.setDefault(Locale.US);
			in = new BufferedReader(new InputStreamReader(System.in));
			out = new PrintWriter(System.out);
			solve();

			out.close();
		} catch (Exception e) {
			e.printStackTrace();
			System.exit(1);
		}
	}


