		}

		static long gcd(long a, long b)
		{
		    while (b > 0)
		    {
		        long temp = b;
		        b = a % b; // % is remainder
		        a = temp;
		    }
		    return a;
		}
		static long modulo(long a,long b,long c) {
			long x=1;
			long y=a;
			while(b > 0){
				if(b%2 == 1){
					x=(x*y)%c;
				}
				y = (y*y)%c; // squaring the base
				b /= 2;
			}
			return  x%c;
		}
		public static void debug(Object... o) {
			System.out.println(Arrays.deepToString(o));
		}

		static long sort(int a[]) {
			int n = a.length;
			int b[] = new int[n];
			return mergeSort(a, b, 0, n - 1);
		}

		static long mergeSort(int a[], int b[], long left, long right) {
			long c = 0;
			if (left < right) {
				long mid = left + (right - left) / 2;
				c = mergeSort(a, b, left, mid);
				c += mergeSort(a, b, mid + 1, right);
				c += merge(a, b, left, mid + 1, right);
			}
			return c;
		}

		static long merge(int a[], int b[], long left, long mid, long right) {
			long c = 0;
			int i = (int) left;
			int j = (int) mid;
			int k = (int) left;
			while (i <= (int) mid - 1 && j <= (int) right) {
				if (a[i] <= a[j]) {
					b[k++] = a[i++];
				} else {
					b[k++] = a[j++];
					c += mid - i;
				}
			}
			while (i <= (int) mid - 1)
				b[k++] = a[i++];
			while (j <= (int) right)
				b[k++] = a[j++];
			for (i = (int) left; i <= (int) right; i++)
				a[i] = b[i];
			return c;
		}  


		static final class InputReader{
			private final InputStream stream;
			private final byte[] buf=new byte[1024];
			private int curChar;
			private int numChars;
			public InputReader(InputStream stream){this.stream=stream;}
			private int read()throws IOException{
				if(curChar>=numChars){
					curChar=0;
					numChars=stream.read(buf);
					if(numChars<=0)
						return -1;
				}
				return buf[curChar++];
			}
			public final int nextInt()throws IOException{return (int)nextLong();}
			public final long nextLong()throws IOException{
				int c=read();
				while(isSpaceChar(c)){
					c=read();
					if(c==-1) throw new IOException();
				}
				boolean negative=false;
				if(c=='-'){
					negative=true;
					c=read();
				}
				long res=0;
				do{
					if(c<'0'||c>'9')throw new InputMismatchException();
					res*=10;
					res+=(c-'0');
					c=read();
				}while(!isSpaceChar(c));
				return negative?(-res):(res);
			}
			public final int[] readIntBrray(int size)throws IOException{
				int[] arr=new int[size];
				for(int i=0;i<size;i++)arr[i]=nextInt();
				return arr;
			}
			public final String next()throws IOException{
				int c=read();
				while(isSpaceChar(c))c=read();
				StringBuilder res=new StringBuilder();
				do{
					res.append((char)c);
					c=read();
				}while(!isSpaceChar(c));
				return res.toString();
			}
			public final String nextLine()throws IOException{
				int c=read();
				while(isSpaceChar(c))c=read();
				StringBuilder res=new StringBuilder();
				do{
					res.append((char)c);
					c=read();
				}while(c!='\n'&&c!=-1);
				return res.toString();
			}
			private boolean isSpaceChar(int c){
				return c==' '||c=='\n'||c=='\r'||c=='\t'||c==-1;
			}
		}
	}

