    static class Task {
        public void solve(InputReader in, PrintWriter out) {
            double l = in.nextInt();//2 5
            double d = in.nextInt();//1 4
            double v = in.nextInt();//3 3
            double g = in.nextInt();//4 1
            double r = in.nextInt();//5 1
