public class StringTyping {

	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);
		int n = scan.nextInt();
		String s = scan.next();
		int ans = 0;
		boolean bal = false;
		for(int i = n-1; i >= 0; i += 0){
			if(i % 2 == 1 && !bal){
				int mid = i/2;
				String a = s.substring(0, mid+1);
				String b = s.substring(mid+1, i+1);
				if(a.equals(b)){
				    bal = true;
					ans++;
					i /= 2;
					continue;
				}
			}
			ans++;
			i--;
		}
		System.out.println(ans);
	}
}

