/**
 * <a href="http://codeforces.com/contest/1040/problem/A">1040A</a>
 */
public class _1040A {
	public static void main(String[] args) throws Exception {
		BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
		int[] array = convert(reader.readLine());
		int n = array[0];

		int[] c = new int[]{array[1], array[2]};

		int[] a = convert(reader.readLine());
		int sum = 0;
		for (int i = 0; i < n / 2; i++) {
			int first = a[i];
			int last = a[n - i - 1];

			if (first == last) {
				if (first == 2) {
					sum += 2 * Math.min(array[1], array[2]);
				}
				continue;
			}
			if (first == 2 || last == 2) {
				int min = Math.min(first, last);
				sum += c[min];
			} else {
				System.out.println(-1);
				return;
			}
		}
		if ((n % 2 != 0 || n < 2) && a[n / 2] == 2) {
			sum += Math.min(array[1], array[2]);
		}
		System.out.println(sum);
	}

	private static int[] convert(String s) {
		return Arrays.stream(s.split(" ")).mapToInt(Integer::valueOf).toArray();
	}
}

