public class C774E {

    static StringBuffer ans1 = new StringBuffer("");
    static FastScanner sc = new FastScanner();
    static PrintWriter printWriter = new PrintWriter(System.out);

    public static void solve(int n, int m) {
        int depth = 0, temp = n;
        while(temp > 1) {
            temp /= 2;
            depth++;
        }
        int[] dp = new int[depth + 1];
        boolean[] visited = new boolean[m * depth + 1];
        int size = 0;
        for (int i = 1; i <= depth; i++) {
            for(int j = 1; j <= m; j++) {
                if(!visited[i * j]) size++;
                visited[i * j] = true;
            }
            dp[i] = size;
        }
        long res = 1;
        boolean[] used = new boolean[n + 1];
        for(int i = 2; i <= n; i++) {
            if(used[i]) continue;
            int k = i, count = 0;
            while(k <= n) {
                used[k] = true;
                count++;
                if(k * 1L * i != k * i) break;
                k *= i;
            }
            res += dp[count];
        }
        printWriter.println(res);
    }

    public static void main(String[] args) {
        int n = sc.nextInt();
        int m = sc.nextInt();
        solve(n, m);
        printWriter.flush();
    }


