import java.io.*;
import java.util.*;
import java.math.*;

import static java.lang.Math.*;

public class Main implements Runnable {

	//«2», «3», «4», «5», «6», «7», «8», «9», «T», «J», «Q», «K», «A».

	class Triplet {
		String card1, card2, card3;

		public Triplet(String card1, String card2, String card3) {
			this.card1 = card1;
			this.card2 = card2;
			this.card3 = card3;
		}

		@Override
		public boolean equals(Object obj) {
			if (obj instanceof Triplet) {
				Triplet t = (Triplet)obj;
				return this.card1.equals(t.card1) && this.card2.equals(t.card2) && this.card3.equals(t.card3);
			} else {
				return false;
			}
		}

		@Override
		public int hashCode() {
			final int prime = 31;
			return card1.hashCode() + prime * (card2.hashCode() + prime * card3.hashCode());
		}
	}

	boolean mayPutOn(String top, String bottom) {
		return top.charAt(0) == bottom.charAt(0) || top.charAt(1) == bottom.charAt(1);
	}

	void solve() throws Exception {
		int n = sc.nextInt();
		String[] cards = new String[n];
		for (int i = 0; i < n; i++) {
			cards[i] = sc.nextToken();
		}
		if (n == 1 || n == 2 && mayPutOn(cards[1], cards[0])) {
			out.println("YES");
			return;
		}
		if (n == 1 || n == 2) {
			out.println("NO");
			return;
		}
		HashSet<Triplet>[] dp = new HashSet[n];
		for (int i = 0; i < n; i++) {
			dp[i] = new HashSet<Triplet>();
		}
		dp[n - 1].add(new Triplet(cards[n - 1], cards[n - 2], cards[n - 3]));
		for (int i = n - 1; i >= 3; i--) {
			for (Triplet t : dp[i]) {
				if (mayPutOn(t.card1, cards[i - 3])) {
					dp[i - 1].add(new Triplet(t.card2, t.card3, t.card1));
				}
				if (mayPutOn(t.card1, t.card2)) {
					dp[i - 1].add(new Triplet(t.card1, t.card3, cards[i - 3]));
				}
			}
		}
		for (Triplet t : dp[2]) {
			if (mayPutOn(t.card1, t.card2) && mayPutOn(t.card1, t.card3)) {
				out.println("YES");
				return;
			}
		}
		out.println("NO");
	}

	BufferedReader in;
	PrintWriter out;
	FastScanner sc;

	static Throwable uncaught;

	@Override
	public void run() {
		try {
			in = new BufferedReader(new InputStreamReader(System.in));
			out = new PrintWriter(System.out);
			sc = new FastScanner(in);
			solve();
		} catch (Throwable t) {
			Main.uncaught = t;
		} finally {
			out.close();
		}
	}

	public static void main(String[] args) throws Throwable {
		Thread t = new Thread(null, new Main(), "", 128 * 1024 * 1024);
		t.start();
		t.join();
		if (uncaught != null) {
			throw uncaught;
		}
	}

}

