	static int binary(int x, int y){
	//	System.out.println("binary on "+x+","+y);
		if(x==y) return isOk(x)? x: -1;
		if(y==x+1) return isOk(x)? x: isOk(y)? y: -1;
		int m = (x+y)>>1;
		return isOk(m)? binary(x, m): binary(m+1, y);
	}


	static boolean isOk(int sz){
		size = sz;
		curIter++;
		fal++;
		boolean b = canGet(1);
		//System.out.println(sz+" "+b);
		return b;
	}

