	static boolean canGet(int mask){
	//	System.out.println(mask+" "+cur);
	//	if(cur==n) System.out.println("OH YEAH");
		int cur = -1;
		for(int i=n; i>=0; i--){
			if((mask&(1<<i))!=0){
				cur = i;
				break;
			}
		}
		cur++;
	//	System.out.println(mask+" "+cur);
		if(cur==n) return true;
		if(dp[mask]==curIter || dp[mask]==fal) return dp[mask]==curIter;
		if(!can(mask, a[cur])){
			dp[mask] = fal;
			return false;
		}
		int M = mask;
		if(Integer.bitCount(mask)+1<=size){
	//		System.out.println(Integer.bitCount(mask)+" "+size+" calling");
			if(canGet((M^(1<<cur)))){
				dp[mask] = curIter;
				return true;
			}
		}
		for(int i=0; i<cur; i++){
			M = mask;
			if((M&(1<<i))!=0){
				M ^= (1<<i);
				M ^= (1<<cur);
				if(canGet(M)){
					dp[mask] = curIter;
					return true;
				}
			}
		}
		dp[mask] = fal;
		return false;
	}

	static boolean can(int mask, int sum){
		HashSet<Integer> set = new HashSet<Integer>();
		for(int s=0; s<n; s++) if((mask&(1<<s))!=0){
			set.add(a[s]);
