public class Main {
	public static void main(String[] args) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		Scanner in = new Main().new Scanner(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		Main solver = new Main();
		solver.solve(1, in, out);
		out.close();
	}

	// prefix sum
	public void solve(int testNumber, Scanner in, PrintWriter out) {
		char[] s1 = in.readLine().toCharArray();
		char[] s2 = in.readLine().toCharArray();

		int s1p = 0, s1m = 0, s2p = 0, s2m = 0, q = 0;
		for(int i = 0; i < s1.length; i++) {
			if(s1[i] == '+') s1p++;
			else if (s1[i] == '-') s1m++;
			if(s2[i] == '+') s2p++;
			else if (s2[i] == '-') s2m++;
			else q++;
		}
		int p = s1p - s2p;
		int m = s1m - s2m;
		if(Math.abs(p) + Math.abs(m) != q) {
			out.println(0);
		} else {
			long num = fact(p + m) / (fact(p) * fact(m));
			long den = (long) Math.pow(2, p + m);
			double ans = num * 1.0 / den;
			out.println(ans);
		}
	}

	public long fact(int n) {
		long ret = 1;
		for(int i = 1; i <= n; i++) ret *= i;
		return ret;
	}

	class Scanner {

		BufferedReader br;
		StringTokenizer in;

		public Scanner(InputStream inputStream) {
			br = new BufferedReader(new InputStreamReader(inputStream));
		}

		public String next() {
			return hasMoreTokens() ? in.nextToken() : null;
		}

		public String readLine() {
			try {
				return br.readLine();
			} catch (Exception e) {
				e.printStackTrace();
				return null;
			}
		}

		boolean hasMoreTokens() {
			while (in == null || !in.hasMoreTokens()) {
				String s = readLine();
				if (s == null)
					return false;
				in = new StringTokenizer(s);
			}
			return true;
		}

		public String ns() {
			return next();
		}

		public int ni() {
			return Integer.parseInt(ns());
		}

		public long nl() {
			return Long.parseLong(ns());
		}

		public int[] nextIntArray(int n) {
			int[] a = new int[n];
			for (int i = 0; i < n; i++) {
				a[i] = ni();
			}
			return a;
		}

		public long[] nextLongArray(int n) {
			long[] a = new long[n];
			for (int i = 0; i < n; i++) {
				a[i] = nl();
			}
			return a;
		}
	}
}

