		int[] bit = new int[128];
		while (nn >= 1) {
			bit[len] = (int)(nn % 2);
			nn /= 2L;
			len++;
		}

		long[][][] dp = new long[len+1][fc+1][3];
		dp[0][fc][0] = 1;
		for (int i = 0 ; i < len ; i++) {
			for (int f = 0 ; f <= fc ; f++) {
				for (int c = 0 ; c <= 2 ; c++) {
					if (dp[i][f][c] == 0) {
						continue;
					}
					long base = dp[i][f][c];
					if (bit[i] == 0) {
						// use one
						if (f >= 1) {
							dp[i+1][f-1][1] += base;
						}

						// use zero
						dp[i+1][f][c] += base;
					} else {
						// use one
						if (f >= 1) {
							dp[i+1][f-1][c] += base;
						}

						// use zero
						dp[i+1][f][2] += base;
					}
				}
			}
		}

		long ans = dp[len][0][2] + dp[len][0][0];
		if (t == 1) {
			ans--;
		}
		out.println(ans);
		out.flush();
	}

	public static long[][] generate(int m ){
		long[][] a = new long[m+2][m+2];
		a[1][m+1] = 1;
		for (int i = 2 ; i <= m + 1 ; i++) {
			for (int j = 1 ; j <= m + 1 ; j++) {
				if (j == 1) {
					a[i][j] = a[i-1][j+1];
				} else {
					if (j == m + 1) {
						a[i][j] = a[i-1][j-1];
					} else {
						a[i][j] = a[i-1][j-1] ^ a[i-1][j+1];
					}
				}
			}
		}
		return a;
	}


