import java.util.Scanner;

public class TaskB {

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        String x = in.nextLine();
        String result = computeMaxDigitSumNumber(x);
        System.out.println(result);
    }

    static String computeMaxDigitSumNumber(String x) {
        int len = x.length();
        if (len == 1) {
            return x;
        }
        int firstDigit = Character.getNumericValue(x.charAt(0));
        int secondDigit = Character.getNumericValue(x.charAt(1));
        String nines = repeatChar('9', len - 2);
        String xPostfix = x.substring(2);
        boolean endToNines = xPostfix.equals(nines);
        if (secondDigit < 8 || secondDigit == 8 && !endToNines) {
            return (firstDigit == 1 ? "" : firstDigit - 1) + "9" + nines;
        } else if (endToNines) {
            return x;
        } else {
            String newXPostfix = computeMaxDigitSumNumber(xPostfix);
            newXPostfix = fillZerosToLen(newXPostfix, len - 2);
            if (computeDigitSum(newXPostfix) >= 9 * (len - 2) - 1) {
                return firstDigit + "" + secondDigit + newXPostfix;
            } else {
                return (firstDigit * 10 + secondDigit - 1) + nines;
            }
        }
    }

    private static int computeDigitSum(String x) {
        int digitSum = 0;
        for (int i = 0; i < x.length(); ++i) {
            digitSum += x.charAt(i) - '0';
        }
        return digitSum;
    }

    private static String repeatChar(char c, int count) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < count; ++i) {
            sb.append(c);
        }
        return sb.toString();
    }

    private static String fillZerosToLen(String x, int len) {
        return repeatChar('0', len - x.length()) + x;
    }

}

