            }
            for (int i = 0; i < temp.length; i++)
                for (int j = 0; j < temp.length; j++) {
                    if (i == j)
                        continue;
                    long[] temp2 = new long[temp.length - 1];
                    if (S[4 - temp.length].equals("*"))
                        temp2[0] = temp[i] * temp[j];
                    else
                        temp2[0] = temp[i] + temp[j];
                    int c = 1;
                    for (int k = 0; k < temp.length; k++)
                        if (k != i && k != j)
                            temp2[c++] = temp[k];
                    Q.add(temp2);
                }
        }
        System.out.println(min);
    }
