public class cf109b {
	static ArrayList<Long> lucky = new ArrayList<Long>();
	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		genLucky(0,11);
		Collections.sort(lucky);
		long pl = in.nextLong();
		long pr = in.nextLong();
		long vl = in.nextLong();
		long vr = in.nextLong();
		int k = in.nextInt();
		double ret = 0;
		for(int i=0; i<lucky.size()-k-2; i++) {
			//assume p is lower
			//probability that p got in the interval (lucky[i],lucky[i+1]]
			long lo = Math.max(lucky.get(i)+1, pl);
			long hi = Math.min(lucky.get(i+1), pr);
			double p = Math.max(0,(hi-lo+1.)/(pr-pl+1));
			//probability that v got in the interval [lucky[i+k],lucky[i+k+1)
			lo = Math.max(lucky.get(i+k),vl);
			hi = Math.min(lucky.get(i+k+1)-1,vr);
			double v = Math.max(0,(hi-lo+1.)/(vr-vl+1));
			ret += p*v;

			//assume v is lower
			//probability that v got in the interval (lucky[i],lucky[i+1]]
			lo = Math.max(lucky.get(i)+1, vl);
			hi = Math.min(lucky.get(i+1), vr);
			v = Math.max(0,(hi-lo+1.)/(vr-vl+1));
			//probability that p got in the interval [lucky[i+k],lucky[i+k+1)
			lo = Math.max(lucky.get(i+k),pl);
			hi = Math.min(lucky.get(i+k+1)-1,pr);
			p = Math.max(0,(hi-lo+1.)/(pr-pl+1));
			ret += p*v;

			//remove double counting (probability they got the same)
			if(k==1) {
				lo = Math.max(lucky.get(i), vl);
				hi = Math.min(lucky.get(i), vr);
				v = Math.max(0,(hi-lo+1.)/(vr-vl+1));
				lo = Math.max(lucky.get(i),pl);
				hi = Math.min(lucky.get(i),pr);
				p = Math.max(0,(hi-lo+1.)/(pr-pl+1));
				ret -= p*v;
			}
		}
		System.out.printf("%.12f%n", ret);
	}
