class AC {
    int n , m;
    boolean judge(int x,int y) {
        return 1<=x && x <= n && 1 <= y && y <= m;
    }
    int x , y  , dx , dy;
    long  go() 
    {
         int delta;
         if(dx < 0) {
             if(dy < 0)  {
                 delta = Math.min(x-1, y-1);
             } else {
                 delta = Math.min(m-y, x-1);
             }
         } else {
             if(dy < 0) {
                 delta = Math.min(n-x, y-1);
             } else {
                 delta = Math.min(n-x,m-y);
             }
         }
         x += dx * delta;
         y += dy * delta;
         if(x+dx<1 || x+dx>n) dx *= -1;
         if(y+dy<1 || y+dy>m) dy *= -1;
         return (long)x*dx*1000000 + y*dy;
    }
    public void solve(InputReader in, PrintWriter out) {
          int x0 , y0;
          String cmd;
          HashSet<Long> mp = new HashSet<Long>();
          HashSet<Long> M = new HashSet<Long>();
          n = in.nextInt();
          m = in.nextInt();
          x0 = in.nextInt(); y0 = in.nextInt();
          cmd = in.next();
          int tot = n + m - 2;
          if(cmd.charAt(0)=='D') {
              dx = 1;
          } else dx = -1;
          if(cmd.charAt(1)=='R') {
              dy = 1;
          } else dy = -1;
          long  ans = 1;
          x = x0 ; y = y0;
          if(x0==1 || x0==n || y0==1 || y0==m){
              M.add((long)x0*1000000+y0);
              tot --;
          }
          while(true) {
              long  tmp = go();
              if(mp.contains(tmp)){
                 ans = -1;
                 break;
              } else {
                  mp.add(tmp);
              }
              ans += Math.abs(x - x0);
              //out.println(x+" "+y);
              x0 = x ; y0 = y ;

              long flag = (long)x0*1000000+y0;
              if(!M.contains(flag)) {
                // out.println(tot);
                  M.add(flag);
                  if(--tot == 0) break;
              }
          }
          out.println(ans);
    }
}
