import java.util.Scanner;

public class ER82_D {
	private static final int N = 200001;
	private static final int MOD = 998244353;

	public static void main(String[] args) {
		int[] fact = new int[N];
		fact[0] = 1;
		for (int i = 1; i < N; i++) {
			fact[i] = mul(fact[i-1], i);
		}

		Scanner in = new Scanner(System.in);
		int n = in.nextInt();
		int m = in.nextInt();

		int ans = 0;

		if (n > 2) {
			ans = mul(C(m, n-1, fact), mul(n - 2, binpow(2, n - 3)));
		}
		System.out.println(ans);
	}

	private static int add(int x, int y) {
		x += y;

		return x % MOD;

	}

	private static int mul(int x, int y) {
		int res = (int) (((long) x * y) % MOD);
		return res;

	}

	private static int binpow(int x, int y) {
		int z = 1;
		while (y > 0) {
			if (y % 2 != 0)
				z = mul(z, x);
			x = mul(x, x);
			y >>= 1;
		}
		return z;
	}

	private static int inv(int x) {
		return binpow(x, MOD - 2);
	}

	private static int devide(int x, int y) {
		return mul(x, inv(y));
	}

	private static int C(int n, int k, int[] fact) {
		return devide(fact[n], mul(fact[k], fact[n-k]));
	}
}

