    static ArrayList<Long> sieveOfEratosthenes() {
        int n = 1000000;
        ArrayList<Long> list = new ArrayList<>();
        boolean[] prime = new boolean[n];

        for(int p = 2; p*p <n; p++) {
            if(!prime[p]) {
                for(int i = p*p; i < n; i += p)
                    prime[i] = true;
            }
        }

        for(int i = 2; i < n; i++) {
            if(!prime[i]) {
                list.add((long) i);
            }
        }
        return list;
    }
