    static void update(int v, int tl, int tr, int l, int r, long val) {
        if(tl>r||tr<l)
            return;
        if(tl>=l&&tr<=r){
            max[v] = Math.max(val, max[v]);
            return;
        }
        int tm = ((tl + tr) >> 1);
        update(v*2, tl, tm, l, r, val);
        update(v*2+1, tm+1, tr, l, r, val);
        max[v] = Math.max(max[2*v],max[2*v+1]);
    }

