	static int factorial(int n)
	{
		if(n == 0) return 1;
		return n * factorial(n - 1);
	}

	static int[] permutar(boolean[] usados, int[] numeros, int n, int k)
	{
		if(n == usados.length)
			return numeros;
		int faltantes = usados.length - n;
		int sigFact = factorial(faltantes - 1);
		for(int i = 0; i < usados.length; i++)
		{
			if(!usados[i])
			{
				if(sigFact >= k)
				{
					usados[i] = true;
					numeros[n] = i;
					return permutar(usados, numeros, n + 1, k);
				}
				else
					k -= sigFact;
			}
		}
		return null;
	}

	static int contarHasta(int n) 
	{
		int cuenta = 0;
		for(int i = 1; i < 10; i++)
		{
			int limite = 1 << i;
			for(int j = 0; j < limite; j++)
			{
				char[] val = new char[i];
				for(int k = 0; k < i; k++)
				{
					if((j & (1 << k)) != 0)
						val[k] = '4';
					else
						val[k] = '7';
				}
				if(Integer.parseInt(new String(val)) <= n)
					cuenta++;
			}
		}
		return cuenta;
	}

	static boolean esLucky(int j) 
	{
		for(char c : (j + "").toCharArray())
			if(c != '4' && c != '7')
				return false;
		return true;
	}

