			int total = contarHasta(n - 13);
			int[] vals = permutar(new boolean[13], new int[13], 0, k);
			for(int i = 0; i < 13; i++) vals[i] += n - 12;
			for(int i = 0, j = n - 12; i < 13; i++, j++)
				if(esLucky(vals[i]) && esLucky(j)) total++;
			System.out.println(total);
