         mergedSortedArray= new ArrayList<Integer>();

		 int rightIndex ;
        rightIndex= midind+1;

        int leftIndex ;
        leftIndex= startind;


        while(midind>=leftIndex && endind>=rightIndex){
            if(arr.get(leftIndex)<=arr.get(rightIndex)){
                mergedSortedArray.add(arr.get(leftIndex));
                leftIndex++;
            }else{
