	public static void main(String[] args) throws IOException {
		FastReader in = new FastReader(System.in);
		PrintWriter out = new PrintWriter(System.out);
		int n = in.nextInt();
		int m = in.nextInt();
		int f = 0;
		int c = 0;
		int x = 1;
		while (true) {
			if (x < n) {
				if (x != 1) {
					--f;
				}
				int max = m - f;
				f += max;
				c += (x * (max));
				if (x + f == n) {
					break;
				} else if (x + f > n) {
					int y = (x + f) - n;
					c -= (y * x);
					break;
				}
				++x;
			}
		}
		out.println(c);
		out.flush();
		out.close();

	}

