		public int[] key = null;
		public double factor = 0.7;
		public int size = 0;
		public int init = 16;
		public IntSet(){
			used  = new boolean[init];
			key = new int[init];
		}
		public void rehash(){
			int newlen = (key.length<<1)+1;
			boolean[] oldused = used;
			int[] oldkey = key;
			used = new boolean[newlen];
			key = new int[newlen];
			size = 0;
			for (int i = 0; i < oldused.length; i++){
				if (oldused[i]){
					add(oldkey[i]);
				}
			}
		}
		public int idx(int key1){
			int id = hash(key1);
			if (id < 0) id *= -1;
			id %= key.length;
			for (int i = 0; ; i++){
				int add = i*i;
				if (add < 0) add *= -1;
				id += add;
				id %= key.length;
				if (used[id]){
					if (key[id] == key1){
						return id;
					}
				}
				else {
					return id;
				}
			}
		}

		public void add(int key1){
			int id = idx(key1);
			if (!used[id]){
				used[id] = true;
				key[id] = key1;
				size++;
			}
			if (size >= factor * key.length){
				rehash();
			}
		}
		public void remove(int key1){
			int id = idx(key1);
			if (used[id]){
				used[id] = false;
				size--;
			}
		}
