/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author prakharjain
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        CNewYearAndPermutation solver = new CNewYearAndPermutation();
        solver.solve(1, in, out);
        out.close();
    }

    static class CNewYearAndPermutation {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            long[] fac = factorial(n, m);
            long[] ifac = factorialInverse(n, m);

            long ans = n * fac[n];
            ans %= m;

            for (int i = 2; i <= n; i++) {
                long ca = fac[i];
                ca *= fac[n - i + 1];
                ca %= m;
                ca *= ifac[n];
                ca %= m;
                ca *= (n - i + 1);
                ca %= m;
                ca *= fac[n];
                ca %= m;

                ans += ca;
                ans %= m;
            }

            out.println(ans);
        }

        long[] factorial(int n, int mod) {
            long[] factorial = new long[n + 1];

            factorial[0] = 1;

            for (int i = 1; i <= n; i++) {
                factorial[i] = i * factorial[i - 1];
                factorial[i] %= mod;
            }

            return factorial;
        }

        long[] factorialInverse(int n, int mod) {
            long[] factorialInverse = new long[n + 1];

            long[] inv = new long[n + 1];

            inv[1] = 1;

            for (int i = 2; i <= n; i++) {
                inv[i] = inv[mod % i];
                inv[i] *= (mod - mod / i);
                inv[i] %= mod;
            }

            factorialInverse[0] = 1;

            for (int i = 1; i <= n; i++) {
                factorialInverse[i] = inv[i] * factorialInverse[i - 1];
                factorialInverse[i] %= mod;
            }

            return factorialInverse;
        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void close() {
            writer.close();
        }

        public void println(long i) {
            writer.println(i);
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
