		int n = scan.nextInt();
		int t = scan.nextInt();
		if(n <= t){
			out.println(0);
			out.close();
			return;
		}

		int dp[][][][] = new int[n+2][4 * 4 + 5][n+1][n+1];
		for(int i = 0; i < n; i++){
			if(i == 0){
				for(int j = 0; j < 4; j++){
					dp[i+1][j][0][0] = 1;
				}
			} else if(i == 1){
				for(int state = 0; state < 4; state++){
					for(int j = 0; j < 4; j++){
						if(state == j) continue;
						dp[i+1][state * 4 + j][0][0] += dp[i][state][0][0];
					}
				}
			} else {			
				for(int state = 0; state < 16; state++){
					int first = state / 4;
					int second = state % 4;
					if(first == second) continue;
					for(int c = 0; c <= i/2; c++){
						for(int d = 0; d <= i/2; d++){
							for(int j = 0; j < 4; j++){
								if(second == j) continue;
								if(first < second){
									if(second < j){
										dp[i+1][second * 4 + j][c][d] += dp[i][state][c][d];
									} else if(second > j){
										dp[i+1][second * 4 + j][c+1][d] += dp[i][state][c][d];
									}
								} else if(first > second){
									if(second < j){
										dp[i+1][second * 4 + j][c][d+1] += dp[i][state][c][d];
									} else if(second > j){
										dp[i+1][second * 4 + j][c][d] += dp[i][state][c][d];
									}
								}
							}
						}
					}
				}
			}
		}
		/*
		for(int i = 0; i <= n+1; i++)
			for(int state = 0; state < 16; state++)
				for(int c = 0; c <= i / 2; c++)
					for(int d = 0; d <= i / 2; d++)
						System.out.println(i + ", (" + (state / 4) + "," + (state % 4) + "), " + c + "," + d + "  => " + dp[i][state][c][d]);
		*/
		int ret = 0;
		for(int state = 0; state < 16; state++){
			int first = state / 4;
			int second = state % 4;
			if(first == second) continue;
			ret += dp[n][state][t][t-1];
		}
		out.println(ret);
		out.close();		
	}

