public class A {

	static long s3(long x) { return x * x * x; }

	static Pair bt(long M)
	{
		if(M == 0)
			return new Pair();
		int a = 1; while(s3(a + 1) <= M) ++a;
		Pair p1 = bt(Math.min(M, s3(a + 1) - 1) - s3(a));
		p1.inc(a);
		if(a > 1)
		{
			Pair p2 = bt(Math.min(M, s3(a) - 1) - s3(a - 1));
			p2.inc(a - 1);
			p1 = combine(p1, p2);
		}
		return p1;
	}

	public static void main(String[] args) throws IOException 
	{
		Scanner sc = new Scanner(System.in);
		PrintWriter out = new PrintWriter(System.out);

		Pair ans = bt(sc.nextLong());
		out.println(ans.maxCnt + " " + ans.maxX);

		out.flush();
		out.close();
	}

	static Pair combine(Pair p1, Pair p2)
	{
		if(p1.maxCnt > p2.maxCnt || p1.maxCnt == p2.maxCnt && p1.maxX > p2.maxX)
			return p1;
		return p2;
	}

	static class Pair 
	{ 
		long maxX; int maxCnt; 

		void inc(long a) { maxCnt++; maxX += s3(a); }
	}


	static class Scanner 
	{
		StringTokenizer st;	
		BufferedReader br;

		public Scanner(InputStream s){	br = new BufferedReader(new InputStreamReader(s));}

		public Scanner(FileReader r){	br = new BufferedReader(r);}

		public String next() throws IOException 
		{
			while (st == null || !st.hasMoreTokens()) 
				st = new StringTokenizer(br.readLine());
			return st.nextToken();
		}

		public int nextInt() throws IOException {return Integer.parseInt(next());}

		public long nextLong() throws IOException {return Long.parseLong(next());}

		public String nextLine() throws IOException {return br.readLine();}

		public double nextDouble() throws IOException { return Double.parseDouble(next()); }

		public boolean ready() throws IOException {return br.ready();}


	}
}

