class TaskD {
    public void solve(int testNumber, InputReader in, PrintWriter out) {
        int x1 = in.nextInt();
        int x2 = in.nextInt();
        int a = in.nextInt();
        int b = in.nextInt();
        int ia = a;

        if (canKill(x1, x2, a, b)) {
            out.println("FIRST");
            out.println(x2);
            return;
        }



        if (a <= 0 && b >= 0) {
            out.println("DRAW");
            return;
        }

        int delta = x2 - x1;
        if (b < 0) {
            delta = -delta;
            int temp = -b;
            b = -a;
            a = temp;
        }

        if (delta < 0) {
            out.println("DRAW");
            return;
        }
        if (delta % (a + b) == 0) {
            out.println("SECOND");
            return;
        }

        int mod = delta % (a + b);
        if (mod >= a && mod <= b) {
            out.println("FIRST");
            int sign = ia < 0 ? -1 : 1;
            out.println(x1 + sign * mod);
            return;
        }

        out.println("DRAW");
    }

    private boolean canKill(int x1, int x2, int a, int b) {
        int delta = x2 - x1;
        return delta >= a && delta <= b;
    }

}

