class TextDocumentAnalysis {
  public static String input(String str) {
    int len = str.length();
    boolean open = false;
    int wc = 0;
    int max = 0;
    int wlen = 0;
    for (int i=0; i<len; i++) {
      char ch = str.charAt(i);
      if (ch == '(') {
        if (wlen > 0) {
          if (wlen > max) max = wlen;
          wlen = 0;
        }
        open = true;
      } else if (ch == ')') {
        if (wlen > 0) {
          wc++;
          wlen = 0;
        }
        open = false;
      } else if (ch == '_') {
        if (wlen > 0) {
          if (open) {
            wc++;
          } else {
            if (wlen > max) max = wlen;
          }
          wlen = 0;
        }
      } else {
        wlen++;
      }
    }
    if (wlen > 0) {
      if (open) {
        wc++;
      } else {
        if (wlen > max) max = wlen;
      }
    }
    return max + " " + wc;
  }
}

