 public boolean isWhiteSpace(byte n) {
   return (n == ' ' || n == '\n' || n == '\r' || n == '\t');
 }

 public char nextChar() throws IOException {
   byte c = read();
   while (isWhiteSpace(c))
     c = read();
   return (char)c;
 }

 public int nextInt() throws IOException {
   int ret = 0;
   byte c = read();
   while (isWhiteSpace(c))
     c = read();
   boolean neg = (c == '-');
   if (neg)
     c = read();
   if (!(c >= '0' && c <= '9'))
     throw new InputMismatchException();
   do {
     ret = ret * 10 + c - '0';
   } while ((c = read()) >= '0' && c <='9');
   if (neg)
     return -ret;
   return ret;
 }

 public long nextLong() throws IOException {
   long ret = 0;
   byte c = read();
   while (isWhiteSpace(c))
     c = read();
   boolean neg = (c == '-');
   if (neg)
     c = read();
   if (!(c >= '0' && c <= '9'))
     throw new InputMismatchException();
   do {
     ret = ret * 10 + c - '0';
   } while ((c = read()) >= '0' && c <='9');
   if (neg)
     return -ret;
   return ret;
 }

 public double nextDouble() throws IOException {
   double ret = 0 , div = 1;
   byte c = read();
   while (isWhiteSpace(c))
     c = read();
   boolean neg = (c == '-');
   if (neg)
     c = read();
   do {
     ret = ret * 10 + c - '0';
   } while ((c = read()) >= '0' && c <= '9');

   if (c == '.') {
     while ((c = read()) >= '0' && c <= '9') {
       ret += (c - '0') / (div *= 10);
     }
   }

   if (neg)
     return -ret;
   return ret;
 }
