class Task {

    private final static int N = 20;

    public void solve(InputReader in, PrintWriter out) {

        int n = in.nextInt();
        String[] s = new String[n];
        for (int i = 0; i < n; i++) {
            s[i] = new String(in.next());
        }

        int m = s[0].length();
        long[] d = new long[(1 << N)];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if(i == j) continue;

                int mask = 0;
                for (int pos = 0; pos < m; pos++) {
                    if(s[i].charAt(pos) == s[j].charAt(pos)) {
                        mask |= (1 << pos);
                    }
                }
                d[mask] |=  (1L << i);
            }
        }


        for(int i = 0; i < m; i++){
            for(int pos = 0; pos < (1 << m) ; pos++){
                d[pos] |= d[pos|(1 << i)];
            }
        }

        int[] sum = new int[(1 << m)];
        for(int k = 0;k < (1 << m); k++){
            sum[k] = Long.bitCount(d[k]);
        }

        double[] f = new double[60];
        f[0] = 1;
        for(int i = 1;i < 60;i++)
            f[i] = f[i-1] * i;

        double[] ps = new double[m];
        for(int k = 0;k < m;k++){
            ps[k] = f[k] * f[m-1-k] / f[m];
        }

        double ans = 0;
        for(int i = 0; i < (1 << m); i++) {
            int k = Integer.bitCount(i);
            for(int j = 0; j < m; j++){
                if( i << ~j < 0){
                    ans += k * ps[k-1] * (sum[i^1<<j] - sum[i]);
                }
            }
        }

        out.printf(Locale.US, "%.12f\n", ans/n);


        return;
    }

}



