import java.util.Scanner;

public class CF105D {

	public static double [][] probArray;
	public static int bagSize;

	public static void main(String args[]) {
		Scanner scan = new Scanner(System.in);
		int w = scan.nextInt();
		int b = scan.nextInt();
		bagSize = w + b;
		probArray = new double[w+1][b+1];
		for(int i = 0; i <= w; i++) {
			for(int j = 0; j <= b; j++) {
				probArray[i][j] = -1;
			}
		}
		System.out.println(recursiveProb(w, b));
	}

	private static double recursiveProb(int w, int b) {
		if(w == 0 && b == 0) {
			// No mice left, princess cannot win.
			return 0;
		} else if(w == -1 || b == -1) {
			// Ran out of one kind of mouse, princess loses.
			return 0;
		} else if(probArray[w][b] != -1) {
			// Already filled this value.
			return probArray[w][b];
		} else {
			double nextW = (double)w / (w + b);
			double nextB = (double)b / (w + b);
			double probP; // Princess

			if((bagSize - (w + b)) % 3 == 0) {
				// Princess' turn.
				probP = nextW + nextB * recursiveProb(w, b - 1);
			} else if((bagSize - (w + b)) % 3 == 1) {
				// Dragon's turn.
				probP = nextB * recursiveProb(w, b - 1);
			} else {
				// Escaped mouse.
				probP = nextW * recursiveProb(w - 1, b) + nextB * recursiveProb(w, b - 1);
			}

			probArray[w][b] = probP;
			return probArray[w][b];
		}
	}
}

