import static java.lang.Math.*;
public class Main {
    static final long MOD = 1_000_000_007 , INF = 1_000_000_000_000_000L;
    static final int INf = 1_000_000_000;
    static FastReader reader;
    static PrintWriter writer;
    public static void main(String[] args) {
        Thread t = new Thread(null, new O(), "Integer.MAX_VALUE", 100000000);
        t.start();
    }
    static class O implements Runnable {
        public void run() {
            try {
                magic();
            }
            catch (Exception e) {
                e.printStackTrace();
                System.exit(1);
            }
        }
    }
    static class FastReader {
        final private int BUFFER_SIZE = 1 << 16;
        private DataInputStream din;
        private byte[] buffer;
        private int bufferPointer, bytesRead;

        public FastReader() {
            din = new DataInputStream(System.in);
            buffer = new byte[BUFFER_SIZE];
            bufferPointer = bytesRead = 0;
        }

        public FastReader(String file_name) throws IOException {
            din = new DataInputStream(new FileInputStream(file_name));
            buffer = new byte[BUFFER_SIZE];
            bufferPointer = bytesRead = 0;
        }

        public String readLine() throws IOException {
            byte[] buf = new byte[1000000];
            int cnt = 0, c;
            while ((c = read()) != -1) {
                if (c == '\n') break;
                buf[cnt++] = (byte) c;
            }
            return new String(buf, 0, cnt);
        }

        public int nextInt() throws IOException {
            int ret = 0;
            byte c = read();
            while (c <= ' ') c = read();
            boolean neg = (c == '-');
            if (neg) c = read();
            do {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');
            if (neg) return -ret;
            return ret;
        }

        public long nextLong() throws IOException {
            long ret = 0;
            byte c = read();
            while (c <= ' ') c = read();
            boolean neg = (c == '-');
            if (neg) c = read();
            do {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');
            if (neg) return -ret;
            return ret;
        }

        public double nextDouble() throws IOException {
            double ret = 0, div = 1;
            byte c = read();
            while (c <= ' ') c = read();
            boolean neg = (c == '-');
            if (neg) c = read();
            do {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');
            if (c == '.') while ((c = read()) >= '0' && c <= '9') ret += (c - '0') / (div *= 10);
            if (neg) return -ret;
            return ret;
        }

        private void fillBuffer() throws IOException {
            bytesRead = din.read(buffer, bufferPointer = 0, BUFFER_SIZE);
            if (bytesRead == -1) buffer[0] = -1;
        }

        private byte read() throws IOException {
            if (bufferPointer == bytesRead) fillBuffer();
            return buffer[bufferPointer++];
        }

        public void close() throws IOException {
            if (din == null) return;
            din.close();
        }
    }
    static int n, dp0[][], dp1[][];
    static void magic() throws IOException {
        reader = new FastReader();
        writer = new PrintWriter(System.out, true);
        n = reader.nextInt();
        dp0 = new int[2*n+1][2*n+1];
        dp1 = new int[2*n+1][2*n+1];
        for(int i=0;i<=n+n;++i) {
            for(int j=0;j<=n+n;++j) {
                dp0[i][j] = dp1[i][j] = -1;
            }
        }
        //fd(0, 0);
        writer.println(max(f(0,0,1), f(0,0,0)));
    }
    static int f(int idx, int open_count, int to_be_inc) {
        //writer.println("idx: "+idx+" open_count: "+open_count+" to_be_inc: "+to_be_inc);
        if(idx==2*n) {
            return 0;
        }
        if(to_be_inc==0) {
            if(dp0[idx][open_count]!=-1) {
                return dp0[idx][open_count];
            }
            //placing open
            int max = 0;
            int left_iske_baad = 2*n - idx - 1;
            if(left_iske_baad>open_count) {
                max+=max(f(idx+1, open_count+1, 0), f(idx+1, open_count+1, 1));
            }
            //placing close
            if(open_count>0) {
                max+=max(f(idx+1, open_count-1, 0), f(idx+1, open_count-1, 1));
            }
            return dp0[idx][open_count] = (int)(max%MOD);
        }
        else {
            if(dp1[idx][open_count]!=-1) {
                return dp1[idx][open_count];
            }
            //placing open
            int max = 0;
            int left_iske_baad = 2*n - idx - 1;
            if(left_iske_baad>open_count) {
                max = 1+f(idx+1, open_count+1, 0);
                if(open_count>0) {
                    max+=max(f(idx+1, open_count-1, 0), f(idx+1, open_count-1, 1));
                }
            }
            //placing close
            if(open_count>0) {
                int ispe = 1+f(idx+1, open_count-1, 0);
                if(left_iske_baad>open_count) {
                    ispe+=max(f(idx+1, open_count+1, 0), f(idx+1, open_count+1, 1));
                }
                max = max(max, ispe);
            }
            return dp1[idx][open_count] = (int)(max%MOD);
        }
    }
    static void fd(int idx, int open_count) {
        //writer.println("idx: "+idx+" open_count: "+open_count+" to_be_inc: "+to_be_inc);
        if(idx==2*n) {
            writer.println("Open count: " + open_count);
            if(open_count==0) {
            }
        }

        //placing open
        int max = 0;
        int left_iske_baad = 2*n - idx - 1;
        if(left_iske_baad>open_count) {
            fd(idx+1, open_count+1);
        }
        //placing close
        if(open_count>0) {
            fd(idx+1, open_count-1);
        }
    }
}

