  static class DNekoAndAkisPrank {
    int[][][] dp;
    static int MOD = (int) (1e9 + 7);

    int func(int idx, int inc, int last) {
      if (inc < 0 || last * 2 > dp.length) return 0;

      if (idx >= dp.length) {
        return 0;
      }

      if (dp[idx][inc][last] != -1) return dp[idx][inc][last];

      int ans = 0;
      int remain = dp.length - idx;

      if (last == 0) {
        if (inc + 1 <= remain && inc > 0) {
          ans = Math.max(ans, 1 + func(idx + 1, inc + 1, 1) + func(idx + 1, inc - 1, 0)) % MOD;
          ans = Math.max(ans, 1 + func(idx + 1, inc - 1, 1) + func(idx + 1, inc + 1, 0)) % MOD;
        } else if (inc > 0) ans = Math.max(ans, 1 + func(idx + 1, inc - 1, 1));
        else {
          ans = Math.max(ans, 1 + func(idx + 1, inc + 1, 1)) % MOD;
        }

      } else {
        if (inc > 0) ans += func(idx + 1, inc - 1, 0) % MOD;
        if (inc + 1 <= remain) ans += func(idx + 1, inc + 1, 0) % MOD;
      }
      dp[idx][inc][last] = ans % MOD;
      return ans;
    }

    public void solve(int testNumber, InputReader in, OutputWriter out) {
      int n = in.readInt();
      dp = new int[n * 2][n + 1][3];

      for (int i = 0; i < dp.length; ++i) ArrayUtils.fill(dp[i], -1);

      out.printLine(Math.max(func(0, 0, 0), func(0, 0, 1)));
    }
  }

