public class p1152d {
    static boolean[][] hasVal;
    static boolean[][] doneVal;
    static long[][][] dp;
    static boolean[][][] done;

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        hasVal = new boolean[2*n+1][2*n+1];
        doneVal = new boolean[2*n+1][2*n+1];
        dp = new long[2*n+1][2*n+1][2];
        done = new boolean[2*n+1][2*n+1][2];
        System.out.println(traverse(2*n, 0, 0)%1_000_000_007);
    }

    public static long traverse(int ind, int diff, int flag) {
        if(ind <= 0 || diff < 0) return 0;
        if(done[ind][diff][flag]) return dp[ind][diff][flag];
        done[ind][diff][flag] = true;
        long num = 0;
        if(flag == 1) {
            if(hasVal(ind-1, diff-1)) num += traverse(ind-1, diff-1, 0);
            if(hasVal(ind-1, diff+1)) num += traverse(ind-1, diff+1, 0);
            if(num >= 1_000_000_007) num -= 1_000_000_007;
            return dp[ind][diff][flag] = num;
        }
        if(hasVal(ind-1, diff-1)) {
            long tmp = traverse(ind-1, diff-1, 1)+1;
            if(hasVal(ind-1, diff+1)) tmp += traverse(ind-1, diff+1, 0);
            num = max(num, tmp);
        }
        if(hasVal(ind-1, diff+1)) {
            long tmp = traverse(ind-1, diff+1, 1)+1;
            if(hasVal(ind-1, diff-1)) tmp += traverse(ind-1, diff-1, 0);
            num = max(num, tmp);
        }
        if(num >= 1_000_000_007) num -= 1_000_000_007;
        return dp[ind][diff][flag] = num%1_000_000_007;
    }
    static long max(long a, long b) {return a > b ? a : b;}

    public static boolean hasVal(int ind, int diff) {
        if(diff < 0) return false;
        return diff <= ind;
    }
}

