import java.util.Arrays;
import java.util.Scanner;

public class D {
    private static int solve(int len, int open, boolean avail, int n, int[][][] memo) {
        int mod = 1000000007;

        if (len == 2 * n) {
            return 0;
        }

        int availInt = avail ? 0 : 1;

        if (memo[availInt][len][open] != -1) {
            return memo[availInt][len][open];
        }

        int closed = len - open;
        boolean canOpen = open < n;
        boolean canClose = closed < open;

        int ans = 0;
        if (avail) {
            if (canOpen && canClose) {
                ans += solve(len + 1, open + 1, true, n, memo);
                ans += solve(len + 1, open, false, n, memo);
            } else if (canOpen) {
                ans += solve(len + 1, open + 1, false, n, memo);
            } else if (canClose) {
                ans += solve(len + 1, open, false, n, memo);
            }

            ans++;
        } else {
            if (canOpen) {
                ans += solve(len + 1, open + 1, true, n, memo);
            }

            if (canClose) {
                ans += solve(len + 1, open, true, n, memo);
            }
        }

        memo[availInt][len][open] = ans % mod;

        return ans % mod;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();

        int[][][] memo = new int[2][2 * n + 1][n + 1];

        for (int i = 0; i < 2 * n + 1; i++) {
            Arrays.fill(memo[0][i], -1);
            Arrays.fill(memo[1][i], -1);
        }

        System.out.println(solve(0, 0, true, n, memo));
    }
}

