public class cf4 implements Runnable { 

	long[][][] dp;
	long mod = (long)1e9 + 7;

	void recur(int n, int k, int x) {

		dp[n][k][x] = 0;

		if(k == dp[n].length - 1) {

			if(n != 0)
				dp[n][k][x] = -2;

			return;
		}

		int c = 0;

		if(x == 0) {

			if(n > 0) {

				if(dp[n - 1][k + 1][1] == -1)
					recur(n - 1, k + 1, 1);

				if(dp[n - 1][k + 1][1] != -2) {
					dp[n][k][0] = (dp[n - 1][k + 1][1] + dp[n][k][0]) % mod;
					c++;
				}	
			}

			if(dp[n + 1][k + 1][1] == -1)
				recur(n + 1, k + 1, 1);

			if(dp[n + 1][k + 1][1] != -2) {
				dp[n][k][0] = (dp[n + 1][k + 1][1] + dp[n][k][0]) % mod;
				c++;
			}
		}

		else if(x == 1) {

			dp[n][k][x] = 1;

			if(n > 0) {

				if(dp[n - 1][k + 1][0] == -1)
					recur(n - 1, k + 1, 0);

				if(dp[n - 1][k + 1][0] != -2) {
					dp[n][k][1] = (dp[n - 1][k + 1][0] + dp[n][k][1]) % mod;
					c++;
				}

				if(dp[n + 1][k + 1][1] == -1)
					recur(n + 1, k + 1, 1);

				if(dp[n + 1][k + 1][1] != -2) {
					dp[n][k][1] = (dp[n + 1][k + 1][1] + dp[n][k][1]) % mod;
					c++;
				}
			}

			else {

				if(dp[n + 1][k + 1][0] == -1)
					recur(n + 1, k + 1, 0);

				if(dp[n + 1][k + 1][0] != -2) {
					dp[n][k][1] = (dp[n + 1][k + 1][0] + dp[n][k][1]) % mod;
					c++;
				}
			}

		}

		if(c == 0)
			dp[n][k][x] = -2;
	}

