public class Codeforces {
    final static int P = 1000000007;
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        int n = input.nextInt();
        int[][] table = new int[n+1][n+1];   
        table[0][0] = 0;
        for (int i=0; i<=n; i++) for (int j=i; j<=n; j++) {
            if (i == 0 && j == 0) continue;
            else if (i == 0) table[i][j] = (table[i][j-1]+(i+j&1))%P;
            else if (j == 0) table[i][j] = (table[i-1][j]+(i+j&1))/P;
            else table[i][j] = (table[i-1][j] + table[i][j-1] + (i+j&1))%P;
        }
        System.out.println(table[n][n]);
    }
}

