                    if (j != 0) dp[i][j] = (dp[i][j] + (dp[i - 1][j - 1])) % mod;
                    if (j + 1 <= 2 * n) dp[i][j] = (dp[i][j] + dp[i - 1][j + 1]) % mod;
                }
                if (i % 2 == 1) for (int j = 0; j <= Math.min(i, 2 * n - i); j++) ans = (ans + dp[i][j]) % mod;
            }
