            this.right = right;
            this.value = value;
            this.c = c;
        }

        @Override
        public int compareTo(Object o) {
            return Integer.compare(this.value, ((Node)o).value);
        }
    }

    private static int fib(int n, int m){
        if (n < 2) return n;
        int a = 0;
        int b = 1;
        for (int i=0;i<n-2;i++){
            int c = (a + b) % m;
            a = b;
            b = c;
        }
        return (a + b) % m;
    }

    static long gcd(long a, long b) {
        if (b == 0) return a;
        return gcd(b, a % b);
    }

    static long lcm(long a, long b) {
        return Math.abs(a * b) / gcd(a, b);
    }

    static long dp[][][] = new long[2][2001][2001];

    static long m = 1_000_000_000 + 7;

    static long f(int o, int n, boolean canUse) {
        int k = canUse ? 1 : 0;
        if (dp[k][o][n] == -1) {
            if (n == 0) return 0;
            int d = canUse ? 1 : 0;
            if (o == 0) {
                dp[k][o][n] = f(o + 1, n - 1, !canUse) + d;
            }
            else if (n == o) {
                dp[k][o][n] = f(o - 1, n - 1, !canUse) + d;
            }
            else if (canUse) {
                dp[k][o][n] = f(o + 1, n - 1, false) + 1 + f(o - 1, n - 1, true);
            }
            else {
                dp[k][o][n] = f(o + 1, n - 1, true) + f(o - 1, n - 1, true);
            }
        }
        return dp[k][o][n] % m;
    }

    public static void main(String[] args){
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter printer = new PrintWriter(System.out);
        int n = scanner.nextInt() * 2;
        for (int i = 0; i < 2; i++) {
            for (int j = 0; j < 2001; j++) {
                for (int k = 0; k < 2001; k++) {
                    dp[i][j][k] = -1;
                }
            }
        }
        printer.println(f(0, n, true));
        printer.flush();
        printer.close();
    }
}

