	static int [][][]memo;
	static int dp(int balance,int length,int free) {

		int open=balance + (length-balance)/2;
		if(length==2*n)
			return 0;
		if(memo[free][balance][length]!=-1)
			return memo[free][balance][length];
		int ans=0;
		if(open<n) {
			ans += Math.max(dp(balance+1,length+1, 1),dp(balance+1,length+1,free^1)+free);
			if(ans>=MOD)
				ans-=MOD;
		}
		if(balance>0) {
			int x=+open<n?0:free;
			ans += Math.max(dp(balance-1,length+1, 1),dp(balance-1,length+1,x^1)+x);
			if(ans>=MOD)
				ans-=MOD;
		}
		return memo[free][balance][length]=ans;

	}
