import static java.lang.Math.max;

public class D {
    static int n;
    static long dp[][][], mod = (long) 1e9 + 7, inf = (long) 1e18;

    public static void main(String[] args) throws Exception {
        Scanner in = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        n = in.nextInt();
        dp = new long[2][n + n + 1][n + n + 1];
        for (long a[][] : dp) for (long b[] : a) Arrays.fill(b, -1);
        pw.println(solve(0, 0, 0));
        pw.close();
    }

    static long solve(int last, int pos, int sum) {
        if (pos >= n + n) {
            if (sum == 0) return 0;
            return -inf;
        }
        if (dp[last][pos][sum] != -1) return dp[last][pos][sum];
        long ans = 0, a = 0, b = 0, rem = n + n - pos;
        if (rem >= sum + 1) a = max(0, solve(0, pos + 1, sum + 1));
        if (sum - 1 >= 0) b = max(0, solve(0, pos + 1, sum - 1));
        ans = max(ans, a + b);
        if (last == 0) {
            a = 0;
            b = 0;
            if (rem >= sum + 1) a = max(0, solve(1, pos + 1, sum + 1));
            if (sum - 1 >= 0) b = max(0, solve(1, pos + 1, sum - 1));
            ans = max(ans, 1 + a + b);
        }
        if (ans >= 0) ans %= mod;
        return dp[last][pos][sum] = ans;
    }

    static void debug(Object... obj) {
        System.err.println(Arrays.deepToString(obj));
    }
}

