public class Solution implements Runnable {

	class Edge {
		int from, to, u, f, c;

		public Edge(int from, int to, int u, int c) {
			this.from = from;
			this.to = to;
			this.u = u;
			this.c = c;
		}
	}

	int dr [] = new int [] {0, 0, 1, -1};
	int dc [] = new int [] {1, -1, 0, 0};

	int N, S, T;
	ArrayList<Edge> edges;
	ArrayList<Integer> g[];
	int [] d, pv, pe;
	boolean [] inQueue;

	void addEdge (int from, int to, int u, int c) {
		g[from].add(edges.size());
		edges.add(new Edge (from, to, u, c));
		g[to].add(edges.size());
		edges.add(new Edge (to, from, 0, -c));
	}

	int minCostMaxFlow () {
		int result = 0;

		d = new int [N];
		inQueue = new boolean [N];
		pe = new int [N];
		pv = new int [N];
		Queue<Integer> q = new ArrayDeque<>();

		while (true) {
			Arrays.fill(inQueue, false);
			Arrays.fill(d, Integer.MAX_VALUE / 2);
			d[S] = 0;
			inQueue[S] = true;
			q.add(S);
			while (!q.isEmpty()) {
				int v = q.poll();
				inQueue[v] = false;
				for (int i = 0; i < g[v].size(); i++) {
					int index = g[v].get(i);
					Edge e = edges.get(index);
					if (e.u > e.f) {
						if (d[e.to] > d[v] + e.c) {
							d[e.to] = d[v] + e.c;
							pv[e.to] = v;
							pe[e.to] = index;
							if (!inQueue[e.to]) {
								inQueue[e.to] = true;
								q.add(e.to);
							}
						}
					}
				}
			}
			if (d[T] == Integer.MAX_VALUE / 2) break;
			int addFlow = Integer.MAX_VALUE / 2;
			for (int v = T; v != S; v = pv[v]) {
				int index = pe[v];
				Edge e = edges.get(index);
				addFlow = min (addFlow, e.u - e.f);
			}
			for (int v = T; v != S; v = pv[v]) {
				int index = pe[v];
				Edge dir = edges.get(index);
				Edge rev = edges.get(index ^ 1);
				result += addFlow * dir.c;
				dir.f += addFlow;
				rev.f -= addFlow;
			}
		}
		return result;
	}

	public void solve() throws Exception {
		int n = sc.nextInt();
		int m = sc.nextInt();

		int a [][] = new int [n][m];
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				a[i][j] = sc.nextInt();
			}
		}

		N = n * m + 2;
		S = n * m;
		T = n * m + 1;

		edges = new ArrayList<>();

		g = new ArrayList[N];
		for (int i = 0; i < N; i++)
			g[i] = new ArrayList<>();


		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				if ((i + j) % 2 == 0) {
					addEdge(S, i * m + j, 1, 0);
					for (int k = 0; k < 4; k++) {
						int di = dr[k] + i;
						int dj = dc[k] + j;
						if (di >= 0 && dj >= 0 && di < n && dj < m) {
							int cost = 1;
							if (a[i][j] == a[di][dj]) cost = 0;
							addEdge(i * m + j, di * m + dj, 1, cost);
						}
					}
				} else {
					addEdge(i * m + j, T, 1, 0);
				}
			}
		}
		out.println(minCostMaxFlow());
	}

	BufferedReader in;
