import java.io.*;
import java.util.ArrayList;
import java.util.List;

public class ProblemC1 {
    BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
    PrintWriter writer = new PrintWriter(new OutputStreamWriter(System.out));

    ProblemC1() throws IOException {
//        reader = new BufferedReader(new FileReader("input.txt"));
//        writer = new PrintWriter(new FileWriter("output.txt"));
    }

    int[] readInts() throws IOException {
        String[] strings = reader.readLine().split(" ");
        int[] ints = new int[strings.length];
        for(int i = 0; i < ints.length; i++) {
            ints[i] = Integer.parseInt(strings[i]);
        }
        return ints;
    }

    int[] tt = null;
    int tx = 0;
    int readInt() throws IOException {
        if(tt == null || tx >= tt.length) {
            tt = readInts();
            tx = 0;
        }
        return tt[tx++];
    }

    boolean isBit(int x, int bit) {
        return ((x >> bit) & 1) > 0;
    }

    void solve() throws IOException {
        int n = readInt();
        int m = readInt();
        int[][] table = new int[n][];
        for(int i = 0; i < n; i++) table[i] = readInts();
        int[][][] dp = new int[n + 1][m][1 << m];
        for(int i = 0; i <= n; i++) for(int j = 0; j < m; j++) for(int k = 0; k < 1 << m; k++) dp[i][j][k] = Integer.MAX_VALUE;
        dp[0][0][0] = 0;
        int inf = Integer.MAX_VALUE;
        for(int i = 0; i < n; i++) {
            for(int j = 0; j < m; j++) {
                for(int mask = 0; mask < 1 << m; mask++) {
                    if(dp[i][j][mask] == inf) continue;
                    if(isBit(mask, j)) {
                        int newJ = j + 1;
                        int newI = i;
                        if(newJ == m) {
                            newI++;
                            newJ = 0;
                        }
                        int newMask = mask ^ (1 << j);
                        dp[newI][newJ][newMask] = Math.min(dp[newI][newJ][newMask], dp[i][j][mask]);
                    }
                    else {
                        if(i + 1 < n) {
                            int newJ = j + 1;
                            int newI = i;
                            if(newJ == m) {
                                newI++;
                                newJ = 0;
                            }
                            int newMask = mask ^ (1 << j);
                            dp[newI][newJ][newMask] = Math.min(dp[newI][newJ][newMask], dp[i][j][mask] + (table[i][j] == table[i + 1][j] ? 0 : 1));
                        }
                        if(j + 1 < m && !isBit(mask, j + 1)) {
                            int newJ = j + 2;
                            int newI = i;
                            if(newJ == m) {
                                newI++;
                                newJ = 0;
                            }
                            int newMask = mask;
                            dp[newI][newJ][newMask] = Math.min(dp[newI][newJ][newMask], dp[i][j][mask] + (table[i][j] == table[i][j + 1] ? 0 : 1));
                        }
                    }
                }

            }
        }
        writer.println(dp[n][0][0]);
        writer.flush();
    }

    void multiSolve() throws IOException {
        int n = readInts()[0];
        for(int i = 0; i < n; i++) {
            solve();
        }
        writer.flush();
    }

    public static void main(String[] args) throws IOException{
        new ProblemC1().solve();
    }
}

import static java.lang.Double.parseDouble;
import static java.lang.Integer.parseInt;
import static java.lang.Long.parseLong;
import static java.lang.System.exit;
import static java.util.Arrays.fill;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.PriorityQueue;
import java.util.StringTokenizer;

public class C {

	static BufferedReader in;
	static PrintWriter out;
	static StringTokenizer tok;

	static final int DI[] = {1, 0, -1, 0};
	static final int DJ[] = {0, 1, 0, -1};

	static class Pos implements Comparable<Pos> {
		final int i, j, dist;

		Pos(int i, int j, int dist) {
			this.i = i;
			this.j = j;
			this.dist = dist;
		}

		public int compareTo(Pos o) {
			return dist - o.dist;
		}
	}

	static void solve() throws Exception {
		int n = nextInt();
		int m = nextInt();
		int id[][] = new int[n][m];
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				id[i][j] = nextInt() - 1;
			}
		}
		int cap[][][] = new int[n][m][4];
		int cost[][][] = new int[n][m][4];
		int imbalance[][] = new int[n][m];
		int totalCost = n * m / 2;
		int totalImbalance = 0;
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				if (((i ^ j) & 1) != 0) {
					--imbalance[i][j];
					continue;
				}
				++imbalance[i][j];
				for (int d = 0; d < 4; d++) {
					int ii = i + DI[d];
					int jj = j + DJ[d];
					if (ii < 0 || ii >= n || jj < 0 || jj >= m) {
						continue;
					}
					if (id[i][j] == id[ii][jj]) {
						cap[ii][jj][d ^ 2] = 1;
						cost[ii][jj][d ^ 2] = 1;
						cost[i][j][d] = -1;
						--imbalance[i][j];
						++imbalance[ii][jj];
						--totalCost;
					} else {
						cap[i][j][d] = 1;
					}
				}
				totalImbalance += imbalance[i][j];
			}
		}
		int dist[][] = new int[n][m];
		int distAdj[][] = new int[n][m];
		int back[][] = new int[n][m];
		PriorityQueue<Pos> queue = new PriorityQueue<>();
		while (totalImbalance > 0) {
			for (int t[]: dist) {
				fill(t, Integer.MAX_VALUE);
			}
			for (int t[]: back) {
				fill(t, -1);
			}
			for (int i = 0; i < n; i++) {
				for (int j = 0; j < m; j++) {
					if (imbalance[i][j] > 0) {
						dist[i][j] = 0;
						queue.add(new Pos(i, j, 0));
					}
				}
			}
			do {
				Pos pos = queue.remove();
				int i = pos.i;
				int j = pos.j;
				int cdist = pos.dist;
				if (dist[i][j] != cdist) {
					continue;
				}
				for (int d = 0; d < 4; d++) {
					if (cap[i][j][d] == 0) {
						continue;
					}
					int ii = i + DI[d];
					int jj = j + DJ[d];
					int ndist = cdist + cost[i][j][d] + distAdj[ii][jj] - distAdj[i][j];
					if (ndist < cdist) {
						throw new AssertionError();
					}
					if (dist[ii][jj] > ndist) {
						dist[ii][jj] = ndist;
						back[ii][jj] = d ^ 2;
						queue.add(new Pos(ii, jj, ndist));
					}
				}
			} while (!queue.isEmpty());
			int resDist = Integer.MAX_VALUE;
			int resI = -1;
			int resJ = -1;
			for (int i = 0; i < n; i++) {
				for (int j = 0; j < m; j++) {
					if (imbalance[i][j] < 0 && resDist > dist[i][j]) {
						resDist = dist[i][j];
						resI = i;
						resJ = j;
					}
				}
			}
			if (resDist == Integer.MAX_VALUE) {
				throw new AssertionError();
			}
			{
				int i = resI, j = resJ;
				++imbalance[i][j];
				while (true) {
					int d = back[i][j];
					int ii = i + DI[d];
					int jj = j + DJ[d];
					++cap[i][j][d];
					--cap[ii][jj][d ^ 2];
					i = ii;
					j = jj;
					if (imbalance[i][j] > 0) {
						break;
					}
				}
				--imbalance[i][j];
				--totalImbalance;
				totalCost += dist[resI][resJ] - distAdj[resI][resJ] - dist[i][j] + distAdj[i][j];
			}
			for (int i = 0; i < n; i++) {
				for (int j = 0; j < m; j++) {
					if (dist[i][j] != Integer.MAX_VALUE) {
						distAdj[i][j] -= dist[i][j];
					}
				}
			}
		}
		out.print(totalCost);
	}

	static int nextInt() throws IOException {
		return parseInt(next());
	}

	static long nextLong() throws IOException {
		return parseLong(next());
	}

	static double nextDouble() throws IOException {
		return parseDouble(next());
	}

	static String next() throws IOException {
		while (tok == null || !tok.hasMoreTokens()) {
			tok = new StringTokenizer(in.readLine());
		}
		return tok.nextToken();
	}

	public static void main(String[] args) {
		try {
			in = new BufferedReader(new InputStreamReader(System.in));
			out = new PrintWriter(new OutputStreamWriter(System.out));
			solve();
			in.close();
			out.close();
		} catch (Throwable e) {
			e.printStackTrace();
			exit(1);
		}
	}
}

import java.util.Scanner;

public class Main {
    private static int m;
    private static int size=1;
    private static int[] que=new int[(80*80+5)*8];   //队列
    //dis 表示最小花费
    private static int[] dis=new int[80*80+5],pr = new int[80*80+5];
    //vis 表示是否访问过
    private static int[] ed=new int[80*80+5],vis = new int[80*80+5];
    private static int[] edge=new int[80*80+5],next = new int[80*80+5];
    //cost 表示单位流量费用  weight 表示剩余容量
    private static int[] cost=new int[80*80+5],weight = new int[80*80+5],pre = new int[80*80+5];

    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int n = scan.nextInt();
        m =scan.nextInt();
        int s = n*m+1,t=n*m+2;
        int[][] a = new int[80+5][80+5];
        for (int i=1;i<=n;i++){
            for (int j=1;j<= m;j++){
                a[i][j] = scan.nextInt();
            }
        }
        for (int i=1;i<=n;i++){
            for (int j=1;j<=m;j++){
                if ((i+j)%2!=0){                //i+j为奇数分到s（起点）那一拨
                    addedge2(s,getNo(i,j),1,0);
                }else {                     //i+j为偶数分到t（终点）那一拨
                    addedge2(getNo(i,j),t,1,0);
                }
                if (j<m) {
                    if ((i+j)%2!=0) addedge2(getNo(i,j),getNo(i,j+1),1,isok(a[i][j],a[i][j+1]));
                    else addedge2(getNo(i,j+1),getNo(i,j),1,isok(a[i][j],a[i][j+1]));
                }
                if (i<n) {
                    if ((i+j)%2!=0) addedge2(getNo(i,j),getNo(i+1,j),1,isok(a[i][j],a[i+1][j]));
                    else addedge2(getNo(i+1,j),getNo(i,j),1,isok(a[i][j],a[i+1][j]));
                }
            }
        }

        int out = Costflow(s,t);
        System.out.println(out);
    }

    private static int Costflow(int s, int t) {
        int totcost=0;
        while (SPFA(s,t)) {
            int flow= 0x7f7f7f7f;
            for(int x=t;x!=s;x=pr[x]){
                flow=Math.min(flow,weight[ed[x]]);
            }
            totcost+=flow*dis[t];
            for(int x=t;x!=s;x=pr[x]){
                weight[ed[x]]-=flow;
                weight[ed[x]^1]+=flow;
            }
        }
        return totcost;

    }

    private static boolean SPFA(int s, int t) {
        for (int i=0;i<dis.length;i++){
            dis[i]= 127;
        }
        for (int i=0;i<vis.length;i++){
            vis[i]= 0;
        }

        dis[que[1]=s]=0;vis[s]=1;
        int head=1,tail=1;
        while (head<=tail) {
            int getNow=que[head++];
            for(int p=pre[getNow];p!=0;p=next[p]) {
                int v=edge[p];
                if (weight[p]>0&&dis[getNow]+cost[p]<dis[v]) {  //存在路径，且权值变小。
                    dis[v]=dis[getNow]+cost[p];
                    if (vis[v]==0){ vis[v]=1;que[++tail]=v;}
                    pr[v]=getNow;
                    ed[v]=p;
                }
            }
            vis[getNow]=0;
        }
        return dis[t]<dis[0];

    }

    private static int isok(int i, int j) {   //判断相邻两格是否相同，相同费用为0，不同为1
        if (i!=j){
            return 1;
        }else {
            return 0;
        }
    }

    private static void addedge2(int u, int v, int w, int c) {
        addedge(u,v,w,c);
        addedge(v,u,0,-c);
    }

    private static void addedge(int u, int v, int w, int c) {
        edge[++size]=v;
        weight[size]=w;
        cost[size]=c;
        next[size]=pre[u];
        pre[u]=size;
    }

    private static int getNo(int i, int j) {
        return (i-1)*m+j;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

/**
 * @author pashka
 */
public class Main {


    private void solve() throws IOException {
        int n = nextInt();
        int m = nextInt();
        int[][] a = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                a[i][j] = nextInt();
            }
        }
        init(n * m + 2, n * m * 6);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int c = i * m + j;
                if ((i + j) % 2 == 0) {
                    addEdge(0, 2 + c, 1, 0);
                } else {
                    addEdge(2 + c, 1, 1, 0);
                }
                if (i < n - 1) {
                    int cost = 0;
                    if (a[i][j] != a[i + 1][j]) cost = 1;
                    addEdge(2 + c, 2 + c + m, 1, cost);
                    addEdge(2 + c + m, 2 + c, 1, cost);
                }
                if (j < m - 1) {
                    int cost = 0;
                    if (a[i][j] != a[i][j + 1]) cost = 1;
                    addEdge(2 + c, 2 + c + 1, 1, cost);
                    addEdge(2 + c + 1, 2 + c, 1, cost);
                }
            }
        }
        long res = minCostMaxFlow(0, 1);
        out.println(res);
    }

    private BufferedReader br;
    private PrintWriter out;
    private StringTokenizer st;

    String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            st = new StringTokenizer(br.readLine());
        }
        return st.nextToken();
    }

    int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    long nextLong() throws IOException {
        return Long.parseLong(next());
    }

    public static void main(String[] args) throws IOException {
        new Main().run();
    }

    private void run() throws IOException {
        br = new BufferedReader(new InputStreamReader(System.in));
//        br = new BufferedReader(new FileReader("input.txt"));
        out = new PrintWriter(System.out);
        solve();
        out.close();
    }


    void init(int n, int m) {
        m *= 2;
        this.n = n;
        this.m = m;
        last = 0;
        head = new int[n];
        nx = new int[m];
        dst = new int[m];
        src = new int[m];
        cp = new int[m];
        ct = new long[m];
        fl = new int[m];
        prev = new int[n];
        heap = new int[n];
        heapRev = new int[n];
        d = new long[n];
        bestDist = new long[n];
        for (int i = 0; i < n; i++) {
            heap[i] = i;
            heapRev[i] = i;
        }
        Arrays.fill(head, -1);
    }

    void addEdge(int x, int y, int capacity, int cost) {
        nx[last] = head[x];
        src[last] = x;
        dst[last] = y;
        cp[last] = capacity;
        ct[last] = cost;
        head[x] = last;
        last++;
        nx[last] = head[y];
        src[last] = y;
        dst[last] = x;
        cp[last] = 0;
        ct[last] = -cost;
        head[y] = last;
        last++;
    }

    // Returns the total cost. Max flow value will be in field maxFlow.
    long minCostMaxFlow(int s, int t) {
        for (int i = 0; i < n; i++) {
            d[i] = INF;
        }
        d[s] = 0;
        boolean ok = false;
        while (!ok) {
            ok = true;
            for (int j = 0; j < m; j++)
                if (fl[j] < cp[j]) {
                    int x = src[j];
                    int y = dst[j];
                    if (d[x] < INF) {
                        if (d[y] > d[x] + ct[j]) {
                            d[y] = d[x] + ct[j];
                            ok = false;
                        }
                    }
                }
        }
        long res = 0;
        maxFlow = 0;
        while (true) {
            dijkstra(s);
            if (bestDist[t] == INF) break;
            {
                int i = t;
                int f = Integer.MAX_VALUE;
                while (i != s) {
                    int e = prev[i];
                    f = Math.min(f, cp[e] - fl[e]);
                    i = src[e];
                }
                if (f < 0) throw new RuntimeException();
                maxFlow += f;
                i = t;
                while (i != s) {
                    int e = prev[i];
                    fl[e] += f;
                    fl[e ^ 1] -= f;
                    if (fl[e] > cp[e]) throw new RuntimeException();
                    res += ct[e] * f;
                    i = src[e];
                }
            }
            for (int i = 0; i < n; i++) {
                d[i] += bestDist[i];
            }
        }
        return res;
    }

    private static final long INF = Long.MAX_VALUE;

    int n, m;
    int[] head;
    int[] nx;
    int[] src;
    int[] dst;
    int[] cp;
    long[] ct;
    int[] fl;
    int last;

    long[] d;
    long[] bestDist;
    int[] prev;
    int[] heap;
    int[] heapRev;
    int heapSize;
    long maxFlow;

    private void dijkstra(int start) {
        Arrays.fill(bestDist, INF);
        heapSize = n;
        bestDist[start] = 0;
        siftUp(heapRev[start]);
        for (int i = 0; i < n; i++) {
            int x = removeMin();
            if (bestDist[x] == INF) {
                break;
            }
            int j = head[x];
            while (j >= 0) {
                if (fl[j] < cp[j]) {
                    int y = dst[j];
                    long d = ct[j] + this.d[x] - this.d[y];
                    if (d < 0) {
                        throw new AssertionError("negative edge");
                    }
                    long ll = bestDist[x] + d;
                    if (bestDist[y] > ll) {
                        prev[y] = j;
                        bestDist[y] = ll;
                        siftUp(heapRev[y]);
                    }
                }
                j = nx[j];
            }
        }
    }

    private void siftUp(int i) {
        while (i > 0 && bestDist[heap[(i - 1) / 2]] > bestDist[heap[i]]) {
            swap(i, (i - 1) / 2);
            i = (i - 1) / 2;
        }
    }

    private int removeMin() {
        int res = heap[0];
        swap(0, heapSize - 1);
        heapSize--;
        int i = 0;
        while (2 * i + 1 < heapSize) {
            int j = i;
            if (bestDist[heap[2 * i + 1]] < bestDist[heap[j]]) {
                j = 2 * i + 1;
            }
            if (2 * i + 2 < heapSize && bestDist[heap[2 * i + 2]] < bestDist[heap[j]]) {
                j = 2 * i + 2;
            }
            if (i == j) break;
            swap(i, j);
            i = j;
        }
        return res;
    }

    private void swap(int i, int j) {
        int t = heap[i];
        heap[i] = heap[j];
        heap[j] = t;
        heapRev[heap[i]] = i;
        heapRev[heap[j]] = j;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.*;


public class C {	
	BufferedReader reader;
    StringTokenizer tokenizer;
    PrintWriter out;

	public void solve() throws IOException {				
		int N = nextInt();
		int M = nextInt();
		int[][] a = new int[N][M];
		for(int i = 0; i < N; i++)
			for(int j = 0; j < M; j++)
				a[i][j] = nextInt();

		int size = N*M + 2;
		int[][] cap = new int[size][size];
		int[][] cost = new int[size][size];
		int src = N*M;
		int dst = N*M+1;

		int[] dx = new int[]{-1,1,0,0};
		int[] dy = new int[]{0,0,-1,1};

		for(int i = 0; i < N; i++){
			for(int j = 0; j < M; j++){
				int index = i*M+j;
				if( (i+j) % 2 == 0){
					cap[src][index] = 1;
					for(int k = 0; k < 4; k++){
						int newx = i + dx[k];
						int newy = j + dy[k];
						if( newx < 0 || newx >= N || newy < 0 || newy >= M) continue;
						int newindex = newx*M + newy;
						cap[index][newindex] = 1;
						cost[index][newindex] = a[i][j] == a[newx][newy]? 0: 1;					
//						cost[newindex][index] = -1* cost[index][newindex];
					}
				}
				else{
					cap[index][dst] = 1;
				}
			}
		}

		MinCostMaxFlow flow = new MinCostMaxFlow();
		int result[] = flow.getMaxFlow(cap, cost, src, dst);
		if( result[0] == N*M/2 )
			out.println(result[1]);
		else
			out.println(-1);
	}

	/**
	 * @param args
	 */
	public static void main(String[] args) {
		new C().run();
	}

	public void run() {
        try {
            reader = new BufferedReader(new InputStreamReader(System.in));
            tokenizer = null;
            out = new PrintWriter(System.out);
            solve();
            reader.close();
            out.close();
        } catch (Exception e) {
            e.printStackTrace();
            System.exit(1);
        }
    }

