    }

}

//Min cost max flow algorithm using an adjacency matrix.  If you
//want just regular max flow, setting all edge costs to 1 gives
//running time O(|E|^2 |V|).
//
//Running time: O(min(|V|^2 * totflow, |V|^3 * totcost))
//
//INPUT: cap -- a matrix such that cap[i][j] is the capacity of
//          a directed edge from node i to node j
//
//   cost -- a matrix such that cost[i][j] is the (positive)
//           cost of sending one unit of flow along a 
//           directed edge from node i to node j
//
//   source -- starting node
//   sink -- ending node
//
//OUTPUT: max flow and min cost; the matrix flow will contain
//    the actual flow values (note that unlike in the MaxFlow
//    code, you don't need to ignore negative flow values -- there
//    shouldn't be any)
//
//To use this, create a MinCostMaxFlow object, and call it like this:
//
//MinCostMaxFlow nf;
//int maxflow = nf.getMaxFlow(cap,cost,source,sink);

class MinCostMaxFlow {
	boolean found[];
	int N, cap[][], flow[][], cost[][], dad[], dist[], pi[];

	static final int INF = Integer.MAX_VALUE / 2 - 1;

	boolean search(int source, int sink) {
		Arrays.fill(found, false);
		Arrays.fill(dist, INF);
		dist[source] = 0;
		while (source != N) {
			int best = N;
			found[source] = true;
			for (int k = 0; k < N; k++) {
				if (found[k]) continue;
				if (flow[k][source] != 0) {
					int val = dist[source] + pi[source] - pi[k] - cost[k][source];
					if (dist[k] > val) {
						dist[k] = val;
						dad[k] = source;
					}
				}
				if (flow[source][k] < cap[source][k]) {
					int val = dist[source] + pi[source] - pi[k] + cost[source][k];
					if (dist[k] > val) {
						dist[k] = val;
						dad[k] = source;
					}
				}		
				if (dist[k] < dist[best]) best = k;
			}
			source = best;
		}
		for (int k = 0; k < N; k++)
			pi[k] = Math.min(pi[k] + dist[k], INF);
		return found[sink];
	}

	int[] getMaxFlow(int cap[][], int cost[][], int source, int sink) {
		this.cap = cap;
		this.cost = cost;

		N = cap.length;
		found = new boolean[N];
		flow = new int[N][N];
		dist = new int[N+1];
		dad = new int[N];
		pi = new int[N];

		int totflow = 0, totcost = 0;
		while (search(source, sink)) {
			int amt = INF;
			for (int x = sink; x != source; x = dad[x])
				amt = Math.min(amt, flow[x][dad[x]] != 0 ? flow[x][dad[x]] :cap[dad[x]][x] - flow[dad[x]][x]);
			for (int x = sink; x != source; x = dad[x]) {
				if (flow[x][dad[x]] != 0) {
					flow[x][dad[x]] -= amt;
					totcost -= amt * cost[x][dad[x]];
				} else {
					flow[dad[x]][x] += amt;
					totcost += amt * cost[dad[x]][x];
				}
			}
			totflow += amt;
		}	
		return new int[]{ totflow, totcost };
	}  
}

import java.io.*;
import java.util.*;

public class Problem {

    class Rib {
        Vertex to;
        int capacity, weight, flow;
        Rib invert, next;

        Rib(Vertex to, int capacity, int weight) {
            this.to = to;
            this.capacity = capacity;
            this.weight = weight;
            this.flow = 0;
            next = null;
        }
    }

    class Vertex {
        Rib last;
        int phi, dist;
        int flow;
        boolean used;
        Rib way;

        Vertex() {
            last = null;
            phi = dist = 0;
            flow = 0;
            used = false;
            way = null;
        }
    }


    Scanner in = new Scanner(System.in);
    PrintWriter out = new PrintWriter(System.out);

    int minCostMaxFlow(Vertex[] g) {
        int n = g.length - 2;
        Vertex s, t;
        int cost = 0;

        while (true) {
            s = g[n];
            t = g[n + 1];
            dejkstra(g, s);
            if (t.way == null) break;
            int df = t.flow;
//            out.println("(" + t.dist + "-(" + s.phi + "-" + t.phi + "))*" + t.flow);
            cost += (t.dist - (s.phi - t.phi)) * t.flow;
            while (t.way != null) {
                t.way.flow += df;
                t.way.invert.flow -= df;
                t = t.way.invert.to;
//                outVertex(t, g, g[g.length - 2], g[g.length - 1]);
//                out.print(" ");
            }
//            out.println();
        }

        return cost;
    }

    void outVertex(Vertex v, Vertex[] g, Vertex s, Vertex t) {
        if (v == s) out.print("s"); else
        if (v == t) out.print("t"); else
            for (int i = 0; i < g.length; i++) {
                if (v == g[i]) out.print(i);
            }
        out.flush();
    }
    int goCnt = 0;

    void dejkstra(Vertex[] g, Vertex s) {
        for (Vertex v : g) {
            v.way = null;
            v.phi += v.dist;
            v.dist = g.length * g.length;
            v.used = false;
        }
        s.flow = g.length * g.length;
        class GoInfo {
            int dist;
            Rib rib;
            Vertex vertex;
            int ind;

            GoInfo(int dist, Vertex vertex, Rib rib, int ind) {
                this.dist = dist;
                this.vertex = vertex;
                this.rib = rib;
                this.ind = ind;
            }
        }
        class GoComp implements Comparator<GoInfo> {
            public int compare(GoInfo a, GoInfo b) {
                if (a.dist == b.dist) {
                    return a.ind - b.ind;
                }
                return a.dist - b.dist;
            }
        }
        TreeSet<GoInfo> q = new TreeSet<GoInfo>(new GoComp());
        q.add(new GoInfo(0, s, null, goCnt++));
        while (!q.isEmpty()) {
            GoInfo info = q.first();
            q.remove(info);
            Vertex v = info.vertex;
            if (v.used) continue;


//            out.print(info.dist + " [");
//            if (info.rib != null) outVertex(info.rib.invert.to, g, s, g[g.length - 1]);
//            out.print(" ");
//            outVertex(v, g, s, g[g.length - 1]);
//            out.println("]");
            v.dist = info.dist;
            v.way = info.rib;
            v.used = true;
            if (info.rib != null) v.flow = Math.min(info.rib.invert.to.flow, info.rib.capacity - info.rib.flow);
            for (Rib rib = v.last; rib != null; rib = rib.next) {
                if (rib.flow == rib.capacity) continue;
                q.add(new GoInfo(v.dist + rib.weight + (v.phi - rib.to.phi), rib.to, rib, goCnt++));
            }
        }
//        for (int i = 0; i < g.length; i++) {
//            out.print("d[");
//            outVertex(g[i], g, g[g.length - 2], g[g.length - 1]);
//            out.println("] = dist(" + g[i].dist + ") phi(" + g[i].phi + ")");
//        }
//        out.println("\n");
    }

    void addRib(Vertex from, Vertex to, int capacity, int weight) {
        Rib direct = new Rib(to, capacity, weight);
        Rib invert = new Rib(from, 0, -weight);
        direct.invert = invert;
        invert.invert = direct;
        direct.next = from.last;
        from.last = direct;
        invert.next = to.last;
        to.last = invert;
    }

    boolean inRange(int x, int min, int max) {
        return x >= min && x <= max;
    }

    Vertex[] readAndMakeGraph() {
        int n = in.nextInt();
        int m = in.nextInt();
        int[][] a = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                a[i][j] = in.nextInt();
            }
        }
        Vertex[] v = new Vertex[n * m + 2];
        for (int i = 0; i < n * m + 2; i++) v[i] = new Vertex();
        Vertex s = v[n * m];
        Vertex t = v[n * m + 1];
        for (int i = 0; i < n; i++) {
            for (int j = i % 2; j < m; j += 2) {
                for (int dx = -1; dx <= 1; dx++) {
                    for (int dy = -1; dy <= 1; dy++) {
                        if (Math.abs(dx) + Math.abs(dy) == 1) {
                            int ni = i + dx;
                            int nj = j + dy;
                            if (inRange(ni, 0, n - 1) && inRange(nj, 0, m - 1)) {
                                addRib(v[i * m + j], v[ni * m + nj], 1, (a[i][j] == a[ni][nj]? 0 : 1));
                            }
                        }
                    }
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if ((i + j) % 2 == 0) {
                    addRib(s, v[i * m + j], 1, 0);
                } else {
                    addRib(v[i * m + j], t, 1, 0);
                }
            }
        }
        v[v.length - 1].last = null;

        return v;
    }

    void solve() {
        out.print(minCostMaxFlow(readAndMakeGraph()));
        out.close();
    }

    public static void main(String[] args) {
        (new Problem()).solve();
    }
}

