    void calc(int i, int j, int cnt) {
        if (cnt < best) {
            if (i == n - 1 && j == m) {
                best = cnt;
            } else {
                if (j == m) {
                    j = 0;
                    ++i;
                }
                if (c[i][j]) {
                    calc(i, j + 1, cnt);
                } else {
                    c[i][j] = true;
                    int a = f[i][j];
                    if (j < m - 1 && !c[i][j + 1]) {
                        int b = f[i][j + 1];
                        c[i][j + 1] = true;
                        mask[a] = true;
                        calc(i, j + 2, a == b ? cnt : cnt + 1);
                        mask[a] = false;
                        /*
                        if (a != b) {
                            mask[b] = true;
                            calc(i, j + 2, cnt + 1);
                            mask[b] = false;
                        }
                        */
                        c[i][j + 1] = false;
                    }
                    if (i < n - 1 && !c[i + 1][j]) {
                        int b = f[i + 1][j];
                        c[i + 1][j] = true;
                        mask[a] = true;
                        calc(i, j + 1, a == b ? cnt : cnt + 1);
                        mask[a] = false;
                        /*
                        if (a != b) {
                            mask[b] = true;
                            calc(i, j + 1, cnt + 1);
                            mask[b] = false;
                        }
                        */
                        c[i + 1][j] = false;
