			}

			for (int i = 0; i < permLabelSz; i++) {
				int v = permLabel[i];
				pi[v] -= d[v] - d[T];
			}

			for (int v = T; v != S; ) {
				Edge last = from[v];
				last.flow++;
				last.rev.flow--;
				ans += last.cost;
				v = last.rev.to;
