import java.io.*;
import java.math.*;
import java.awt.geom.*;

import static java.lang.Math.*;

public class Solution implements Runnable {

	class Edge {

		int to, capacity, cost;
		int flow = 0;
		Edge compl = null;

		public Edge(int to, int capacity, int cost) {
			this.to = to;
			this.capacity = capacity;
			this.cost = cost;
		}

	}

	int n, m;
	Edge[][] graph;
	int[] size;

	void addEdge(int from, int to, int cost) {
		Edge e1 = new Edge(to, 1, cost);
		Edge e2 = new Edge(from, 0, -cost);
		e1.compl = e2;
		e2.compl = e1;
		graph[from][size[from]++] = e1;
		graph[to][size[to]++] = e2;
	}

	boolean inBounds(int i, int j) {
		return i >= 0 && i < n && j >= 0 && j < m;
	}

	int getIndex(int i, int j) {
		return i * m + j;
	}

	void randomShuffle(int[] arr) {
		Random rnd = new Random();
		for (int i = arr.length - 1; i >= 0; i--) {
			int pos = rnd.nextInt(i + 1);
			int temp = arr[pos];
			arr[pos] = arr[i];
			arr[i] = temp;
		}
	}

	public void solve() throws Exception {
		n = sc.nextInt();
		m = sc.nextInt();
		int[][] field = new int[n][m];

		int[] arr = new int[n * m];
		for (int i = 0; i < n * m; i += 2) {
			arr[i] = arr[i + 1] = i / 2 + 1;
		}

		randomShuffle(arr);

		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				field[i][j] = sc.nextInt();
			}
		}
		graph = new Edge[n * m + 2][20];
		size = new int[n * m + 2];
		int source = n * m;
		int sink = n * m + 1;
		graph[source] = new Edge[n * m];
		graph[sink] = new Edge[n * m];
		int gsize = n * m + 2;
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				if ((i + j) % 2 == 0) {
					addEdge(source, getIndex(i, j), 0);
					if (inBounds(i - 1, j)) {
						if (field[i - 1][j] == field[i][j]) {
							addEdge(getIndex(i, j), getIndex(i - 1, j), 0);
						} else {
							addEdge(getIndex(i, j), getIndex(i - 1, j), 1);
						}
					}
					if (inBounds(i + 1, j)) {
						if (field[i + 1][j] == field[i][j]) {
							addEdge(getIndex(i, j), getIndex(i + 1, j), 0);
						} else {
							addEdge(getIndex(i, j), getIndex(i + 1, j), 1);
						}
					}
					if (inBounds(i, j - 1)) {
						if (field[i][j - 1] == field[i][j]) {
							addEdge(getIndex(i, j), getIndex(i, j - 1), 0);
						} else {
							addEdge(getIndex(i, j), getIndex(i, j - 1), 1);
						}
					}
					if (inBounds(i, j + 1)) {
						if (field[i][j + 1] == field[i][j]) {
							addEdge(getIndex(i, j), getIndex(i, j + 1), 0);
						} else {
							addEdge(getIndex(i, j), getIndex(i, j + 1), 1);
						}
					}
				} else {
					addEdge(getIndex(i, j), sink, 0);
				}
			}
		}


		int[] dist = new int[gsize];
		int[] from = new int[gsize];
		Edge[] byEdge = new Edge[gsize];
		Deque<Integer> q = new ArrayDeque<Integer>();

		int cost = 0;
		int flow = 0;

		while (true) {
			Arrays.fill(dist, Integer.MAX_VALUE / 4);
			q.clear();
			Arrays.fill(from, -1);
			Arrays.fill(byEdge, null);
			dist[source] = 0;
			q.offer(source);
			while (!q.isEmpty()) {
				int v = q.poll();
				for (int i = 0; i < size[v]; i++) {
					Edge e = graph[v][i];
					if (e.capacity - e.flow > 0 && dist[e.to] > dist[v] + e.cost) {
						dist[e.to] = dist[v] + e.cost;
						from[e.to] = v;
						byEdge[e.to] = e;
						if (e.cost == 0) {
							q.offerFirst(e.to);
						} else {
							q.offerLast(e.to);
						}
					}
				}
			}
			if (dist[sink] == Integer.MAX_VALUE / 4) {
				break;
			}
			cost += dist[sink];
			flow++;
			int curv = sink;
			while (from[curv] != -1) {
				Edge e = byEdge[curv];
				Edge compl = e.compl;
				e.flow++;
				compl.flow--;
				curv = from[curv];
			}
		}

		out.println(cost);
	}

	static Throwable uncaught;

	BufferedReader in;
	FastScanner sc;
	PrintWriter out;

	@Override
	public void run() {
		try {
			in = new BufferedReader(new InputStreamReader(System.in));
			out = new PrintWriter(System.out);
			sc = new FastScanner(in);
			solve();
		} catch (Throwable uncaught) {
			Solution.uncaught = uncaught;
		} finally {
			out.close();
		}
	}

	public static void main(String[] args) throws Throwable {
		Thread thread = new Thread(null, new Solution(), "", (1 << 26));
		thread.start();
		thread.join();
		if (Solution.uncaught != null) {
			throw Solution.uncaught;
		}
	}

}

