	class Graph {
		final int infinity = 1500000000;
		int n, s, t;

		final int N = 80 * 80 + 100;
		final int M = 8 * N;
		int[] firstEdge = new int[N];
		{
			Arrays.fill(firstEdge, -1);
		}
		int[] edgeFrom = new int[M];
		int[] edgeTo = new int[M];
		int[] edgeCap = new int[M];
		int[] edgeCost = new int[M];
		int[] edgeFlow = new int[M];
		int[] nextEdge = new int[M];
		int[] edgeId = new int[M];
		int numEdges;

		int[] heap = new int[N];
		int[] heapWhere = new int[N];
		int[] dist = new int[N];
		int heapSize;

		int[] prev = new int[N];
		int[] phi = new int[N];

		Graph(int n) {
			this.n = n;
			s = n - 1;
			t = n - 2;			
		}
		void addEdge(int from, int to, int cap, int cost, int id) {
			int e;

			e = numEdges++;
			nextEdge[e] = firstEdge[from];
			firstEdge[from] = e;
			edgeFrom[e] = from;
			edgeTo[e] = to;
			edgeCap[e] = cap;
			edgeCost[e] = cost;
			edgeId[e] = id;

			e = numEdges++;
			nextEdge[e] = firstEdge[to];
			firstEdge[to] = e;
			edgeFrom[e] = to;
			edgeTo[e] = from;
			edgeCap[e] = 0;
			edgeCost[e] = -cost;
			edgeId[e] = id;
		}
		int minCostFlow() {			
			/*
			for (int step = 0; step < n - 1; step++) {
				for (int i = 0; i < n; i++) {
					for (int e = firstEdge[i]; e >= 0; e = nextEdge[e]) {
						int j = edgeTo[e];
						if (phi[j] > phi[i] + edgeCost[e]) {
							phi[j] = phi[i] + edgeCost[e];
						}
					}
				}
			}
			*/
			int flow = 0;
			int flowCost = 0;
			Arrays.fill(heapWhere, 0, n, -1);			
			while (true) {				
				Arrays.fill(prev, 0, n, -1);
				Arrays.fill(dist, 0, n, infinity);
				dist[s] = 0;
				heapSize = 1;
				heapWhere[s] = 0;
				heap[0] = s;
				while (heapSize > 0) {
					int v = heap[0];					
					if (heapSize > 1) {
						heapSwap(0, heapSize - 1);
						--heapSize;
						heapWhere[v] = -1;
						heapDown(0);
					} else {
						--heapSize;
						heapWhere[v] = -1;
					}
					for (int e = firstEdge[v]; e >= 0; e = nextEdge[e]) {
						if (edgeFlow[e] >= edgeCap[e]) continue;
						int u = edgeTo[e];
						if (dist[u] > dist[v] + edgeCost[e] + phi[v] - phi[u]) {
							dist[u] = dist[v] + edgeCost[e] + phi[v] - phi[u];
							prev[u] = e;
							if (heapWhere[u] < 0) {
								heapWhere[u] = heapSize++;
								heap[heapSize - 1] = u;
							}
							heapUp(heapWhere[u]);
							heapDown(heapWhere[u]);
						}
					}
				}
				if (prev[t] < 0) {
					break;
				}				
				int dCost = dist[t] + phi[t] - phi[s];
				int v = t;				
				while (v != s) {
					int e = prev[v];
					++edgeFlow[e];
					--edgeFlow[e ^ 1];
					v = edgeFrom[e];
				}
				++flow;
				flowCost += dCost;
				for (int i = 0; i < n; i++) {
					if (dist[i] < infinity) {
						phi[i] += dist[i];
					}
				}
			}
			return flowCost;
		}
		private void heapUp(int i) {
			while (i > 0) {
				int p = (i - 1) / 2;
				if (dist[i] < dist[p]) {
					heapSwap(i, p);
					i = p;
				} else {
					break;
				}
			}
		}
		private void heapDown(int i) {
			while (true) {
				int j = i;
				if (2*i + 1 < heapSize && dist[2*i + 1] < dist[j]) {
					j = 2*i + 1;
				}
				if (2*i + 2 < heapSize && dist[2*i + 2] < dist[j]) {
					j = 2*i + 2;
				}
				if (i == j) {
					break;
				} else {
					heapSwap(i, j);
					i = j;
				}
			}
		}
		private void heapSwap(int i, int j) {
			int ai = heap[i];
			int aj = heap[j];
			heapWhere[ai] = j;
			heapWhere[aj] = i;
			heap[i] = aj;
			heap[j] = ai;
		}

	}


