	void solve()
	{
		int n = ni(), m = ni();
		int[][] map = new int[n][m];
		for(int i = 0;i < n;i++){
			for(int j = 0;j < m;j++){
				map[i][j] = ni();
			}
		}

		int[][] dp = new int[n][1<<m];
		for(int i = 0;i < n;i++){
			Arrays.fill(dp[i], -99999);
		}
		dp[0] = makeRow(map[0]);
		for(int i = 1;i < n;i++){
			int[] row = makeRow(map[i]);
			for(int j = 0;j < 1<<m;j++){
				for(int k = 0;k < 1<<m;k++){ // k->j
					int inv = (~k&(1<<m)-1);
					if((inv&j) == inv){
						int nex = row[j^inv] + dp[i-1][k];
						for(int l = 0;l < m;l++){
							if(inv<<31-l<0 && map[i-1][l] == map[i][l]){
								nex++;
							}
						}
						dp[i][j] = Math.max(dp[i][j], nex);
					}
				}
			}
		}
		out.println(n*m/2-dp[n-1][(1<<m)-1]);
	}

	int[] makeRow(int[] r)
	{
		int m = r.length;
		int[] row = new int[1<<m];
		Arrays.fill(row, -99999);
		row[0] = 0;
		for(int i = 0;i < 1<<m;i++){
			for(int j = 3, k = 0;j < 1<<m;j*=2, k++){
				if((i&j) == j){
					if(row[i^j] != -99999){
						row[i] = row[i^j] + (r[k] == r[k+1] ? 1 : 0);
					}
					break;
				}
			}
		}
		return row;
	}

