	private static int magic(int ny, int nx) {
		return ny*M + nx;
	}

	static class MinCostFlow {
		  public static int MINCOSTFLOW = 0, MINCOSTMAXFLOW = 1;
		  public int s, t;
		  int N, ss, tt;
		  public long oo = (long) 1e12;
		  long[] ex;
		  ArrayList<Edge>[] adjj;
		  public Edge[][] adj;

		  public MinCostFlow(int NN) {
		    this(NN, MINCOSTMAXFLOW);
		  }

		  public MinCostFlow(int NN, int flowType) {
		    N = (tt = (ss = (t = (s = NN) + 1) + 1) + 1) + 1;
		    adj = new Edge[N][0];
		    adjj = new ArrayList[N];
		    for (int i = 0; i < N; i++)
		      adjj[i] = new ArrayList<Edge>();
		    ex = new long[N];
		    add(t, s, oo, -oo / 10 * flowType);
		  }

		  public void add(int i, int j, long cap, long cost) {
		    Edge fwd = new Edge(i, j, cap, 0, cost);
		    Edge rev = new Edge(j, i, 0, 0, -cost);
		    adjj[i].add(rev.rev = fwd);
		    adjj[j].add(fwd.rev = rev);
		  }

		  public long[] getFlow() {
		    preFlow();
		    for (int i = 0; i < N; i++)
		      adj[i] = adjj[i].toArray(adj[i]);
		    boolean[] canU = new boolean[N], hasU = new boolean[N];
		    long[] dist = new long[N], width = new long[N];
		    Edge[] prev = new Edge[N];
		    while (true) {
		      Arrays.fill(dist, oo);
		      dist[ss] = 0;
		      width[ss] = oo;
		      boolean updated = hasU[ss] = true;
		      while (updated) {
		        updated = false;
		        for (int i = 0; i < N; hasU[i++] = false)
		          canU[i] = hasU[i];
		        for (int i = 0; i < N; i++)
		          if (canU[i])
		            for (Edge e : adj[i])
		              if (e.flow != e.cap && dist[e.j] > dist[e.i] + e.cost) {
		                dist[e.j] = dist[e.i] + (prev[e.j] = e).cost;
		                width[e.j] = Math.min(width[e.i], e.cap - e.flow);
		                hasU[e.j] = updated = true;
		              }
		      }
		      if (dist[tt] >= oo)
		        break;
		      for (Edge e = prev[tt]; e != null; e = prev[e.i])
		        e.rev.flow = -(e.flow += width[tt]);
		    }
		    long flow = 0, cost = 0;
		    for (Edge e : adj[s])
		      if (e.flow > 0)
		        flow += e.flow;
		    for (int i = 0; i < N; i++)
		      for (Edge e : adj[i])
		        if (e.flow > 0 && e.i != t && e.j != s && e.i < ss && e.j < ss)
		          cost += e.flow * e.cost;
		    return new long[] { flow, cost };
		  }

		  public void preFlow() {
		    for (int i = 0; i < N; i++)
		      for (Edge e : adjj[i])
		        if (e.cost < 0 && e.cap - e.flow > 0) {
		          ex[e.i] -= e.cap - e.flow;
		          ex[e.j] += e.cap - e.flow;
		          e.rev.flow = -(e.flow = e.cap);
		        }
		    for (int i = 0; i < N; i++)
		      if (ex[i] > 0)
		        add(ss, i, ex[i], -oo);
		      else if (ex[i] < 0)
		        add(i, tt, -ex[i], -oo);
		    Arrays.fill(ex, 0);
		  }

		  public class Edge {
		    public int i, j;
		    public long cap, flow, cost;
		    Edge rev;

		    Edge(int ii, int jj, long cc, long ff, long C) {
		      i = ii;
		      j = jj;
		      cap = cc;
		      flow = ff;
		      cost = C;
		    }
		  }
		}

	static class MScanner{
