public class C {

	private void solve() throws IOException {
		long n = nextLong();

		if (n % 3 != 0) {
			println("0");
			return;
		}

		n /= 3;

		int res = 0;
		for (long i = 1; i * i * i <= n; i++) {
			if (n % i != 0) {
				continue;
			}

			for (long a = 1; a * a <= n && a + a <= i; a++) {
				long b = i - a;
				long m = n / i;
				long d = i * i - 4 * (a * b - m);

				if (d <= 0) {
					continue;
				} else {
					long sq = (long)Math.sqrt(d);
					if (sq * sq != d || sq < i || (sq - i) % 2 == 1) {
						continue;
					}

					long c = (sq - i) / 2;
					if (c < a || c < b) {
						continue;
					}

					if (a == b && a == c) {
						res++;
					} else if (a != b && a != c && b != c) {
						res += 6;
					} else {
						res += 3;
					}
				}
			}
		}

		println(res);
	}

