class TaskB {
    public void solve(int testNumber, InputReader in, OutputWriter out) {
        int n = in.nextInt(), d = in.nextInt(), i, a[] = new int[n], total = 0, j;
        for(i=0;i<n;i++) {
            a[i] = in.nextInt();
            total += a[i];
        }
        boolean canSum[] = new boolean[total+1];
        canSum[0] = true;
        for(i=0;i<n;i++) {
            for(j=total;j>=a[i];j--) {
                if(canSum[j - a[i]])
                    canSum[j] = true;
            }
        }
        int max = 0, ans = 0;
        while (true) {
            int nmax = max;
            for(i=max+1;i<=total && i<=max+d;i++) {
                if(canSum[i])
                    nmax = i;
            }
            if(nmax == max)
                break;
            ans++;
            max = nmax;
        }
        out.printLine(max +" "+ans);
    }
}

class InputReader
{
    BufferedReader in;
