public class Main {
    final static Integer MOD = 1000000009;
    public static BigInteger Com(int a,Integer n){
        if(a==0) return BigInteger.ONE;
        if(a==n) return BigInteger.ONE;
        BigInteger fenz = new BigInteger(n.toString());
        BigInteger fenm = BigInteger.ONE;
        //System.out.println(fenz + " "+fenm);
        for(int i=1;i<a; i++){
            n--;
            BigInteger next = new BigInteger(n.toString());
            //System.out.println(next);
            fenz = fenz.multiply(next);
            //System.out.println(fenz);

        }
        for(Integer i=2;i<=a;i++){
            BigInteger next = new BigInteger(i.toString());
            fenm = fenm.multiply(next);
        }
        return fenz.divide(fenm);
    }
    public static void main(String[] args){
        Scanner in = new Scanner(System.in);
        BigInteger BigMod = new BigInteger(MOD.toString());
        while(in.hasNextInt()){
            int n = in.nextInt() ;
            int w = in.nextInt();
            int b = in.nextInt();
            //System.out.println(n+" "+w+" "+b);
            //BigInteger  res = BigInteger.ZERO;
            long res = 0;
            int Bnum = b;

                if(w < 2) continue;
                long fact_w = fact(w);
                long len_w = w - 1;
                long fact_b = fact(Bnum);
                res = res + ( fact_w * len_w ) % MOD ;
                res = (res * fact_b) % MOD;
                BigInteger mul = Com(n-3,b-1+w-2);
                //System.out.println(n-2+""mul);
                mul = mul.mod(BigMod);
                //System.out.println(mul); 
                String smul = mul.toString();
                res = res * Integer.parseInt(smul) % MOD;

            System.out.println(res);
        }
    }
    private static long fact(int wnum) {
        long ans=1;
        for(int i=1;i<=wnum;i++){
            ans*=i;
            ans%=MOD;
        }
        return ans;
    }
}

