public class Prob_Hanoi{
    public static long V[][];
    public static boolean Visited[][][];
    public static long MEMO[][][];
    public static void main(String args[]){
        Scanner input=new Scanner(System.in);
        V=new long[3][];
        V[0]=new long[3];
        V[1]=new long[3];
        V[2]=new long[3];
        for(int i=0;i<3;i++){
            for(int j=0;j<3;j++){
                V[i][j]=input.nextLong();
            }
        }
        int n=input.nextInt();
        Visited=new boolean[n+1][][];
        MEMO=new long[n+1][][];
        for(int i=0;i<=n;i++){
            Visited[i]=new boolean[3][];
            MEMO[i]=new long[3][];
            for(int j=0;j<3;j++){
                Visited[i][j]=new boolean[3];
                for(int k=0;k<3;k++){
                    Visited[i][j][k]=false;
                }
                MEMO[i][j]=new long[3];
            }
        }
        onlyOne();        
        for(int i=1;i<n;i++){
            for(int j=0;j<3;j++){
                for(int k=0;k<3;k++){
                    if(j!=k){
                     //   System.out.println(i+""+j+""+k+")="+DP(i,j,k));                        
                    }
                }
            }
        }
        System.out.println(DP(n,0,2));

    }
    public static void onlyOne(){
        for(int i=0;i<3;i++){
            for(int j=0;j<3;j++){
                    if(i==j) continue;
                    int k=0+1+2-i-j;
                    MEMO[1][i][j]=Math.min(V[i][j],V[i][k]+V[k][j]);
                    Visited[1][i][j]=true;
            }
        }
    }
    public static long DP(int n,int i,int j){
        if(Visited[n][i][j])
            return MEMO[n][i][j];
        int k=0+1+2-i-j;
        MEMO[n][i][j]=Math.min(DP(n-1,i,k)+V[i][j]+DP(n-1,k,j),
                               DP(n-1,i,j)+V[i][k]+DP(n-1,j,i)+V[k][j]+DP(n-1,i,j)); 
       Visited[n][i][j]   =true;
       return MEMO[n][i][j];
    }
}

