public class CF946F extends PrintWriter {
	CF946F() { super(System.out, true); }
	Scanner sc = new Scanner(System.in);
	public static void main(String[] $) {
		CF946F o = new CF946F(); o.main(); o.flush();
	}

	static final int MD = 1000000007;
	long power(int a, int k) {
		if (k == 0)
			return 1;
		long p = power(a, k >> 1);
		p = p * p % MD;
		if ((k & 1) == 1)
			p = p * a % MD;
		return p;
	}
	void main() {
		int n = sc.nextInt();
		int x = sc.nextInt();
		byte[] cc = sc.next().getBytes();
		if (x == 0) {
			println(n == 1 && cc[0] == '0' ? 1 : 0);
			return;
		}
		int[] ff = new int[x + 1];
		ff[0] = ff[1] = 1;
		for (int i = 2; i <= x; i++)
			ff[i] = (ff[i - 1] + ff[i - 2]) % (MD - 1);
		for (int i = 0; i <= x; i++)
			ff[i] = (int) power(2, ff[i]);
		int[][][] ds = new int[x + 1][n][n + 1];
		for (int l = 0; l < n; l++) {
			ds[0][l][l] = ds[1][l][l] = 1;
			ds[0][l][l + 1] = cc[l] == '0' ? 1 : 0;
			ds[1][l][l + 1] = cc[l] == '1' ? 1 : 0;
		}
		for (int i = 2; i <= x; i++)
			for (int l = 0; l < n; l++)
				for (int r = l; r < n; r++) {
					long z = 0;
					for (int m = l; m <= r; m++)
						z = (z + (long) ds[i - 1][l][m] * ds[i - 2][m][r]) % MD;
					ds[i][l][r] = (int) z;
				}
		int[][] dp = new int[x + 1][n];
		int[][] dq = new int[x + 1][n];
		if (n > 1) {
			dp[0][n - 1] = ds[0][n - 1][n];
			dp[1][n - 1] = ds[1][n - 1][n];
			for (int i = 2; i <= x; i++)
				for (int l = 1; l < n; l++) {
					long z = (long) dp[i - 1][l] * ff[i - 2] % MD;
					for (int m = l; m < n; m++)
						z = (z + (long) ds[i - 1][l][m] * dp[i - 2][m]) % MD;
					dp[i][l] = (int) z;
				}
			dq[0][1] = ds[0][0][1];
			dq[1][1] = ds[1][0][1];
			for (int i = 2; i <= x; i++)
				for (int r = 1; r < n; r++) {
					long z = (long) ff[i - 1] * dq[i - 2][r] % MD;
					for (int m = r; m > 0; m--)
						z = (z + (long) dq[i - 1][m] * ds[i - 2][m][r]) % MD;
					dq[i][r] = (int) z;
				}
		}
		int[] dr = new int[x + 1];
		dr[0] = ds[0][0][n];
		dr[1] = ds[1][0][n];
		for (int i = 2; i <= x; i++) {
			long z = ((long) dr[i - 1] * ff[i - 2] + (long) ff[i - 1] * dr[i - 2]) % MD;
			for (int m = 1; m < n; m++)
				z = (z + (long) dq[i - 1][m] * dp[i - 2][m]) % MD;
			dr[i] = (int) z;
		}
		println(dr[x]);
	}
}

import java.io.*;
import java.util.Arrays;
import java.util.Locale;
import java.util.StringTokenizer;
import java.util.function.Function;

public class E {
    String fileName = "E";

    public int n, m;

    public static class Event implements Comparable<Event> {
        public static final int OPEN_TYPE = 0;
        public static final int POINT_TYPE = 1;
        public static final int CLOSE_TYPE = 2;

        public int x, type;

        public Event(int x, int type) {
            this.x = x;
            this.type = type;
        }

        @Override
        public int compareTo(Event event) {
            if (Integer.compare(x, event.x) != 0)
                return Integer.compare(x, event.x);
            else return Integer.compare(type, event.type);
        }
    }

    public static final class Node {
        public int l, r;
        public int max, maxInd;

        public Node leftNode, rightNode;

        public Node(int l, int r) {
            this.l = l;
            this.r = r;
        }
    }

    public void relax(Node root) {
        if (root.leftNode.max > root.rightNode.max) {
            root.max = root.leftNode.max;
            root.maxInd = root.leftNode.maxInd;
        } else {
            root.max = root.rightNode.max;
            root.maxInd = root.rightNode.maxInd;
        }
    }

    public Node build(int l, int r, Function<Integer, Integer> getItem) {
        Node res = new Node(l, r);
        if (l == r) {
            res.max = getItem.apply(l);
            res.maxInd = l;
        } else {
            int m = (r + l) / 2;
            res.leftNode = build(l, m, getItem);
            res.rightNode = build(m + 1, r, getItem);
            relax(res);
        }
        return res;
    }

    public void set(Node root, int ind, int val) {
        if (ind < root.l || ind > root.r)
            return;
        if (root.l == root.r) {
            root.max = val;
            return;
        }
        set(root.leftNode, ind, val);
        set(root.rightNode, ind, val);
        relax(root);
    }

    public static class QueryResult {
        public int max, maxInd;

        public QueryResult(int max, int maxInd) {
            this.max = max;
            this.maxInd = maxInd;
        }

        public QueryResult(QueryResult first, QueryResult second) {
            if (first.max > second.max) {
                this.max = first.max;
                this.maxInd = first.maxInd;
            } else {
                this.max = second.max;
                this.maxInd = second.maxInd;
            }
        }
    }

    public QueryResult query(Node root, int l, int r) {
        if (r == -1)
            return new QueryResult(0, -1);
        if (r < root.l || l > root.r)
            return new QueryResult(Integer.MIN_VALUE, -1);
        if (l <= root.l && r >= root.r) {
            return new QueryResult(root.max, root.maxInd);
        }
        return new QueryResult(query(root.leftNode, l, r), query(root.rightNode, l, r));
    }

    public int[] getLens(int[] a) {
        Node root = build(0, n, ind -> 0);
        int[] len = new int[a.length];
        for (int i = 0; i < a.length; i++) {
            int curVal = a[i];
            int prevLen = query(root, 0, curVal).max;
            len[i] = prevLen + 1;
            if (query(root, curVal, curVal).max < len[i])
                set(root, curVal, len[i]);
        }
        return len;
    }

    public void solve() throws IOException {
        n = nextInt();
        m = nextInt();
        Event[] events = new Event[2 * n + m];
        for (int i = 1; i <= m; i++) {
            events[i - 1] = new Event(i, Event.POINT_TYPE);
        }
        for (int i = 0; i < n; i++) {
            int l = nextInt();
            int r = nextInt();
            events[m + 2 * i] = new Event(l, Event.OPEN_TYPE);
            events[m + 2 * i + 1] = new Event(r, Event.CLOSE_TYPE);
        }
        Arrays.sort(events);
        int[] cnt = new int[m];
        int balance = 0;
        for (int i = 0; i < events.length; i++) {
            Event curEvent = events[i];
            if (curEvent.type == Event.OPEN_TYPE) {
                balance++;
            } else if (curEvent.type == Event.CLOSE_TYPE) {
                balance--;
            } else if (curEvent.type == Event.POINT_TYPE) {
                cnt[curEvent.x - 1] = balance;
            }
        }
        int[] lenUp = getLens(cnt);
        int[] newCnt = new int[cnt.length];
        for (int i = 0; i < cnt.length; i++) {
            newCnt[i] = cnt[cnt.length - i - 1];
        }
        int[] lenDown = getLens(newCnt);
        int[] revLenDown = new int[lenDown.length];
        for (int i = 0; i < lenDown.length; i++) {
            revLenDown[i] = lenDown[lenDown.length - i - 1];
        }
        int max = 0;
        for (int i = 0; i < lenDown.length; i++) {
            int cur = lenUp[i] + revLenDown[i] - 1;
            max = Math.max(max, cur);
        }
        out.print(max);
    }

    public void run() {
        try {
            br = new BufferedReader(new InputStreamReader(System.in));
            out = new PrintWriter(System.out);

            solve();

            out.close();
        } catch (IOException e) {
            e.printStackTrace();
            System.exit(1);
        }
    }

    BufferedReader br;
    StringTokenizer in;
    PrintWriter out;

    public String nextToken() throws IOException {
        while (in == null || !in.hasMoreTokens()) {
            in = new StringTokenizer(br.readLine());
        }
        return in.nextToken();
    }

    public int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    public double nextDouble() throws IOException {
        return Double.parseDouble(nextToken());
    }

    public long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }

    public static void main(String[] args) throws IOException {
        Locale.setDefault(Locale.US);
        new E().run();
    }
}

