    }

    static long bin(long a, long b){
        if(a==b) return a;
        if(b==a+1) return check(a) ? a : b;
        long m = (a+b)/2;
        return check(m) ? bin(a, m) : bin(m+1, b);
    }

    static boolean check(long X){
        long A = a - count(X), C = c-X;
        return C <= A;
    }

    static long count(long X){
        if(X<=P) return simulation((int)X);
        long res = 1L*S*(X/P);
        return res + count(X % P);
    }

    static int simulation(int X){
        int num = 0;
        int B = b;
        for(int i=0; i<X; i++){
            if(B>=x){
                B -= x;
            }
            else{
                B -= x;
                B += w;
                num++;
            }
        }
        return num;
    }

    static void countPeriods(){
        int curB = b;
        boolean first = true;
        while(true){
            if(curB==b && !first) break;
            first = false;
            if(curB >= x){
                curB -= x;
                P++;
            }
            else{
                P++;
                S++;
                curB -= x;
                curB += w;
            }
        }
    }

    static int P, S;

    static int a, b, w, x, c;

}

