public class tr0 {
	static StringBuilder sb;
	static int inf = (int) 1e9;
	static int mod = 998244353;
	static int n, m, k;
	static ArrayList<Integer>[] ad;
	static long[] f, inv, memo[];
	static PrintWriter out;

	public static void main(String[] args) throws Exception {
		Scanner sc = new Scanner(System.in);
		out = new PrintWriter(System.out);
		n = sc.nextInt();
		k = sc.nextInt();
		memo = new long[n + 5][k + 5];
		f = new long[n + 4];
		inv = new long[n + 4];
		f[0] = 1;
		inv[0] = 1;
		for (int i = 1; i < f.length; i++) {
			f[i] = (i * f[i - 1]) % mod;
			inv[i] = modPow(f[i], mod - 2);
		}
		for (long[] a : memo)
			Arrays.fill(a, -1);
		out.println(dp(0, 1));
		out.flush();
	}

	static long dp(int i, int ck) {
		if (i == n - 1)
			return f[n - 1];
		if (ck > k)
			return 0;

		if (memo[i][ck] != -1)
			return memo[i][ck];
		long ans = dp(i, ck + 1);
		for (int j = 1; true; j++) {
			if (i + j > n - 1)
				break;
			long tem = (dp(i + j, ck + 1) * inv[j]) % mod;
			tem = (tem * modPow(k - ck + 1, (j * (j - 1) / 2) + j * i)) % mod;
			ans += tem;
			ans %= mod;
		}
		return memo[i][ck] = ans;
	}

	static long modPow(long a, long e)

	{
		long res = 1;
		while (e > 0) {
			if ((e & 1) == 1)
				res = (res * a) % mod;
			a = (a * a) % mod;
			e >>= 1;
		}
		return res;
	}

