public class Sum {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        String v1 = sc.next();
        String v2 = sc.next();

        int max = 0;
        max = getMaxDigit(v1);
        max = max > getMaxDigit(v2) ? max : getMaxDigit(v2) ;

        int base = max +1;
//      System.out.println(base);


        int number1 = Integer.parseInt(v1, base);
        int number2 = Integer.parseInt(v2, base);

        int sum = number1 + number2;
        System.out.println(Integer.toString(sum, base).length());

    }

    private static int getMaxDigit(String number) {

        int max =0;

        for(int i =0 ; i< number.length(); i++){
            int v = number.charAt(i) - '0' ;
            if(v > max) max = v;
        }
        return max;
    }

}

