public class Abood2D {

	static int n, min[], G[], pG[];

	static int solve(int c) {
		if(G[c] != -1)
			return G[c];

		HashSet<Integer> set = new HashSet<>();

		min[c] = c;

		for (int i = 2, j = 3; j <= c; j += ++i) 
			if((c - j) % i == 0) {
				int l = 1 + (c - j) / i;
				int r = i + (c - j) / i;

				int x = pG[r] ^ pG[l - 1];

				if(x == 0)
					min[c] = Math.min(min[c], i);

				set.add(x);
			}

		int ans = 0;
		while(set.contains(ans))ans++;

		return G[c] = ans;

	}
	public static void main(String[] args) throws IOException {
		Scanner sc = new Scanner(System.in);
		PrintWriter out = new PrintWriter(System.out);

		n = sc.nextInt();

		G = new int[(int) 1e6 + 1];
		pG = new int[(int) 1e6 + 1];
		min = new int[(int) 1e6 + 1];

		Arrays.fill(G, -1);

		for (int i = 1; i <= n; i++) 
			pG[i] = pG[i - 1] ^ solve(i);

		if(G[n] != 0)
			out.println(min[n]);
		else
			out.println(-1);

		out.flush();

	}



