public class AbilityToConvert {
    public static InputReader in;
    public static PrintWriter out;

    public static final int myMotivation = 0;
    public static final int MOD = (int) (1e9 + 7);
    public static final long INF = (long) (2e18);

    public static int len, n;
    public static char[] num;
    public static long[] memo;
    public static void main(String[] args) {
	in = new InputReader(System.in);
	out = new PrintWriter(System.out);

	n = in.nextInt();
	len = Integer.toString(n).length();	
	num = ("$" + in.readString()).toCharArray();

	memo = new long[num.length];
	Arrays.fill(memo, -1);
	memo[0] = 0;
	solve(num.length - 1);
	out.println(memo[num.length - 1]);

	out.close();
    }

    public static void solve(int idx) {
	if(idx < 0 || memo[idx] != -1) {
	    return;
	}
	solve(idx - 1);
	long result = INF;
	for (int size = 1; size <= Math.min(len, idx); size++) {
	    long curr = Long.parseLong(new String(num, idx - size + 1, size));
	    solve(idx - size);
	    if(curr >= n || (size > 1 && num[idx - size + 1] == '0')) {
		continue;
	    }
	    result = Math.min(result, add(mul(memo[idx - size], n), curr)); 
	}
	memo[idx] = result;
    }

    public static long add(long a, long b) {
	return Math.min(a + b, INF);
    }

    public static long mul(long a, long b) {
	if(a == 0 || b == 0) {
	    return 0;
	}
	long m = a*b;
	if(m%a == 0 && m%b == 0) {
	    return Math.min(m, INF);
	}
	return INF;
    }

