                long right = 2*k-1;
                int count = 0;
                while(ptr+count < n){
                    if(depths[ptr+count] >= k) break;
                    long templ = k-depths[ptr+count];
                    long tempr = k+depths[ptr+count];
                    templ+=count;
                    tempr+=count;
                    if(templ > right || tempr < left){
