public class LittleCLoves3II {
    void solve() {
        long n = in.nextInt(), m = in.nextInt();
        if (n > m) {
            long tmp = n; n = m; m = tmp;
        }

        if (n == 1) {
            out.println(m / 6 * 6 + Math.max(m % 6 - 3, 0) * 2);
            return;
        }

        if (n == 2) {
            if (m == 2) out.println(0);
            else if (m == 3) out.println(4);
            else if (m == 7) out.println(12);
            else out.println(n * m);
            return;
        }

