public class Test {

    static int readInt() {
        int ans = 0;
        boolean neg = false;
        try {
            boolean start = false;
            for (int c = 0; (c = System.in.read()) != -1; ) {
                if (c == '-') {
                    start = true;
                    neg = true;
                    continue;
                } else if (c >= '0' && c <= '9') {
                    start = true;
                    ans = ans * 10 + c - '0';
                } else if (start) break;
            }
        } catch (IOException e) {
        }
        return neg ? -ans : ans;
    }

    static long readLong() {
        long ans = 0;
        boolean neg = false;
        try {
            boolean start = false;
            for (int c = 0; (c = System.in.read()) != -1; ) {
                if (c == '-') {
                    start = true;
                    neg = true;
                    continue;
                } else if (c >= '0' && c <= '9') {
                    start = true;
                    ans = ans * 10 + c - '0';
                } else if (start) break;
            }
        } catch (IOException e) {
        }
        return neg ? -ans : ans;
    }

    static String readLine() {
        StringBuilder b = new StringBuilder();
        try {
            for (int c = 0; (c = System.in.read()) != -1; ) {
                if (c == '\n') {
                    break;
                } else {
                    b.append((char) (c));
                }
            }
        } catch (IOException e) {
        }
        return b.toString().trim();
    }

    static PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

    int gcd(int a, int b) {
        if (b == 0) return a;
        return gcd( b, a % b);
    }

    int SZ = 200_000;

    void start() {
        Set<Long> seen = new HashSet<>();
        TreeMap<Long, Integer> cnt = new TreeMap<>();
        int m = readInt(), a = readInt(), b = readInt();
        PriorityQueue<long[]> q = new PriorityQueue<>(1, (x, y) -> Long.compare(x[1], y[1]));
        q.offer(new long[]{0, 0});
        seen.add(0L);
        cnt.put(0L, 1);
        while (!q.isEmpty() && seen.size() < SZ) {
            long[] e = q.poll();
            long v = e[0], r = e[1];
            long nv = v + a;
            if (!seen.contains(nv)) {
                seen.add(nv);
                long nr = Math.max(nv, r);
                cnt.put(nr, cnt.getOrDefault(nr, 0) + 1);
                q.offer(new long[]{nv, nr});
            }
            nv = v - b;
            if (nv > 0 && !seen.contains(nv)) {
                seen.add(nv);
                cnt.put(r, cnt.getOrDefault(r, 0) + 1);
                q.offer(new long[]{nv, r});
            }
        }
        long ans = 0, pk = 0, pc = 0;
        for (long k : cnt.keySet()) {
            if (k > m) break;
            int c = cnt.get(k);
            ans += (c + pc);
            ans += pc*(k - pk - 1);
            pc += c;
            pk = k;
        }
        int d = gcd(a, b);
        if (pk < m) {
            if (seen.size() >= m) ans += pc*(m - pk);
            else {
                long d0 = (pk + d) / d, d1 = m / d;
                ans += pc * (m - pk);
                ans += (1 + d1 - d0 + 1) * (d1 - d0 + 1) / 2 * d;
                ans += (m - d1*d + 1 - d)*(d1 - d0 + 1);
            }
        }
        writer.println(ans);
     }

    public static void main(String[] args) {
        Test te = new Test();
        te.start();
        writer.flush();
    }
}

