public class A {
	static long nCk(long n, long k) {
		if (k > n)
			return 0;
		if (k * 2 > n)
			k = n - k;
		if (k == 0)
			return 1;

		long result = n;
		for (int i = 2; i <= k; ++i) {
			result *= (n - i + 1);
			result /= i;
		}
		return result;
	}

	public static void main(String[] args) throws Exception {
		BufferedReader bf = new BufferedReader(new InputStreamReader(System.in));
		long n = Long.parseLong(bf.readLine());
		System.out.println(4 * 3 * 2 * pow(4, n - 3) + (n - 3) * 4 * 9
				* pow(4, n - 4));
	}

	private static long pow(long i, long l) {
		if (l < 0)
			return 0;
		if (l == 0)
			return 1;
		return i * pow(i, l - 1);
	}
}

