		int[] per = new int[n];
		int n_flag=0;
		for(int i=0 ; i<m-1 ; i++)
		{
			int dif = arr[i+1]-arr[i];
			if(dif<=0)
				dif+=n;
			if(per[arr[i]-1]!=0 && per[arr[i]-1]!=dif)
			{
				n_flag=2;
				break;
			}
			per[arr[i]-1] = dif;
		}
		per = complete(per);
		if(repeat(per)==true || n_flag==2)
		{
			System.out.println(-1);
		}
		else
		{
			for(int i=0 ; i<per.length ; i++)
			{
				System.out.print(per[i]+" ");
			}
		}
	}
	public static int[] complete(int[] A)
	{
		int[] B = new int[A.length];
		for(int i=0 ; i<B.length ; i++)
		{
			B[i]=i+1;
		}
		for(int i=0 ; i<A.length ; i++)
		{
			int j=0;
			if(A[i]==0)
			{
				while(contains(A,B[j])!=false && j<B.length)
				{
					j++;
				}
				if(contains(A,B[j])==false)
				{
					A[i] = B[j];
				}
			}
		}
		return A;
	}
	public static boolean contains(int[] A, int x)
	{
		for(int i=0 ; i<A.length ; i++)
		{
			if(A[i]==x)
				return true;
		}
		return false;
	}
	public static boolean repeat(int[] per)
	{
		int[] B = new int[per.length];
		for(int i=0 ; i<B.length ; i++)
		{
			B[i] = per[i];
		}
		Arrays.sort(B);
		for(int i=0 ; i<B.length-1 ; i++)
		{
			if(B[i]==B[i+1])
				return true;
		}
		return false;
	}
}

