					int ways = 1;
					for (int pick = 1; j + pick <= 6 && k + pick * i <= 9 && pick <= cnt[i]; pick++) {
						ways = (int)((long)ways * (cnt[i] - pick + 1) % MOD);
						dp[j + pick][k + pick * i] += (int)((long)dp[j][k] * ways % MOD * c[6 - j][pick] % MOD);
						if (dp[j + pick][k + pick * i] >= MOD)
							dp[j + pick][k + pick * i] -= MOD;
					}
				}
		}		

		int[] res = dp[6];

		int sum = 0;

		int ans = 0;

		for (int i = 1; i < cnt.length; i++) {
			sum += res[i - 1];
			if (sum >= MOD)
				sum -= MOD;
			ans += (int)((long)sum * cnt[i] % MOD);
			if (ans >= MOD)
				ans -= MOD;
		}

