    public static void main(String[] args) {
        int n = sc.nextint();
        int mod = sc.nextint();
        long[] dp1 = new long[n + 9];
        long[] dp2 = new long[n + 9];
        dp2[1] = 1;
        for(int i = 1; i <= n; i++){
            dp1[i] += dp1[i - 1];
            dp1[i] %= mod;
            dp2[i] = dp1[i];
            if(i == 1){
                dp2[i] = 1;
            }
            dp1[i + 1] += dp2[i];
            dp1[i + 1] %= mod;
            for(int j = 2; i * j <= n; j++){
                dp1[i * j] += dp2[i];
                dp1[i * j] %= mod;
                if((i + 1) * j <= n) {
                    dp1[(i + 1) * j] += mod - dp2[i];
                    dp1[(i + 1) * j] %= mod;
                }
            }
        }
        out.print(dp2[n]);
        out.close();
    }
