    void solve() throws IOException
    {
        n = nextInt();
        T = nextInt();
        as = new char[n][];
        bs = new char[n][];
        for(int i = 0; i < n; i++) as[i] = next().toCharArray();
        for(int i = 0; i < n; i++) bs[i] = next().toCharArray();
        vs = new boolean[n][n][T + 1];
        for(int i = 0; i < n; i++)
            for(int j = 0; j < n; j++)
                vs[i][j][0] = as[i][j] < '0' || as[i][j] > '9';
        for(int t = 1; t <= T; t++)
            for(int i = 0; i < n; i++)
                for(int j = 0; j < n; j++)
                {
                    if(vs[i][j][t - 1])
                    {
                        vs[i][j][t] = true;
                        continue;
                    }

                    for(int dx = -1; dx <= 1; dx++)
                        for(int dy = -1; dy <= 1; dy++)
                        {
                            if(abs(dx) + abs(dy) != 1) continue;

                            int px = i + dx;
                            int py = j + dy;
                            if(px < 0 || px >= n || py < 0 || py >= n) continue;

                            if(vs[px][py][t - 1] && as[px][py] != 'Y') vs[i][j][t] = true;
                        }
                }
        N = n * n;
        m = n * n * 2 + 2;
        cap = new int[m][m];
        st = m - 2;
        en = m - 1;
        //print(as[0][0]);
        for(int i = 0; i < n; i++)
            for(int j = 0; j < n; j++)
                if(as[i][j] >= '0' && as[i][j] <= '9') BFS(i * n + j, as[i][j] - '0');

        for(int i = 0; i < n; i++)
            for(int j = 0; j < n; j++)
                if(as[i][j] >= '0' && as[i][j] <= '9') cap[st][i * n + j] = as[i][j] - '0';
        for(int i = 0; i < n; i++)
            for(int j = 0; j < n; j++)
                if(bs[i][j] >= '0' && bs[i][j] <= '9') cap[i * n + j + N][en] = bs[i][j] - '0';

        //for(int i = 0; i < m - 2; i++)
        //  for(int j = 0; j < m - 2; j++)
        //      if(cap[i][j] > 0) print(i, j);

        out.println(runflow(st, en));
    }
    int[][] cap;
    int runflow(int st, int en)
    {
        int res = 0;
        while(true)
        {
            int flow = maxflow(st, en, INF, new boolean[m]);
            if(flow == 0) break;
            res += flow;
        }
        return res;
    }

    int maxflow(int st, int en, int curflow, boolean[] vs)
    {
        if(st == en) return curflow;

        for(int i = 0; i < m; i++)
            if(cap[st][i] > 0 && !vs[i])
            {
                vs[i] = true;
                int flow = maxflow(i, en, min(curflow, cap[st][i]), vs);
                if(flow > 0)
                {
                    cap[st][i] -= flow;
                    cap[i][st] += flow;
                    return flow;
                }
            }
        return 0;
    }
    int N;
    int INF = 1 << 20;  
    void BFS(int st, int val)
    {
        Queue<Integer> q = new LinkedList<Integer>();
        int[] dist = new int[m];
        fill(dist, INF);
        q.offer(st);
        dist[st] = 0;
        if(bs[st / n][st % n] > '0' && bs[st / n][st % n] <= '9') cap[st][st + N] = val;
        while(!q.isEmpty())
        {
            int u = q.poll();
            if(dist[u] >= T) continue;


            int x = u / n, y = u % n;
            for(int dx = -1; dx <= 1; dx++)
                for(int dy = -1; dy <= 1; dy++)
                {
                    if(abs(dx) + abs(dy) != 1) continue;
                    int tx = x + dx;
                    int ty = y + dy;

                    if(tx < 0 || tx >= n || ty < 0 || ty >= n) continue;

                    if(vs[tx][ty][dist[u]]) continue;
                    int v = tx * n + ty;
                    if(!vs[tx][ty][dist[u] + 1])
                    {
                        if(dist[v] > dist[u] + 1)
                        {
                            dist[v] = dist[u] + 1;
                            q.offer(v);
                            cap[st][v + N] = val;
                        }
                    }
                    else if(bs[tx][ty] > '0' && bs[tx][ty] <= '9') cap[st][v + N] = val;
                }
        }
    }
    int m, st, en;
    char[][] as, bs;
    boolean[][][] vs;
    int n, T;



