    static void bfs(int x0, int y0) {
        danger = new int[n][n];
        for (int i = 0; i < n; i++)
            Arrays.fill(danger[i], -1);
        danger[x0][y0] = 0;

        Pair[] q = new Pair[nn];
        int i = 0;
        q[i++] = new Pair(x0, y0);
        for (int j = 0; j < i; j++) {
            Pair fi = q[j];
            for (int[] dir : dirs) {
                int x = fi.x + dir[0];
