    static void go(int t, int x0, int y0, int x1, int y1) {
        if (dp[t][x0][y0][x1][y1] != -1)
            return;

        if (t == 0) {
            if (x0 == x1 && y0 == y1)
                dp[t][x0][y0][x1][y1] = 2;
            else
                dp[t][x0][y0][x1][y1] = 0;
            return;
        }

        if (danger[x1][y1] != -1 && danger[x1][y1] < t) {
            dp[t][x0][y0][x1][y1] = 0;
            return;
        }

        int val = dp[t - 1][x0][y0][x1][y1];
        for (int[] dir : dirs) {
            int x = x1 + dir[0];
            int y = y1 + dir[1];
            if (x >= 0 && x < n && y >= 0 && y < n && a[x][y] < 'Y')
                val |= dp[t - 1][x0][y0][x][y];
        }

//        dbg(t, x0, y0, x1, y1, dp[t][x0][y0][x1][y1]);

        if ((val & 2) == 2)
            dp[t][x0][y0][x1][y1] = 2;
        else
            dp[t][x0][y0][x1][y1] = 0;

        if (dp[t][x0][y0][x1][y1] == 2 && danger[x1][y1] == t)
            dp[t][x0][y0][x1][y1] = 1;
    }


    static class FordFulkerson {
        int n;
        int[][] c;

        FordFulkerson(int[][] c) {
            this.c = c;
            n = c.length;
        }

        int findMaxFlow(int s, int t) {
            int[][] c1 = new int[n][n];
            for (int v = 0; v < n; v++)
                for (int u = 0; u < n; u++)
                    c1[v][u] = c[v][u];

            int maxFlow = 0;
            int[] par = new int[n];
            while (bfs(s, t, c1, par)) {
                int delta = oo;
                int v = t;
                while (v != s) {
                    int u = par[v];
                    delta = Math.min(delta, c1[u][v]);
                    v = u;
                }
                v = t;
                while (v != s) {
                    int u = par[v];
                    c1[u][v] -= delta;
                    c1[v][u] += delta;
                    v = u;
                }
                maxFlow += delta;
            }

            return maxFlow;
        }

        boolean bfs(int s, int t, int[][] c1, int[] par) {
            int[] q = new int[n];
            int i = 0;
            q[i++] = s;
            int[] d = new int[n]; Arrays.fill(d, -1);
            d[s] = 0;
            for (int j = 0; j < i; j++) {
                int v = q[j];
                for (int u = 0; u < n; u++) {
                    if (d[u] == -1 && c1[v][u] > 0) {
                        par[u] = v;
                        q[i++] = u;
                        d[u] = d[v] + 1;
                    }
                }
            }
            return d[t] != -1;
        }
