    static class TaskE {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.nextInt(), t = in.nextInt();
            char[][] scientists = in.nextCharArray2(n, n), capsules = in.nextCharArray2(n, n);
            boolean[][] table = new boolean[n][n];
            int x0 = -1, y0 = -1;
            for (int i = 0; i < n; i++)
                for (int j = 0; j < n; j++) {
                    table[i][j] = Character.isDigit(scientists[i][j]);
                    if (scientists[i][j] == 'Z') {
                        x0 = i;
                        y0 = j;
                    }
                }
            int n2 = n * n, N = 2 * n2 + 2, sink = N - 1, source = sink - 1;
            ArrayList<MaxFlowDinic.Edge>[] graph = new ArrayList[N];
            for (int i = 0; i < N; i++) graph[i] = new ArrayList<>();
            for (int i = 0; i < n; i++)
                for (int j = 0; j < n; j++)
                    MaxFlowDinic.addEdge(graph, source, i * n + j, table[i][j] ? scientists[i][j] - '0' : 0);
            for (int i = 0; i < n; i++)
                for (int j = 0; j < n; j++)
                    MaxFlowDinic.addEdge(graph, n2 + i * n + j, sink, table[i][j] ? capsules[i][j] - '0' : 0);
            for (int i = 0; i < n; i++)
                for (int j = 0; j < n; j++)
                    for (int k = 0; k < n; k++)
                        for (int l = 0; l < n; l++)
                            if (f(table, i, j, k, l, x0, y0, t)) {
                                if (table[i][j] && table[k][l] && scientists[i][j] != '0' && capsules[k][l] != '0')
                                    System.err.println(i + " " + j + " " + k + " " + l);
                                MaxFlowDinic.addEdge(graph, i * n + j, n2 + k * n + l, Integer.MAX_VALUE);
                            }
            int ans = MaxFlowDinic.maxFlow(graph, source, sink);
            out.println(ans);
        }

        boolean f(boolean[][] table, int xs, int ys, int xe, int ye, int x0, int y0, int t) {
            int n = table.length;
            int[][] last = new int[n][n], now = new int[n][n];
            final int[] dx = new int[]{-1, 0, 0, 1}, dy = new int[]{0, -1, 1, 0};
            now[xs][ys] = 1;
            now[x0][y0] = -1;
            while (t-- > 0) {
                boolean can1 = false;
                for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) last[i][j] = now[i][j];
                for (int i = 0; i < n; i++)
                    for (int j = 0; j < n; j++)
                        if (last[i][j] == 1) for (int k = 0; k < 4; k++) {
                            int i2 = i + dx[k], j2 = j + dy[k];
                            if (i2 >= 0 && i2 < n && j2 >= 0 && j2 < n && table[i2][j2] && now[i2][j2] == 0) {
                                now[i2][j2] = 1;
                                can1 = true;
                            }
                        }
                boolean can2 = false;
                for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) last[i][j] = now[i][j];
                for (int i = 0; i < n; i++)
                    for (int j = 0; j < n; j++)
                        if (last[i][j] == -1) for (int k = 0; k < 4; k++) {
                            int i2 = i + dx[k], j2 = j + dy[k];
                            if (i2 >= 0 && i2 < n && j2 >= 0 && j2 < n && table[i2][j2] && (now[i2][j2] == 0 || (now[i2][j2] == 1 && (i2 != xe || j2 != ye)))) {
                                now[i2][j2] = -1;
                                can2 = true;
                            }
                        }
                if (!can1 && !can2) break;
            }
            return now[xe][ye] == 1;
        }

    }

    static class MaxFlowDinic {
        public static void addEdge(List<MaxFlowDinic.Edge>[] graph, int s, int t, int cap) {
            graph[s].add(new MaxFlowDinic.Edge(t, graph[t].size(), cap));
            graph[t].add(new MaxFlowDinic.Edge(s, graph[s].size() - 1, 0));
        }

        static boolean dinicBfs(List<MaxFlowDinic.Edge>[] graph, int src, int dest, int[] dist) {
            Arrays.fill(dist, -1);
            dist[src] = 0;
            int[] Q = new int[graph.length];
            int sizeQ = 0;
            Q[sizeQ++] = src;
            for (int i = 0; i < sizeQ; i++) {
                int u = Q[i];
                for (MaxFlowDinic.Edge e : graph[u]) {
                    if (dist[e.t] < 0 && e.f < e.cap) {
                        dist[e.t] = dist[u] + 1;
                        Q[sizeQ++] = e.t;
                    }
                }
            }
            return dist[dest] >= 0;
        }

        static int dinicDfs(List<MaxFlowDinic.Edge>[] graph, int[] ptr, int[] dist, int dest, int u, int f) {
            if (u == dest)
                return f;
            for (; ptr[u] < graph[u].size(); ++ptr[u]) {
                MaxFlowDinic.Edge e = graph[u].get(ptr[u]);
                if (dist[e.t] == dist[u] + 1 && e.f < e.cap) {
                    int df = dinicDfs(graph, ptr, dist, dest, e.t, Math.min(f, e.cap - e.f));
                    if (df > 0) {
                        e.f += df;
                        graph[e.t].get(e.rev).f -= df;
                        return df;
                    }
                }
            }
            return 0;
        }

        public static int maxFlow(List<MaxFlowDinic.Edge>[] graph, int src, int dest) {
            int flow = 0;
            int[] dist = new int[graph.length];
            while (dinicBfs(graph, src, dest, dist)) {
                int[] ptr = new int[graph.length];
                while (true) {
                    int df = dinicDfs(graph, ptr, dist, dest, src, Integer.MAX_VALUE);
                    if (df == 0)
                        break;
                    flow += df;
                }
            }
            return flow;
        }

        public static class Edge {
            public int t;
            public int rev;
            public int cap;
            public int f;

            public Edge(int t, int rev, int cap) {
                this.t = t;
                this.rev = rev;
                this.cap = cap;
            }

        }

    }

