public class Evacuation {
	static class MaxFlow_EdmondsKarp {

		/**
		 * @param args
		 */

		public static int maxflow(int[][] cap,int src,int dest){
			int cost=0;
			int c=0;
			int[][] flow=new int[cap.length][cap[0].length];
			while((c=bfs(cap,src,dest,flow))!=0){
				cost+=c;
			}

			return cost;
		}
		private static int bfs(int[][] cap, int src, int dest,int[][] flow) {
			Queue<Integer> q=new LinkedList<Integer>();
			q.add(src);
			boolean[] vis=new boolean[cap.length];
			vis[src]=true;
			int[] parent=new int[cap.length];
			Arrays.fill(parent, -1);
			while(!q.isEmpty()){
				int front=q.remove();
				if(front==dest)break;
				for(int i=0;i<cap[front].length;i++){
					if(vis[i]||cap[front][i]<=0)continue;
					vis[i]=true;
					parent[i]=front;
					q.add(i);
				}
			}
			int current=dest;
			int min=Integer.MAX_VALUE;
			while(parent[current]!=-1){
				min=Math.min(min,cap[parent[current]][current]);
				current=parent[current];
			}
			current=dest;
			while(parent[current]!=-1){
				cap[parent[current]][current]-=min;
				cap[current][parent[current]]+=min;
				flow[current][parent[current]]-=min;
				flow[parent[current]][current]+=min;
				current=parent[current];
			}
			return min==Integer.MAX_VALUE?0:min;
		}

	}

