			}
		int[][] cap=new int[n*n*2+2][n*n*2+2]; // 2*n^2 + 2 
		// first i*n+j , second n*n+a*n+b , src n*n*2 dest n*n*2+1
		for(int i=0;i<n;i++){
			for(int j=0;j<n;j++){
				for(int a=0;a<n;a++){
					for(int b=0;b<n;b++){
						if(arr[i][j]>'0'&&arr[i][j]<='9'&&rescue[a][b]>'0'&&rescue[a][b]<='9'){
							boolean can = false;
							q=new LinkedList<Integer>();
							q.add(i);
							q.add(j);
							q.add(0);
							vis=new boolean[n][m];
							vis[i][j]=true;
							while(!q.isEmpty()){
								int fx = q.remove();
