								}
								int ft = q.remove();
								if(inf[fx][fy]<=ft)continue;
								for(int u=0;u<4;u++){
									int nx=fx+dx[u];
									int ny=fy+dy[u];
									if(nx>=0&&nx<n&&ny>=0&&ny<m&&!vis[nx][ny]&&arr[nx][ny]!='Y'&&(inf[nx][ny]>=ft+1)){
										q.add(nx);
										q.add(ny);
										q.add(ft+1);
										vis[nx][ny]=true;
									}
								}
							}
							if(can){
								cap[i*n+j][n*n+a*n+b]=Math.min(arr[i][j]-'0',rescue[a][b]-'0');
							}
						}
					}
				}
			}
		}
		for(int i=0;i<n*n;i++){
