class Matching implements Solver {
    public void solve(int testNumber, InputReader in, PrintWriter out) {
        int size = in.nextInt();
        int bomb = in.nextInt();
        char doctors[][] = new char[size][size];
        char capsuls[][] = new char[size][size];
        for (int i = 0; i < size; ++i) {
            doctors[i] = in.nextToken().toCharArray();
        }
        for (int i = 0; i < size; ++i) {
            capsuls[i] = in.nextToken().toCharArray();
        }

        Queue<Point> Q = new LinkedList<Point>() ;
        int dist[][] = new int[size][size];
        for (int[] a : dist) Arrays.fill(a, Integer.MAX_VALUE / 10);
        for (int i = 0; i < size; ++i)
            for (int j = 0; j < size; ++j)
                if (doctors[i][j] == 'Z') {
                    dist[i][j] = 0;
                    Q.add(new Point(j, i));
                }
        int dj[] = {-1, 1, 0, 0};
        int di[] = {0, 0, -1, 1};
        while (Q.size() > 0) {
            Point p = Q.poll();
            int j = p.x;
            int i = p.y;
            for (int u = 0; u < di.length; ++u) {
                int ni = i + di[u];
                int nj = j + dj[u];
                if (ni >= 0 && nj >= 0 && ni < size && nj < size && dist[ni][nj] == Integer.MAX_VALUE / 10 && Character.isDigit(capsuls[ni][nj])) {
                    dist[ni][nj] = dist[i][j]  + 1;
                    Q.add(new Point(nj, ni));
                }
            }
        }
       /* out.print("curse dist : \n");
        for (int d[] : dist) {
            out.print(Arrays.toString(d) + "\n"); out.flush();;
        */
        int d[][][][][] = new int[size][size][bomb + 2][size][size];
        for (int a[][][][] : d)
            for (int b[][][] : a)
                for (int c[][] : b)
                    for (int e[] : c)
                        Arrays.fill(e, -1);
        for (int y = 0; y < size; ++y) {
            for (int x = 0; x < size; ++x) {
                if (Character.isDigit(doctors[y][x]) && doctors[y][x] - '0' >= 0) {
                  Queue<Tuples> queue = new LinkedList<Tuples>();
                    queue.add(new Tuples(x, y, 0));
                    d[y][x][0][y][x] = 1;
                    while (queue.size() > 0) {
                        Tuples p = queue.poll();
                        int i = p.y;
                        int j = p.x;
                        int time = p.time;
                        for (int u = 0; u < di.length; ++u) {
                            int ni = i + di[u];
                            int nj = j + dj[u];


                            if (ni >= 0 && nj >= 0 && ni < size && nj < size && time + 1 <= bomb && d[y][x][time + 1][ni][nj] == -1 && dist[ni][nj] >= time + 1 && Character.isDigit(doctors[ni][nj]) ) {
                                if (dist[ni][nj] > time + 1)
                                    queue.add(new Tuples(nj, ni, time + 1));
                                d[y][x][time + 1][ni][nj] = 1;
                            }
                        }
                    }
                }
            }
        }

        int nodes = size * size * 2 + 2;
        int src = nodes - 2;
        int des= nodes - 1;
        int capa[][] = new int[nodes][nodes];
        int flow[][] = new int[nodes][nodes];
        int prev[] = new int[nodes];
        for (int y = 0; y < size; ++y) {
            for (int x= 0; x <size; ++x) {
                if (Character.isDigit(doctors[y][x]) && doctors[y][x] - '0' > 0) {
                    capa[src][y * size + x] = doctors[y][x] - '0';
                    for (int i = 0; i < size; ++i)
                        for (int j = 0; j < size; ++j) {
                            for (int t = 0; t <= bomb; ++t)
                                if (d[y][x][t][i][j] >= 0 && Character.isDigit(capsuls[i][j]) && capsuls[i][j] - '0' > 0) {
                                    capa[y * size + x][size * size + i * size + j] = Integer.MAX_VALUE / 10;
                               //     out.println("add edge" + "(" + y + ", " + x + ")" + "->" + "(" + i + ", " + j + ")" );
                                }
                        }
                }
            }
        }
        for (int y = 0; y < size; ++y) {
            for (int x = 0; x < size; ++x)
                if (Character.isDigit(capsuls[y][x]) && capsuls[y][x] - '0' > 0) {
                    capa[size * size + y * size + x][des] = capsuls[y][x] - '0';
                }
        }

        int res = 0;
        while (true) {
            int q[] = new int[nodes];
            int dd[] = new int[nodes];
            int h = 0;
            q[h ++] = src;
            dd[src] = 1;
            for (int i = 0; i < h; ++i) {
                int cur = q[i];
                for (int j = 0; j < nodes; ++j) {
                    if (capa[cur][j] - flow[cur][j] > 0 && dd[j] == 0) {
                        prev[j] = cur;
                        q[h ++] = j;
                        dd[j] = 1;
                    }
                }
            }
            if (dd[des] == 0) break;
            int add = Integer.MAX_VALUE / 10;
            for (int cur = des; cur != src; cur = prev[cur]) {
                int p = prev[cur];
                add = Math.min(add, capa[p][cur] - flow[p][cur]);
            }
            for (int cur = des; cur != src; cur = prev[cur]) {
                int p = prev[cur];
                flow[p][cur] += add;
                flow[cur][p] -= add;
            }
            res += add;
        }
        out.print(res);
    }
    class Tuples {
        int x, y, time;

        Tuples(int x, int y, int time) {
            this.x = x;
            this.y = y;
            this.time = time;
        }
    }
    class Point {
        int x, y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }
}

import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.Iterator;
import java.util.LinkedList;
import java.util.Locale;
import java.util.Queue;
import java.util.Random;
import java.util.StringTokenizer;
import java.util.TreeMap;
import java.util.TreeSet;

public class Solution implements Runnable {

	public static void main(String[] args) {
		(new Thread(new Solution())).start();
	}

	BufferedReader in;
	PrintWriter out;
	StringTokenizer st;

	String nextToken() throws IOException {
		while (st == null || !st.hasMoreTokens()) {
			String r = in.readLine();
			if (r == null) return null;
			st = new StringTokenizer(r);
		}
		return st.nextToken();
	}

	int nextInt() throws IOException {
		return Integer.parseInt(nextToken());
	}

	long nextLong() throws IOException {
		return Long.parseLong(nextToken());
	}

	double nextDouble() throws IOException {
		return Double.parseDouble(nextToken());
	}

	int[][] a = new int[10][10];
	int[][] b = new int[10][10];
	int[][] c = new int[10][10];
	boolean[][] mat;
	boolean[] w;
	int t, n;

	void bfsc(int x, int y) {
		c[x][y] = 1;
		for (int tt = 1; tt <= t; tt++) {
			for (int i = 0; i < n; i++) {
				for (int j = 0; j < n; j++) {
					if (a[i][j] >= 0 && c[i][j] == 0) {
						if (i > 0 && c[i - 1][j] == tt) c[i][j] = tt + 1;
						if (j > 0 && c[i][j - 1] == tt) c[i][j] = tt + 1;
						if (j < n - 1 && c[i][j + 1] == tt) c[i][j] = tt + 1;
						if (i < n - 1 && c[i + 1][j] == tt) c[i][j] = tt + 1;
					}
				}
			}
		}
	}

	void bfs(int x, int y) {
		int[][] d = new int[10][10];
		d[x][y] = 1;
		Queue<Integer> qx = new LinkedList<Integer>();
		Queue<Integer> qy = new LinkedList<Integer>();
		Queue<Integer> qt = new LinkedList<Integer>();
		qx.add(x); qy.add(y); qt.add(0);
		while (!qx.isEmpty()) {
			int xx = qx.poll(), yy = qy.poll(), tt = qt.poll();
			if (tt == t) break;
			if (c[xx][yy] == tt + 1) continue;
			if (xx > 0 && a[xx - 1][yy] >= 0 && d[xx - 1][yy] == 0 && (c[xx - 1][yy] == 0 || c[xx - 1][yy] > tt + 1)) {
				d[xx - 1][yy] = 1;
				qx.add(xx - 1); qy.add(yy); qt.add(tt + 1);
			}
			if (yy > 0 && a[xx][yy - 1] >= 0 && d[xx][yy - 1] == 0 && (c[xx][yy - 1] == 0 || c[xx][yy - 1] > tt + 1)) {
				d[xx][yy - 1] = 1;
				qx.add(xx); qy.add(yy - 1); qt.add(tt + 1);
			}
			if (xx < n - 1 && a[xx + 1][yy] >= 0 && d[xx + 1][yy] == 0 && (c[xx + 1][yy] == 0 || c[xx + 1][yy] > tt + 1)) {
				d[xx + 1][yy] = 1;
				qx.add(xx + 1); qy.add(yy); qt.add(tt + 1);
			}
			if (yy < n - 1 && a[xx][yy + 1] >= 0 && d[xx][yy + 1] == 0 && (c[xx][yy + 1] == 0 || c[xx][yy + 1] > tt + 1)) {
				d[xx][yy + 1] = 1;
				qx.add(xx); qy.add(yy + 1); qt.add(tt + 1);
			}
		}
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < n; j++) {
				if (d[i][j] == 1 && b[i][j] > 0) {
					for (int k1 = 0; k1 < a[x][y]; k1++) {
						for (int k2 = 0; k2 < b[i][j]; k2++) {
							mat[x * 100 + y * 10 + k1][i * 100 + j * 10 + k2] = 
								mat[x * 100 + y * 10 + k1][i * 100 + j * 10 + k2] = true; 
						}
					}
				}
			}
		}
	}

	int[] px = new int[1010];

	boolean dfs(int q) {
		w[q] = true;
		for (int i = 0; i < 1000; i++) {
			if (mat[q][i]) {
				if (px[i] == -1 || !w[px[i]] && dfs(px[i])) {
					px[i] = q;
					return true;
				}
			}
		}
		return false;
	}

	void solve() throws Exception {
		n = nextInt();
		t = nextInt();
		mat = new boolean[1010][1010];
		w = new boolean[1010];
		for (int i = 0; i < n; i++) {
			String s = nextToken();
			for (int j = 0; j < n; j++) {
				if (s.charAt(j) == 'Y') a[i][j] = -1; else
					if (s.charAt(j) == 'Z') a[i][j] = -2; else 
						a[i][j] = s.charAt(j) - '0';
			}
		}
		for (int i = 0; i < n; i++) {
			String s = nextToken();
			for (int j = 0; j < n; j++) {
				if (s.charAt(j) == 'Y') b[i][j] = 10; else
					if (s.charAt(j) == 'Z') b[i][j] = 11; else 
						b[i][j] = s.charAt(j) - '0';
			}
		}
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < n; j++) {
				if (a[i][j] == -2) bfsc(i, j); 
			}
		}
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < n; j++) {
				if (a[i][j] > 0) bfs(i, j);
			}
		}
		int ans = 0;
		Arrays.fill(px, -1);
		for (int i = 0; i < 1000; i++) {
			Arrays.fill(w, false);
			if (dfs(i)) ans++;
		}
		out.println(ans);
	}

	public void run() {
		Locale.setDefault(Locale.UK);
		try {
			in = new BufferedReader(new InputStreamReader(System.in));
			out = new PrintWriter(System.out);
//			in = new BufferedReader(new FileReader("input.txt"));
//			out = new PrintWriter("output.txt");
			solve();
		} catch (Exception e) {
			e.printStackTrace();
			System.exit(1);
		} finally {
			out.flush();
		}
	}

}

