    private boolean find(int v) {
        used[v] = true;
        boolean result = false;
        ArrayList<Integer> list = g.get(v);
        for(int i : list) {
            if (pair2[i] == -1 || (!used[pair2[i]] && find(pair2[i]))) {
                result = true;
                pair1[v] = i;
                pair2[i] = v;
                break;
            }
        }
        return result;
    }

    public static void main(String[] args) {
