class TaskE {
    private static final int INF = (int) 1e9;
    int n;
    int timeExplode;
    boolean[][] hasWall;
    int badStartX, badStartY;
    int[][] numberOfScientists;
    int[][] numberOfReactors;
    int[][] becomeBad;

    public void solve(int testNumber, InputReader in, PrintWriter out) {
        n = in.nextInt();
        timeExplode = in.nextInt();
        hasWall = new boolean[n][n];
        numberOfScientists = new int[n][n];
        numberOfReactors = new int[n][n];
        for (int i = 0; i < n; ++i) {
            String line = in.nextString();
            for (int j = 0; j < n; ++j) {
                char c = line.charAt(j);
                if (c == 'Z') {
                    badStartX = i;
                    badStartY = j;
                    hasWall[i][j] = true;
                } else if (c == 'Y') {
                    hasWall[i][j] = true;
                } else {
                    numberOfScientists[i][j] = c - '0';
                }
            }
        }
        for (int i = 0; i < n; ++i) {
            String line = in.nextString();
            for (int j = 0; j < n; ++j) {
                char c = line.charAt(j);
                if (Character.isDigit(c)) {
                    numberOfReactors[i][j] = c - '0';
                }
            }
        }

        becomeBad = new int[n][n];
        ArrayUtils.fill(becomeBad, INF);
        becomeBad[badStartX][badStartY] = 0;
        int[] qx = new int[n * n];
        int[] qy = new int[n * n];
        int qSize = 1;
        qx[0] = badStartX;
        qy[0] = badStartY;
        for (int qi = 0; qi < qSize; ++qi) {
            int cx = qx[qi];
            int cy = qy[qi];
            for (int d = 0; d < dx.length; ++d) {
                int nx = cx + dx[d];
                int ny = cy + dy[d];
                if (isValid(nx, ny, n)) {
                    if (!hasWall[nx][ny]) {
                        if (becomeBad[nx][ny] == INF) {
                            becomeBad[nx][ny] = becomeBad[cx][cy] + 1;
                            qx[qSize] = nx;
                            qy[qSize] = ny;
                            ++qSize;
                        }
                    }
                }
            }
        }

        Graph maxFlowGraph = new Graph();
        maxFlowGraph.initGraphWithFlow(n * n * 2 + 2, n * n * n * n * 4 * 3 + 10 * n * n + 100);

        int source = 0;
        int shiftForPerson = 1;
        int shiftForReactor = n * n + 1;
        int dest = n * n + n * n + 1;

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (numberOfScientists[i][j] > 0) {
                    maxFlowGraph.addFlowEdge(source, i * n + j + shiftForPerson, numberOfScientists[i][j]);
                }
            }
        }
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (numberOfReactors[i][j] > 0) {
                    maxFlowGraph.addFlowEdge(i * n + j + shiftForReactor, dest, numberOfReactors[i][j]);
                }
            }
        }

        for (int xPerson = 0; xPerson < n; ++xPerson) {
            for (int yPerson = 0; yPerson < n; ++yPerson) {
                if (numberOfScientists[xPerson][yPerson] > 0) {
                    boolean[][] canReach = new boolean[n][n];
                    boolean[][] marked = new boolean[n][n];
                    boolean[][] newMarked = new boolean[n][n];
                    marked[xPerson][yPerson] = true;
                    canReach[xPerson][yPerson] = true;
                    for (int curTime = 0; curTime < timeExplode; ++curTime) {
                        for (int i = 0; i < n; ++i) {
                            for (int j = 0; j < n; ++j) {
                                if (marked[i][j]) {
                                    for (int d = 0; d < 4; ++d) {
                                        int ni = i + dx[d];
                                        int nj = j + dy[d];
                                        if (isValid(ni, nj, n)) {
                                            if (!hasWall[ni][nj]) {
                                                if (curTime + 1 <= becomeBad[ni][nj]) {
                                                    canReach[ni][nj] = true;
                                                }
                                                if (curTime + 1 < becomeBad[ni][nj]) {
                                                    newMarked[ni][nj] = true;
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                        for (int i = 0; i < n; ++i) {
                            for (int j = 0; j < n; ++j) {
                                marked[i][j] = newMarked[i][j];
                                newMarked[i][j] = false;
                            }
                        }
                    }
                    for (int xReactor = 0; xReactor < n; ++xReactor) {
                        for (int yReactor = 0; yReactor < n; ++yReactor) {
                            if (numberOfReactors[xReactor][yReactor] > 0) {
                                if (canReach[xReactor][yReactor]) {
                                    maxFlowGraph.addFlowEdge(xPerson * n + yPerson + shiftForPerson, xReactor * n + yReactor + shiftForReactor, INF);
                                }
                            }
                        }
                    }
                }
            }
        }
        long flow = MaxFlowDinic.dinic(maxFlowGraph, source, dest);
        out.println(flow);
    }

    private boolean isValid(int x, int y, int n) {
        return x >= 0 && y >= 0 && x < n && y < n;
    }

    int[] dx = new int[] {1, 0, -1, 0};
    int[] dy = new int[] {0, 1, 0, -1};
}

