class Graph {
    public int[] from;
    public int[] to;
    public int[] first;
    public int[] next;
    public int[] cost;
    public int[] capacity;
    public long[] flow;
    public int[] last;
    public int nVertex;
    public int nEdges;
    int[] reverseEdge;
    public int curEdge;

    public Graph() {}

    public void initGraphWithFlow(int n, int m) {
        curEdge = 0;
        nVertex = n;
        nEdges = m;
        from = new int[m * 2];
        to = new int[m * 2];
        first = new int[n];
        next = new int[m * 2];
        cost = new int[m * 2];
        capacity = new int[m * 2];
        flow = new long[m * 2];
        reverseEdge = new int[m * 2];
        last = new int[m * 2];
        Arrays.fill(first, -1);
        Arrays.fill(last, -1);
    }

    public void addFlowEdge(int a, int b, int f) {
//        System.err.println("Added edge " + a + " - " + b + " with flow: " + f);
        next[curEdge] = first[a];
        first[a] = curEdge;
        to[curEdge] = b;
        from[curEdge] = a;
        capacity[curEdge] = f;
        flow[curEdge] = 0;
        reverseEdge[curEdge] = curEdge + 1;
        ++curEdge;

        next[curEdge] = first[b];
        first[b] = curEdge;
        to[curEdge] = a;
        from[curEdge] = b;
        capacity[curEdge] = 0;
        flow[curEdge] = 0;
        reverseEdge[curEdge] = curEdge - 1;
        ++curEdge;
    }

    public final void pushFlow(int id, long fl) {
        if (fl == 0) {
            return;
        }
        flow[id] += fl;
        flow[id^1] -= fl;
    }

}

class MaxFlowDinic {
    private final Graph graph;
    private int source;
    private int dest;
    private int[] queue;
    private int[] distance;
    private int[] nextEdge;

    public MaxFlowDinic(Graph graph, int source, int dest) {
        this.graph = graph;
        this.source = source;
        this.dest = dest;
        int n = graph.nVertex;
        queue = new int[n];
        distance = new int[n];
        nextEdge = new int[n];
    }

    public static long dinic(Graph graph, int source, int destination) {
        return new MaxFlowDinic(graph, source, destination).dinic();
    }

    private long dinic() {
        long totalFlow = 0;
        while (true) {
            edgeDistances();
            if (distance[dest] == -1)
                break;
            Arrays.fill(nextEdge, -2);
            totalFlow += dinicImpl(source, Long.MAX_VALUE);
        }
        return totalFlow;
    }

    private void edgeDistances() {
        Arrays.fill(distance, -1);
        distance[source] = 0;
        int size = 1;
        queue[0] = source;
        for (int i = 0; i < size; i++) {
            int cur = queue[i];
            for (int id = graph.first[cur]; id != -1; id = graph.next[id]) {
                if (graph.capacity[id] > graph.flow[id]) {
                    int next = graph.to[id];
                    if (distance[next] == -1) {
                        distance[next] = distance[cur] + 1;
                        queue[size++] = next;
                    }
                }
            }
        }
    }

    private long dinicImpl(int source, long flow) {
        if (source == dest) {
            return flow;
        }
        if (flow == 0 || distance[source] == distance[dest]) {
            return 0;
        }
        int id = nextEdge[source];
        if (id == -2) {
            nextEdge[source] = id = graph.first[source];
        }
        long totalPushed = 0;
        while (id != -1) {
            int nextDestinationID = graph.to[id];
            if (graph.capacity[id] > graph.flow[id] && distance[nextDestinationID] == distance[source] + 1) {
                long pushed = dinicImpl(nextDestinationID, Math.min(flow, graph.capacity[id] - graph.flow[id]));
                if (pushed != 0) {
                    graph.pushFlow(id, pushed);
                    flow -= pushed;
                    totalPushed += pushed;
                    if (flow == 0)
                        return totalPushed;
                }
            }
            nextEdge[source] = id = graph.next[id];
        }
        return totalPushed;
    }

}

