    int n;
    int t;
    int[][][] isBad;
    int[][][][][] can;

    int[] dx = new int[] {-1,1,0,0};
    int[] dy = new int[] {0,0,1,-1};

    int[][] map, flow;

    int INF = 1000000;

    int findFlow() {
    	int m = n*n*2+2;
    	int[] from = new int[m];
    	while (true) {
    		Arrays.fill(from, -1);
    		from[m-2] = -2;
	    	LinkedList<Integer> list = new LinkedList<Integer>();
	    	list.addFirst(m-2);
	    	while (list.size() != 0) {
	    		int cur = list.removeLast();
	    		for (int next = 0; next < m; next++) {
	    			if (map[cur][next] != -1 && from[next] == -1 && map[cur][next]-flow[cur][next] > 0) {
	    				from[next] = cur;
	    				list.addFirst(next);
	    			}
	    		}
	    	}
	    	if (from[m-1] != -1) {
	    		int min = Integer.MAX_VALUE;
	    		int pos = m-1;
	    		while (from[pos] != -2) {
	    			min = Math.min(min, map[from[pos]][pos]-flow[from[pos]][pos]);
	    			pos = from[pos];
	    		}
	    		pos = m-1;
	    		while (from[pos] != -2) {
	    			flow[from[pos]][pos] += min;
	    			flow[pos][from[pos]] -= min;
	    			pos = from[pos];
	    		}
	    	} else {
	    		break;
	    	}
    	}
    	int ans = 0;
    	for (int i = 0; i < m; i++) {
    		if (map[i][m-1] != -1) {
    			ans += flow[i][m-1];
    		}
    	}
    	return ans;
    }

