    	}
    	for (int tt = 1; tt <= t; tt++) {
    		for (int i = 0; i < n; i++) {
        		for (int j = 0; j < n; j++) {
        			isBad[tt][i][j] = isBad[tt-1][i][j];
        			if (isBad[tt][i][j] == 0) {
	            		for (int d = 0; d < 4; ++d) {
	            			if (i+dx[d] >= 0 && i+dx[d] < n && j+dy[d] >= 0 && j+dy[d] < n) {
		            			if (isBad[tt-1][i+dx[d]][j+dy[d]] == 2) {
		            				isBad[tt][i][j] = 2;
		            			}
	            			}
	            		}
        			}
            	}	
        	}
    	}

    	can = new int[n][n][t+1][n][n];
    	for (int si = 0; si < n; si++) {
    		for (int sj = 0; sj < n; sj++) {
        		if (ss1[si].charAt(sj) >= '1' && ss1[si].charAt(sj) <= '9') {
        			can[si][sj][0][si][sj] = 1;
        			for (int tt = 1; tt <= t; tt++) {
        	    		for (int i = 0; i < n; i++) {
        	        		for (int j = 0; j < n; j++) {
        	        			if (isBad[tt-1][i][j] == 0) {
        		            		for (int d = 0; d < 4; ++d) {
        		            			if (i+dx[d] >= 0 && i+dx[d] < n && j+dy[d] >= 0 && j+dy[d] < n) {
	        		            			if (can[si][sj][tt-1][i+dx[d]][j+dy[d]] == 1 && isBad[tt-1][i+dx[d]][j+dy[d]] == 0) {
	        		            				can[si][sj][tt][i][j] = 1;
	        		            			}
        		            			}
        		            		}
        	        			}
        	            	}	
        	        	}
        	    	}
        		}
        	}
    	}

    	map = new int[2*n*n+2][2*n*n+2];
    	flow = new int[2*n*n+2][2*n*n+2];
    	for (int i = 0; i < map.length; i++) {
    		Arrays.fill(map[i], -1);
    	}
    	for (int i = 0; i < n; i++) {
    		for (int j = 0; j < n; j++) {
        		if (ss1[i].charAt(j) >= '1' && ss1[i].charAt(j) <= '9') {
        			for (int ri = 0; ri < n; ri++) {
