public class check {
    public static int find(ArrayList<Integer> inp, int n, int target){
        Collections.sort(inp);
        Collections.reverse(inp);
        int res = 0;
        int num = n;
        for(int i = 0;i<n && num>0;i++){
            int curr = inp.get(i);
            int times = target/curr;
            if(target%curr != 0)
                times++;
            if(times*curr<=target)
                times++;
            if(times>num)
                return res;
            num = num-times;
            res++;
        }
        return res;
    }

    public static void main(String args[]) throws java.lang.Exception{
        Scanner in;
        try{
            in = new Scanner(new FileReader("./input.txt"));
