        n = n-1;

        if(n == 0){
            System.out.println(3);
            return;
        }
        if(n == 1){
            System.out.println(5);
            return;
        }

        long gp = (n-2)/3;
        long pos = (n-2)%3;

        long base = 5+gp*4;
        if(pos == 0){
            base = base+2;
        }
        else if(pos == 1)
            base = base+3;
        else
            base = base+4;

        System.out.println(base);
    }
}

