public class A {	
	BufferedReader reader;
    StringTokenizer tokenizer;
    PrintWriter out;

    int ans = Integer.MAX_VALUE/2;
	public void solve() throws IOException {
        int N = nextInt();
		String[] ss = reader.readLine().split(" ");
		int[][] cards = new int[ss.length][];
        for (int i = 0; i < cards.length; i++) {
            int color = -1;
            switch (ss[i].charAt(0)) {
                case 'R':
                    color = 0;
                    break;
                case 'G':
                    color = 1;
                    break;
                case 'B':
                    color = 2;
                    break;
                case 'Y':
                    color = 3;
                    break;
                case 'W':
                    color = 4;
                    break;
            }
            cards[i] = new int[] {color, Character.getNumericValue(ss[i].charAt(1)) - 1};
        }

        dfs(cards, 0, 0, new boolean[5], new boolean[5]);
        out.println(ans);
	}

    public void dfs(int[][] cards, int colorIndex, int numIndex, boolean[] pColors, boolean[] pNums) {
        boolean OK = true;
        out: for (int i = 0; i < cards.length; i++) {
            for (int j = i+1; j < cards.length; j++) {
                if (cards[i][0] == cards[j][0] && cards[i][1] == cards[j][1]) continue;
                if (cards[i][0] != cards[j][0]) {
                    if (pColors[cards[i][0]] || pColors[cards[j][0]]) continue;
                }
                if (cards[i][1] != cards[j][1]) {
                    if (pNums[cards[i][1]] || pNums[cards[j][1]]) continue;
                }
                OK = false;
                break out;
            }
        }
        if (OK) {
            int tmpAns = 0;
            for (int i = 0; i < 5; i++) {
                if (pColors[i]) tmpAns++;
                if (pNums[i]) tmpAns++;
            }
            ans = Math.min(ans, tmpAns);
            return;
        }

        if (numIndex == 5) {
            return;
        }

        if (colorIndex == 5) {
            dfs(cards, colorIndex, numIndex+1, pColors, pNums);
            pNums[numIndex] = true;
            dfs(cards, colorIndex, numIndex+1, pColors, pNums);
            pNums[numIndex] = false;
        } else {
            dfs(cards, colorIndex+1, numIndex, pColors, pNums);
            pColors[colorIndex] = true;
            dfs(cards, colorIndex+1, numIndex, pColors, pNums);
            pColors[colorIndex] = false;
        }
    }

	/**
	 * @param args
	 */
	public static void main(String[] args) {
		new A().run();
	}

	public void run() {
        try {
            reader = new BufferedReader(new InputStreamReader(System.in));
            tokenizer = null;
            out = new PrintWriter(System.out);
            solve();
            reader.close();
            out.close();
        } catch (Exception e) {
            e.printStackTrace();
            System.exit(1);
        }
    }

    int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }

    double nextDouble() throws IOException {
        return Double.parseDouble(nextToken());
    }

    String nextToken() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }

}

