import java.util.HashSet;
import java.util.InputMismatchException;

public class FlexingOP3A {

	public static long max_val = (long)1e10;

	public static void solve() {
		int w = s.nextInt();
		long m = s.nextLong();
		if(w == 2) {
			out.println("YES");
			return;
		}
		if(w >= 4) {
			//BruteForces
			int max = 0;
			long curr = 1;
			while(max_val/w > curr) {
				max++;
				curr *= (long)w;
			}
			powers = new long[max + 1];
			powers[0] = 1;
			for(int i = 1; i < max + 1; i++) {
				powers[i] = powers[i - 1] * (long)w;
			}
			boolean ok = Recur(0, max + 1, m, 0);
			if(ok) {
				out.println("YES");
			}else {
				out.println("NO");
			}
			return;
		}
		//Meet in the middle
		int max = 10;
		first = new HashSet<Long>();
		second = new HashSet<Long>();
		powerof3 = new long[21];
		powerof3[0] = 1;
		for(int i = 1; i <= 20; i++) {
			powerof3[i] = powerof3[i - 1] * 3L;
		}
		Recur(0, max, true, 0);
		Recur(max + 1, 20, false, 0);
		if(first.contains(m) || second.contains(m)) {
			out.println("YES");
			return;
		}
		for(Long x : first) {
			if(second.contains(x - m) || second.contains(x + m)) {
				out.println("YES");
				return;
			}
		}
		out.println("NO");
	}

	public static HashSet<Long> first;
	public static HashSet<Long> second;
	public static long[] powerof3;

	public static void Recur(int power, int max, boolean type, long answer) {
		if(power == max + 1) {
			if(type) first.add(answer);
			else second.add(answer);
			return;
		}
		long curr = powerof3[power];
		Recur(power + 1, max, type, answer + curr);
		Recur(power + 1, max, type, answer);
		Recur(power + 1, max, type, answer - curr);
	}

	public static long[] powers;
	public static boolean Recur(int power, int max, long m, long curr) {
		if(m == curr) {
			return true;
		}
		if(power == max) {
			return false;
		}
		boolean ok = false;
		long cur = powers[power];
		ok |= Recur(power + 1, max, m, curr + cur);
		ok |= Recur(power + 1, max, m, curr - cur);
		ok |= Recur(power + 1, max, m, curr);
		return ok;
	}

	public static void main(String[] args) {
		new Thread(null, null, "Thread", 1 << 27) {
			public void run() {
				try {
					out = new PrintWriter(new BufferedOutputStream(System.out));
					s = new FastReader(System.in);
					solve();
					out.close();
				} catch (Exception e) {
					e.printStackTrace();
					System.exit(1);
				}
			}
		}.start();
	}

	public static PrintWriter out;
	public static FastReader s;

	public static class FastReader {

		private InputStream stream;
		private byte[] buf = new byte[4096];
		private int curChar, snumChars;

		public FastReader(InputStream stream) {
			this.stream = stream;
		}

		public int read() {
			if (snumChars == -1) {
				throw new InputMismatchException();
			}
			if (curChar >= snumChars) {
				curChar = 0;
				try {
					snumChars = stream.read(buf);
				} catch (IOException E) {
					throw new InputMismatchException();
				}
			}
			if (snumChars <= 0) {
				return -1;
			}
			return buf[curChar++];
		}

		public int nextInt() {
			int c = read();
			while (isSpaceChar(c)) {
				c = read();
			}
			int sgn = 1;
			if (c == '-') {
				sgn = -1;
				c = read();
			}
			int number = 0;
			do {
				number *= 10;
				number += c - '0';
				c = read();
			} while (!isSpaceChar(c));
			return number * sgn;
		}

		public long nextLong() {
			int c = read();
			while (isSpaceChar(c)) {
				c = read();
			}
			long sgn = 1;
			if (c == '-') {
				sgn = -1;
				c = read();
			}
			long number = 0;
			do {
				number *= 10L;
				number += (long) (c - '0');
				c = read();
			} while (!isSpaceChar(c));
			return number * sgn;
		}

		public int[] nextIntArray(int n) {
			int[] arr = new int[n];
			for (int i = 0; i < n; i++) {
				arr[i] = this.nextInt();
			}
			return arr;
		}

		public long[] nextLongArray(int n) {
			long[] arr = new long[n];
			for (int i = 0; i < n; i++) {
				arr[i] = this.nextLong();
			}
			return arr;
		}

		public String next() {
			int c = read();
			while (isSpaceChar(c)) {
				c = read();
			}
			StringBuilder res = new StringBuilder();
			do {
				res.appendCodePoint(c);
				c = read();
			} while (!isSpaceChar(c));
			return res.toString();
		}

		public String nextLine() {
			int c = read();
			while (isSpaceChar(c)) {
				c = read();
			}
			StringBuilder res = new StringBuilder();
			do {
				res.appendCodePoint(c);
				c = read();
			} while (!isEndofLine(c));
			return res.toString();
		}

		public boolean isSpaceChar(int c) {
			return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
		}

		public boolean isEndofLine(int c) {
			return c == '\n' || c == '\r' || c == -1;
		}

	}


}

