			System.out.println("YES");
			return;
		}

		long up = (long)1e11;

		long pow[] = new long[21];
		pow[0] = 1;
		int n = 21;

		for(int i=1;i<21;i++){
			pow[i] = w * pow[i-1];
			if(pow[i] >= up){
				n = i + 1;
				break;
			}
		}

		int state[] = new int[n];

		for(int i=0;i<(1<<n);i++){
			long left = m,right = 0;
			for(int j=0;j<n;j++)
				if(((1<<j) & i) != 0){
					state[j] = 1;
					left += pow[j];
				}
				else{
					state[j] = 0;
					right += pow[j];
				}
			long left2 = left,right2 = right;
			if(left > right){
				long diff = left - right;
				for(int j=n-1;j>=0;j--){
					if(state[j] == 1 && pow[j] <= diff){
						diff -= pow[j];
						left -= pow[j];
					}
				}
			}
			if(right > left){
				long diff = right - left;
				for(int j=n-1;j>=0;j--){
					if(state[j] == 0 && pow[j] <= diff){
						diff -= pow[j];
						right -= pow[j];
					}
				}
			}
			if(left == right){
				System.out.println("YES");
				return;
			}
			if(right2 > left2){
				long diff = right2 - left2;
				for(int j=n-1;j>=0;j--){
					if(state[j] == 0 && pow[j] <= diff){
						diff -= pow[j];
						right2 -= pow[j];
					}
				}
			}
			if(left2 > right2){
				long diff = left2 - right2;
				for(int j=n-1;j>=0;j--){
					if(state[j] == 1 && pow[j] <= diff){
						diff -= pow[j];
						left2 -= pow[j];
					}
				}
			}
			if(left2 == right2){
				System.out.println("YES");
				return;
			}
		}

		p.println("NO");
