import java.util.Scanner;

public class VanyaandScales {
	static int w;

	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		w = in.nextInt();
		int m = in.nextInt();
		int bitmask = 0;
		System.out.println(check(m, bitmask) ? "YES" : "NO");

	}

	public static boolean check(int m, int mask) {
		// System.out.println(m + ":" + Integer.toBinaryString(mask));
		int pos = (int) Math.floor(Math.log(m) / Math.log(w));
		if (((mask >> pos) & 1) == 1)
			return false;
		if (m - Math.pow(w, pos) == 0)
			return true;
		boolean s1 = (((mask >> pos) & 1) == 1 ? false : check(
				(int) (m - Math.pow(w, pos)), mask | (1 << pos)));
		boolean s2 = ((mask >> (pos + 1)) & 1) == 1 ? false : check(
				(int) (Math.pow(w, pos + 1) - m), mask | (1 << (pos + 1)));
		return s1 || s2;
	}
}

