    static class TaskC {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            long w = in.nextInt();
            long m = in.nextInt();

            if (w == 2) {
                out.println("YES");
                return;
            }

            long[] p = new long[30];
            p[0] = 1;
            int n = 1;
            while (n <= 20 && p[n - 1] * w < 1e12) {
                p[n] = p[n - 1] * w;
                ++n;
            }

            long[] sum = new long[1 << n];
            for (int i = 0; i < 1 << n; ++i) {
                for (int j = 0; j < n; ++j) {
                    if ((i & (1 << j)) != 0) {
                        sum[i] += p[j];
                    }
                }
            }

            for (int i = 0; i < 1 << n; ++i) {
                long target = sum[i] + m;
                int lo = 0;
                int hi = (1 << n) - 1;
                while (lo <= hi) {
                    int mid = (lo + hi) / 2;
                    if (sum[mid] == target) {
                        if ((mid & i) == 0) {
                            out.println("YES");
                            return;
                        } else {
                            break;
                        }
                    } else if (sum[mid] < target) {
                        lo = mid + 1;
                    } else {
                        hi = mid - 1;
                    }
                }
            }

            out.println("NO");
        }

