import java.util.Scanner;

public class weight {

	public static void main(String[] args) {
		Scanner scanner = new Scanner(System.in);
		final int w = scanner.nextInt();
		final int m = scanner.nextInt();
		long[] weights = new long[100];
		long[] wSums = new long[100];
		boolean[] used = new boolean[100];
		long wt = 1, wSum = 0;
		for (int i = 1; i < 100; i++, wt *= w) {
			weights[i] = wt;
			wSum += wt;
			wSums[i] = wSum;
		}
		boolean found = false;
		long left = m;

		if (w == 2)
			found = true;

		SEARCH: while (!found) {
			for (int i = 0; i < 100; i++) {
				if (left <= weights[i]) {
					// see which side is closer
					if (weights[i] - left <= wSums[i - 1]) {
						if (used[i]) {
							break SEARCH;
						}
						left = weights[i] - left;
						used[i] = true;
					} else if (left <= wSums[i - 1]) {
						if (used[i - 1]) {
							break SEARCH;
						}
						left -= weights[i - 1];
						used[i - 1] = true;
					} else {
						break SEARCH;
					}
					break;
				}
			}
			found = (left == 0);
		}
		if (found)
			System.out.println("YES");
		else
			System.out.println("NO");
	}
}

