		g = new int[n * m][];
		for (int x = 0; x < m; x++) {
			for (int y = 0; y < n; y++) {
				int[] w = new int[5];
				int cnt = 0;
				for (int dir = 0; dir < 5; dir++) {
					int nx = x + dx[dir];
					int ny = y + dy[dir];
					if (nx >= 0 && nx < m && ny >= 0 && ny < n) {
						w[cnt++] = ny * m + nx;
					}
				}
				g[y * m + x] = copyOf(w, cnt);
			}
		}
		go(n, m, 0, (1L << (n * m)) - 1);
		return ans;
	}

