    public static int Genetic(String s) {
        int n = 0;
        if (s.length() < 2) {
            return n;
        }
        char c = s.charAt(0);
        int i = 1;
        int count = 1;
        while (i < s.length()) {
            if (s.charAt(i) == c) {
                count++;
            } else {
                if (count % 2 == 0) {
                    n++;
                }
                c = s.charAt(i);
                count = 1;
            }
            i++;
        }
        if (count % 2 == 0) {
            n++;
        }
        return n;
    }
}

