class TaskA {
	public void solve(int testNumber, InputReader in, PrintWriter out) {
		char[] s = in.next().toCharArray();
		int cnt = 0;
		int res = 0;
		for (int i = 0; i < s.length; i++) {
			++cnt;
			if (i == s.length - 1 || s[i] != s[i + 1]) {
				if (cnt % 2 == 0) {
					++res;
				}
				cnt = 0;
			}
		}
		out.println(res);
	}
