public class Task extends ASolver {

    char[] dna;


    public static void main(String[] args) throws IOException {
        Task task = new Task();
        task.init();
        task.readData();
        task.writeData(task.solve());
    }

    @Override
    public void init() {
        super.init();
    }

    @Override
    public boolean readData() {
        try {

            dna = next().toCharArray();

        } catch (Exception ex) {
            System.out.println(ex.getCause());
            System.out.println(ex.getMessage());
            return false;
        }
        return true;
    }

    public long solve() throws IOException {

        int result = 0;

        for (int i = 0; i < dna.length; ) {

            int equalsCount = 0;
            int j = i + 1;

            while (j < dna.length && dna[j] == dna[i]) {
                equalsCount++;
                j++;
            }

            i = j;

            if (equalsCount % 2 != 0) {
                result++;
            }

        }

        return result;
    }
}

abstract class ASolver {

    protected StringTokenizer tokens;
    protected BufferedReader input;
    protected PrintWriter output;

    public void init() {
        input = new BufferedReader(new InputStreamReader(System.in));
    }

    public abstract boolean readData();

    public void writeData(String result) {
        System.out.println(result);
    }

    public void writeData(int result) {
        System.out.println(result);
    }

    public void writeData(long result) {
        System.out.println(result);
    }

    public int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    public byte nextByte() throws IOException {
        return Byte.parseByte(next());
    }

    public double nextDouble() throws IOException {
        return Double.parseDouble(next());
    }

    public long nextLong() throws IOException {
        return Long.parseLong(next());
    }

    public String next() throws IOException {
        while (tokens == null || !tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(input.readLine());
        }
        return tokens.nextToken();
    }

    public String nextPoints() throws IOException {
        while (tokens == null || !tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(input.readLine(), "\n");
        }
        return tokens.nextToken();
    }

    public long infinityImitator(long a, long b) {
        if (a == Long.MIN_VALUE) {
            return Long.MIN_VALUE;
        } else {
            return a + b;
        }
    }

    public int infinityImitator(int a, int b) {
        if (a == Integer.MIN_VALUE) {
            return Integer.MIN_VALUE;
        } else {
            return a + b;
        }
    }

    /*
     * public long max(long... a) { long result = Long.MIN_VALUE; for (int i =
     * 0; i < a.length; i++) { result = Math.max(result, a[i]); } return result;
     * }
     */
    public int indexMax(int... a) {
        int result = 0;
        int index = -1;
        int length = a.length;
        for (int i = 0; i < length; i++) {
            if (a[i] > result) {
                result = a[i];
                index = i;
            }
        }
        return index;
    }

    public int indexMax(long... a) {
        long result = 0;
        int index = -1;
        int length = a.length;
        for (int i = 0; i < length; i++) {
            if (a[i] > result) {
                result = a[i];
                index = i;
            }
        }
        return index;
    }

    public int max(int... a) {
        int result = Integer.MIN_VALUE;
        for (int i = 0; i < a.length; i++) {
            result = Math.max(result, a[i]);
        }
        return result;
    }

    public long max(long... a) {
        long result = Integer.MIN_VALUE;
        for (int i = 0; i < a.length; i++) {
            result = Math.max(result, a[i]);
        }
        return result;
    }

    public int nod(int[] array) {
        int nod = array[0];

        for (int i = 1; i < array.length; i++) {
            nod = nod(nod, array[i]);
        }

        return nod;
    }

    private int nod(int m, int n) {

        int result = 0;

        if (m == 0) {
            return n;
        }

        if (n == 0) {
            return m;
        }

        if (n == m) {
            return m;
        }

        if (m == 1 || n == 1) {
            return 1;
        }

        int mDel = m % 2;
        int nDel = n % 2;


        if (mDel != 0 && nDel != 0) {
            return nod((Math.max(m, n) - Math.min(m, n)) / 2, Math.min(m, n));
        } else if (mDel == 0 && nDel != 0) {
            return nod(m / 2, n);
        } else if (mDel != 0 && nDel == 0) {
            return nod(m, n / 2);
        } else {
            return 2 * nod(m / 2, n / 2);
        }
    }
}

