class TaskC {
    public void solve(int testNumber, FastScanner in, FastPrinter out) {
        int x1 = in.nextInt();
        int y1 = in.nextInt();
        int x2 = in.nextInt();
        int y2 = in.nextInt();
        int x3 = in.nextInt();
        int y3 = in.nextInt();
        for (int rot = 0; rot < 4; rot++) {
            if (canSolve(x2 - x1, y2 - y1, x3, y3)) {
                out.println("YES");
                return;
            }
            int nx1 = -y1;
            int ny1 = x1;
            x1 = nx1;
            y1 = ny1;
        }
        out.println("NO");
    }

    static boolean canSolve(int x1, int y1, int x2, int y2) {
        if (x2 == 0 && y2 == 0) {
            return x1 == 0 && y1 == 0;
        }
        long a1 = x2;
        long b1 = -y2;
        long c1 = x1;
        long a2 = y2;
        long b2 = x2;
        long c2 = y1;
        long z = a1 * b2 - a2 * b1;
        long dx = b1 * c2 - c1 * b2;
        long dy = c1 * a2 - a1 * c2;
        if (z == 0) {
            if (dx != 0 || dy != 0) {
                return false;
            }
            return c1 % MathUtils.gcd(Math.abs(a1), Math.abs(b1)) == 0;
        }
        return dx % z == 0 && dy % z == 0;
    }
}

class FastScanner extends BufferedReader {

    boolean isEOF;

    public FastScanner(InputStream is) {
        super(new InputStreamReader(is));
    }

    public int read() {
        try {
            int ret = super.read();
            if (isEOF && ret < 0) {
                throw new InputMismatchException();
            }
            isEOF = ret == -1;
            return ret;
        } catch (IOException e) {
            throw new InputMismatchException();
        }
    }

    static boolean isWhiteSpace(int c) {
        return c >= -1 && c <= 32;
    }

    public int nextInt() {
        int c = read();
        while (isWhiteSpace(c)) {
            c = read();
        }
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int ret = 0;
        while (!isWhiteSpace(c)) {
            if (c < '0' || c > '9') {
                throw new NumberFormatException("digit expected " + (char) c
                        + " found");
            }
            ret = ret * 10 + c - '0';
            c = read();
        }
        return ret * sgn;
    }

    }

class FastPrinter extends PrintWriter {

    public FastPrinter(OutputStream out) {
        super(out);
    }

    public FastPrinter(Writer out) {
        super(out);
    }


}

class MathUtils {


    public static long gcd(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    }

