	public static void main(String[] $) {
		CF27E o = new CF27E(); o.main(); o.flush();
	}

	static final long INF = 0x3f3f3f3f3f3f3f3fL;
	long ans = INF;
	int[] pp = { 2, 3, 5, 7, 11, 13, 17, 19, 23 };
	void solve(int n, int b, int i, long m) {
		if (n == 1) {
			ans = Math.min(ans, m);
			return;
		}
		int p = pp[i];
		for (int a = 2; a <= b && m <= INF / p; a++, m *= p)
			if (n % a == 0)
				solve(n / a, a, i + 1, m * p);
	}
