public class GregandFriends {
    static long[][] C;

    public static long[][] C(int MAX) {
        long C[][] = new long[MAX + 1][MAX + 1];
        for (int i = 0; i < C.length; i++)
            C[i][0] = 1;
        for (int i = 1; i < C.length; i++)
            C[0][i] = 0;
        for (int i = 1; i < C.length; i++)
            for (int j = 1; j < C[i].length; j++)
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD;
        return C;
    }

    static int k;
    static long[][][] dp;
    static int[][][] dist;
    static int c1, c2;
    static long MOD = 1000000007;

    public static long modMul(long a, long b, long c) {
        return (((a * b) % MOD) * c) % MOD;
    }

    public static long go(int p, int ci, int cj) {
        if (ci == c1 && cj == c2 && p == 1)
            return 1;
        long ret = 0;
        if (dp[p][ci][cj] != -1) {
            return dp[p][ci][cj];
        }
        for (int i = 0; i * 50 <= k && i <= ci; i++) {
            for (int j = 0; i * 50 + j * 100 <= k && j <= cj; j++) {
                if (i == 0 && j == 0)
                    continue;
                int nexti = c1 - ci + i;
                int nextj = c2 - cj + j;
                int nextp = p ^ 1;
                if (dist[nextp][nexti][nextj] == dist[p][ci][cj] + 1) {
                    ret = (ret + modMul(C[ci][i], C[cj][j],
                            go(nextp, nexti, nextj)))
                            % MOD;
                }
            }
        }
        return dp[p][ci][cj] = ret;
    }

    public static void main(String[] args) throws Exception {
        InputReader in = new InputReader(System.in);
        int n = in.nextInt();
        k = in.nextInt();
        dist = new int[2][n + 1][n + 1];
        for (int[][] a : dist)
            for (int[] b : a)
                Arrays.fill(b, 1 << 20);
        for (int i = 0; i < n; i++) {
            int x = in.nextInt();
            if (x == 50)
                c1++;
            else
                c2++;
        }
        C = C(52);
        dist[0][c1][c2] = 0;
        dp = new long[2][n + 1][n + 1];
        for (long[][] a : dp)
            for (long[] b : a)
                Arrays.fill(b, -1);
        Queue<int[]> Q = new ArrayDeque<int[]>();
        Q.add(new int[] { 0, c1, c2 });
        while (!Q.isEmpty()) {
            int[] state = Q.poll();
            // System.out.println(Arrays.toString(state));
            int cp = state[0];
            int ci = state[1];
            int cj = state[2];
            for (int i = 0; i * 50 <= k && i <= ci; i++) {
                for (int j = 0; i * 50 + j * 100 <= k && j <= cj; j++) {
                    if (i == 0 && j == 0)
                        continue;
                    int nexti = c1 - ci + i;
                    int nextj = c2 - cj + j;
                    int nextp = cp ^ 1;
                    if (dist[nextp][nexti][nextj] == 1 << 20) {
                        dist[nextp][nexti][nextj] = 1 + dist[cp][ci][cj];
                        Q.add(new int[] { nextp, nexti, nextj });
                    }
                }
            }
        }
        if (dist[1][c1][c2] == 1 << 20) {
            System.out.println(-1);
            System.out.println(0);
        } else {
            System.out.println(dist[1][c1][c2]);
            System.out.println(go(0, c1, c2));
        }
    }

