	static int[][][][] d;
	static int[][] C;
	static int slim = 0;
	static int fat = 0;
	static int k;

	public static int get(int boat, int i, int j, int n) {
		if (i < 0 || j < 0 || n < 0) {
			return 0;
		}
		if (d[boat][i][j][n] != 0) {
			return d[boat][i][j][n] - 1;
		}
		if (n == 0) {
			if (i == 0 && j == 0) {
				d[boat][i][j][0] = 2;
			} else {
				d[boat][i][j][0] = 1;
			}
			return d[boat][i][j][0] - 1;
		}
		d[boat][i][j][n] = 1;
		long delta = 0;
		if (boat == 1) {
			for (int countSlim = 0; countSlim <= i; countSlim++) {
				for (int countFat = 0; countFat <= j && countSlim + 2 * countFat <= k; countFat++) {
					if (countFat + countSlim > 0) {
						delta = ((long)get(0,i - countSlim, j - countFat, n - 1) * (C[slim - i + countSlim][countSlim])) % 1000000007;
						delta = (delta * C[fat - j + countFat][countFat]) % 1000000007;
						d[boat][i][j][n] = (int)((d[boat][i][j][n] + delta) % 1000000007);
					}
				}
			}
		} else {
			for (int countSlim = 0; countSlim <= slim - i; countSlim++) {
				for (int countFat = 0; countFat <= fat - j && countSlim + 2 * countFat <= k; countFat++) {
					if (countFat + countSlim > 0) {
						delta = ((long)get(1, i + countSlim, j + countFat, n - 1) * (C[i + countSlim][countSlim])) % 1000000007;
						delta = (delta * C[j + countFat][countFat]) % 1000000007;
						d[boat][i][j][n] = (int)((d[boat][i][j][n] + delta) % 1000000007);
					}
				}
			}
		}
		return d[boat][i][j][n] - 1;
	}

	public static void main(String[] args) {
		FastScanner in  = new FastScanner(System.in);
		int n = in.nextInt();
		k = in.nextInt() / 50;
		for (int i = 0; i < n; i++) {
			if (in.nextInt() == 50) {
				slim++;
			} else {
				fat++;
			}
		}
		C = new int[Math.max(slim, fat) + 1][Math.max(slim, fat) + 1];
		d = new int[2][slim + 1][fat + 1][n * n + 2];
		for (int i = 0; i < Math.max(slim, fat) + 1; i++) {
			C[0][i] = 0;
			C[i][0] = 1;
		}
		for (int i = 1; i < Math.max(slim, fat) + 1; i++) {
			for (int j = 1; j < Math.max(slim, fat) + 1; j++) {
				C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % 1000000007;
			}
		}
		for (int i = 0; i < n * n + 2; i++) {
			if (get(1, slim, fat, i) != 0) {
				System.out.println(i);
				System.out.println(get(1, slim, fat, i));
				return;
			}
		}
		System.out.println(-1);
		System.out.println(0);
	}
}

