    dp[src] = 1;
    ArrayDeque<Integer> q = new ArrayDeque<Integer>();
    q.add(src);
    while(!q.isEmpty()) {
      int[] curState = getState(q.poll());
      int cur = compressState(curState);
      if(curState[0] == 0) {
        for(int i=0; i<=curState[1]; i++)
          for(int j=0; j<=curState[3]; j++) {
            if(i+j == 0) continue;
            if(i+2*j > k) continue;
            int[] nextState = new int[]{1-curState[0], curState[1]-i, curState[2]+i, curState[3]-j, curState[4]+j};
            int next = compressState(nextState);
            if(dist[next] > dist[cur] + 1) {
              dist[next] = dist[cur]+1;
              q.add(next);
              dp[next] = 0;
            }
            if(dist[next] == dist[cur]+1) {
              dp[next] = (dp[next] + dp[cur]*((pasc[curState[1]][i]*pasc[curState[3]][j])%mod))%mod;
            }
          }
      }
      else {
        for(int i=0; i<=curState[2]; i++)
          for(int j=0; j<=curState[4]; j++) {
            if(i+j == 0) continue;
            if(i+2*j > k) continue;
            int[] nextState = new int[]{1-curState[0], curState[1]+i, curState[2]-i, curState[3]+j, curState[4]-j};
            int next = compressState(nextState);
            if(dist[next] > dist[cur] + 1) {
              dist[next] = dist[cur]+1;
              q.add(next);
              dp[next] = 0;
            }
            if(dist[next] == dist[cur]+1) {
              dp[next] = (dp[next] + dp[cur]*((pasc[curState[2]][i]*pasc[curState[4]][j])%mod))%mod;
            }
          }
      }
    }
    int dest = compressState(end);
    if(dist[dest] >= oo) dist[dest] = -1;
    out.println(dist[dest]);
    out.println(dp[dest]);
    out.close();
  }
  static int[] getState(int state) {
    return new int[]{state/10000, (state%10000)/100, ones-(state%10000)/100, state%100, twos-state%100};
  }
  static int compressState(int[] state) {
    return state[0]*100*100+state[1]*100+state[3];
  }

  static class FastIO extends PrintWriter {
    BufferedReader br;
    StringTokenizer st;

    public FastIO() {
      this(System.in, System.out);
    }

    public FastIO(InputStream in, OutputStream out) {
      super(new BufferedWriter(new OutputStreamWriter(out)));
      br = new BufferedReader(new InputStreamReader(in));
      scanLine();
    }

    public void scanLine() {
      try {
        st = new StringTokenizer(br.readLine().trim());
      } catch (Exception e) {
        throw new RuntimeException(e.getMessage());
      }
    }

    public int numTokens() {
      if (!st.hasMoreTokens()) {
        scanLine();
        return numTokens();
      }
      return st.countTokens();
    }

    public String next() {
      if (!st.hasMoreTokens()) {
        scanLine();
        return next();
      }
      return st.nextToken();
    }

    public double nextDouble() {
      return Double.parseDouble(next());
    }

    public long nextLong() {
      return Long.parseLong(next());
    }

    public int nextInt() {
      return Integer.parseInt(next());
    }
  }
