	Scanner input = new Scanner(System.in);
	int n = input.nextInt(), k = input.nextInt();
	small = big = 0;
	for(int i = 0; i<n; i++)
	{
		if(input.nextInt() == 50) small++;
		else big++;
	}
	int[][][] ds = new int[2][small+1][big+1];
	for(int[][] A : ds)
		for(int[] B : A)
			Arrays.fill(B, 987654321);
	long[][][] ways = new long[2][small+1][big+1];
	ds[0][small][big] = 0;
	ways[0][small][big] = 1;
	Queue<Integer> q = new LinkedList<Integer>();
	q.add(0);
	q.add(small);
	q.add(big);
	while(!q.isEmpty())
	{
		int side = q.poll();
		int a = q.poll();
		int b = q.poll();
		int d = ds[side][a][b];
		long w = ways[side][a][b];
		int maxa = a, maxb = b;
		if(side == 1)
		{
			maxa = small - a;
			maxb = big - b;
		}
		for(int i = 0; i<=maxa; i++)
			for(int j = 0; j<=maxb; j++)
			{
				if(i*50 +  j*100 > k) break;
				if(i == 0 && j == 0) continue;
				int ns = 1 - side;
				int na = a + i * (side == 1 ? 1 : -1);
				int nb = b + j * (side == 1 ? 1 : -1);
				long edgeWays = ((long)cs[maxa][i] * cs[maxb][j])%mod;
				//System.out.println(side+" "+a+" "+b+" "+ns+" "+na+" "+nb);
				if(1+d < ds[ns][na][nb])
				{
					ds[ns][na][nb] = 1 + d;
					ways[ns][na][nb] = (w * edgeWays)%mod;
					q.add(ns);
					q.add(na);
					q.add(nb);
				}
				else if(1+d == ds[ns][na][nb])
				{
					ways[ns][na][nb] += (w*edgeWays)%mod;
					if(ways[ns][na][nb] >= mod) ways[ns][na][nb] -= mod;
				}
			}
	}
	if(ds[1][0][0] > 1e8)
		ds[1][0][0] = -1;
	System.out.println(ds[1][0][0]);
	System.out.println(ways[1][0][0]);

}
public static int[][] comb(int n)
{
	int[][] comb = new int[n+1][n+1];
	for(int i = 0; i<= n; i++)
		comb[i][0] = 1;
	for(int i = 1; i<= n; i++)
		for(int j = 1; j<= i; j++)
			comb[i][j] = (comb[i-1][j] + comb[i-1][j-1])%(int)(mod);
	return comb;
}
}

