public class C {
	static int mod = 1000000007;

	static class State implements Comparable<State> {
		int fiftyCnt, hundertCnt, where;
		int steps;
		long ways;

		public State(int f, int h, int w, int s, long way) {
			fiftyCnt = f;
			hundertCnt = h;
			where = w;
			steps = s;
			ways = way;
		}

		public int compareTo(State s) {
			return new Integer(steps).compareTo(new Integer(s.steps));
		}
	}

	static long[][] dp;
	static long[][][][] cache;
	static int boatWeight, fiftyCnt, hundretCnt;

	public static long solve(int fifty, int hundert, int where, int rem) {
		if (rem == 0) {
			if (where == 1 && fifty == 0 && hundert == 0) {
				return 1;
			}
			return 0;
		}
		if (cache[fifty][hundert][where][rem] != -1)
			return cache[fifty][hundert][where][rem];
		long res = 0;
		if (where == 0) {
			int maxFifty = boatWeight / 50;
			for (int i = 0; i <= Math.min(maxFifty, fifty); i++) {
				int maxHundret = (boatWeight - i * 50) / 100;
				int fiftyTaken = i;
				for (int j = 0; j <= Math.min(maxHundret, hundert); j++) {
					int hundretTaken = j;
					if (fiftyTaken + hundretTaken == 0)
						continue;
					res = (res + ((((solve(fifty - fiftyTaken, hundert
							- hundretTaken, 1, rem - 1) * combin(fifty,
							fiftyTaken)) % mod) * combin(hundert, hundretTaken)) % mod))
							% mod;
				}
			}
		} else {
			int maxFifty = boatWeight / 50;
			int fiftyHere = fiftyCnt - fifty;
			int hundretHere = hundretCnt - hundert;
			for (int i = 0; i <= Math.min(maxFifty, fiftyHere); i++) {
				int maxHundret = (boatWeight - i * 50) / 100;
				int fiftyTaken = i;
				for (int j = 0; j <= Math.min(maxHundret, hundretHere); j++) {
					int hundretTaken = j;
					if (fiftyTaken + hundretTaken == 0)
						continue;
					res = (res + ((((solve(fifty + fiftyTaken, hundert
							+ hundretTaken, 0, rem - 1) * combin(fiftyHere,
							fiftyTaken)) % mod) * combin(hundretHere,
							hundretTaken)) % mod))
							% mod;
				}
			}
		}
		return cache[fifty][hundert][where][rem] = res;
	}

	public static long combin(int n, int k) {
		if (n < k)
			return 0;
		if (k == 0)
			return 1;
		if (n == k)
			return 1;
		if (dp[n][k] != -1)
			return dp[n][k];
		return dp[n][k] = (combin(n - 1, k) + combin(n - 1, k - 1)) % mod;
	}

	public static void main(String[] args) throws Exception {
		int peopleCnt = nextInt();
		boatWeight = nextInt();
		fiftyCnt = 0;
		hundretCnt = 0;
		for (int i = 0; i < peopleCnt; i++) {
			if (nextInt() == 50) {
				fiftyCnt++;
			} else {
				hundretCnt++;
			}
		}
		dp = new long[Math.max(fiftyCnt, hundretCnt) + 1][Math.max(fiftyCnt,
				hundretCnt) + 1];
		for (int i = 0; i < dp.length; i++) {
			Arrays.fill(dp[i], -1);
		}
		int maxSteps = 1000;
		cache = new long[fiftyCnt + 1][hundretCnt + 1][2][maxSteps + 1];
		for (int i = 0; i <= fiftyCnt; i++) {
			for (int j = 0; j <= hundretCnt; j++) {
				for (int k = 0; k < 2; k++) {
					Arrays.fill(cache[i][j][k], -1);
				}
			}
		}
		for (int i = 1; i <= maxSteps; i++) {
			long tmp = solve(fiftyCnt, hundretCnt, 0, i);
			if (tmp != 0) {
				System.out.println(i);
				System.out.println(tmp);
				return;
			}
		}
		System.out.println(-1);
		System.out.println(0);
	}

	static BufferedReader br = new BufferedReader(new InputStreamReader(
			System.in));
	static StringTokenizer st = new StringTokenizer("");

	static int nextInt() throws Exception {
		return Integer.parseInt(next());
	}

	static String next() throws Exception {
		while (true) {
			if (st.hasMoreTokens()) {
				return st.nextToken();
			}
			String s = br.readLine();
			if (s == null) {
				return null;
			}
			st = new StringTokenizer(s);
		}
	}
}

