public class C implements Runnable{
	public static void main (String[] args) {new Thread(null, new C(), "_cf", 1 << 28).start();}

	int[] fact;
	int n50, n100;
	int n, k, MOD = (int)1e9+7, oo = (int)2e9;

	public void run() {
		FastScanner fs = new FastScanner();
		PrintWriter out = new PrintWriter(System.out);
		System.err.println("Go!");

		fact = new int[100];
		fact[0] = fact[1] = 1;
		for(int i = 2; i < fact.length; i++)
			fact[i] = mult(fact[i-1], i);
		int[][] nCk = new int[100][100];
		for(int i = 0; i < nCk.length; i++) {
			for(int j = 0; j <= i; j++) {
				nCk[i][j] = nCk(i, j);
			}
		}

		n = fs.nextInt();
		k = fs.nextInt();
		int n50 = 0, n100 = 0;
		for(int i = 0; i < n; i++) {
			int x = fs.nextInt();
			if(x == 50) n50++;
			else n100++;
		}
		this.n50 = n50;
		this.n100 = n100;

		int[][][] dist = new int[2][n50+1][n100+1];
		int[][][] ways = new int[2][n50+1][n100+1];
		for(int[][] d : dist)
			for(int[] dd : d)
				Arrays.fill(dd, oo);
		dist[0][n50][n100] = 0;
		ways[0][n50][n100] = 1;
		ArrayDeque<Node> bfs = new ArrayDeque<>();
		bfs.add(new Node(n50, n100, 0, 0));
		while(!bfs.isEmpty()) {
			Node now = bfs.pollFirst();
//			System.out.println(now);
			int nn50 = n50 - now.n50;
			int nn100 = n100 - now.n100;
			for(int i = 0; i <= now.n50; i++) {
				for(int j = 0; j <= now.n100; j++) {
					if(i + j == 0) continue;
					if(i*50 + j*100 > k) continue;
					int ndist = 1 + dist[now.side][now.n50][now.n100];
					int x = dist[now.side^1][nn50+i][nn100+j];
					int tf = mult(ways[now.side][now.n50][now.n100], mult(nCk[now.n50][i], nCk[now.n100][j]));

					if(x > ndist) {
						dist[now.side^1][nn50+i][nn100+j] = ndist;
						ways[now.side^1][nn50+i][nn100+j] = tf;
						bfs.add(new Node(nn50+i, nn100+j, now.side^1, ndist));
					}
					else if(x == ndist) {
						ways[now.side^1][nn50+i][nn100+j] = add(ways[now.side^1][nn50+i][nn100+j], tf);
					}
				}
			}
		}

		int res = dist[1][n50][n100];
		int way = ways[1][n50][n100];
		if(res == oo) { res = -1; way = 0; }
		out.printf("%d\n%d\n", res, way);

		out.close();
	}

	int add(long a, long b) {
		a %= MOD;
		b %= MOD;
		a += b;
		a %= MOD;
		return (int)a;
	}

	int nCk(int n, int k) {
		int num = fact[n];
		int den = mult(fact[k], fact[n-k]);
		int inv = inv(den);
		return mult(num, inv);
	}

	int inv(long x) {
		long res = power(x, MOD - 2, MOD);
		while(res < 0) res += MOD;
		return (int)res;
	}

	int mult(long a, long b) {
		a %= MOD;
		b %= MOD;
		a *= b;
		a %= MOD;
		return (int)a;
	}

	long power (long x, long y, long m) {
		long res = 1;
		x %= m;
		while(y > 0) {
			if(y % 2 == 1) {
				res = (res * x) % m;
			}
			y >>= 1L;
						x = (x * x) % m;
		}
		return res;
	}

	class Node implements Comparable<Node> {
		int n50, n100, side, dist;
		Node(int a, int b, int c, int d) {
			n50 = a; n100 = b;
			side = c; dist = d;
		}
		public String toString() {
			return String.format("(%d, %d) %d %d", n50, n100, side, dist);
		}
		public int compareTo(Node n) {
			return Integer.compare(dist, n.dist);
		}
	}

