public class C {

	final static long MOD = 1000000007;

	static void solve() {
		long[][] cnk = new long[100][100];
		cnk[0][0] = 1;
		for (int i = 1; i < cnk.length; i++) {
			cnk[i][0] = 1;
			for (int j = 1; j <= i; j++) {
				cnk[i][j] = cnk[i - 1][j - 1] + cnk[i - 1][j];
			}
		}

		int n = nextInt(), k = nextInt() / 50;
		int[] total = new int[3];
		for (int i = 0; i < n; i++) {
			total[nextInt() / 50]++;
		}
		long[][][] d = new long[total[1] + 1][total[2] + 1][2];
		boolean[][][] was = new boolean[total[1] + 1][total[2] + 1][2];
		int[][][] dist = new int[total[1] + 1][total[2] + 1][2];
		was[total[1]][total[2]][0] = true;
		d[total[1]][total[2]][0] = 1;
		int[] q = new int[100000];
		int ql = 0, qr = 0;
		q[qr++] = total[1];
		q[qr++] = total[2];
		q[qr++] = 0;
		while (ql < qr) {
			int c1 = q[ql++];
			int c2 = q[ql++];
			int side = q[ql++];
			int curDist = dist[c1][c2][side];
			int maxTake1 = side == 0 ? c1 : total[1] - c1;
			int maxTake2 = side == 0 ? c2 : total[2] - c2;
			for (int take1 = 0; take1 <= maxTake1; take1++) {
				for (int take2 = 0; take2 <= maxTake2 && take1 + 2 * take2 <= k; take2++) {
					if (take1 == 0 && take2 == 0)
						continue;
					int nc1 = c1 + (side == 0 ? -take1 : take1);
					int nc2 = c2 + (side == 0 ? -take2 : take2);
					int nside = 1 - side;
					if (!was[nc1][nc2][nside]) {
						was[nc1][nc2][nside] = true;
						dist[nc1][nc2][nside] = curDist + 1;
						q[qr++] = nc1;
						q[qr++] = nc2;
						q[qr++] = nside;
					}
					int nDist = dist[nc1][nc2][nside];
					if (nDist == curDist + 1) {
						long add = d[c1][c2][side] * cnk[maxTake1][take1];
						add %= MOD;
						d[nc1][nc2][nside] += add * cnk[maxTake2][take2];
						d[nc1][nc2][nside] %= MOD;
					}
				}
			}
		}
		if (!was[0][0][1]) {
			writer.println(-1);
		} else {
			writer.println(dist[0][0][1]);
		}
		writer.println(d[0][0][1]);
	}

	public static void main(String[] args) throws Exception {
		reader = new BufferedReader(new InputStreamReader(System.in));
		writer = new PrintWriter(System.out);

		setTime();
		solve();
		printTime();
		printMemory();

		writer.close();
	}

	static BufferedReader reader;
	static PrintWriter writer;
	static StringTokenizer tok = new StringTokenizer("");
	static long systemTime;

	static void debug(Object... o) {
