                c[i][j] = (c[i - 1][j] + c[i - 1][j - 1]) % p;
            }
        }

        int a = 0, b = 0;
        for(int i = 0; i < n; i++) {
            int r = nextInt();
            if (r == 50) {
                a++;
            } else {
                b++;
            }
        }

        long ans_d[][] = new long[a + 1][b + 1];
        long ans_c[][] = new long[a + 1][b + 1];

        int inf = 1 << 20;

        for(int i = 0; i <= a; i++)
            for(int j = 0; j <= b; j++) {
                ans_d[i][j] = inf;
                ans_c[i][j] = 0;
            }

        ArrayList<Integer> nowa = new ArrayList<>(0);
        ArrayList<Integer> nowb = new ArrayList<>(0);

        nowa.add(0);
        nowb.add(0);
        ans_d[0][0] = -1;
        ans_c[0][0] = 1;

        while (nowa.size() > 0) {
            int x = nowa.remove(0);
            int y = nowb.remove(0);

            for(int i = 0; i <= x; i++) {
                for(int j = 0; j <= y; j++) {
                    if (i == 0 && j == 0 && !(x == 0 && y == 0)) 
                        continue;
                    if (i + 2 * j > k)
                        break;

                    long ans = (c[x][i] * c[y][j]) % p; 

                    int q_a = a - x + i;
                    int q_b = b - y + j;

                    for(int i2 = 0; i2 <= q_a; i2++) {
                        for(int j2 = 0; j2 <= q_b; j2++) {
                            if (i2 == 0 && j2 == 0) 
                                continue;
                            if (i2 + 2 * j2 > k)
                                break;

                            int nx = x - i + i2; 
                            int ny = y - j + j2; 

                            if (ans_d[nx][ny] >= ans_d[x][y] + 2) {
                                long ans2 = (c[q_a][i2] * c[q_b][j2]) % p; 
                                ans_c[nx][ny] = (ans_c[nx][ny] + (ans_c[x][y] * ((ans * ans2) % p ) )) % p;
                            }

                            if (ans_d[nx][ny] > ans_d[x][y] + 2) {
                                ans_d[nx][ny] = ans_d[x][y] + 2;
                                nowa.add(nx);
                                nowb.add(ny);
                            }

                        }
                    }
                }
            }
        }

        out.println(ans_d[a][b] == inf ? -1 :  ans_d[a][b]);
        out.println(ans_c[a][b]);
    }

