public class C295 {
    public static Scanner sc=new Scanner(in);
    //public static Random sc=new Random();

    class Node{
        public int id;
        public int s,b,lr;
        public int val;
        public Node(int _s,int _b,int _lr){
            s=_s;b=_b;lr=_lr;
        }
//      public String toString() {
//          return val+" ("+id+")=>"+link;
//      }
    }
    class Edge{
