            this.to=to;
        }
        public Edge(int from,int to,int c){
            this(from,to);
            this.c=c;
        }
        public String toString() {
            return from+"→"+to;
        }
    }

    //nCr
    public long[][] comb(int n){
        long[][] comb=new long[n][n];
        for(int i=0;i<n;i++){
            comb[i][0]=comb[i][i]=1;
            for(int j=1;j<=i;j++){
                comb[i][j]=(j==0)?1:(comb[i-1][j]+comb[i-1][j-1])%mod;
            }
        }
        return comb;
    }

    final int mod=1000000007;
    void run() throws RuntimeException{
        final int n=sc.nextInt(),k=sc.nextInt();

        long[][] c=comb(n+1);

        int s=0,b=0;
        for(int i=0;i<n;i++){
            int v=sc.nextInt();
            if(v==50)
                s++;
            else b++;
        }

        Node[][][] nodes=new Node[s+1][b+1][2];
        long[][][] count=new long[s+1][b+1][2];
        boolean[][][] passed=new boolean[s+1][b+1][2];



        count[s][b][0]=1;
        Queue<Node> que=new LinkedList<>();
        for(int si=0;si<=s;si++)for(int bi=0;bi<=b;bi++){
            nodes[si][bi][0]=new Node(si,bi,0);
            nodes[si][bi][1]=new Node(si,bi,1);
        }

        que.add(nodes[s][b][0]);
        passed[s][b][0]=true;
        int turn=0;
        while(!que.isEmpty()){
            Queue<Node> tmp=new LinkedList<>();
            while(!que.isEmpty()){
                Node node=que.poll();
                int lr=node.lr==0?1:0;
                for(int si=0;si<=s;si++)for(int bi=0;bi<=b;bi++){
                    if(passed[si][bi][lr])continue;
                    if(node.s==si && node.b==bi)continue;
                    if(node.lr==0 && node.s>=si && node.b>=bi && abs(node.s-si)*50+abs(node.b-bi)*100<=k){//l to r
                        if(!tmp.contains(nodes[si][bi][lr]))tmp.add(nodes[si][bi][lr]);
                        count[si][bi][lr]=(count[si][bi][lr]+(c[node.s][abs(node.s-si)]*c[node.b][abs(node.b-bi)]%mod*count[node.s][node.b][node.lr]%mod))%mod;
                    }
                    if(node.lr==1 && node.s<=si && node.b<=bi && abs(node.s-si)*50+abs(node.b-bi)*100<=k){//r to l
                        if(!tmp.contains(nodes[si][bi][lr]))tmp.add(nodes[si][bi][lr]);
                        count[si][bi][lr]=(count[si][bi][lr]+(c[s-node.s][abs(node.s-si)]*c[b-node.b][abs(node.b-bi)]%mod*count[node.s][node.b][node.lr]%mod))%mod;
                    }
                }
            }
            for(Node node:tmp)passed[node.s][node.b][node.lr]=true;

            que=tmp;
            turn++;
            if(passed[0][0][1]){//end
                ln(turn);
                ln(count[0][0][1]);
                return;
            }
        }
        ln(-1);
        ln(0);
    }

    public static void main(String[] args) {
        new C295().run();
    }


    //output lib
    static final String br=System.getProperty("line.separator");
    static final String[] asep=new String[]{""," ",br,br+br};
    static String str(boolean o){
        return o?"YES":"NO";
    }
    static <K,V> String str(Map<K, V> map){
        StringBuilder sb=new StringBuilder();
        boolean isFirst=true;
        for(Entry<K,V> set:map.entrySet()){
            if(!isFirst)sb.append(br);
            sb.append(str(set.getKey())).append(":").append(str(set.getValue()));
            isFirst=false;
        }
        return sb.toString();
    }
    static <E> String str(Collection<E> list){
        StringBuilder sb=new StringBuilder();
        boolean isFirst=true;
        for(E e:list){
            if(!isFirst)sb.append(" ");
            sb.append(str(e));
            isFirst=false;
        }
        return sb.toString();
    }
    static String str(Object o){
        int depth=_getArrayDepth(o);
        if(depth>0)return _strArray(o,depth);
        return o.toString();
    }
    static int _getArrayDepth(Object o){
        if(!o.getClass().isArray() || Array.getLength(o)==0) return 0;
        return  1+_getArrayDepth(Array.get(o,0));
    }
    //depth ex A[10]…1 A[10][10]…2 exception A[0]…0 A[10][0]…1 A[0][0]…0
    static String _strArray(Object o,int depth){
        if(depth==0) return str(o);
        StringBuilder sb=new StringBuilder();
        for(int i=0,len=Array.getLength(o);i<len;i++){
            if(i!=0)sb.append(asep[depth]);
            sb.append(_strArray(Array.get(o,i),depth-1));
        }
        return sb.toString();
    }
    static void pr(Object... os){
        boolean isFirst=true;
        for(Object o:os){
            if(!isFirst)out.print(" ");
            out.print(o);
            isFirst=false;
        }
    }
    static void ln(){
        out.println();
    }
    static void ln(Object... os){
        for(Object o:os){
            pr(o);ln();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.LinkedList;
import java.util.Queue;
import java.util.StringTokenizer;


public class C {	
	BufferedReader reader;
    StringTokenizer tokenizer;
    PrintWriter out;

    public class State{
    	int c50, c100, side, step;
    	public State(int c50, int c100, int side, int step){
    		this.c50 = c50;
    		this.c100 = c100;
    		this.side = side;
    		this.step = step;
    	}
    }

    long MODULAR = 1000000007;

    public static long[][] generateCombo(int MAX, long MOD) {
		long[][] result = new long[MAX + 1][MAX + 1];
		if (MOD == 1)
			return result;
		for (int i = 0; i <= MAX; i++) {
			result[i][0] = 1;
			for (int j = 1; j <= i; j++) {
				result[i][j] = result[i - 1][j - 1] + result[i - 1][j];
				if (result[i][j] >= MOD)
					result[i][j] -= MOD;
			}
		}
		return result;
	}

	public void solve() throws IOException {				
		int N = nextInt();
		int K = nextInt();
		int c50 = 0; int c100 = 0;
		for(int i = 0; i < N; i++)
			if( nextInt() == 50)
				c50++;
			else
				c100++;

		long[][] c = generateCombo( Math.max(c50, c100), MODULAR);

		long dp[][][] = new long[c50+1][c100+1][2];
		int[][][] visited = new int[c50+1][c100+1][2];
		for(int i = 0; i <= c50; i++)
			for(int j = 0; j <= c100; j++)
				Arrays.fill(visited[i][j], -1);

		dp[c50][c100][0] = 1;
		State state = new State( c50, c100, 0, 0 );
		Queue<State> queue = new LinkedList<State>();
		queue.add(state);
		visited[c50][c100][0] = 0;

		while( !queue.isEmpty() ){
			State current = queue.poll();	

//			System.out.println( current.c50 + ", " + current.c100 + ", " + current.side + ", " + current.step );

			int iTo = current.side == 0? current.c50: c50 - current.c50;
			int jTo = current.side == 0? current.c100: c100 - current.c100;

			for(int i = 0; i <= iTo; i++){
				for(int j = 0; j <= jTo; j++){
					if( i == 0 && j == 0 ) continue;
					if( i * 50 + j * 100 > K ) continue;

					int newc50 = current.side == 0? current.c50 - i: current.c50 + i;
					int newc100 = current.side == 0? current.c100 - j: current.c100 + j;
					int newside = 1 - current.side;					 
					int newstep = current.step + 1;					

					long ways = dp[current.c50][current.c100][current.side];
					if( current.side == 0 ){
						ways = ways * c[current.c50][i] % MODULAR;
						ways = ways * c[current.c100][j] % MODULAR;
					}
					else{
						ways = ways * c[c50 - current.c50][i] % MODULAR;
						ways = ways * c[c100 - current.c100][j] % MODULAR;
					}

					if( visited[newc50][newc100][newside] == -1 ){
						dp[newc50][newc100][newside] = ways;
						visited[newc50][newc100][newside] = newstep;
						queue.add( new State(newc50, newc100, newside, newstep) );
					}
					else if ( visited[newc50][newc100][newside] == newstep ){
						dp[newc50][newc100][newside] += ways;
						dp[newc50][newc100][newside] %= MODULAR;
					}					
				}
			}

		}		

		out.println( visited[0][0][1] );
		out.println( dp[0][0][1] );
	}

	/**
	 * @param args
	 */
	public static void main(String[] args) {
		new C().run();
	}

