public class Main {
	public static BufferedReader in;
	public static PrintWriter out;

	public static void main(String[] args) throws IOException {
		in = new BufferedReader(new InputStreamReader(System.in));
		out = new PrintWriter(System.out);

		boolean showLineError = true;
		if (showLineError) {
			solve();
			out.close();
		} else {
			try {
				solve();
			} catch (Exception e) {
			} finally {
				out.close();
			}
		}

	}

	static void debug(Object... os) {
		out.println(Arrays.deepToString(os));
	}

	private static int fifty;
	private static int hundred;
	private static final long MOD = 1000000007L;

	private static void solve() throws IOException {
		String[] line = nss();
		int n = Integer.parseInt(line[0]);
		int k = Integer.parseInt(line[1]);
		fifty = 0;
		hundred = 0;
		line = nss();
		for (int i = 0; i < n; i++)
			if (line[i].equals("50")) {
				fifty++;
			} else {
				hundred++;
			}
		int m = Math.max(fifty+1, fifty+hundred+1);
		long[][] choose = new long[m][m];
		for(int i =0;i<m;i++){
			choose[i][i]=1;
			choose[i][0]=1;
		}
		for(int i =1;i<m;i++)
			for(int j =1;j<i;j++)
				choose[i][j]=(choose[i-1][j]+choose[i-1][j-1])%MOD;

		Queue<State> q = new LinkedList<State>();
		Map<State, Integer> dist = new HashMap<State, Integer>(hundred * fifty * 4);
		Map<State, Long> ways = new HashMap<State, Long>(hundred * fifty * 4);

		dist.put(new State(fifty, hundred, 0), 0);
		q.add(new State(fifty, hundred, 0));
		ways.put(new State(fifty, hundred, 0), 1L);

		while (!q.isEmpty()) {
			State u = q.poll();
			if (u.this_side == 0) {
				for (int f = 0; f <= u.fif; f++)
					for (int h = 0; h <= u.hund; h++)
						if (f+h>0)
							if (50 * f + 100 * h <= k) {
								State next = new State(u.fif - f, u.hund - h, 1);
								if (!dist.containsKey(next)) {
									dist.put(next, dist.get(u) + 1);

									long aux = (choose[u.fif][f] * choose[u.hund][h]) %MOD;
									aux = (ways.get(u)*aux) %((long )MOD);
									ways.put(next,aux);

									q.add(next);
								} else if (dist.get(next) == 1 + dist.get(u)) {
									long aux = (choose[u.fif][f] * choose[u.hund][h]) %MOD;
									aux = (ways.get(u)*aux) %((long )MOD);

									ways.put(next, (aux+ ways.get(next))%MOD);
								}
							}

			} else {
				for (int f = u.fif; f <= fifty; f++)
					for (int h = u.hund; h <= hundred; h++)
						if (f != u.fif || h != u.hund) {
							int weight = 50 * (f-u.fif) + 100 * (h-u.hund);
							if (weight <= k) {
								State next = new State(f, h, 0);
								if (!dist.containsKey(next)) {
									dist.put(next, dist.get(u) + 1);

									long aux = ( choose[fifty - u.fif][f-u.fif] * choose[hundred - u.hund][h-u.hund])%MOD;
									aux = (ways.get(u)*aux) %((long )MOD);
									ways.put(next, aux);

									q.add(next);
								} else if (dist.get(next) == 1 + dist.get(u)) {
									long aux = ( choose[fifty - u.fif][f-u.fif] * choose[hundred - u.hund][h-u.hund])%MOD;
									aux = (ways.get(u)*aux) %((long )MOD);

									ways.put(next, (ways.get(next) + aux)%MOD);
								}
							}
						}

			}
		}
		State last = new State(0, 0, 1);
		out.println((!dist.containsKey(last)?-1:dist.get(last)));
		out.println((!dist.containsKey(last)?0:ways.get(last)));

	}

	private static class State {
		public final int fif;
		public final int hund;
		public final int this_side;

		public State(int fif, int hund, int this_side) {
			super();
			this.fif = fif;
			this.hund = hund;
			this.this_side = this_side;
		}

		 @Override
		 public int hashCode() {
		 return fif + (fifty +1)* hund + (fifty +1)* (hundred +1)* this_side;
		 }

		@Override
		public String toString() {
			return "State [fif=" + fif + ", hund=" + hund + ", this_side="
					+ this_side + "]";
		}

		@Override
		public boolean equals(Object obj) {
			if (this == obj)
				return true;
			if (obj == null)
				return false;
			if (getClass() != obj.getClass())
				return false;
			State other = (State) obj;
			if (fif != other.fif)
				return false;
			if (hund != other.hund)
				return false;
			if (this_side != other.this_side)
				return false;
			return true;
		}

	}

	private static String[] nss() throws IOException {
		return in.readLine().split(" ");
	}

	private static int ni() throws NumberFormatException, IOException {
		return Integer.parseInt(in.readLine());
	}
}

