        for(int i=0;i<n;i++){
            if(is.nextInt()==50)
                l++;
            else
                m++;
        }

        long[][][] d = new long[l+1][m+1][2];
        int[][][] rides = new int[l+1][m+1][2];

        long[][] nCk = new long[101][101];
        for(int i = 0;i <= 100;i++){
            nCk[i][0] = 1;
            for(int j = 1;j <= i;j++){
                nCk[i][j] = nCk[i-1][j] + nCk[i-1][j-1];
                if(nCk[i][j] >= mod)nCk[i][j] -= mod;
            }
        }

        for(int i=0;i<=l;i++)
            for(int j=0;j<=m;j++)
                rides[i][j][1] = rides[i][j][0] = -1;

        rides[l][m][0]=0;
        d[l][m][0]=1L;
        Queue<int[]> q = new ArrayDeque<int[]>();
        q.add(new int[]{l,m,0});
        while(!q.isEmpty()){
            int[] C = q.poll();
            int s1 = C[0],s2 =C[1];

            if(C[2]==0){
            for(int i=0;i<=s1;i++)
                for(int j=0;j<=s2;j++){
                    if(i+j==0)
                        continue;
                    if(i*50+j*100>K)
                        break;
                    if(rides[s1-i][s2-j][1]==-1){
                        rides[s1-i][s2-j][1]=rides[s1][s2][0]+1;
                        d[s1-i][s2-j][1]= d[s1][s2][0]*nCk[s1][i]%mod*nCk[s2][j]%mod;
                        q.add(new int[]{s1-i,s2-j,1});
                    }else if(rides[s1-i][s2-j][1]==rides[s1][s2][0]+1){
                        d[s1-i][s2-j][1]= (d[s1-i][s2-j][1]+ d[s1][s2][0]*nCk[s1][i]%mod*nCk[s2][j]%mod) % mod;
                    }
                }
            }
            else{
                for(int i=0;i<=l-s1;i++)
                    for(int j=0;j<=m-s2;j++){
                        if(i+j==0)
                            continue;
                        if(i*50+j*100>K)
                            break;
                        if(rides[s1+i][s2+j][0]==-1){
                            rides[s1+i][s2+j][0]=rides[s1][s2][1]+1;
                            d[s1+i][s2+j][0]= d[s1][s2][1]*nCk[l-s1][i]%mod*nCk[m-s2][j]%mod;
                            q.add(new int[]{s1+i,s2+j,0});
                        }else if(rides[s1+i][s2+j][0]==rides[s1][s2][1]+1){
                            d[s1+i][s2+j][0]= (d[s1+i][s2+j][0]+ d[s1][s2][1]*nCk[l-s1][i]%mod*nCk[m-s2][j]%mod) % mod;
                        }
                    }
                }
        }

        if(rides[0][0][1]==-1){
            out.println(-1);
            out.println(0);
        }
        else{
            out.println(rides[0][0][1]);
            out.println(d[0][0][1]);
        }

    }

    void run() throws Exception
    {
        is = new Scanner(System.in);
        out = new PrintWriter(System.out);

        long s = System.currentTimeMillis();
        solve();
        out.flush();
        tr(System.currentTimeMillis()-s+"ms");
    }

