import java.io.BufferedOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;

public class Round179C {

	public static final long mod = (long)1e9 + 7;
	public static final int max = 55;
	public static long[] fact;
	public static long[] invfact;

	public static void Pre() {
		fact = new long[max];
		invfact = new long[max];
		fact[0] = invfact[0] = 1;
		for(int i = 1; i < max; i++) {
			fact[i] = (fact[i - 1] * i)%mod;
			invfact[i] = (invfact[i - 1] * ModInverse(i, mod))%mod;
		}
	}

	public static long nCr(int n, int r) {
		return (((fact[n] * invfact[n - r])%mod) * invfact[r])%mod;
	}

	public static void solve() {
		Pre();
		n = s.nextInt();
		int k = s.nextInt()/50;
		int[] arr = s.nextIntArray(n);
		int ones = 0, twos = 0;
		for(int i = 0; i < n; i++) {
			if(arr[i] == 50) {
				ones++;
			}else {
				twos++;
			}
		}
		tot_ones = ones;
		tot_twos = twos;
		reachable = new int[n + 5][n + 5][4 * n + 1];
		for(int i = 0; i < n + 5; i++) {
			for(int j = 0; j < n + 5; j++) {
				Arrays.fill(reachable[i][j], -1);
			}
		}
		int min = Recur(ones, twos, k, 0);
		if(min == Integer.MAX_VALUE) {
			out.println(-1);
			out.println(0);
		}else {
			out.println(min);
			min_moves = min;
			ways = new long[n + 5][n + 5][4 * n + 1];
			for(int i = 0; i < n + 5; i++) {
				for(int j = 0; j < n + 5; j++) {
					Arrays.fill(ways[i][j], -1);
				}
			}
			long ans = Recur2(ones, twos, k, 0);
			out.println(ans);
		}
	}

	public static int[][][] reachable;
	public static int n;
	public static int tot_ones, tot_twos;
	public static int min_moves;

	public static int Recur(int ones, int twos, int k, int move) {
		if(move > 4 * n) {
			return Integer.MAX_VALUE;
		}
		if(ones == 0 && twos == 0) {
			return reachable[ones][twos][move] = move;
		}
		if(reachable[ones][twos][move] != -1) {
			return reachable[ones][twos][move];
		}
		if((move&1) == 1) {
			int min = Integer.MAX_VALUE;
			if(tot_ones - ones >= 1) min = Integer.min(min, Recur(ones + 1, twos, k, move + 1));
			if(tot_twos - twos >= 1)min = Integer.min(min, Recur(ones, twos + 1, k, move + 1));
			reachable[ones][twos][move] = min;
		}else {
			int min = Integer.MAX_VALUE;
			for(int i = 0; i <= ones; i++) {
				if(i > k) {
					break;
				}
				int adjust = k - i;
				adjust /= 2;
				min = Integer.min(min, Recur(ones - i, adjust >= twos ? 0 : twos - adjust, k, move + 1));
			}
			reachable[ones][twos][move] = min;
		}
		return reachable[ones][twos][move];
	}

	public static long[][][] ways;

	public static long Recur2(int ones, int twos, int k, int move) {
		if(move > min_moves) {
			return 0L;
		}
		if(ones == 0 && twos == 0) {
			return 1L;
		}
		if(ways[ones][twos][move] != -1) {
			return ways[ones][twos][move];
		}
		if((move&1) == 1) {
			long ans = 0;
			int right_ones = tot_ones - ones;
			int right_twos = tot_twos - twos;
			for(int i = 0; i <= right_ones; i++) {
				if(i > k) continue;
				int aval = k - i;
				aval /= 2;
				long val = nCr(right_ones, i);
				for(int j = 0; j <= Integer.min(aval, right_twos); j++) {
					if(i == 0 && j == 0) continue;
					long tempans = (val * nCr(right_twos, j))%mod;
					ans += (tempans * Recur2(ones + i, twos + j, k, move + 1))%mod;
					if(ans >= mod) ans -= mod;
				}
			}
//			if(tot_ones - ones >= 1) ans = ((tot_ones - ones) * Recur2(ones + 1, twos, k, move + 1))%mod;
//			if(tot_twos - twos >= 1) {
//				ans += ((tot_twos - twos) * Recur2(ones, twos + 1, k, move + 1))%mod;
//				if(ans >= mod) ans -= mod;
//			}
			ways[ones][twos][move] = ans;
		}else {
			long ans = 0;
			for(int i = 0; i <= ones; i++) {
				if(i > k) {
					break;
				}
				int aval = k - i;
				aval /= 2;
				long val = nCr(ones, i);
				for(int j = 0; j <= Integer.min(aval, twos); j++) {
					if(i == 0 && j == 0) continue;
					long tempans = (val * nCr(twos, j))%mod;
					ans += (tempans * Recur2(ones - i, twos - j, k, move + 1))%mod;
					if(ans >= mod) ans -= mod;
				}
			}
			ways[ones][twos][move] = ans;
		}
		return ways[ones][twos][move];
	}

