		for (int i = 1; i < 51; i++) {
			c[i][0] = 1;
			c[i][i] = 1;
			for (int j = 1; j < i; j++) {
				c[i][j] = c[i - 1][j] + c[i - 1][j - 1];
				c[i][j] %= MOD;
			}
		}
		for (int[] x : o) {
			Arrays.fill(x, -2);
