	public static long cal(int index, int left, int a, int n, int f, int k,
			int total) {
		if (index > total) {
			return 0;
		}

		if (dp[index][left][a] != -1) {
			return dp[index][left][a];
		}
		if(index + 1 == total){
			if(a*50 + (left -a)*100 <=k){
				return 1;
			}
			return 0;
		}
		long result = 0;
		for (int i = 0; i <= a && i * 50 <= k; i++) {
			for (int x = 0; x <= left - a && x * 100 + i * 50 <= k; x++) {

				int other = n - left + x + i;
				int nxt = f - a + i;
				if(x + i == 0){
					continue;
				}
				// System.out.println(left + " " + a + " " + other + " " + nxt);
				if (left == x + i) {
					result += 1;
					// System.out.println("HE HE");
					result %= MOD;
					break;
				} else {
					long con = c[a][i] * c[left - a][x];
					con %= MOD;
					for (int j = 1; j <= other; j++) {
						for (int h = Math.min(j, nxt); h >= 0; h--) {
							if (h * 50 + (j - h) * 100 <= k && other - nxt >= j - h) {

								long v = con
										* cal(index + 2, left - x - i + j, a
												- i + h, n, f, k, total);
								v %= MOD;

								v *= c[nxt][h] * c[other - nxt][j - h];
								v %= MOD;
								result += v;
								result %= MOD;
							}else{
								break;
							}
						}
					}
				}
			}
		}
		return dp[index][left][a] = result;
	}

	public static int min(int left, int a, int n, int f, int k) {
		// System.out.println(left + " " + a);
		if (left == 0) {
			return 0;
		}
		if (o[left][a] != -2) {
			return o[left][a];
		}
		int result = -1;
		for (int i = 0; i <= a && i * 50 <= k; i++) {
			int x = k - i * 50;
			x = x / 100;
			x = Math.min(left - a, x);
			int other = n - left + x + i;
			int nxt = f - a + i;
			if (left == x + i) {
				result = 1;
				break;
			} else {
				int tmp = Integer.MAX_VALUE;
				if (nxt > 0 && (x + i > 1 || x == 1)) {
					tmp = 2 + min(left - x - i + 1, a - i + 1, n, f, k);
				}
				if (other > 0 && other != nxt && x + i > 1) {
					tmp = Math.min(tmp,
							2 + min(left - x - i + 1, a - i, n, f, k));
				}
				if (tmp != Integer.MAX_VALUE && (result == -1 || result > tmp)) {
					result = tmp;
				}
			}
		}
		return o[left][a] = result;
	}

	public static int[] KMP(String val) {
		int i = 0;
		int j = -1;
		int[] result = new int[val.length() + 1];
		result[0] = -1;
		while (i < val.length()) {
			while (j >= 0 && val.charAt(j) != val.charAt(i)) {
				j = result[j];
			}
			j++;
			i++;
			result[i] = j;
		}
		return result;

	}

	public static boolean nextPer(int[] data) {
		int i = data.length - 1;
		while (i > 0 && data[i] < data[i - 1]) {
			i--;
		}
		if (i == 0) {
			return false;
		}
		int j = data.length - 1;
		while (data[j] < data[i - 1]) {
			j--;
		}
		int temp = data[i - 1];
		data[i - 1] = data[j];
		data[j] = temp;
		Arrays.sort(data, i, data.length);
		return true;
	}

	public static int digit(long n) {
		int result = 0;
		while (n > 0) {
			n /= 10;
			result++;
		}
		return result;
	}

	public static double dist(long a, long b, long x, long y) {
		double val = (b - a) * (b - a) + (x - y) * (x - y);
		val = Math.sqrt(val);
		double other = x * x + a * a;
		other = Math.sqrt(other);
		return val + other;

	}

