class TaskE {
    final static long MOD = 1000000007;
    public void solve(@SuppressWarnings("UnusedParameters") int testNumber, TokenizerReader in, PrintWriter out) {
        int n = in.nextInt(), maxWeight = in.nextInt();
        long[][] C = new long[n+1][n+1];
        for (int i = 0; i <= n; ++i) {
            C[i][0] = C[i][i] = 1;
            for (int j = 1; j < i; ++j)
                C[i][j] = (C[i-1][j-1] + C[i-1][j]) % MOD;
        }
        maxWeight /= 50;
        int totalSmall = 0, totalBig = 0;
        for (int i = 0; i < n; ++i) {
            if (in.nextInt() == 50)
                ++totalSmall;
            else
                ++totalBig;
        }

        int[][][] time = new int[2][totalSmall + 1][totalBig + 1];
        for (int[][] ii: time)
            for (int[] i: ii)
                Arrays.fill(i, Integer.MAX_VALUE);
        for (int side = 0; side <= 1; ++side)
            for (int thisPeople = 0; thisPeople <= n; ++thisPeople)
                for (int thisSmall = Math.min(totalSmall, thisPeople); thisSmall >= 0; --thisSmall) {
                    int thisBig = thisPeople - thisSmall;
                    if (thisBig > totalBig)
                        continue;
                    int thatSmall = totalSmall - thisSmall;
                    int thatBig = totalBig - thisBig;
                    if (side == 1) {
                        if (thisPeople == n)
                            time[side][thisSmall][thisBig] = 0;
                        else if (thisSmall > 0)
                            time[side][thisSmall][thisBig] = 1 + time[0][thatSmall+1][thatBig];
                        else if (thisBig > 0)
                            time[side][thisSmall][thisBig] = 1 + time[0][thatSmall][thatBig+1];
                        continue;
                    }
                    if (thisPeople == 0)
                        continue;
                    for (int big = 0; big <= thisBig && 2*big <= maxWeight; ++big)
                        for (int small = 0; small <= thisSmall && 2*big+small <= maxWeight; ++small) {
                            if (big == thisBig && small == thisSmall)
                                time[side][thisSmall][thisBig] = 1;
                            else if (2*big + small > 1) {
                                int nextRightSmall = thatSmall + small;
                                int nextLeftBig, nextLeftSmall;
                                if (nextRightSmall > 0) {
                                    nextLeftBig = thisBig - big;
                                    nextLeftSmall = thisSmall + 1 - small;
                                } else {
                                    nextLeftBig = thisBig + 1 - big;
                                    nextLeftSmall = thisSmall - small;
                                }
                                if (nextLeftBig != thisBig || nextLeftSmall != thisSmall) {
                                    if (time[side][nextLeftSmall][nextLeftBig] < Integer.MAX_VALUE)
                                        time[side][thisSmall][thisBig] = Math.min(
                                                time[side][thisSmall][thisBig],
                                                time[side][nextLeftSmall][nextLeftBig] + 2
                                        );
                                }
                            }
                        }
                }

        int T = time[0][totalSmall][totalBig];
        if (T == Integer.MAX_VALUE) {
            out.println(-1);
            out.println(0);
            return;
        }
        long[][][] res = new long[2][totalSmall+1][totalBig+1];
        for (int t = 0; t <= T; ++t)
            for (int thisPeople = 0; thisPeople <= n; ++thisPeople)
                for (int thisSmall = 0; thisSmall <= totalSmall && thisSmall <= thisPeople; ++thisSmall) {
                    int thisBig = thisPeople - thisSmall;
                    if (thisBig > totalBig)
                        continue;
                    int side = 1 - t % 2;
                    if (time[side][thisSmall][thisBig] == 0) {
                        res[side][thisSmall][thisBig] = 1;
                        continue;
                    }
                    if (time[side][thisSmall][thisBig] != t)
                        continue;
                    for (int big = 0; big <= thisBig && 2*big <= maxWeight; ++big)
                        for (int small = 0; small <= thisSmall && 2*big + small <= maxWeight; ++small)
                            if (big + small > 0) {
                                int nextSmall = totalSmall - thisSmall + small;
                                int nextBig = totalBig - thisBig + big;
                                int nextSide = 1 - side;
                                if (time[nextSide][nextSmall][nextBig] == t-1) {
                                    long tmp = res[nextSide][nextSmall][nextBig] * C[thisBig][big] % MOD * C[thisSmall][small] % MOD;
                                    res[side][thisSmall][thisBig] += tmp;
                                    res[side][thisSmall][thisBig] %= MOD;
                                }
                            }
                }


        out.println(T);
        out.println(res[0][totalSmall][totalBig]);
    }
}

