import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.StringTokenizer;

public class C {
	static int n, k, f, h;

	public static void main(String[] args) throws IOException {
		InputReader in = new InputReader();
		n = in.nextInt();
		k = in.nextInt();
		for (int i = 0; i < n; i++) {
			int w = in.nextInt();
			if (w == 100)
				h++;
			else
				f++;
		}
		nCr(55, 55);
		dp1 = new int[55][55];
		for (int i = 0; i < 55; i++)
			Arrays.fill(dp1[i], -1);
		dp2 = new long[55][55][202];
		for (int i = 0; i < 55; i++)
			for (int j = 0; j < 55; j++)
				Arrays.fill(dp2[i][j], -1);
		r1 = getMin(f, h);
		if (r1 >= 1 << 25) {
			System.out.println(-1);
			System.out.println(0);
		} else {
			long r2 = go(f, h, 0);
			System.out.println(r1);
			System.out.println(r2);
		}
	}

	static int r1;

	public static long go(int x, int y, int t) {
		if (x == f && y == h && t == r1)
			return 1;
		if(t>=r1)return 0;
		int side = t % 2;
		if (dp2[x][y][t] != -1)
			return dp2[x][y][t];
		long ret = 0;
		for (int i = 0; i <= x && i * 50 <= k; i++) {
			for (int j = 0; j <= y && i * 50 + j * 100 <= k; j++) {
				if (i + j == 0 || (i == x && j == y && side == 1))
					continue;
				ret = (ret+((go(f-x+i, h-y+j, t+1)*c[x][i])%mod)*c[y][j])%mod;
			}
		}
		return dp2[x][y][t] = ret;
	}

	static long[][][] dp2;
	static int[][] dp1;
	static int mod = 1000000007;

	public static int getMin(int x, int y) {
		if (x == 0 && y == 0)
			return 0;
		if (dp1[x][y] != -1)
			return dp1[x][y];
		int ret = 1 << 25;
		for (int i = 0; i <= x && i * 50 <= k; i++) {
			for (int j = 0; j <= y && i * 50 + j * 100 <= k; j++) {
				if (i + j == 0)
					continue;
				if (i == x && j == y) {
					ret = 1;
				} else {
					if (i != 0 && j != 0) {
						ret = Math.min(
								ret,
								2 + Math.min(getMin(x - i + 1, y - j),
										getMin(x - i, y - j + 1)));
					} else if (i > 1 && j == 0) {
						ret = Math.min(ret, 2 + getMin(x - i + 1, y));
					} else if (i == 0) {
						if (j > 1) {
							ret = Math.min(2+getMin(x - i, y - j + 1), ret);
						}
						if (f - x >= 1) {
							ret = Math.min(2+getMin(x + 1, y - j), ret);
						}
					}
				}
			}
		}
		return dp1[x][y] = ret;
	}

	static long[][] c;

	public static void nCr(int n, int r) {
		c = new long[n + 1][r + 1];
		for (int i = 0; i < n + 1; i++)
			c[i][0] = 1;

		for (int j = 1; j <= r; j++)
			for (int i = j; i <= n; i++)
				c[i][j] = (c[i - 1][j - 1] + c[i - 1][j]) % mod;
	}

	static class InputReader {
		BufferedReader in;
		StringTokenizer st;

		public InputReader() throws IOException {
			in = new BufferedReader(new InputStreamReader(System.in));
			st = new StringTokenizer(in.readLine());
		}

		public String next() throws IOException {
			while (!st.hasMoreElements())
				st = new StringTokenizer(in.readLine());
			return st.nextToken();
		}

		public int nextInt() throws NumberFormatException, IOException {
