	static class Solver implements Runnable
	{
		int n, b;
		int[] arr;
		InputReader in;
		PrintWriter out;

		void solve() throws IOException
		{
			n = in.nextInt();
			b = in.nextInt();
			arr = in.nextIntArray(n);

			PriorityQueue<Integer> set = new PriorityQueue<>(Integer::compareTo);
			int odd = 0;
			int even = 0;

			for (int i = 0; i < n; i++)
			{
				if (arr[i] % 2 == 0)
					even++;
				else
					odd++;

				if (i < n - 1 && even == odd)
					set.add(Math.abs(arr[i] - arr[i + 1]));
			}

			int cnt = 0;

			while (set.size() > 0)
			{
				int x = set.poll();

				if (x <= b)
				{
					cnt++;
					b -= x;
				}
				else
					break;
			}

			out.println(cnt);
		}

