public class Cutting {
	public static void main(String[] args) {
		Scanner input = new Scanner(System.in);

		int n = input.nextInt();
		int b = input.nextInt();

		int[] a = new int[n + 1];
		int[] even = new int[n + 1];
		int[] odd = new int[n + 1];

		for (int i = 1; i <= n; i++) {
			a[i] = input.nextInt();
			if (a[i] % 2 == 0) {
				even[i] = even[i - 1] + 1;
				odd[i] = odd[i - 1];
			} else {
				odd[i] = odd[i - 1] + 1;
				even[i] = even[i - 1];
			}
		}

		input.close();

		List<Integer> l = new ArrayList<>();
		for (int j = 2; j < n; j++) {
			int diff = Math.abs(a[j] - a[j + 1]);
			if (even[j] == odd[j]) {
				l.add(diff);
			}
		}

		Collections.sort(l);

		int count = 0;
		for (int i = 0; i < l.size(); i++) {
			if (b >= l.get(i)) {
				b -= l.get(i);
				count++;
			}
		}

		System.out.println(count);
	}
}

