        int n = Integer.parseInt(input.split(" ")[0]);
        int bitCoins = Integer.parseInt(input.split(" ")[1]);
        String[] values = s.nextLine().split(" ");
        int odd = 0;
        int even = 0;
        int count = 0;
        ArrayList<Integer> val = new ArrayList<Integer>();
        for (int i = 0; i < n - 1; i++ ) {
            if(Integer.parseInt(values[i]) % 2 == 0) {
                even++;   
            } else {
                odd++;
            }
            if(odd == even) {
               int diff =  Integer.parseInt(values[i + 1]) - Integer.parseInt(values[i]);
               if (diff < 0) {
                   diff = diff * -1;
               }
               val.add(diff);
            }
        }
        Collections.sort(val);
        for (int j = 0; j < val.size(); j++ ) {
            if (val.get(j) <= bitCoins) {
                bitCoins = bitCoins - val.get(j);
                count++;
            } else {
                break;
            }
        }
        System.out.println(count);
     }
}

