        int start = 0, end = n - 1, mid, ans = -1;

        while (start <= end) {
            mid = (start + end) >> 1;
            if (a[mid] >= v) {
                ans = mid;
                end = mid - 1;
            } else if (a[mid] < v) {
                //ans=mid;
                start = mid + 1;
            }

        }
        return ans;
    }

    static boolean Last_Ocuu(long[] a, int n, long v) {
        int sta = 1, end = n - 1;
        while (sta <= end) {
            int mid = (sta + end) >> 1;
            if (a[mid] == v) {
                return true;
            } else if (a[mid] > v) {
                end = mid - 1;
            } else {
                sta = mid + 1;
            }
        }
        return false;
    }

