public class Main {

    public static int MOD = (int)Math.pow(10, 9)+7;


    public static long powMod(long X,long N){
        long result = 1;
        X = X % MOD;
        while(N > 0){
            if(N % 2 == 1)
                result = (result * X) % MOD;
            N >>= 1;
            X = (X*X)%MOD;
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);

        long X = in.nextLong();
        long K = in.nextLong();
        if(X == 1)
            System.out.println(powMod(2, K) + 1);
        else if(X == 0)
            System.out.println(0);
        else if(K == 0)
            System.out.println((X*2)%MOD);
        else {
            long upperLimit = ((X%MOD) * powMod(2, K)) /*% MOD*/;
            long diff = (X - 1) % MOD;
            long lowerLimit = ((-diff*((1-powMod(2, K)))) + (X%MOD))%MOD;

            System.out.println((upperLimit + lowerLimit) % MOD);
        }

    }
}

