	void solve() throws IOException {
		long sum = readLong();

		List<Long> divisors = new ArrayList<Long>();
		for (long d = 1; d <= sum / d; ++d) {
			if (sum % d == 0) {
				divisors.add(d);
				if (sum / d != d) {
					divisors.add(sum / d);
				}
			}
		} 

		Map<Long, Integer> indexes = new HashMap<Long, Integer>();
		for (int i = 0; i < divisors.size(); ++i) {
			long d = divisors.get(i);
			indexes.put(d, i);
		}

		Map<Long, List<Integer>> classes = new HashMap<Long, List<Integer>>();
		for (int i = 0; i < divisors.size(); ++i) {
			long d = divisors.get(i) - 1;

			boolean found = false;
			for (long prime = 2; prime <= d / prime; ++prime) {
				if (d  % prime == 0) {
					long x = d;
					while (x % prime == 0) {
						x /= prime;
					}

					if (x == 1) {
						add(classes, prime, i);
						found = true;
					}

					break;
				}
			}

			if (!found) {
				boolean isPrime = (d > 1);
				for (long dd = 2; dd <= d / dd; ++dd) {
					if (d % dd == 0) {
						isPrime = false;
						break;
					}
				}

				if (isPrime) {
					add(classes, d, i);
				}
			}
		}

		int divisorsCount = divisors.size();
		int classesCount = classes.size();

		long[] curDp = new long[divisorsCount];
		long[] nextDp = new long[divisorsCount];

		curDp[indexes.get(1L)] = 1;

		for (Map.Entry<Long, List<Integer>> e : classes.entrySet()) {
			List<Integer> classIndexes = e.getValue();

			for (int i = 0; i < divisorsCount; ++i) {
				long d = divisors.get(i);
				if (curDp[i] == 0) continue;

				for (int classIndex : classIndexes) {
					long classD = divisors.get(classIndex);

					if (sum / classD >= d) {
						long nextD = d * classD;

						if (sum % nextD == 0) {
							int nextI = indexes.get(nextD);

							nextDp[nextI] += curDp[i];
						}
					}
				}
			}

			for (int i = 0; i < divisorsCount; ++i) {
				curDp[i] += nextDp[i];
				nextDp[i] = 0;
			}
		}

		out.println(curDp[indexes.get(sum)]);
	}

	void add(Map<Long, List<Integer>> classes, long key, int value) {
		List<Integer> keyClass = classes.get(key);
		if (keyClass == null) {
			classes.put(key, keyClass = new ArrayList<Integer>());
		}

		keyClass.add(value);
	}
}

