    static class O implements Runnable {
        public void run() {
            try {
                magic();
            }
            catch (Exception e) {
                e.printStackTrace();
                System.exit(1);
            }
        }
    }
    static class FastReader {
        final private int BUFFER_SIZE = 1 << 16;
        private DataInputStream din;
        private byte[] buffer;
        private int bufferPointer, bytesRead;

        public FastReader() {
            din = new DataInputStream(System.in);
            buffer = new byte[BUFFER_SIZE];
            bufferPointer = bytesRead = 0;
        }

        public FastReader(String file_name) throws IOException {
            din = new DataInputStream(new FileInputStream(file_name));
            buffer = new byte[BUFFER_SIZE];
            bufferPointer = bytesRead = 0;
        }

        public String readLine() throws IOException {
            byte[] buf = new byte[1000000];
            int cnt = 0, c;
            while ((c = read()) != -1) {
                if (c == '\n') break;
                buf[cnt++] = (byte) c;
            }
            return new String(buf, 0, cnt);
        }

        public int nextInt() throws IOException {
            int ret = 0;
            byte c = read();
            while (c <= ' ') c = read();
            boolean neg = (c == '-');
            if (neg) c = read();
            do {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');
            if (neg) return -ret;
            return ret;
        }

        public long nextLong() throws IOException {
            long ret = 0;
            byte c = read();
            while (c <= ' ') c = read();
            boolean neg = (c == '-');
            if (neg) c = read();
            do {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');
            if (neg) return -ret;
            return ret;
        }

        public double nextDouble() throws IOException {
            double ret = 0, div = 1;
            byte c = read();
            while (c <= ' ') c = read();
            boolean neg = (c == '-');
            if (neg) c = read();
            do {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');
            if (c == '.') while ((c = read()) >= '0' && c <= '9') ret += (c - '0') / (div *= 10);
            if (neg) return -ret;
            return ret;
        }

        private void fillBuffer() throws IOException {
            bytesRead = din.read(buffer, bufferPointer = 0, BUFFER_SIZE);
            if (bytesRead == -1) buffer[0] = -1;
        }

        private byte read() throws IOException {
            if (bufferPointer == bytesRead) fillBuffer();
            return buffer[bufferPointer++];
        }

        public void close() throws IOException {
            if (din == null) return;
            din.close();
        }
    }
    static int n,m,k[],rem[];
    static Pair offers[];
    static TreeSet<Integer> offers_at[];
    static void magic() throws IOException {
        reader = new FastReader();
        writer = new PrintWriter(System.out, true);
        n = reader.nextInt();
        m = reader.nextInt();
        k = new int[n];
        rem = new int[n];
        for(int i=0;i<n;++i) {
            k[i] = reader.nextInt();
        }
        offers = new Pair[m];
        offers_at = new TreeSet[n];
        for(int i=0;i<n;++i) {
            offers_at[i] = new TreeSet<>();
        }
        for(int i=0;i<m;++i) {
            offers[i] = new Pair(reader.nextInt(), reader.nextInt()-1);
            offers_at[offers[i].y].add(offers[i].x);
        }
        Arrays.sort(offers);
        int low = 1, high = 4000000, mid;
        while(low<high) {
            mid = (low+high)>>1;
            if(check(mid)) {
                if(!check(mid-1)) {
                    low = mid;
                    break;
                }
                else high = --mid;
            }
            else low = ++mid;
        }
        writer.println(low);
    }
    static boolean check(int D) {
        for(int i=0;i<n;++i) {
            rem[i] = k[i];
        }
        int curr = 0, prev = 0;
        for(int i=0;i<m;++i) {
            if(offers[i].x>D) {
                break;
            }
            curr+=(offers[i].x - prev);
            prev = offers[i].x;
            if(offers_at[offers[i].y].lower(D+1)==offers[i].x) {
                int liya = min(curr, rem[offers[i].y]);
                curr-=liya;
                rem[offers[i].y]-=liya;
            }
            else {
                continue;
            }
        }
        curr+=(D-prev);
        int left = 0;
        for(int i=0;i<n;++i) {
            left+=rem[i];
        }
        return curr>=2*left;
    }
    static class Pair implements Comparable<Pair>
    {
        int x,y;
        Pair(int x,int y)
        {
            this.x=x;
            this.y=y;
        }
        public int compareTo(Pair other)
        {
            if(this.x!=other.x)
                return this.x-other.x;
            return this.y-other.y;
        }
        public String toString()
        {
            return "("+x+","+y+")";
        }
    }
}

