    static void process(int index, String val) {
        for (int i = 0; i < val.length(); i++) {
            int j = val.charAt(i) - '0';
            pre[index][j] = true;
        }
    }

    static boolean check(String val, String[] guess, int[] b, int[] c) {
        boolean[] count = new boolean[10];
        for (int i = 0; i < val.length(); i++) {
            int index = val.charAt(i) - '0';
            if (count[index]) {
                return false;
            }
            count[index] = true;
        }
        for (int i = 0; i < guess.length; i++) {
            int m = 0;
            int n = 0;
            for (int j = 0; j < 4; j++) {
                if (val.charAt(j) == guess[i].charAt(j)) {
                    m++;
                } else if (count[guess[i].charAt(j) - '0']) {
                    n++;
                }
            }
            if (b[i] != m || c[i] != n) {
                return false;
            }
        }
        return true;

    }

