class TaskE_CF_Round {
    public static final int MOD = (int)1e9 + 7;

    public void solve(int testNumber, InputReader in, PrintWriter out) {
        int[] w = Utils.readIntArray(in, 7);
        int[][][] a = new int[7][][];
        for (int i = 1; i <= 7; ++i) {
            a[i-1] = getMatrix(i);
            a[i-1] = MatrixUtils.pow(a[i-1], w[i-1], MOD);
        }
        int[] d = new int[1 << 7];
        int last = -1;
        int[] memo = new int[1 << 7];
        for (int i = 0; i < 7; ++i) {
            for (int j = (1 << (i+1))-1; j >= 0; --j) {
                if (d[j] != 0) {
                    d[j | (1 << i)] = d[j];
                    d[j] = 0;
                }
            }
            if (w[i] != 0) {
                if (last == -1) {
                    d[(1 << (i+1)) - 1] = 1;
                }
                last = i;
                int[] nd = new int[1 << 7];
                for (int j = 0; j < (1 << 7); ++j) {
                    if (d[j] > 0) {
                        for (int k = 0; k < (1 << 7); ++k) {
                            if (a[i].length > j && a[i][j].length > k) {
                                nd[k] += (d[j] * 1L * a[i][j][k]) % MOD;
                                if (nd[k] >= MOD) {
                                    nd[k] -= MOD;
                                }
                            }
                        }
                    }
                }
                int[] temp = d;
                d = nd;
                nd = temp;
                Arrays.fill(nd, 0);
                memo = d.clone();
            }
        }
        out.println(memo[(1 << (last+1)) - 1]);
    }

    private int[][] getMatrix(int w) {
        int[][] a = new int[1 << w][1 << w];
        for (int maskLeft = 0; maskLeft < (1 << w); ++maskLeft) {
            for (int maskRight = 0; maskRight < (1 << w); ++maskRight) {
                for (int mask = 0; mask < (1 << (w-1)); ++mask) {
                    boolean ok = true;
                    for (int bit = 0; bit < w; ++bit) {
                        if (BitUtils.checkBit(maskLeft, bit) && BitUtils.checkBit(maskRight, bit)) {
                            boolean upper = bit == 0 || BitUtils.checkBit(mask, bit-1);
                            boolean lower = bit == w-1 || BitUtils.checkBit(mask, bit);
                            if (upper && lower) {
                                ok = false;
                            }
                        }
                    }
                    if (ok) {
                        ++a[maskLeft][maskRight];
                    }
                }
            }
        }
        return a;
    }
}

