import java.util.LinkedList;
import java.util.Scanner;


public class T440C {
	private long[] N = {
			1,
			11,
			111,
			1111,
			11111,
			111111,
			1111111,
			11111111,
			111111111,
			1111111111,
			11111111111L,
			111111111111L,
			1111111111111L,
			11111111111111L,
			111111111111111L,
			1111111111111111L
		};

	public long solve(long n) {
		long ans = Long.MAX_VALUE;
		LinkedList<long[]> l = new LinkedList<long[]>();
		l.add(new long[] {n, 0});
		long[] e;
		while (!l.isEmpty()) {
			e = l.getFirst();
			l.removeFirst();

			if (e[0] == 0 || e[1] > ans) {
				ans = Math.min(ans, e[1]);
				continue;
			}
			for (int i = N.length - 1; i >= 0; i --) {
				if (e[0] >= N[i]) {
					long x,y;

					y = e[1] + (e[0] / N[i]) *(i + 1);
					x = e[0] % N[i];
					l.add(new long[] {x, y});

					if (i < N.length - 1) {
						y = e[1] + (i + 1) + 1;
						x = N[i + 1] - e[0];
						l.add(new long[] {x, y});

					}
					break;
				}
			}
		}
		return ans;
	}
	public static void main(String[] args) {
		T440C t = new T440C();


		//long n = 973546235465729L;
		Scanner in = new Scanner(System.in);
		long n = in.nextLong();

		System.out.println(t.solve(n));
	}

}

import java.util.Arrays;
import java.util.Scanner;

public class C {
    static int inf = (int) 1e6;
    static int[][][][] DP;
    static String number;

    public static int get(int index, int pos, int neg, int carry) {
        int truCarry = carry - 50;
        if (index == 17) {
            if (pos + neg + truCarry == 0) {
                return 0;
            } else {
                return inf;
            }
        }
        if (DP[index][pos][neg][carry] != -1)
            return DP[index][pos][neg][carry];
        int res = inf;
        for (int p = 0; p <= Math.min(15, pos); p++)
            for (int n = 0; n <= Math.min(15, neg); n++) {
                int sum = pos - neg + truCarry;
                int currentBit = (sum % 10 + 10) % 10;
                int nextCarry = sum > 0 ? (sum / 10) : ((sum - 9) / 10);
                if (currentBit != number.charAt(index) - '0')
                    continue;
                res = Math.min(res,
                        get(index + 1, pos - p, neg - n, nextCarry + 50)
                                + (p + n) * (index + 1));
            }
        return DP[index][pos][neg][carry] = res;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        long n = in.nextLong();
        int size = 50;
        DP = new int[20][size][size][100];
        for (int i = 0; i < 20; i++)
            for (int j = 0; j < size; j++)
                for (int k = 0; k < size; k++)
                    Arrays.fill(DP[i][j][k], -1);
        number = "" + n;
        while (number.length() < 17)
            number = "0" + number;
        number = new StringBuffer(number).reverse().toString();
        int res = inf;
        for (int pos = 0; pos < size; pos++)
            for (int neg = 0; neg < size; neg++)
                res = Math.min(res, get(0, pos, neg, 50));
        System.out.println(res);
    }
}

