public class C{
	int n;
	int[][]min;
	int[][]max;
	int[][]active;		
	int[]pFlow;
	int inf=Integer.MAX_VALUE/100;
	int[]res;
	int allCost=0;
	void solve()throws Exception
	{		

		n=nextInt();
		min=new int[n][n];
		max=new int[n][n];
		active=new int[n][n];
		int sum=0;
		for(int step=1;step<=n*(n-1)/2;step++)
		{
			int a=nextInt()-1;
			int b=nextInt()-1;
			min[a][b]=nextInt();
			max[a][b]=nextInt();
			active[a][b]=nextInt();
			sum+=max[a][b];
		}
		res=new int[]{inf,-inf};
		sum++;								
		pFlow=new int[n];
		rec(0,1);
		if(res[0]==inf)
			res=new int[]{-1,-1};
		System.out.println(res[0]+" "+res[1]);
	}


	private void rec(int a, int b) {
		if(res[0]<pFlow[0])
			return;
		if(a==n-1)
		{									
			if(pFlow[0]<res[0] || (res[0]==pFlow[0] && allCost>res[1]))
			{
				res[0]=pFlow[0];
				res[1]=allCost;

			}
			return ;
		}		
		if(b==n)
		{
			if(a!=0 && pFlow[a]!=0)
				return;
			rec(a+1,a+2);			
		}
		else
		{							
			for(int x=min[a][b];x<=max[a][b];x++)
			{
				int curCost=x*x+(x>0?active[a][b]:0);
				pFlow[a]+=x;
				pFlow[b]-=x;
				allCost+=curCost;
				rec(a,b+1);
				allCost-=curCost;
				pFlow[a]-=x;
				pFlow[b]+=x;				
			}						
		}

	}


	BufferedReader reader;
	PrintWriter writer;
	StringTokenizer stk;
	void run()throws Exception
	{
		reader=new BufferedReader(new InputStreamReader(System.in));
		stk=null;
		writer=new PrintWriter(System.out);
		solve();
		reader.close();
		writer.close();
	}
	int nextInt()throws Exception
	{
		return Integer.parseInt(nextToken());
	}
	long nextLong()throws Exception
	{	
		return Long.parseLong(nextToken());
	}
	double nextDouble()throws Exception
	{		
		return Double.parseDouble(nextToken());
	}
	String nextString()throws Exception
	{
		return nextToken();
	}
	String nextLine()throws Exception
	{
		return reader.readLine();
	}
	String nextToken()throws Exception
	{
		if(stk==null || !stk.hasMoreTokens())
		{
			stk=new StringTokenizer(nextLine());
			return nextToken();
		}
		return stk.nextToken();
	}

	public static void main(String[]args) throws Exception
	{	
		new C().run();

	}

}

