class TaskD {
    private long MOD;

    private long powInd(long a, long n) {
        if (n == 0) return 1;
        if ((n & 1) != 0) return (a * powInd((a * a) % MOD, n / 2)) % MOD;
        return powInd((a * a) % MOD, n / 2) % MOD;
    }

    private long getFibb(long n) {
        long a11 = 1, a12 = 1, a21 = 1, a22 = 0;
        long r11 = 1, r12 = 0;
        long q11 = 0, q12 = 0, q21 = 0, q22 = 0;
        while (n > 0) {
            if ((n & 1) == 1) {
                q11 = (r11 * a11 + r12 * a21) % MOD;
                q12 = (r11 * a12 + r12 * a22) % MOD;
                r11 = q11;
                r12 = q12;
            }
            q11 = (a11 * a11 + a12 * a21) % MOD;
            q12 = (a11 * a12 + a12 * a22) % MOD;
            q21 = (a21 * a11 + a22 * a21) % MOD;
            q22 = (a21 * a12 + a22 * a22) % MOD;
            a11 = q11;
            a12 = q12;
            a21 = q21;
            a22 = q22;

            n >>= 1;
        }
        return r12;
    }

    public void solve(int testNumber, Scanner in, PrintWriter out) {
        long n = in.nextLong(), k = in.nextLong(), l = in.nextLong(), m = in.nextLong();
        MOD = m;

        if (l < 63 && k >= (1L << l)) {
            out.println(0);
            return;
        }

        long fib = getFibb(n + 2);
        long pow = powInd(2, n);
        long res = 1;

        long diff = pow - fib;
        while (diff < 0) diff += MOD;

        for (int bit = 0; bit < l; bit++) {
            if ((k & (1L << bit)) != 0) {
                res = (res * diff) % MOD;
            } else {
                res = (res * fib) % MOD;
            }
        }


        out.println(res % MOD);
    }
}

