// Hide-and-Seek
// 2012/04/17
public class _P032E{
	Scanner sc=new Scanner(System.in);

	int INF=1<<28;
	double EPS=1e-9;

	P v, p, w1, w2, m1, m2;

	void run(){
		v=new P(sc.nextInt(), sc.nextInt());
		p=new P(sc.nextInt(), sc.nextInt());
		w1=new P(sc.nextInt(), sc.nextInt());
		w2=new P(sc.nextInt(), sc.nextInt());
		m1=new P(sc.nextInt(), sc.nextInt());
		m2=new P(sc.nextInt(), sc.nextInt());
		solve();
	}

	void solve(){
		println((ok1()||ok2())?"YES":"NO");
	}

	boolean ok1(){
		if(crsSS(p, v, w1, w2)){
			return false;
		}else if(crsSS(p, v, m1, m2)){
			return linear(p, v, m1)&&linear(p, v, m2);
		}else{
			return true;
		}
	}

	boolean ok2(){
		P m=m2.sub(m1);
		if(m.det(p.sub(m1))*m.det(v.sub(m1))<EPS){
			return false;
		}else{
			P h=isLL(m1, m2, p, proj(m1, m2, v).mul(2).sub(v));
			return disSP(m1, m2, h)<EPS&&!crsSS(p, h, w1, w2)
					&&!crsSS(h, v, w1, w2);
		}
	}

	// p1,p2,p3の1直線上判定
	boolean linear(P p1, P p2, P p3){
		return abs(p2.sub(p1).det(p3.sub(p1))/2)<EPS;
	}

	// 線分と点の距離
	double disSP(P p1, P p2, P q){
		if(p2.sub(p1).dot(q.sub(p1))<EPS)
			return q.sub(p1).abs();
		if(p1.sub(p2).dot(q.sub(p2))<EPS)
			return q.sub(p2).abs();
		return disLP(p1, p2, q);
	}

	// 直線と点の距離
	double disLP(P p1, P p2, P q){
		return abs(p2.sub(p1).det(q.sub(p1)))/p2.sub(p1).abs();
	}

	// 線分と線分の交差判定
	boolean crsSS(P p1, P p2, P q1, P q2){
		if(max(p1.x, p2.x)+EPS<min(q1.x, q2.x))
			return false;
		if(max(q1.x, q2.x)+EPS<min(p1.x, p2.x))
			return false;
		if(max(p1.y, p2.y)+EPS<min(q1.y, q2.y))
			return false;
		if(max(q1.y, q2.y)+EPS<min(p1.y, p2.y))
			return false;
		return signum(p2.sub(p1).det(q1.sub(p1)))
				*signum(p2.sub(p1).det(q2.sub(p1)))<EPS
				&&signum(q2.sub(q1).det(p1.sub(q1)))
						*signum(q2.sub(q1).det(p2.sub(q1)))<EPS;
	}

	// 点から直線に下ろした垂線の足
	P proj(P p1, P p2, P q){
		return p1.add(p2.sub(p1).mul(
				p2.sub(p1).dot(q.sub(p1))/p2.sub(p1).abs2()));
	}

	// 直線と直線の交点
	P isLL(P p1, P p2, P q1, P q2){
		double d=q2.sub(q1).det(p2.sub(p1));
		if(abs(d)<EPS)
			return null;
		return p1.add(p2.sub(p1).mul(q2.sub(q1).det(q1.sub(p1))/d));
	}

	class P{
		double x, y;

		P(){
			this(0, 0);
		}

		P(double x, double y){
			this.x=x;
			this.y=y;
		}

		P add(P p){
			return new P(x+p.x, y+p.y);
		}

		P sub(P p){
			return new P(x-p.x, y-p.y);
		}

		P mul(double m){
			return new P(x*m, y*m);
		}

		P div(double d){
			return new P(x/d, y/d);
		}

		double abs(){
			return sqrt(abs2());
		}

		double abs2(){
			return x*x+y*y;
		}

		double arg(){
			return atan2(y, x);
		}

		double dot(P p){
			return x*p.x+y*p.y;
		}

		double det(P p){
			return x*p.y-y*p.x;
		}

		double ang(P p){
			return atan2(det(p), dot(p));
		}

		P rot(double d){
			return new P(cos(d)*x-sin(d)*y, sin(d)*x+cos(d)*y);
		}
	}

