public class Main implements Runnable {

	final static double eps = 1e-7;

	class Point {
		double x, y;
		Point(double x, double y) {
			this.x = x;
			this.y = y;
		}
		Point add(Point o) {
			return new Point(x + o.x, y + o.y);
		}
		Point sub(Point o) {
			return new Point(x - o.x, y - o.y);
		}
		Point scale(double f) {
			return new Point(x * f, y * f);
		}
		double len() {
			return Math.sqrt(x * x + y * y);
		}
	}

	double dot(Point a, Point b) {
		return a.x * b.x + a.y * b.y;
	}

	double cross(Point a, Point b) {
		return a.x * b.y - a.y * b.x;	
	}

	boolean onSegment(Point x, Point a, Point b) {
		if (!zero(cross(a.sub(x), b.sub(x))))
			return false;
		return dot(a.sub(x), b.sub(x)) <= eps;
	}

	Point linesIntersection(Point a, Point b, Point c, Point d) {
		double d1 = cross(c.sub(a), b.sub(a));
		double d2 = cross(d.sub(a), b.sub(a));
		if (Math.abs(d1 - d2) < eps)
			return null;		
		return (d.scale(d1).sub(c.scale(d2))).scale(1 / (d1 - d2));
	}

	boolean segsIntersect(Point a, Point b, Point c, Point d) {
		Point p = linesIntersection(a, b, c, d);
		if (p == null)
			return false;
		return onSegment(p, a, b) && onSegment(p, c, d);
	}

	boolean zero(double x) {
		return Math.abs(x) < eps;
	}

	int sign(double x) {
		if (zero(x)) return 0;
		return x < 0 ? -1 : 1;
	}

	Point reflect(Point x, Point a, Point b) {
		Point v = x.sub(a);
		Point dir = b.sub(a);
		dir = dir.scale(1 / dir.len());
		Point pr = dir.scale(dot(dir, v));
		return a.add(pr.scale(2).sub(v));
	}

