public class b implements Runnable {

	Vec me, other;
	Seg wall, mirror;

	double getAngle(Vec a, Vec mid, Vec b) {
		Vec u = a.sub(mid), v = b.sub(mid);
		//u.v = |u|*|v|*cos(theta)
		//theta = arccos((u.v)/(|u|*|v|))
		return Math.acos(u.dot(v) / u.mag() / v.mag());
	}

	double go(double scale) {
		Vec unit = mirror.dir.unit();
		Vec leftmost = mirror.from.sub(unit);
		Vec rightmost = mirror.to.add(unit);
		Vec pt = mirror.from.add(unit.scale(scale));
		double left = getAngle(me, pt, leftmost);
		double right = getAngle(other, pt, rightmost);
		return Math.abs(left - right);
	}

	public void solve(FS in, PrintWriter out) {
		me = new Vec(in.nextDouble(), in.nextDouble());
		other = new Vec(in.nextDouble(), in.nextDouble());
		wall = new Seg(new Vec(in.nextDouble(), in.nextDouble()), new Vec(in.nextDouble(), in.nextDouble()));
		mirror = new Seg(new Vec(in.nextDouble(), in.nextDouble()), new Vec(in.nextDouble(), in.nextDouble()));

		Seg meOther = new Seg(me, other);
		if(!meOther.intersects(wall, true) && !meOther.intersects(mirror, false)) {
			out.println("YES");
			return;
		}
		if(meOther.intersects(mirror, false)) {
			out.println("NO");
			return;
		}

		double lo = 0, hi = mirror.dir.mag();
		for(int it = 0; it < 2000; ++it) {
			double delta = (hi - lo) / 3;
			double m1 = lo + delta, m2 = hi - delta;
			double leftDiff = go(m1), rightDiff = go(m2);
			if(leftDiff < rightDiff) hi = m2;
			else lo = m1;
		}

		Vec mirrorPt = mirror.from.add(mirror.dir.unit().scale(lo));
		double diff = go(lo);
		if(diff > 1e-6) {
			out.println("NO");
			return;
		}

		if(!mirror.containsPoint(mirrorPt)) {
			out.println("NO");
			return;
		}
		Seg meMirror = new Seg(me, mirrorPt);
		Seg otherMirror = new Seg(other, mirrorPt);
		if(meMirror.intersects(wall, true) || otherMirror.intersects(wall, true)) {
			out.println("NO");
			return;
		}
		out.println("YES");
	}

	public void run() {
		System.err.println("go!");
		FS in = new FS();
		PrintWriter out = new PrintWriter(System.out);
		solve(in, out);
		out.close();
	}

	static class Vec {
		static final double EPS=1e-6;
		double x, y;

		public Vec(double x, double y) {
			this.x=x;
			this.y=y;
		}

		public Vec add(Vec o) {
			return new Vec(x+o.x, y+o.y);
		}

		public Vec sub(Vec o) {
			return new Vec(x-o.x, y-o.y);
		}

		public Vec scale(double s) {
			return new Vec(x*s, y*s);
		}

		public double dot(Vec o) {
			return x*o.x+y*o.y;
		}

		public double cross(Vec o) {
			return x*o.y-y*o.x;
		}

		public double mag2() {
			return dot(this);
		}

		public double mag() {
			return Math.sqrt(mag2());
		}

		public Vec unit() {
			return scale(1/mag());
		}

		public Vec rot90() {
			return new Vec(-y, x);
		}

		public Vec rot270() {
			return new Vec(y, -x);
		}

		public Vec rotate(double theta) {
			double PI=Math.PI;
			double newX=x*Math.cos(theta)+y*Math.cos(PI/2+theta);
			double newY=x*Math.sin(theta)+y*Math.sin(PI/2+theta);
			return new Vec(newX, newY);
		}

		//angle between 0 and 2PI
		public double angle() {
			return (Math.atan2(y, x)+2*Math.PI)%(2*Math.PI);
		}

		public String toString() {
			DecimalFormat df=new DecimalFormat("#.##");
			return "("+df.format(x)+", "+df.format(y)+")";
		}

		static boolean eq(double a, double b) {
			return Math.abs(a-b)<EPS;
		}

		static boolean leq(double a, double b) {
			return a-EPS<b;
		}

		static boolean geq(double a, double b) {
			return a+EPS>b;
		}

		public boolean equals(Object oo) {
			Vec o=(Vec)oo;
			return eq(x, o.x)&&eq(y, o.y);
		}
	}

	static class Seg {
		Vec from, to, dir;

		public Seg(Vec from, Vec to) {
			this.from=from;
			this.to=to;
			dir=to.sub(from);
		}

		//line-line intersection
		public Vec lineIntersect(Seg o) {
			double det=o.dir.x*dir.y-dir.x*o.dir.y;
			if (Vec.eq(det, 0)) return null;
			double dist=(o.dir.x*(o.from.y-from.y)-
					o.dir.y*(o.from.x-from.x))/det;
			return from.add(dir.scale(dist));
		}

		public boolean containsPoint(Vec o) {
			double distFromLine=dir.unit().cross(o.sub(from));
			if (!Vec.eq(distFromLine, 0)) return false;
			return Vec.eq(dir.mag(), from.sub(o).mag()+to.sub(o).mag());
		}

		//seg-seg intersection
		public Vec segIntersection(Seg o) {
			Vec intersect=lineIntersect(o);
			return containsPoint(intersect)&&o.containsPoint(intersect)?intersect:null;
		}

		//returns 1 if above, 0 if on, -1 if below
		public int side(Vec o) {
			Vec oDir=o.sub(from);
			double distFromLine=dir.unit().cross(oDir);
			if (Vec.eq(distFromLine, 0))
				return 0;
			return (int)Math.signum(distFromLine);
		}

		public boolean intersects(Seg o, boolean isWall) {
			if(isWall && (containsPoint(o.from) || containsPoint(o.to))) return true;
			return side(o.from)!=side(o.to) && o.side(from)!=o.side(to);
		}

		public Vec getClosestTo(Vec o) {
			double percentThere=o.sub(from).dot(dir)/dir.mag2();
			return from.add(dir.scale(Math.max(0, Math.min(1, percentThere))));
		}

		public Vec projectToLine(Vec o) {
			return dir.scale(o.sub(from).dot(dir)/dir.mag2()).add(from);
		}

		//toContain must be a point with positive x and y coordinates.
		//this method returns the shortest line segment from the x-axis to the point to the y axis
		static Seg getShortestSegFromAxesContainingQ1Point(Vec toContain) {
			double slope=-Math.pow(toContain.y/toContain.x, 1.0/3);
			double b=toContain.y-toContain.x*slope;
			double xInt=-b/slope;
			return new Seg(new Vec(0, b), new Vec(xInt, 0));
		}

		public String toString() {
			return from+" -> "+to;
		}
	}

