public class DTask {

    public static void main(String[] args) throws IOException {
        MyInputReader in = new MyInputReader(System.in);
        long a1 = in.nextInt();
        long b1 = in.nextInt();
        long a2 = in.nextInt();
        long b2 = in.nextInt();
        int l = in.nextInt();
        int r = in.nextInt();
        MutableLong xm = new MutableLong(0);
        MutableLong ym = new MutableLong(1);
        long a = a1;
        long b = -a2;
        long c = b2 - b1;
        long g = gcd(Math.abs(a), Math.abs(b), xm, ym);
        if (c % g != 0) {
            System.out.println("0");
            return;
        }
        if (a1 == 0 && a2 == 0) {
            if (b1 != b2) {
                fail();
            }
            if (b1 == b2 && b1 < l && b2 > r) {
                fail();
            }
            System.out.println(1);
            return;
        }
        long msa = a > 0 ? 1 : -1;
        long msb = b > 0 ? 1 : -1;
        long x = (long) ((c / g) * msa * xm.v);
        long y = (long) ((c / g) * msb * ym.v);
        long minx;
        long maxx;
        if (a1 == 0) {
            minx = Integer.MIN_VALUE;
            maxx = Integer.MAX_VALUE;
        } else {
            minx = (l - b1) / a1;
            maxx = (r - b1) / a1;
        }
        long miny;
        long maxy;
        if (a2 == 0) {
            miny = Integer.MIN_VALUE;
            maxy = Integer.MAX_VALUE;
        } else {
            miny = (l - b2) / a2;
            maxy = (r - b2) / a2;
        }
        minx = Math.max(minx, 0);
        miny = Math.max(miny, 0);
        long ad = b / g;
        long bd = a / g;
        Pair p1 = bounds(x, ad, minx, maxx);
        Pair p2 = bounds(y, -bd, miny, maxy);
        long m1 = Math.max(p1.min, p2.min);
        long m2 = Math.min(p2.max, p1.max);
        if (m1 > m2) {
            fail();
        }
        long vars = Math.abs(m2 - m1) + 1;

        long pos = m2;
        long l1 = x + pos * (b / g);
        long ans = a1 * l1 + b1;

        long posy = m1;
        long k1 = y - posy * (a / g);
        long ansy = a2 * k1 + b2;

        if (ans < l || ans > r) {
            vars -= 1;
        }
        if (ansy < l || ansy > r) {
            vars -= 1;
        }
        /*System.out.println(ans);
        System.out.println(ansy);*/
        System.out.println(Math.max(vars, 0));
    }


    static Pair bounds(long init, long step, long min, long max) {
        long src = step;
        long lo = -1;
        long hi = -1;
        step = Math.abs(step);
        if (init == min) {
            lo = min;
        } else if (init < min) {
            long mult = (min - init) / step;
            lo = init + mult * step;
            if (lo < min) {
                lo += step;
            }
        } else {
            long mult = (init - min) / step;
            lo = init - mult * step;
            if (lo < min) {
                lo += step;
            }
        }
        if (lo > max) {
            fail();
        }
        lo = (lo - init) / src;
        if (init == max) {
            hi = init;
        } else if (init > max) {
            long mult = (init - max) / step;
            hi = init - mult * step;
            if (hi > max) {
                hi -= step;
            }
        } else {
            long mult = (max - init) / step;
            hi = init + mult * step;
            if (hi > max) {
                hi -= step;
            }
        }
        if (hi < min) {
            fail();
        }
        hi = (hi - init) / src;
        if (hi < lo) {
            long tmp = hi;
            hi = lo;
            lo = tmp;
        }
        return new Pair(lo, hi);
    }

    static void fail() {
        System.out.println("0");
        System.exit(0);
    }

    static long gcd(long a, long b, MutableLong x, MutableLong y) {
        if (a == 0) {
            x.v = 0;
            y.v = 1;
            return b;
        }
        long g = gcd(b % a, a, x, y);
        long x1 = x.v;
        long y1 = y.v;
        x.v = y1 - (b / a) * x1;
        y.v = x1;
        return g;
    }

    static class Pair {

        long min;
        long max;

        public Pair(long min, long max) {
            this.min = min;
            this.max = max;
        }
    }

    static class MutableLong {

        long v;

        public MutableLong(long v) {
            this.v = v;
        }

    }

    static class MyInputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public MyInputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }

}

