import java.io.PrintWriter;
import java.util.Scanner;

public class Divisibilityby25 {

	void solve(Scanner in, PrintWriter out) {
		String s = in.next();
		int l = s.length();
		int min = Integer.MAX_VALUE;

		for (int i = 0; i < l; i++) {

			for (int j = 0; j < l; j++) {
				int m = 0;
				char[] a = s.toCharArray();

				if (i == j)
					continue;

				for (int k = i; k < l - 1; k++) {
					char c = a[k];
					a[k] = a[k + 1];
					a[k + 1] = c;
					m++;
				}

				for (int k = j - ((j > i) ? 1 : 0); k < l - 2; k++) {
					char c = a[k];
					a[k] = a[k + 1];
					a[k + 1] = c;
					m++;
				}

				int pos = -1;

				for (int k = 0; k < l - 2; k++) {

					if (a[k] != '0') {
						pos = k;
						break;
					}
				}

				for (int k = pos; k > 0; k--) {

					char c = a[k - 1];
					a[k - 1] = a[k];
					a[k] = c;
					m++;
				}
				long n = Long.parseLong(new String(a));
				if (n % 25 == 0) {
					min = Math.min(m, min);

				}

			}

		}

		if (min == Integer.MAX_VALUE)
			out.println(-1);
		else
			out.println(min);

	}

	void run() {
		try (Scanner in = new Scanner(System.in); PrintWriter out = new PrintWriter(System.out);) {
			solve(in, out);
		}
	}

	public static void main(String args[]) {
		new Divisibilityby25().run();
	}
}

