			for(int j = 0; j < b[0].length; j++)
				for(int k = 0; k < b.length; k++)
					c[i][j] = (c[i][j] + a[i][k] * b[k][j] % MOD) % MOD;
		return c;
	}
	public long[][] exp(long[][] m, int e) {
		if(e == 1) return m;
		long[][] r = exp(m, e >> 1);
		r = mult(r, r);
		if(e%2 == 1)
			r = mult(r, m);
		return r;
	}
	public long exp(long a, int e) {
		if(e == 1) return a;
		long r = exp(a, e >> 1);
		r = r*r%MOD;
		if(e % 2 == 1)
			r = r*a % MOD;
		return r;
	}
