	void solve() {
		long n = scn.nextLong(), m = scn.nextLong();
		long l = scn.nextLong(), r = scn.nextLong(), mod = 998244353;

		if((n * m) % 2 == 1) {
			out.println(pow(r - l + 1, n * m, mod));
			return;
		}

		long x = (r - l + 1) / 2;
		long k = n * m;
		long two = pow(2, k - 1, mod);

		long ans = (pow(x, k, mod) * two) % mod;
		if((r - l + 1) % 2 != 0) {
			long y = r - l + 1 - x;
			ans = (pow(y + x, k, mod) + pow(y - x, k, mod)) % mod;
			ans = (ans * pow(2, mod - 2, mod)) % mod;
		}
		out.println(ans);
	}

	long func(long k, long z, long mod) {
		if(z == 0) {
			return 0;
		}
		long x = z / 2, y = z - x;
		if(x == 0 || y == 0) {
			return 1;
		}

		long ans = 0;
		for(long a = 0; a <= k; a += 2) {
			long b = k - a;

			long rv = pow(x, a, mod) * pow(y, b, mod) % mod;
			ans = (ans + rv) % mod;
		}

		return ans;
	}

	long pow(long a, long x, long m) {
		long rv = 1;
		while (x != 0) {
			if ((x & 1) == 1) {
				rv = (rv * a) % m;
			}
			a = (a * a) % m;
			x = x >> 1;
		}
		return rv;
	}


