class TaskD {
    static long [][] mod;
    static long modulo = 1000000007;

    static long exp(long a, long pow) {
        long ans = 1;
        while(pow > 0) {
           if(pow%2 == 1) ans = ans*a%modulo;
           pow >>= 1;
           a = a*a%modulo;
        }
        return ans;
    }

    static void compute( int n, long q )
    {
        mod = new long[2][ n+1 ];
        mod[0][0] = 1;
        for (int i = 1; i <= n; i++) {
            mod[0][i] = mod[0][i-1]*(n-i+1)%modulo*exp(i, modulo-2)%modulo;
        }

        for(int i = 0; i <= n; ++i) {
            long temp = mod[0][i];
            mod[0][i] = exp(mod[0][i], q);
            mod[1][i] = mod[0][i]*temp%modulo;
        }

    }

	public void solve(int testNumber, Scanner in, PrintWriter out) {

        int n = in.nextInt();
        long m = in.nextLong();
        int k = in.nextInt();
        compute(n,m/n);
        long [][] f = new long[n+1][k+1];

        Arrays.fill(f[0], 0);
        f[0][0] = 1;

        for(int i = 1; i <= n; ++i) {
            f[i][0] = 1;
            int d = 0;
            if(i<=m%n) d++;

            for(int j = 1; j <= k; ++j) {
                f[i][j] = 0;
                for(int l = 0; l <= j && l <= n; ++l)
                    f[i][j] = (f[i][j] + mod[d][l]*f[i-1][j-l])%modulo;
            }
        }
/*
        for(int i = 0; i <= n; ++i) {
            for(int j = 0; j <= k; ++j)
                out.write(f[i][j] + " ");
            out.println("");
        } */
        out.println(new Long(f[n][k]).toString());
	}
}

