    void sol() {
        //long[][] dp = new long[s.length + 1][t.length + 1]; - memory limit
        long[] pred = new long[s.length+1];
        long[] curr = new long[s.length+1];

        ans = 0;
        long save;
        for (int j = 1; j <= t.length; j++){
            save = pred[0];
            for (int i = 1; i <= s.length; i++){

                /* de facto, but it's too slowly
                if (s[i-1] == t[j-1]) {
                    for (int k = 0; k < j; k++){
                        dp[i][j] = (dp[i][j] + dp[i-1][k]) % M;
                    }
                    dp[i][j] += 1;
                    ans = (ans + dp[i][j]) % M;
                */

