public class Main {
    static Reader r = new Reader();
    static StringBuilder sb = new StringBuilder();
    static final int p = 1_000_000_007;

    public static ArrayList<Integer> primeList(int n){
        // return prime numbers less than or equal to n
        if(n==1) return new ArrayList<>();
        ArrayList<Integer> prime = new ArrayList<>();
        prime.add(2);
        if(n==2) return prime;

        boolean[] isPrime = new boolean[(n-1)/2];
        Arrays.fill(isPrime,true);
        for(int i=0;(2*i+3)*(2*i+3)<=n;i++){
            if(!isPrime[i]) continue;
            for(int j=((2*i+3)*(2*i+3)-3)/2;j<(n-1)/2;j+=(2*i+3))
                isPrime[j] = false;
        }
        for(int i=0;i<(n-1)/2;i++){
            if(isPrime[i]) prime.add(2*i+3);
        }
        return prime;
    }
    static int gcd(int n, int m){
        if(n==0) return (m>0)?m:-m;
        return gcd(m%n, n);
    }


    public static void main(String args[]) throws IOException {
        int n = r.readInt();
        ArrayList<Integer> prime = primeList((int)Math.sqrt(n));
        ArrayList<Integer>[] div = new ArrayList[n+1];
        int[] phi = new int[n+1];
        for(int i=1;i<=n;i++)
            div[i] = new ArrayList<>();
        for(int i=1;i<=n/2;i++){
            for(int j=2*i;j<=n;j+=i){
                div[j].add(i);
            }
        }
        for(int i=1;i<=n;i++){
            int m = i;
            int ans = m;
            for(int p:prime){
                if(p>Math.sqrt(m)) break;
                if(m%p!=0) continue;
                ans = (ans/p)*(p-1);
                while(m%p==0)
                    m/=p;
            }
            if(m>1) ans = (ans/m)*(m-1);
            phi[i] = ans;
        }
        long cnt = 0;
        for(int k=1;k<n;k++){
            for(int d:div[k]){
                cnt += (long) phi[k/d]*d*(n-k)/gcd(d,n-k);
                cnt %= p;
            }
        }
        System.out.println(cnt);
    }
}
class Reader {
    final private int BUFFER_SIZE = 1 << 16;
    private DataInputStream din;
    private byte[] buffer;
    private int bufferPointer, bytesRead;

    public Reader() {
        din = new DataInputStream(System.in);
        buffer = new byte[BUFFER_SIZE];
        bufferPointer = bytesRead = 0;
    }

    public String readLine() throws IOException {
        byte[] buf = new byte[1000000]; // line length
        int cnt = 0, c;
        while((c=read())!=-1){
            if(c=='\n'){
                if(cnt!=0) break;
                else continue;
            }
            buf[cnt++] = (byte)c;
        }
        return new String(buf, 0, cnt);
    }

    public int readInt() throws IOException {
        int ret = 0;
        byte c = read();
        while(c <= ' '){ c = read();}
        boolean neg = (c == '-');
        if(neg) c = read();
        do{
            ret = (ret<<3) + (ret<<1) + c - '0';
        } while ((c = read()) >= '0' && c <= '9');
        return neg ? -ret : ret;
    }

    public long readLong() throws IOException {
        long ret = 0;
        byte c = read();
        while(c <= ' '){ c = read();}
        boolean neg = (c == '-');
        if(neg) c = read();
        do{
            ret = (ret<<3) + (ret<<1) + c - '0';
        } while ((c = read()) >= '0' && c <= '9');
        return neg ? -ret : ret;
    }

    private void fillBuffer() throws IOException {
        bytesRead = din.read(buffer, bufferPointer = 0, BUFFER_SIZE);
        if(bytesRead == -1) buffer[0] = -1;
    }

    private byte read() throws IOException {
        if(bufferPointer == bytesRead) fillBuffer();
        return buffer[bufferPointer++];
    }

    public void close() throws IOException {
        if(din==null) return;
        din.close();
    }
}

