            int[][][] count = new int[2][][];
            int[][] sufA = new int[2][];
            for (int i = 0; i < 2; i++) {
                count[i] = count(s[i]);
                sufA[i] = sufA(s[i]);
            }
            int[][] info = new int[2][3];
            for (int i = 0; i < q; i++) {
                int l1 = in.nextInt() - 1, r1 = in.nextInt();
                int l2 = in.nextInt() - 1, r2 = in.nextInt();

                info[0][0] = count[0][0][r1] - count[0][0][l1];
                info[0][1] = count[0][1][r1] - count[0][1][l1];
                info[0][2] = Math.min(sufA[0][r1 - 1], r1 - l1);

                info[1][0] = count[1][0][r2] - count[1][0][l2];
                info[1][1] = count[1][1][r2] - count[1][1][l2];
                info[1][2] = Math.min(sufA[1][r2 - 1], r2 - l2);
                out.print(can(info[0], info[1]) ? '1' : '0');
            }
        }

        private boolean can(int[] a, int[] b) {
            a[0] -= a[2];
            b[0] -= b[2];
            if (a[2] < b[2]) {
                return false;
            }
            if (a[2] % 3 == b[2] % 3) {
                if (can2(a, b)) {
                    return true;
                }
            }
            a[2]--;
            a[1] += 2;

            a[0] += a[2] - b[2];
            return can2(a, b);
        }

        private boolean can2(int[] a, int[] b) {
            if (a[0] < 0 || a[1] < 0) {
                return false;
            }
            if (a[1] > b[1]) {
                return false;
            }
            if (a[1] % 2 != b[1] % 2) {
                return false;
            }
            if (b[1] > a[1] && (a[0] + a[1] == 0)) {
                return false;
            }
            return true;
        }

        private int[] sufA(char[] chars) {
            int[] a = new int[chars.length];
            for (int i = 0; i < chars.length; i++) {
                if (chars[i] == 'A') {
                    a[i] = (i == 0 ? 0 : a[i - 1]) + 1;
                } else {
                    a[i] = 0;
                }
            }
            return a;
        }

        private int[][] count(char[] chars) {
            int[][] a = new int[2][chars.length + 1];
            for (int i = 0; i < chars.length; i++) {
                a[0][i + 1] += a[0][i];
                a[1][i + 1] += a[1][i];
                a[chars[i] - 'A'][i + 1]++;
            }
            return a;
        }

    }

    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                String line = null;
                try {
                    line = br.readLine();
                } catch (IOException e) {
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

    }
}

import static java.lang.Double.parseDouble;
import static java.lang.Integer.parseInt;
import static java.lang.Long.parseLong;
import static java.lang.System.exit;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.math.BigInteger;
import java.util.StringTokenizer;

public class F {

	static BufferedReader in;
	static PrintWriter out;
	static StringTokenizer tok;

	static void solve() throws Exception {
		int n = nextInt();
		int p = nextInt();
		int q = nextInt();
		if (p >= n) {
			p = n - 1;
		}
		int c[] = new int[p + 1];
		c[0] = 1;
		for (int i = 1, val = 1, pow = 0; i <= p; i++) {
			int mul = n - i + 1;
			int shift = Integer.numberOfTrailingZeros(mul);
			val *= mul >> shift;
			pow += shift;
			mul = i;
			shift = Integer.numberOfTrailingZeros(mul);
			val *= BigInteger.valueOf(mul >> shift).modInverse(BigInteger.valueOf(0x100000000L)).intValue();
			pow -= shift;
			c[i] = pow >= 32 ? 0 : val << pow;
		}
		int ans = 0;
		for (int day = 1; day <= q; day++) {
			int cans = 0;
			for (int i = 0, pow = 1; i <= p; i++, pow *= day) {
				cans += c[i] * pow;
			}
			ans ^= day * cans;
		}
		out.print(ans & 0xffffffffL);
	}

	static int nextInt() throws IOException {
		return parseInt(next());
	}

	static long nextLong() throws IOException {
		return parseLong(next());
	}

	static double nextDouble() throws IOException {
		return parseDouble(next());
	}

	static String next() throws IOException {
		while (tok == null || !tok.hasMoreTokens()) {
			tok = new StringTokenizer(in.readLine());
		}
		return tok.nextToken();
	}

	public static void main(String[] args) {
		try {
			in = new BufferedReader(new InputStreamReader(System.in));
			out = new PrintWriter(new OutputStreamWriter(System.out));
			solve();
			in.close();
			out.close();
		} catch (Throwable e) {
			e.printStackTrace();
			exit(1);
		}
	}
}

import java.io.BufferedReader;
