/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author Yuan Lei
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskC {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int n = in.nextInt();
            if (n > 40) {
                out.println(0);
                return;
            } else {
                final ArrayList<TaskC.Point> points = new ArrayList<>();
                for (int i = 0; i < n; ++i) {
                    int a, b, c, d, e;
                    a = in.nextInt();
                    b = in.nextInt();
                    c = in.nextInt();
                    d = in.nextInt();
                    e = in.nextInt();
                    points.add(new TaskC.Point(a, b, c, d, e));
                }
                if (n < 3) {
                    out.println(n);
                    for (int i = 1; i <= n; ++i) {
                        out.println(i);
                    }
                    return;
                }
                ArrayList<Integer> result = new ArrayList<>();
                for (int center = 0; center < n; ++center) {
                    boolean find = false;
                    for (int a = 0; a < n; ++a)
                        if (a != center) {
                            for (int b = 0; b < n; ++b)
                                if (b != center && b != a) {
                                    TaskC.Point A = points.get(a).minus(points.get(center));
                                    TaskC.Point B = points.get(b).minus(points.get(center));
                                    if (A.dot(B)) {
                                        find = true;
                                        break;
                                    }
                                }
                            if (find) break;
                        }
                    if (!find) result.add(center + 1);
                }
                out.println(result.size());
                for (int id : result) {
                    out.println(id);
                }
            }
        }

        static class Point {
            long a;
            long b;
            long c;
            long d;
            long e;

            public Point(long a, long b, long c, long d, long e) {
                this.a = a;
                this.b = b;
                this.c = c;
                this.d = d;
                this.e = e;
            }

            boolean dot(final TaskC.Point rhs) {
                return a * rhs.a + b * rhs.b + c * rhs.c + d * rhs.d + e * rhs.e > 0;
            }

            TaskC.Point minus(final TaskC.Point rhs) {
                return new TaskC.Point(a - rhs.a, b - rhs.b, c - rhs.c, d - rhs.d, e - rhs.e);
            }

        }

    }
}

import java.util.ArrayList;
import java.util.HashSet;
import java.util.Scanner;

/**
 * Created by Pranav ps on 04-09-2017.
 */
public class wedss {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        if(n <= 11){
            long[][] points = new long[n][5];

            for(int i = 0 ; i < n; i++){
                for (int j = 0; j < 5; j++) {
                    points[i][j] = sc.nextLong();
                }
            }

            long[][][] vectors = new long[n][n][5];
            for(int i = 0; i < n; i++){
                for(int j = 0; j < n; j++){
                    for (int k = 0; k < 5; k++) {
                        vectors[i][j][k] = points[j][k] - points[i][k];
                    }
                }
            }

            HashSet<Integer> list = new HashSet<>();

            for(int i = 0; i < n; i++){
                boolean flag = false;
                for (int j = 0; j < n; j++) {
                    for (int k = 0; k < n; k++) {
                        if(!equal(vectors[i][j],vectors[i][k]) && dot(vectors[i][j],vectors[i][k])){
                            list.add(i+1);
                            flag = true;
                            break;
                        }
                    }
                    if(flag)
                        break;
                }
            }

            System.out.println(n - list.size());
            for(int i = 0; i < n; i++){
                if(!list.contains(i+1))
                    System.out.println(i+1);
            }
        }
        else{
            System.out.println(0);
        }
    }
    private static boolean equal(long[] a, long[] b){
        boolean res = true;
        for(int i = 0 ; i < 5; i++){
            res &= a[i]==b[i];
        }
        return res;
    }
    private static boolean dot(long[] a, long[] b){
        long res = 0;
        for(int i = 0 ; i < 5; i++){
            res += a[i]*b[i];
        }

        return res>0;
    }
}

