					int ni = x[i], nj = y[i];
					b = copy(a);
					while(inRange(ni, nj) && b[ni][nj] == 'O') {
						b[ni][nj] = '.';
						int nmask = encode(b);
						// System.out.println("from ");
						// print(a);
						// System.out.println("to ");
						// print(b);
						if (!dfs(nmask)) {
							dp[mask] = 1;
							return true;
						}
						ni+=di[k];
						nj+=dj[k];
					}
				}
			}
		}

		dp[mask] = 0;
		return false;
	}

