		char [][]b = a.clone();
		for(int i=0;i<n;i++) {
			b[i] = b[i].clone();
		}
		return b;
	}

	private int encode(char [][]a) {
		int mask = 0;
		for(int i=0;i<19;i++){
			if (a[x[i]][y[i]] == 'O') {
				mask|=1<<i;
			}
		}
		return mask;
	}

	private char[][] decode(int mask) {
		char [][]r = new char[n][m];
		for(int i=0;i<19;i++){
			if ((mask & (1 << i)) > 0) {
				r[x[i]][y[i]] = 'O';
			}else {
				r[x[i]][y[i]] = '.';
			}
		}
		return r;
	}

