	public static int go(int mask,int turn){
		if(mask==0){
			return 1-turn;
		}
		if(dp[mask][turn]!=null)return dp[mask][turn];
		char[][]arr=encode(mask);
		for(int i=0;i<5;i++){
			for(int j=0;j<arr[i].length;j++){
				if(arr[i][j]=='o'){
					int newMask=mask;
					for(int k=j;k<arr[i].length;k++){
						if(arr[i][k]=='o'){
							int index=get(i,k);
							newMask&=(~(1<<index));
							if(go(newMask,1-turn)==turn){
								return dp[mask][turn]=turn;
							}
						}
						else break;
					}


						newMask=mask;
						int col=j;
						for(int k=i;k<arr.length;k++){
							if(col>=0&&col<arr[k].length&&arr[k][col]=='o'){
								int index=get(k,col);
								newMask&=(~(1<<index));
								if(go(newMask,1-turn)==turn){
									return dp[mask][turn]=turn;
								}
								if(k>=2)col--;
							}
							else break;
						}





						newMask=mask;
					newMask=mask;
					int r=i , c=j;
					while(true){
						if(r<arr.length&&c>=0&&c<arr[r].length&&arr[r][c]=='o'){
							int index=get(r,c);
							newMask&=(~(1<<index));
							if(go(newMask,1-turn)==turn){
								return dp[mask][turn]=turn;
							}
							r++;
							if(r>2);else
							c++;
						}
						else break;
					}
				}
			}
		}
		return dp[mask][turn]=1-turn;
	}
