public class E {

    int[][] f;
    int[] d;

    void solve() throws IOException {
        in("__std"); out("__std");

        f = new int[5][];
        int k = 0;
        for (int i = 0; i < 5; ++i) {
            char[] l = readLine().toCharArray();
            f[i] = new int[l.length];
            Arrays.fill(f[i], -1);
            for (int j = 0; j < l.length; ++j) {
                if (l[j] == 'O') {
                    f[i][j] = k++;
                }
            }
        }
        int c = 1 << k;
        d = new int[c];
        if (win(c - 1)) {
            println("Karlsson");
        } else {
            println("Lillebror");
        }

        exit();
    }

    boolean win(int c) {
        if (d[c] == 0) {
            int r = 2;
            for (int i = 0; i < 5 && r == 2; ++i) {
                for (int j = 0; j < f[i].length && r == 2; ++j) {
                    if (f[i][j] != -1 && (c & (1 << f[i][j])) != 0) {
                        //right
                        int cc = 0;
                        int ii = i;
                        int jj = j;
                        while (jj < f[ii].length && r == 2 && f[ii][jj] != -1 && (c & (1 << f[ii][jj])) != 0) {
                            cc |= 1 << f[ii][jj];
                            if (!win(c & (~cc))) r = 1;
                            jj += 2;
                        }
                        if (r == 2) {
                            //diag left
                            cc = 0;
                            ii = i;
                            jj = j;
                            while (ii < 5 && jj >= 0 && r == 2 && f[ii][jj] != -1 && (c & (1 << f[ii][jj])) != 0) {
                                cc |= 1 << f[ii][jj];
                                if (!win(c & (~cc))) r = 1;
                                ++ii;
                                --jj;
                            }
                            if (r == 2) {
                                //diag right
                                cc = 0;
                                ii = i;
                                jj = j;
                                while (ii < 5 && jj < f[ii].length && r == 2 && f[ii][jj] != -1 && (c & (1 << f[ii][jj])) != 0) {
                                    cc |= 1 << f[ii][jj];
                                    if (!win(c & (~cc))) r = 1;
                                    ++ii;
                                    ++jj;
                                }
                            }
                        }
                    }
                }
            }
            d[c] = r;
        }
        return d[c] == 1;
    }

