    boolean can(int mask)
    {
        //print(mask);
        if(mask == 0) return false;

        if(calc[mask]) return win[mask];
        calc[mask] = true;

        for(int i = 0; i < 19; i++)
        {
            if((mask >> i & 1) == 0) continue;
            int cur = mask ^ (1 << i);
            if(!can(cur)) return win[mask] = true;

            for(int k = 0; k < 6; k++)
            {
                cur = mask ^ (1 << i);

                int x = mapBit[i] / cn;
                int y = mapBit[i] % cn;

