                {
                    x += dx[k];
                    y += dy[k];

                    int j = mapCoord[x * cn + y];
                    if(j == - 1 || (cur >> j & 1) == 0) break;

                    cur ^= 1 << j;
                    if(!can(cur)) return win[mask] = true;
                }
            }
        }
        return win[mask] = false;
