    void solve() throws IOException {
        a = new int[15][];
        a[0] = new int[] {1, 2, 3};
        a[1] = new int[] {17, 18, 19};
        a[2] = new int[] {8, 13, 17};
        a[3] = new int[] {3, 7, 12};
        a[4] = new int[] {1, 4, 8};
        a[5] = new int[] {12, 16, 19};
