        a[7] = new int[] {2, 5, 9, 13};
        a[8] = new int[] {2, 6, 11, 16};
        a[9] = new int[] {13, 14, 15, 16};
        a[10] = new int[] {4, 9, 14, 18};
        a[11] = new int[] {4, 5, 6, 7};
        a[12] = new int[] {8, 9, 10, 11, 12};
        a[13] = new int[] {1, 5, 10, 15, 19};
        a[14] = new int[] {3, 6, 10, 14, 17};



        dm = new int[1 << 19][2];
        for (int i = 0; i < dm.length; ++i)
            dm[i][0] = dm[i][1] = -1;

        for (int i = 0; i < a.length; ++i)
            for (int j = 0; j < a[i].length; ++j)
                a[i][j] -- ;

        int mask = 0;
        for (int t = 0; t < 19; ++t) {
            String str = nextToken();
            if (str.compareTo("O") == 0) mask |= (1 << t) ;;
        }
        int res = brute(mask, 0);
        out.print(res == 1 ? "Karlsson" : "Lillebror");

    }
    int brute(int mask, int turn) {
        if (mask == 0) {
            return turn;
        }
        if (dm[mask][turn] != -1) return dm[mask][turn];
        if (dm[mask][turn ^ 1] != -1) return dm[mask][turn ^ 1] ^ 1;

        for(int v = 0; v < a.length; ++v) {

            for (int i = 0; i < a[v].length; ++i) {
                for(int j = i; j < a[v].length; ++j) {
                    boolean ok = true;
                    for (int u = i; ok && u <= j; ++u) {
                        if ((mask & (1 << a[v][u])) == 0) ok = false;
                    }
                    if (ok) {
                        for (int I = i; I <= j; ++I)
                            for(int J = I; J <= j; ++J) {
                                int cm = 0;
                                for (int k = I; k <= J; ++k) {
                                    cm |= (1 << a[v][k]);
                                }
                                int d = brute(mask ^ cm, turn ^ 1);
                                if (turn == 0 && d == 1)  return dm[mask][turn] = 1;
                                if (turn == 1 && d == 0) return dm[mask][turn] = 0;
                            }
                    }
                }
            }
        }

        return dm[mask][turn] = turn;
    }

