	int n = 5;
	int now;

	void run() {
		for (int i = 0; i < m; i++) {
			now |= sc.next().charAt(0) == 'O' ? (1 << i) : 0;
		}
		solve();
	}

	int[][] map;
	int[] x, y;

	int[] win;

	void solve() {
		map = new int[][] { { 0, 1, 2, -1, -1 }, { 3, 4, 5, 6, -1 },
				{ 7, 8, 9, 10, 11 }, { -1, 12, 13, 14, 15 },
				{ -1, -1, 16, 17, 18 } };
		x = new int[m];
		y = new int[m];
		for (int j = 0; j < n; j++) {
			for (int i = 0; i < n; i++) {
				if (map[j][i] != -1) {
					x[map[j][i]] = i;
					y[map[j][i]] = j;
				}
			}
		}

		win = new int[1 << m];
		fill(win, -1);

		dfs(now);

		// debug(win[now]);
		println(new String[] { "Lillebror", "Karlsson" }[win[now]]);
	}

	int[] dx = { 1, 0, 1 };
	int[] dy = { 0, 1, 1 };

	int dfs(int state) {
		if (win[state] >= 0) {
			return win[state];
		}
		if (state == 0) {
			return win[state] = 0;
		}
		for (int j = 0; j < n; j++) {
			for (int i = 0; i < n; i++) {
				for (int k = 0; k < 3; k++) {
					for (int x = i, y = j, bit = 0; x < n && y < n
							&& map[y][x] != -1 && (state >> map[y][x] & 1) == 1; x += dx[k], y += dy[k]) {
						bit |= 1 << map[y][x];
						if (dfs(state ^ bit) == 0) {
							win[state] = 1;
							return win[state];
						}
					}
				}
