public class Igraskonfetami {
	static BufferedReader br = new BufferedReader(new InputStreamReader(
			System.in));

	static StringTokenizer in;

	static PrintWriter out = new PrintWriter(System.out);

	public static String nextToken() throws IOException {
		while (in == null || !in.hasMoreTokens()) {
			in = new StringTokenizer(br.readLine());
		}

		return in.nextToken();
	}

	public static int nextInt() throws IOException {
		return Integer.parseInt(nextToken());
	}

	public static double nextDouble() throws IOException {
		return Double.parseDouble(nextToken());
	}

	static int[][] pos = new int[][] { { 0, 0, 1, 0, 2, 0, 3, 0, 0 },
			{ 0, 4, 0, 5, 0, 6, 0, 7, 0 }, { 8, 0, 9, 0, 10, 0, 11, 0, 12 },
			{ 0, 13, 0, 14, 0, 15, 0, 16, 0 }, { 0, 0, 17, 0, 18, 0, 19, 0, 0 } };

	static int[][] sweet = new int[][] { { 0, 2 }, { 0, 4 }, { 0, 6 },
			{ 1, 1 }, { 1, 3 }, { 1, 5 }, { 1, 7 }, { 2, 0 }, { 2, 2 },
			{ 2, 4 }, { 2, 6 }, { 2, 8 }, { 3, 1 }, { 3, 3 }, { 3, 5 },
			{ 3, 7 }, { 4, 2 }, { 4, 4 }, { 4, 6 } };

	static boolean[] ans;

	public static int get(boolean[][] c) {
		int mask = 0;
		for (int i = 0; i < c.length; i++) {
			for (int j = 0; j < c[0].length; j++) {
				if (c[i][j])
					mask += (1 << (pos[i][j] - 1));
			}
		}

		return mask;
	}

	static boolean win(int mask) {
		boolean[][] state = new boolean[5][9];

		for (int i = 0; i < 19; i++) {
			if ((mask & (1 << i)) > 0)
				state[sweet[i][0]][sweet[i][1]] = true;
		}

		boolean win = false;
		for (int i = 0; i < 19; i++) {
			int x = sweet[i][0];
			int y = sweet[i][1];

			if (!state[x][y])
				continue;

			// left
			int m = mask;
			for (int j = y; j < 9 && state[x][j]; j += 2) {
				m -= (1 << (pos[x][j] - 1));
				win = win | !ans[m];
				if (win)
					break;
			}

			// leftdiag
			m = mask;
			for (int k = x, j = y; k < 5 && j >= 0 && state[k][j]; k++, j--) {
				m -= (1 << (pos[k][j] - 1));
				win = win | !ans[m];
				if (win)
					break;
			}

			// rightdiag
			m = mask;
			for (int k = x, j = y; k < 5 && j < 9 && state[k][j]; k++, j++) {
				m -= (1 << (pos[k][j] - 1));

				win = win | !ans[m];
				if (win)
					break;
			}

			if (win)
				break;
		}

		return win;
	}

	public static void main(String[] args) throws IOException {
		ans = new boolean[1 << 19];

		ans[0] = false;

		for (int i = 1; i < ans.length; i++) {
			if (i == 281){
				int k = 0;
				k++;
			}

			ans[i] = win(i);
		}

		boolean[][] state = new boolean[5][9];

		for (int i = 0; i < state.length; i++) {
			String S = br.readLine();

			for (int j = 0; j < S.length(); j++) {
				if (S.charAt(j) == 'O')
					state[i][j] = true;
			}
		}

		int mask = get(state);

		if (ans[mask])
			System.out.println("Karlsson");
		else
			System.out.println("Lillebror");

		out.close();
	}
}

