public class E {
	int[]len=new int[]{3,4,5,4,3};
	int[][]getGet;
	boolean[]cached;
	boolean[]answer;
	void solve() throws Exception {
		cached=new boolean[1<<19];
		answer=new boolean[1<<19];
		getGet=new int[5][5];
		for(int r=0;r<5;r++)
			for(int c=0;c<5;c++)
				getGet[r][c]=get(r,c);
		int set=0;
		for(int r=0;r<5;r++)
		{
			String s=nextLine();
			s=s.replaceAll(" ", "");
			for(int j=0;j<len[r];j++)
				if((s.charAt(j))=='O')
					set|=1<<get(r,j);
		}
		if(rec(set))
			System.out.println("Karlsson");
		else
			System.out.println("Lillebror");
	}
	boolean rec(int set)
	{
		if(cached[set])
			return answer[set];		
		boolean res=false;
		for(int r=0;r<5;r++)
			for(int c=0;c<len[r];c++)
			{
				int num=get(r,c);
				if((set&(1<<num))>0)
				{
					int cr=r;
					int cc=c;
					int cset=set;
					while(cr>=0 && cr<5 && cc>=0 && cc<len[cr] && (cset&(1<<getGet[cr][cc]))>0)
					{
						cset^=(1<<getGet[cr][cc]);						
						res|=!rec(cset);
						cc++;
					}
					cr=r;
					cc=c;
					cset=set;
					while(cr>=0 && cr<5 && cc>=0 && cc<len[cr] && (cset&(1<<getGet[cr][cc]))>0)
					{
						cset^=(1<<getGet[cr][cc]);						
						res|=!rec(cset);
						if(cr==2 || cr==3)
							cc--;
						cr++;
					}
					cr=r;
					cc=c;
					cset=set;
					while(cr>=0 && cr<5 && cc>=0 && cc<len[cr] && (cset&(1<<getGet[cr][cc]))>0)
					{
						cset^=(1<<getGet[cr][cc]);						
						res|=!rec(cset);
						if(cr==0 || cr==1)
							cc++;
						cr++;
					}

				}
			}
		cached[set]=true;
		answer[set]=res;
		return res;

	}
	int get(int r,int c)
	{
		int res=0;
		for(int i=0;i<r;i++)
			res+=len[i];
		return res+c;
	}

	BufferedReader reader;
	PrintWriter writer;
	StringTokenizer stk;

	void run() throws Exception {
		reader = new BufferedReader(new InputStreamReader(System.in));
		stk = null;
		writer = new PrintWriter(System.out);
		solve();
		reader.close();
		writer.close();
	}

	int nextInt() throws Exception {
		return Integer.parseInt(nextToken());
	}

	long nextLong() throws Exception {
		return Long.parseLong(nextToken());
	}

	double nextDouble() throws Exception {
		return Double.parseDouble(nextToken());
	}

	String nextString() throws Exception {
		return nextToken();
	}

	String nextLine() throws Exception {
		return reader.readLine();
	}

	String nextToken() throws Exception {
		if (stk == null || !stk.hasMoreTokens()) {
			stk = new StringTokenizer(nextLine());
			return nextToken();
		}
		return stk.nextToken();
	}

	public static void main(String[] a) throws Exception {
		new E().run();
	}

}

