public class Solution implements Runnable {

    public static void main(String[] args) {
        (new Thread(new Solution())).start();
    }

    BufferedReader in;
    PrintWriter out;
    StringTokenizer st;

    String nextToken() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String r = in.readLine();
            if (r == null) return null;
            st = new StringTokenizer(r);
        }
        return st.nextToken();
    }

    int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }

    double nextDouble() throws IOException {
        return Double.parseDouble(nextToken());
    }

    int[][] a = new int[5][5];

    void uncode(int q) {
        int t = 24;
        for (int i = 0; i < 19; i++) {
            while (a[t / 5][t % 5] == -1) t--;
            a[t / 5][t % 5] = q % 2;
            t--; q /= 2;
        }
    }

    int code() {
        int t = 0;
        int res = 0;
        for (int i = 0; i < 19; i++) {
            while (a[t / 5][t % 5] == -1) t++;
            res *= 2;
            res += a[t / 5][t % 5];
            t++;
        }
        return res;
    }

    void clone(int[][] a, int[][] b) {
        for (int i = 0; i < 5; i++) {
            for (int j = 0; j < 5; j++) {
                b[i][j] = a[i][j];
            }
        }
    }

    int[] ans = new int[1000000];

    boolean valid(int q) {
        if (q == 0) return false;
        while (q % 2 == 0) q /= 2;
        return (q & (q - 1)) == 0;
    }

    boolean rek(int q) {
        if (ans[q] != -1) return ans[q] == 1;
        boolean f = false;
        for (int i = 0; i < tl; i++) {
            if ((q | turn[i]) == q) {
                f |= !rek(q ^ turn[i]);
            }
        }
        ans[q] = f? 1 : 0;
        return f;
    }

    int[] turn = new int[25 * 25 * 25];
    int tl = 0;

    void solve() throws Exception {
        Arrays.fill(ans, -1);
        a[0][3] = a[0][4] = a[1][4] = -1;
        a[4][0] = a[4][1] = a[3][0] = -1;
        for (int i = 0; i < 5; i++) {
            for (int j = 0; j < 5; j++) {
                for (int k = 0; i + k < 5 && a[i + k][j] != -1; k++) {
                    int[][] b = new int[5][5];
                    clone(a, b);
                    for (int kk = 0; kk <= k; kk++) a[i + kk][j] = 1;
                    turn[tl++] = code();
                    clone(b, a);
                }
                for (int k = 0; j + k < 5 && a[i][j + k] != -1; k++) {
                    int[][] b = new int[5][5];
                    clone(a, b);
                    for (int kk = 0; kk <= k; kk++) a[i][j + kk] = 1;
                    turn[tl++] = code();
                    clone(b, a);
                }
                for (int k = 0; i + k < 5 && j + k < 5 && a[i + k][j + k] != -1; k++) {
                    int[][] b = new int[5][5];
                    clone(a, b);
                    for (int kk = 0; kk <= k; kk++) a[i + kk][j + kk] = 1;
                    turn[tl++] = code();
                    clone(b, a);
                }
            }
        }
        Arrays.sort(turn, 0, tl);
        int ii = 1;
        for (int i = 1; i < tl; i++) {
            if (turn[i] != turn[i - 1]) turn[ii++] = turn[i];
        }
        tl = ii;
        int res = 0;
        for (int i = 0; i < 19; i++) {
            res *= 2;
            if (nextToken().charAt(0) != '.') res++;
        }
        if (rek(res)) out.println("Karlsson"); else out.println("Lillebror");
    }

    public void run() {
        Locale.setDefault(Locale.UK);
        try {
            in = new BufferedReader(new InputStreamReader(System.in));
            out = new PrintWriter(System.out);
            solve();
        } catch (Exception e) {
            e.printStackTrace();
            System.exit(1);
        } finally {
            out.flush();
        }
    }

}

