        memo[0] = 1;
        int mask = 0;
        for (int i = 0; i < 19; i++) {
            if (in.next().charAt(0) != '.') {
                mask += 1 << i;
            }
        }
        out.println(solve(mask) == 2 ? "Karlsson" : "Lillebror");
    }

    public int solve(int mask) {
        if (memo[mask] == 0) {
            for (int i = 0; i < 19; i++) {
                if ((mask & (1 << i)) > 0) {
                    if (solve(mask & ~(1 << i)) == 1) {
                        return memo[mask] = 2;
                    }
                    for (int[] line: directions[i]) {
                        int removeMask = 1 << i;
                        for (int piece: line) {
                            if ((mask & (1 << piece)) == 0) break;
                            removeMask |= 1 << piece;
                            if (solve(mask & ~removeMask) == 1) {
                                return memo[mask] = 2;
                            }
                        }
                    }
                }
            }
            memo[mask] = 1;
        }
        return memo[mask];
    }
}

