    int[] dp = new int[1<<19];
    final int[] dh = new int[]{0, 3, 7, 12, 16};
    final int[] dw = new int[]{3, 4, 5, 4, 3};
    boolean firstWin(int mask){
        if(dp[mask] != 0)return dp[mask] == 1;
        boolean ok = true;
        loop:
        for(int i = 0; i < 5; i++){
            for(int j = 0; j < dw[i]; j++){
                int k = dh[i] + j;
                if(((mask >> k) & 1) == 0)continue;
                int v = mask;
                int cy = i, cx = j;
                for(;;){
                    int ind = dh[cy] + cx;
                    v -= 1 << ind;
                    boolean ret = firstWin(v);
                    if(!ret){
                        ok = false;
                        break loop;
                    }
                    cy++;
                    if(cy > 2)cx--;
                    if(cy >= 5 || cx < 0 || cx >= dw[cy] || ((v >> (dh[cy] + cx)) & 1) == 0)break;
                }

                cy = i; cx = j;
                v = mask - (1 << (dh[cy] + cx));
                for(;;){
                    cy++;
                    if(cy < 3)cx++;
                    if(cy >= 5 || cx < 0 || cx >= dw[cy] || ((v >> (dh[cy] + cx)) & 1) == 0)break;
                    int ind = dh[cy] + cx;
                    v -= 1 << ind;
                    boolean ret = firstWin(v);
                    if(!ret){
                        ok = false;
                        break loop;
                    }
                }

                cy = i; cx = j;
                v = mask - (1 << (dh[cy] + cx));
                for(;;){
                    cx++;
                    if(cy >= 5 || cx < 0 || cx >= dw[cy] || ((v >> (dh[cy] + cx)) & 1) == 0)break;
                    int ind = dh[cy] + cx;
                    v -= 1 << ind;
                    boolean ret = firstWin(v);
                    if(!ret){
                        ok = false;
                        break loop;
                    }
                }

            }
        }
        if(ok){
            dp[mask] = -1;
            return false;
        }else{
            dp[mask] = 1;
            return true;
        }
    }


    int toi(boolean[] u){
        int ret = 0;
        for(int i = 0; i < u.length; i++)if(u[i])ret += 1 << i;
        return ret;
    }

    void run() throws Exception{
        Scanner sc = new Scanner(System.in);
        //BufferedReader sc = new BufferedReader(new InputStreamReader(System.in));
        // only sc.readLine() is available
        boolean[] u = new boolean[19];
        for(int i = 0; i < 19; i++)u[i] = sc.next().equals("O");
        boolean ret = firstWin(toi(u));
        System.out.println(ret ? "Karlsson" : "Lillebror");
    }
}

import java.util.*;

public class SweetsGame {
	static int[] memo;
	static int[] sj = new int[]{0,0,0,1,2};
	static int[] dj = new int[]{3,4,5,5,5};
	static int[] dx = new int[]{0,1,1};
	static int[] dy = new int[]{1,1,0};
	public static void main(String[] args){
		Scanner reader = new Scanner(System.in);
		int[][] d = new int[5][5];
		for(int i = 0; i < 5; i++){
			for(int j = sj[i]; j < dj[i]; j++){
				d[i][j] = reader.next().equals(".")?0:1;
			}
		}		

		memo = new int[(1<<19)];
		System.out.println(f(e(d))>0?"Karlsson":"Lillebror");
	}

	public static void print(int n, int[][] d){
		System.out.println("At " + n + ", processing " + e(d));
		for(int i = 0; i < 5; i++)
			System.out.println(Arrays.toString(d[i]));
	}

	public static int f(int n){
		//System.out.println(Integer.toString(n,2));
		if(memo[n] == 0){
			if(n == 0){
				memo[n] = -1;
			}else{
				int[][] d = d(n);
				int canwin = -1;
//				print(n, d);
				for(int i = 0; i < 5 && canwin < 0; i++){
					for(int j = sj[i]; j < dj[i] && canwin < 0; j++){
						//Proceed in each direction
						for(int k = 0; k < 3 && canwin < 0; k++){
							int L = 0;
							while(nx(i,k,L) >= 0 && nx(i,k,L) < 5 && ny(j,k,L) >= sj[nx(i,k,L)] && ny(j,k,L) < dj[nx(i,k,L)] && d[nx(i,k,L)][ny(j,k,L)] > 0 && canwin < 0){
								//System.out.println("Killing " + i + " " + j + " " + L + " from " + " " + n);
								d[nx(i,k,L)][ny(j,k,L)] = 0;
//								print(n, d);
								canwin = Math.max(canwin, -f(e(d)));
								L++;
							}

							//Reset bitmask
							for(int z = 0; z < L; z++)
								d[nx(i,k,z)][ny(j,k,z)] = 1;
						}
					}
				}

				memo[n] = canwin;
			}
		}
//		System.out.println(n + " " + memo[n]);
		return memo[n];
	}

	public static int nx(int i, int k, int L){
		return i + dx[k]*L;
	}

	public static int ny(int j, int k, int L){
		return j + dy[k]*L;
	}

	public static int[][] d(int e){
		int[][] d = new int[5][5];

		for(int i = 4; i >= 0; i--){
			for(int j = dj[i]-1; j >= sj[i]; j--){
				d[i][j] = (e&1);
				e >>= 1;
			}
		}

		return d;
	}

	public static int e(int[][] d){
		int e = 0;
		for(int i = 0; i < 5; i++){
			for(int j = sj[i]; j < dj[i]; j++){
				e <<= 1;
				e |= d[i][j];
			}
		}
		return e;
	}
}

