import java.util.Arrays;

public class TaskD extends Thread {

    public TaskD() {
        this.input = new BufferedReader(new InputStreamReader(System.in));
        this.output = new PrintWriter(System.out);
        this.setPriority(Thread.MAX_PRIORITY);
    }


    static class Matrix {
        long[][] grid;
        long[][] helper;

        public Matrix(int size, boolean E) {
            this.grid = new long[size][size];
            this.helper = new long[size][size];
            if (E) {
                for (int i = 0; i < grid.length; ++i) {
                    grid[i][i] = 1;
                }
            }
        }

        public Matrix pow(long power) {
            Matrix result = new Matrix(grid.length, true);
            Matrix stat = new Matrix(grid.length, false);
            for (int i = 0; i < grid.length; ++i) {
                stat.grid[i] = this.grid[i].clone();
            }
            while (power != 0) {
                if ((power & 1) == 1) {
                    result.multiply(stat);
                    --power;
                } else {
                    stat.multiply(stat);
                    power >>= 1;
                }
            }
            return result;
        }


        private void multiply(Matrix another) {
            for (long[] current : helper) {
                Arrays.fill(current, 0);
            }
            for (int i = 0; i < grid.length; ++i) {
                for (int j = 0; j < grid.length; ++j) {
                    for (int k = 0; k < grid.length; ++k) {
                        helper[i][j] += (grid[i][k] * another.grid[k][j]) % MODULO;
                    }
                    helper[i][j] %= MODULO;
                }
            }
            for (int i = 0; i < grid.length; ++i) {
                System.arraycopy(helper[i], 0, grid[i], 0, grid.length);
            }
        }
    }


    static class Rule {
        char letter;
        char value;

        public Rule(char letter, char value) {
            this.letter = letter;
            this.value = value;
        }
    }

    private void generate(int index) {
        if (index == initial.length) {
            states[SIZE++] = initial.clone();
        } else {
            for (char value = 0; value < rules[index].value; ++value) {
                initial[index] = value;
                generate(index + 1);
            }
        }
    }

    private boolean isFinal(int index) {
        for (char letter = 'A'; letter <= 'Z'; ++letter) {
            boolean was = false, isGood = false;
            for (int i = 0; i < rules.length; ++i) {
                if (rules[i].letter == letter) {
                    was = true;
                    isGood |= states[index][i] == 0;
                }
            }
            if (was && !isGood) {
                return false;
            }
        }
        return true;
    }


    private void solve() throws Throwable {
        long n = nextLong();
        int c = nextInt();
        int s = c;
        c = 0;
        rules = new Rule[s];
        int total = 1;
        for (int i = 0; i < s; ++ i) {
            rules[c] = new Rule(nextToken().charAt(0), (char) (nextInt()));
            boolean was = false;
            for (int q = 0; q < c; ++q) {
                if (rules[q].letter == rules[c].letter && rules[q].value == rules[c].value) {
                    was = true;
                    break;
                }
            }
            if (!was){
                total *= rules[c++].value;
            }
        }
        rules = Arrays.copyOf(rules, c);
        initial = new char[c];
        states = new char[total][];
        generate(0);
        Matrix operator = new Matrix(total, false);
        for (int from = 0; from < total; ++from) {
            for (char letter = 'A'; letter <= 'Z'; ++letter) {
                boolean isPresent = false;
                char []helper = states[from].clone();
                for (int i = 0; i < c; ++i) {
                    if (rules[i].letter == letter) {
                        isPresent = true;
                        helper[i] = (char)((helper[i] + 1) % rules[i].value);
                    }
                }
                if (isPresent) {
                    for (int to = 0; to < states.length; ++to) {
                        boolean ok = true;
                        for (int index = 0; index < c; ++index) {
                            ok &= states[to][index] == helper[index];
                        }
                        if (ok) {
                            operator.grid[from][to]++;
                            break;
                        }
                    }
                }
            }
        }

        Matrix finish = operator.pow(n);
        long result = 0;
        for (int current = 0; current < total; ++current) {
            if (isFinal(current)) {
                result = (result + finish.grid[0][current]) % MODULO;
            }
        }
        output.println(result);
    }

    public void run() {
        try {
            solve();
        } catch (Throwable e) {
            System.err.println(e.getMessage());
            e.printStackTrace();
            System.exit(666);
        } finally {
            output.flush();
            output.close();
        }
    }


    public static void main(String[] args) {
        new TaskD().start();
    }

    private String nextToken() throws IOException {
        while (tokens == null || !tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(input.readLine());
        }
        return tokens.nextToken();
    }

    private int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    private double nextDouble() throws IOException {
        return Double.parseDouble(nextToken());
    }

    private long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }

    private int SIZE = 0;
    private static final int MODULO = 12345;
    private char[][] states;
    private char[] initial;
    private Rule[] rules;
    private BufferedReader input;
    private PrintWriter output;
    private StringTokenizer tokens = null;
}

import java.io.*;
import java.util.*;

public class cfRound83_D {

    BufferedReader br;
    PrintWriter out;
    StringTokenizer st;
    boolean eof;

    final int MOD = 12345;

    int[][] mul(int[][] a, int[][] b) {
        int[][] res = new int[sz][sz];
        for (int i = 0; i < sz; i++)
            for (int j = 0; j < sz; j++)
                for (int k = 0; k < sz; k++) {
                    res[i][j] += a[i][k] * b[k][j];
                    res[i][j] %= MOD;
                }


        return res;
    }

    int[][] power(int[][] a, long b) {
        if (b == 0) {
            int[][] res = new int[sz][sz];
            for (int i = 0; i < sz; i++)
                res[i][i] = 1;
            return res;
        }

        if ((b & 1) == 1)
            return mul(a, power(a, b - 1));

        int[][] tmp = power(a, b >> 1);
            return mul(tmp, tmp);

    }

    int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }

    int lcm(int a, int b) {
        if (a == 0)
            return b;
        if (b == 0)
            return a;

        return a / gcd(a, b) * b;
    }

    int sz;

    void solve() throws IOException {
        long n = nextLong();

        ArrayList<Integer>[] list = new ArrayList[26];
        for (int i = 0; i < 26; i++)
            list[i] = new ArrayList<Integer>();

        int c = nextInt();

        for (int i = 0; i < c; i++) {
            String s = nextToken();
            int x = nextInt();
            list[s.charAt(0) - 'A'].add(x);
        }

        ArrayList<Integer> can = new ArrayList<Integer>();
        ArrayList<Integer> mult = new ArrayList<Integer>();
        ArrayList<Integer> lcm = new ArrayList<Integer>();

        sz = 1;

        for (int i = 0; i < 26; i++)
            if (!list[i].isEmpty()) {
                int curLcm = 0;
                for (int x : list[i])
                    curLcm = lcm(curLcm, x);
                can.add(i);
                mult.add(sz);
                sz *= curLcm;
                lcm.add(curLcm);
            }

        mult.add(sz);

//      System.err.println(can);
//      System.err.println(mult);
//      System.err.println(lcm);

        int[][] matr = new int[sz][sz];

        for (int i = 0; i < sz; i++) {
            for (int j = 0; j < can.size(); j++) {
                int oldRem = i % mult.get(j + 1) / mult.get(j);
                int newRem = (oldRem + 1) % lcm.get(j);
                matr[i - oldRem * mult.get(j) + newRem * mult.get(j)][i]++;
            }
        }

        matr = power(matr, n);

        int ans = 0;

        for (int i = 0; i < sz; i++) {
            boolean goodTotalRem = true;
            for (int j = 0; j < can.size(); j++) {
                int curRem = i % mult.get(j + 1) / mult.get(j);
                boolean goodRem = false;
                for (int good : list[can.get(j)])
                    if (curRem % good == 0) {
                        goodRem = true;
                        break;
                    }
                if (!goodRem) {
                    goodTotalRem = false;
                    break;
                }
            }
            if (goodTotalRem) {
                ans += matr[i][0];
                if (ans >= MOD)
                    ans -= MOD;
            }
        }

        out.println(ans);
    }

    void inp() throws IOException {
        br = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(System.out);
        solve();
        out.close();
    }

    public static void main(String[] args) throws IOException {
        new cfRound83_D().inp();
    }

    String nextToken() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                st = new StringTokenizer(br.readLine());
            } catch (Exception e) {
                eof = true;
                return "0";
            }
        }
        return st.nextToken();
    }

    String nextString() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                st = new StringTokenizer(br.readLine());
            } catch (Exception e) {
                eof = true;
                return "0";
            }
        }
        return st.nextToken("\n");
    }

    int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }

    double nextDouble() throws IOException {
        return Double.parseDouble(nextToken());
    }
}

