public class D{

    int mod=12345;
    void solve()throws Exception
    {
        int ones=0;
        HashMap<Integer,ArrayList<Integer>>map=new HashMap<Integer,ArrayList<Integer>>();
        long n=nextLong();
        int c=nextInt();
        int p=1;
        for(int i=0;i<c;i++)
        {
            int t=nextString().charAt(0)-'A';
            int m=nextInt();
            if(!map.containsKey(t))
                map.put(t,new ArrayList<Integer>());
            map.get(t).add(m);
        }
        int[][]ar=new int[map.size()][];
        int[]l=new int[ar.length];

        int ind=0;
        for(Integer x: map.keySet())
            {
                ArrayList<Integer>t=map.get(x);
                ar[ind]=new int[t.size()];
                int ind2=0;
                l[ind]=1;
                for(int i=0;i<t.size();i++)
                {
                    ar[ind][ind2]=t.get(i);
                    l[ind]=getLcm(l[ind],ar[ind][ind2]);
                    ind2++;
                }
                p*=l[ind];
                ind++;
            }
        long[][]mat=new long[p][p];
        for(int i=0;i<p;i++)
        {
            int[]state=new int[ar.length];
            int cur=i;
            for(int j=0;j<state.length;j++)
            {
                state[j]=cur%l[j];
                cur/=l[j];
            }
            for(int j=0;j<state.length;j++)
            {
                int[]ns=state.clone();
                ns[j]=(ns[j]+1)%l[j];
                cur=0;
                for(int k=state.length-1;k>=0;k--)
                {
                    cur=cur*l[k]+ns[k];
                }
                mat[i][cur]++;
            }

        }
        long[][]res=pow(mat,n);
        long sum=0;
        for(int i=0;i<p;i++)
        {
            int[]state=new int[ar.length];
            int cur=i;
            boolean ok=true;
            for(int j=0;j<state.length;j++)
            {
                state[j]=cur%l[j];
                cur/=l[j];
                boolean  any=false;
                for(int x: ar[j])
                    if(state[j]%x==0)
                        any=true;
                if(!any)
                    ok=false;

            }
            if(ok)
                sum=(sum+res[0][i])%mod;

        }
        System.out.println(sum);

    }


    private int getLcm(int a, int b) {
        return a/BigInteger.valueOf(a).gcd(BigInteger.valueOf(b)).intValue()*b;
    }

    private long[][] pow(long[][] mat, long p) {
        if(p==0)
        {
            long[][]res=new long[mat.length][mat.length];
            for(int i=0;i<res.length;i++)
                res[i][i]=1;
            return res;
        }
        long[][]res=pow(mat,p/2);
        res=mul(res,res);
        if(p%2==1)
            res=mul(res,mat);
        return res;
    }

    private long[][] mul(long[][] a, long[][] b) {
        long[][]c=new long[a.length][a.length];
        for(int i=0;i<c.length;i++)
            for(int j=0;j<c.length;j++)
                for(int k=0;k<c.length;k++)
                    c[i][j]=(a[i][k]*b[k][j]+c[i][j])%mod;
        return c;
    }

