public class TaskD {

    int[] product;
    int[][] I;
    final int MOD = 12345;

    int[] decode(int code) {
        int[] a = new int[26];
        for(int i = 0; i < 26; i++) {
            a[i] = code % product[i];
            code /= product[i];
        }
        return a;
    }

    int encode(int[] a) {
        int code = 0;
        for(int i = 25; i >= 0; i--) {
            code = code * product[i] + a[i];
        }
        return code;
    }

    int[][] matrixMult(int[][] a, int[][] b) {
        int[][] c = new int[a.length][a.length];
        for(int k = 0; k < a.length; k++) {
            for(int i = 0; i < a.length; i++) {
                for(int j = 0; j < a.length; j++) {
                    c[i][j] += a[i][k] * b[k][j];
                    c[i][j] %= MOD;
                }
            }
        }
        return c;
    }

    int[][] matrixExponentiation(int[][] a, long N) {
        if(N == 0) return this.I;

        if(N % 2 == 0) {
            int[][] x = matrixExponentiation(a, N / 2);
            return matrixMult(x, x);
        }

        return matrixMult(a, matrixExponentiation(a, N - 1));
    }

    void run() {
        long N = nextLong();
        int c = nextInt();

        ArrayList<Integer>[] multiplicities = new ArrayList[26];
        for(int i = 0; i < multiplicities.length; i++) multiplicities[i] = new ArrayList<Integer>();

        for(int i = 0; i < c; i++) {
            String character = next();
            int multiple = nextInt();
            multiplicities[character.charAt(0) - 'A'].add(multiple);
        }


        int M = 1;
        this.product = new int[26];
        for (int i = 0; i < 26; i++) {
            product[i] = 1;
            for (int x : multiplicities[i])
                product[i] *= x;
            M *= product[i];
        }

        int[][] a = new int[M][M];
        for(int i = 0; i < M; i++) {
            for(int j = 0; j < 26; j++) if(multiplicities[j].size() > 0) {
                int[] d = decode(i);
                d[j]++;
                d[j] %= product[j];
                int code = encode(d);
                a[i][code]++;
            }
        }

        this.I = new int[M][M];
        for(int i = 0; i < M; i++) I[i][i] = 1;

        int[][] na = matrixExponentiation(a, N);

        int ans = 0;
        for(int code = 0; code < M; code++) {
            int[] d = decode(code);

            boolean ok = true;
            for(int j = 0; j < 26 && ok; j++) if(multiplicities[j].size() > 0) {
                boolean got = false;
                for(int x : multiplicities[j])
                    if(d[j] % x == 0) got = true;
                ok = got;
            }

            if(ok) {
                ans = (ans + na[0][code]) % MOD;
            }
        }

        System.out.println(ans);
    }

    int nextInt(){
        try{
            int c = System.in.read();
            if(c == -1) return c;
            while(c != '-' && (c < '0' || '9' < c)){
                c = System.in.read();
                if(c == -1) return c;
            }
            if(c == '-') return -nextInt();
            int res = 0;
            do{
                res *= 10;
                res += c - '0';
                c = System.in.read();
            }while('0' <= c && c <= '9');
            return res;
        }catch(Exception e){
            return -1;
        }
    }

    long nextLong(){
        try{
            int c = System.in.read();
            if(c == -1) return -1;
            while(c != '-' && (c < '0' || '9' < c)){
                c = System.in.read();
                if(c == -1) return -1;
            }
            if(c == '-') return -nextLong();
            long res = 0;
            do{
                res *= 10;
                res += c-'0';
                c = System.in.read();
            }while('0' <= c && c <= '9');
            return res;
        }catch(Exception e){
            return -1;
        }
    }

    double nextDouble(){
        return Double.parseDouble(next());
    }

    String next(){
        try{
            StringBuilder res = new StringBuilder("");
            int c = System.in.read();
            while(Character.isWhitespace(c))
                c = System.in.read();
            do{
                res.append((char)c);
            }while(!Character.isWhitespace(c=System.in.read()));
            return res.toString();
        }catch(Exception e){
            return null;
        }
    }

    String nextLine(){
        try{
            StringBuilder res = new StringBuilder("");
            int c = System.in.read();
            while(c == '\r' || c == '\n')
                c = System.in.read();
            do{
                res.append((char)c);
                c = System.in.read();
            }while(c != '\r' && c != '\n');
            return res.toString();
        }catch(Exception e){
            return null;
        }
    }

