	int[] dec(int a, int[] mul)
	{
		int n = mul.length;
		int[] ret = new int[n];
		for(int i = 0;i < n;i++){
			ret[i] = a % mul[i];
			a /= mul[i];
		}
		return ret;
	}

	int enc(int[] a, int[] mul)
	{
		int n = a.length;
		int ret = 0;
		for(int i = n-1;i >= 0;i--){
			ret = ret * mul[i]+a[i];
		}
		return ret;
	}

	public static int MOD = 12345;

	// int行列*ベクトル
	public static int[] mul(int[][] A, int[] v)
	{
		int m = A.length;
		int n = v.length;
		int[] w = new int[m];
		for(int i = 0;i < m;i++){
			long sum = 0;
			for(int k = 0;k < n;k++){
				sum += (long)A[i][k] * v[k];
				sum %= MOD;
			}
			w[i] = (int)sum;
		}
		return w;
	}

	// int行列の2乗
	public static int[][] p2(int[][] A)
	{
		int n = A.length;
		int[][] C = new int[n][n];
		for(int i = 0;i < n;i++){
			for(int j = 0;j < n;j++){
				long sum = 0;
				for(int k = 0;k < n;k++){
					sum += (long)A[i][k] * A[k][j];
					sum %= MOD;
				}
				C[i][j] = (int)sum;
			}
		}
		return C;
	}

	// A^e*v
	public static int[] pow(int[][] A, int[] v, long e)
	{
		int[][] MUL = A;
		for(;e > 0;e>>>=1) {
			if((e&1)==1)v = mul(MUL, v);
			MUL = p2(MUL);
		}
		return v;
	}

	public static int[][] packD(int n, int[] from, int[] to)
	{
		int[][] g = new int[n][];
		int[] p = new int[n];
		for(int f : from)p[f]++;
		for(int i = 0;i < n;i++)g[i] = new int[p[i]];
		for(int i = 0;i < from.length;i++){
			g[from[i]][--p[from[i]]] = to[i];
		}
		return g;
	}

