class TaskE {
    final int mod = (int) 1e9 + 7;
    public void solve(int testNumber, InputReader in, PrintWriter out) {
        int n = in.readInt();
        int k = in.readInt();
        int[][] c = Combinatorics.GetCombinations(n, n, mod);
        int[][][][] dp = new int[n + 2][n + 2][2][2];
        dp[0][0][0][1] = 1;
        for (int i = 1; i <= n; ++i) {
            for (int j = 0; j <= i; ++j) {
                for (int first = 0; first < 2; ++first) {
                    for (int second = 0; second < 2; ++second) {
                        if (first == 1) {
                            if (j > 0) {
                                dp[i][j][second][1] += dp[i - 1][j - 1][first][second];
                                dp[i][j][second][1] %= mod;
                            }
                        }
                        if (i < n && j > 0) {
                            dp[i][j][second][0] += dp[i - 1][j - 1][first][second];
                            dp[i][j][second][0] %= mod;
                        }
                        dp[i][j][second][1] += dp[i - 1][j][first][second];
                        dp[i][j][second][1] %= mod;
                    }
                }
            }
        }
        long[] fact = new long[n + 5];
        fact[0] = 1;
        for (int i = 1; i <= n; ++i) {
            fact[i] = fact[i - 1] * i;
            fact[i] %= mod;
        }
        long[] f = new long[n + 1];
        for (int i = 0; i <= n; ++i) {
            f[i] = 0;
            for (int first = 0; first < 2; ++first) {
                for (int second = 0; second < 2; ++second) {
                    f[i] += dp[n][i][first][second];
                    f[i] %= mod;
                }
            }
            f[i] *= fact[n - i];
            f[i] %= mod;
        }

        for (int i = n; i >= 0; --i) {
            for (int j = i + 1; j <= n; ++j) {
                f[i] -= (f[j] * c[j][i]) % mod;
                f[i] += mod;
                f[i] %= mod;
            }
        }
        out.println(f[k]);
    }
}

class InputReader {

    private InputStream stream;
    private byte[] buf = new byte[1024];
    private int curChar;
    private int numChars;

    public InputReader(InputStream stream) {
        this.stream = stream;
    }

    public int read() {
        // InputMismatchException -> UnknownError
        if (numChars == -1)
            throw new UnknownError();
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buf);
            } catch (IOException e) {
                throw new UnknownError();
            }
            if (numChars <= 0)
                return -1;
        }
        return buf[curChar++];
    }

    public int readInt() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        } else if (c == '+') {
            c = read();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9')
                throw new InputMismatchException();
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    public static boolean isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    }

class Combinatorics {
    public static int[][] GetCombinations(int n, int m, int MOD) {
        int[][] c = new int[n + 1][m + 1];
        c[0][0] = 1;
        for (int i = 1; i <= n; ++i) {
            c[i][0] = 1;
            for (int j = 1; j < i && j <= m; ++j) {
                c[i][j] = c[i - 1][j] + c[i - 1][j - 1];
                if (c[i][j] >= MOD) {
                    c[i][j] -= MOD;
                }
            }
            c[i][i] = 1;
        }
        return c;
    }

    }

