class E {
    public double[][][][] dp;
    public void solve(int testNumber, InputReader in, PrintWriter out) {
        int x = in.nextInt();
        int k = in.nextInt();
        int p = in.nextInt();
        dp = new double[2][256][251][2];
        for (int i = 0; i < 2; i++) {
            for (int j = 0; j < 256; j++) {
                for (int u = 0; u < 251; u++) {
                    dp[i][j][u][0] = 0;
                    dp[i][j][u][1] = 0;
                }
            }
        }
        int y=x/256;
        if(y==0) {
            dp[0][x&255][0][0]=1;
        } else {
            if((y&1)==0) {
                int z=0;
                for(; (y&1)==0; z++) {
                    y>>=1;
                }
                dp[0][x&255][z][0]=1;
            } else {
                int z=0;
                for(; (y&1)>0; z++) {
                    y>>=1;
                }
                dp[0][x&255][z][1]=1;
            }
        }
        for(int i=0; i<k; i++) {

            for(int j=0; j<256; j++) {
                for (int u = 0; u < 250; u++) {
                    dp[(i+1)&1][j][u][0]=0;
                    dp[(i+1)&1][j][u][1]=0;
                }
            }
            for(int j=0; j<256; j++) {
                for(int u=0; u<250; u++) {
                    if((j&128)>0) {
                        dp[(i+1)&1][(j<<1)&255][1][1]+=dp[i&1][j][u][0]*p*0.01;
                        dp[(i+1)&1][(j<<1)&255][u+1][1]+=dp[i&1][j][u][1]*p*0.01;
                    } else {
                        dp[(i+1)&1][(j<<1)&255][u+1][0]+=dp[i&1][j][u][0]*p*0.01;
                        dp[(i+1)&1][(j<<1)&255][1][0]+=dp[i&1][j][u][1]*p*0.01;
                    }
                    if(j==255) {
                        dp[(i+1)&1][0][1][1]+=dp[i&1][j][u][0]*(1-p*0.01);
                        dp[(i+1)&1][0][u][0]+=dp[i&1][j][u][1]*(1-p*0.01);
                    } else {
                        dp[(i+1)&1][j+1][u][0]+=dp[i&1][j][u][0]*(1-p*0.01);
                        dp[(i+1)&1][j+1][u][1]+=dp[i&1][j][u][1]*(1-p*0.01);
                    }
                }
            }
        }
        double ans=0;
        for(int j=0; j<256; j++) {
            int cnt=0;
            if(j>0) {
                for (int t = j; (t & 1) == 0; cnt++) {
                    t >>= 1;
                }
            }
            for(int u=0; u<250; u++) {
                if(j==0) {
                    ans+=dp[k&1][0][u][0]*(8+u);
                    ans+=dp[k&1][0][u][1]*8;
                } else {
                    ans+=dp[k&1][j][u][0]*cnt;
                    ans+=dp[k&1][j][u][1]*cnt;
                }
            }
        }
        out.printf("%.13f\n",ans);
    }
}

