import java.util.Arrays;
import java.util.Random;
import java.util.Scanner;

public class Prob03 {

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int N = in.nextInt();
        int[] L = new int[N];
        int[] R = new int[N];
        for (int i = 0; i < N; i++) {
            L[i] = in.nextInt();
            R[i] = in.nextInt();
        }
        double[] probabilities = new double[10001];
        for (int i = 0; i < N; i++) {
            for (int j = L[i]; j <= R[i]; j++) {
                double prob = 1./(R[i]-L[i]+1);
                //count probability j to be the second largest
                double probResult = 0;
                outer:
                for (int k = 0; k < N; k++) {
                    if (i == k) continue;

                    double probMax = (1.*R[k] - j)/(R[k]-L[k]+1);
                    if (probMax < 0) continue;
                    if (i < k && L[k]<=j && R[k] >= j)  probMax += 1./(R[k]-L[k]+1);
                    if (probMax > 1) probMax = 1;

                    for (int m = 0; m < N; m++) {
                        if (m==i || m == k) continue;
                        double probMin = (1.*j - L[m])/(R[m]-L[m]+1);
                        if (probMin < 0) continue outer; 
                        if (m < i && L[m]<=j && R[m] >= j)  probMin += 1./(R[m]-L[m]+1);
                        if (probMin > 1) probMin = 1;
//                        System.out.println("second: " + j + " max prob: " + probMax + " min prob: " + probMin);
                        probMax *= probMin;
                    }
                    probResult += probMax;
                }
                prob *= probResult;
                probabilities[j] += prob;
//                System.out.println(Arrays.toString(probabilities));
            }
        }

        double sum = 0;
        double prob = 0;
        for (int i = 1; i < 10001; i++) {
            sum += i *probabilities[i];
            prob += probabilities[i];
        }
//        System.out.println(sum);
//        System.out.println(sum / prob);
        System.out.println(String.format("%.9f", sum));
    }

}

