class TaskE {
    public void solve(int testNumber, InputReader in, PrintWriter out) {
        int counter = in.nextInt();
        int[] bracket = new int[counter];
        int[] stack = new int[counter];
        int size = 0;
        for (int i = 0; i < counter; ++i)
            bracket[i] = in.nextInt();
        counter = in.nextInt();
        for (int i = 0; i < counter; ++i) {
            int index = in.nextInt() - 1;
            bracket[index] = -bracket[index];
        }
        for (int i = bracket.length - 1; i >= 0; --i) {
            if (bracket[i] < 0)
                stack[size++] = bracket[i];
            else if (size > 0 && stack[size - 1] + bracket[i] == 0)
                size--;
            else {
                bracket[i] = -bracket[i];
                stack[size++] = bracket[i];
            }
        }
        if (size > 0)
            out.println("NO");
        else {
            out.println("YES");
            for (int i : bracket) {
                out.print(i);
                out.print(" ");
            }
        }
    }
