		int n = sc.nextInt();

		int[] P = new int[n];

		for (int i = 0; i < n; i++)
			P[i] = sc.nextInt();

		boolean[] Q = new boolean[n];
		boolean[] Ans = new boolean[n];
		boolean[] V = new boolean[n];

		int q = sc.nextInt();

		for (int i = 0; i < q; i++) {
			int x = sc.nextInt() - 1;
			Ans[x] = Q[x] = true;
		}

		int[] next = new int[n + 1];

		for (int i = 0; i <= n; i++)
			next[i] = i;

		for (int i = 0; i < n; i++) {
			if(Q[i]) {
				V[i] = true;
				Stack<Integer> s = new Stack<>();
				boolean f = false;
				for (int j = (i > 0 ? next[i - 1] : -1); j >= 0; j = (j > 0 ? next[j - 1] : -1)) {
					V[j] = true;
					if(P[j] == P[i] && s.isEmpty()) {
						f = true;
						next[i] = j > 0 ? next[j - 1] : -1;
						break;
					} else {
						if(!s.isEmpty() && P[s.peek()] == P[j]) 
							Ans[s.pop()] = true;
						else
							s.push(j);
					}
				}

				if(!f) {
					System.out.println("NO");
					return;
				}
			}
		}


		Stack<Integer> s = new Stack<>();

		for (int i = next[n - 1]; i >= 0; i--) {
			if(V[i])
				continue;
			if(!s.isEmpty() && P[s.peek()] == P[i]) 
				Ans[s.pop()] = true;
			else
				s.push(i);
		}

		if(s.isEmpty()) {
			out.println("YES");
			for (int i = 0; i < n; i++)
				out.print((Ans[i] ? -P[i] : P[i]) + " ");
			out.println();
		}else 
			out.print("NO");

		out.flush();

	}



