public class Main {

	BufferedReader in;
	StringTokenizer str = null;
	PrintWriter out;

	private String next() throws Exception{
		while (str == null || !str.hasMoreElements())
			str = new StringTokenizer(in.readLine());
		return str.nextToken();
	}

	private int nextInt() throws Exception{
		return Integer.parseInt(next());
	}

	private long nextLong() throws Exception{
		return Long.parseLong(next());
	}

	private double nextDouble() throws Exception{
		return Double.parseDouble(next());
	}

	final long MOD = (long)(1e9) + 7;
	long []f;

	final int MAXN = 200010;

	public void run() throws Exception{
		in =  new BufferedReader(new InputStreamReader(System.in));
		out = new PrintWriter(System.out);
		int n = nextInt(), m = nextInt(), g = nextInt();
		if (n == 0) {
			if (m > 1) {
				if (g == 0) {
					out.println(1);
				}else {
					out.println(0);
				}
			}else {
				if (g == 1) {
					out.println(1);
				}else {
					out.println(0);
				}
			}
			out.close();
			return;
		}
		if (m == 0) {
			if (n % 2 == 0) {
				out.println(g);
			}else {
				out.println(g ^ 1);
			}
			out.close();
			return;
		}
		f = new long[MAXN];
		f[0] = 1;
		for(int i = 1; i < MAXN; ++i) f[i] = (f[i-1] * i) % MOD;
		long ret = 0;
		for(int i = 0; i <= n; ++i) {
			if (i % 2 == 0) {
				if (m - 1 > 0 || n - i > 0) {
					if (g == 0) ret += C(m - 1, n - i + m - 1);
				}else {
					if (g == 1) ret += 1;
				}
			}else {
				if (m - 1 > 0 || n - i > 0) {
					if (g == 1) ret += C(m - 1, n - i + m - 1);
				}else {
					if (g == 0) ret += 1;
				}
			}
			if (ret >= MOD) ret -= MOD;
		}
		out.println(ret);
		out.close();
	}

	private long C(int m, int n){
		long ret = f[n];
		ret *= inv((f[m] * f[n - m]) % MOD, MOD);
		return ret % MOD;
	}

	private long inv(long a, long b) {
		return pow(a, b - 2);
	}

	private long pow(long x, long p) {
		long ret = 1;
		while(p > 0) {
			if (p % 2 == 1) ret = (ret * x) % MOD;
			x = (x * x) % MOD;
			p >>= 1;
		}
		return ret;
	}

	public static void main(String[] args) throws Exception{
		new Main().run();
	}
}

