    static BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
	static FastScanner sc=new FastScanner(br);
    static PrintWriter out=new PrintWriter(System.out);
	static Random rnd=new Random();
	static long mod=(long)(1e9+7);

	static long C(long n,long diff)
	{
		long ret=1,upper=n+diff-1;

		for(long x=upper;x>diff;x--)
		{
			long now=x%mod;

			ret=(ret*now)%mod;
		}

		return (ret*pow(fact(n-1),mod-2))%mod;
	}

	static long fact(long n)
	{
		long ret=1;

		for(long i=1;i<=n;i++)	
		{
			ret=(ret*i)%mod;
		}

		return ret;
	}

	static long pow(long a,long b)
	{
		long x=1,y=a;

		while(b>0)
		{
			if(b%2==1)
			{
				x=(x*y)%mod;
			}

			y=(y*y)%mod;b=b/2;
		}

		return x;
	}

	static Map<Long,Long> merge(Map<Long,Long> m1,long now)
	{	
		Map<Long,Long> m2=new HashMap<>(),ret=new HashMap<>();

		m2.put(0L,1L);m2.put(now,(-1L+mod)%mod);

		for(Map.Entry<Long,Long> en1:m1.entrySet())
		{
			for(Map.Entry<Long,Long> en2:m2.entrySet())
			{
				long add=en1.getKey()+en2.getKey(),mul=(en1.getValue()*en2.getValue())%mod;

				ret.put(add,(ret.getOrDefault(add,0L)+mul)%mod);
			}
		}

		return ret;
	}

    public static void main(String args[]) throws Exception
    {
		int n=sc.nextInt();long s=sc.nextLong();

		long[] a=new long[n];

		for(int i=0;i<n;i++)
		{
			a[i]=sc.nextLong();
		}

		// 1-x^a[i]+1..

		Map<Long,Long> m1=new HashMap<>();m1.put(0L,1L);

		for(int i=0;i<n;i++)
		{
			m1=merge(m1,a[i]+1);
		}

		long res=0;

		for(Map.Entry<Long,Long> en:m1.entrySet())
		{	
			long curr=en.getKey();

			if(curr<=s)
			{
				long diff=s-curr;

				long now=C(n,diff);

				long mul=(en.getValue()*now)%mod;

				res=(res+mul)%mod;
			}
		}

		out.println(res);out.close();
    }

