import java.io.*;
import java.math.*;
import java.util.*;

public class Main{
    FastScanner in;
    PrintWriter out;

    public long mod = 1000000000+7;
    long[] fact;

    public long bin_pow(long d, long step) {
        if (step == 0) return 1;
        if (step == 1) return d % mod;
        long x = bin_pow(d, step/2);
        x = (x * x) % mod;
        if (step % 2 == 1)
            x = (x * d) % mod;
        return x;
    }

    public long bC(int n, int k) {
        long res = fact[n];
        res *= bin_pow(fact[k], mod-2);
        res %= mod;
        res *= bin_pow(fact[n-k], mod-2);
        res %= mod;
        return res;
    }

    public long C(long n, int k) {
        if (n <= k)
            return bC((int)n, k);

        long res = 1;
        for (int p = 0; p < k ; p++) {
            res *= (n-p) % mod;
            res %= mod;
        }

        res *= bin_pow(fact[k], mod-2);
        res %= mod;

        return res;
    }

    public void solve()
    {
        int n = in.nextInt();
        long s = in.nextLong();
        long[] f = new long[n];
        long sum = 0;
        for (int i = 0; i < n; i++) {
            f[i] = in.nextLong();
            sum += f[i];
        }

        fact = new long[n+10];
        fact[0] = 1;
        for (int i = 1; i < n+10; i++) {
            fact[i] = i * fact[i-1];
            fact[i] %= mod;
        }


        long ans = 0;
        long sg;
        for(int mask = 0; mask < (1<<n); mask++) {
            int cnt = 0;
            sum = s;
            for (int i = 0; i < n; i++)
            if ((mask >> i) % 2 == 1)
            {
                cnt++;
                sum -= f[i]+1;
            }

            if (sum < 0) continue;

            if (cnt % 2 == 1)
                sg = -1;
            else
                sg = 1;

            long tmp_ans = 0;

            tmp_ans = C(sum + n - 1, n - 1);

            ans += sg * tmp_ans;
            ans += 2*mod;
            ans %= mod;
        }


        out.println(ans);
    }

    public void run()
    {
        in = new FastScanner();
        out = new PrintWriter(System.out);

        solve();

        out.close();
    }


    public static void main(String[] args) {
        new Main().run();
    }

    class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
