import java.text.NumberFormat;

public class P595D {
    private static final double TWO_PI = Math.PI * 2;

    private static double newton(double x) {
        double t = x/2;
        double nt = t - (t + Math.sin(t) - x)/(1 + Math.cos(t));
        while (Math.abs(nt-t) >= 1e-7) {
            t = nt;
            nt = t - (t + Math.sin(t) - x)/(1 + Math.cos(t));
        }
        return nt;
    }

    private static double minTime(long d, int r, int v) {
        final double th = d / (double)r;
        final double k = Math.floor(th/TWO_PI);
        final double x = th % TWO_PI;
        final double t = newton(x/2);
        return (2*t + k*TWO_PI) * r / v;
    }

    public static void main(String[] args) throws IOException {
        final NumberFormat formatter = new DecimalFormat("#.#######");

        final BufferedReader in = new BufferedReader(
            new InputStreamReader(System.in));

        String[] s = in.readLine().split(" ");
        final int n = Integer.parseInt(s[0]);
        final int r = Integer.parseInt(s[1]);
        final int v = Integer.parseInt(s[2]);
        for (int i = 0; i<n; i++) {
            s = in.readLine().split(" ");
            final int si = Integer.parseInt(s[0]);
            final int fi = Integer.parseInt(s[1]);
            System.out.println(formatter.format(minTime(fi-si, r, v)));
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.util.NoSuchElementException;

public class Main {
    public void solve() {
	FastScanner scanner = new FastScanner();
	int N = scanner.nextInt();
	final int R = scanner.nextInt();
	final double V = scanner.nextInt();
	final double cycle = 2.0 * Math.PI * R;

	StringBuilder builder = new StringBuilder();
	for (int i = 0; i < N; i++) {
	    int start = scanner.nextInt();
	    int finish = scanner.nextInt();
	    final int L = finish - start;

	    int A = (int) (L / cycle);
	    double rest = L - cycle * A;
	    rest /= 2.0;
	    double theta = 0.0;
	    double low = 0, high = Math.PI;
	    double plow = low, phigh = high;
	    while (low < high) {
		theta = (high + low) / 2.0;
		double x = R * theta + R * Math.sin(theta);
		if (x > rest) {
		    high = theta;
		} else {
		    low = theta;
		}
		if (plow == low && phigh == high) {
		    break;
		}
		plow = low;
		phigh = high;
	    }

	    double dist = cycle * A + R * 2 * theta;
	    dist /= V;
	    builder.append(dist);
	    builder.append("\n");
	}
	System.out.println(builder.toString());
    }

    public static void main(String[] args) {
	new Main().solve();
    }

}

class FastScanner {
    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;

    private boolean hasNextByte() {
	if (ptr < buflen) {
	    return true;
	} else {
	    ptr = 0;
	    try {
		buflen = in.read(buffer);
	    } catch (IOException e) {
		e.printStackTrace();
	    }
	    if (buflen <= 0) {
		return false;
	    }
	}
	return true;
    }

    private int readByte() {
	if (hasNextByte())
	    return buffer[ptr++];
	else
	    return -1;
    }

    private static boolean isPrintableChar(int c) {
	return 33 <= c && c <= 126;
    }

    private void skipUnprintable() {
	while (hasNextByte() && !isPrintableChar(buffer[ptr]))
	    ptr++;
    }

    public boolean hasNext() {
	skipUnprintable();
	return hasNextByte();
    }

    public String next() {
	if (!hasNext())
	    throw new NoSuchElementException();
	StringBuilder sb = new StringBuilder();
	int b = readByte();
	while (isPrintableChar(b)) {
	    sb.appendCodePoint(b);
	    b = readByte();
	}
	return sb.toString();
    }

    public long nextLong() {
	if (!hasNext())
	    throw new NoSuchElementException();
	long n = 0;
	boolean minus = false;
	int b = readByte();
	if (b == '-') {
	    minus = true;
	    b = readByte();
	}
	if (b < '0' || '9' < b) {
	    throw new NumberFormatException();
	}
	while (true) {
	    if ('0' <= b && b <= '9') {
		n *= 10;
		n += b - '0';
	    } else if (b == -1 || !isPrintableChar(b)) {
		return minus ? -n : n;
	    } else {
		throw new NumberFormatException();
	    }
	    b = readByte();
	}
    }

    public int nextInt() {
	return (int) nextLong();

    }
}

