public class D {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int r = scanner.nextInt();
        int v = scanner.nextInt();
        for(int i=0; i<n; ++i) {
          int s = scanner.nextInt();
          int f = scanner.nextInt();
          double d = f - s;
          int cycle = (int)(d/(2*Math.PI*r));
          d -= cycle*(2*Math.PI*r);
          System.out.println((cycle*(2*Math.PI*r) + r*D.bs(d, r))/v);
        }
    }

    public static double bs(double d, int r) {
      double l = 0;
      double u = Math.PI * 2;
      double middle=0;
      while(l<u) {
        middle = (l+u)/2;
        double value = D.eval(middle, r);
        if(value < d) {
          l = middle;
        }
        else {
          u = middle;
        }
        if(Math.abs(value-d) < 0.000001) return middle;
      }
      return middle;
    }
    public static double eval(double theta, double r) {
      return r*theta + 2 * r * Math.sin(theta/2);
    }
}

