        for (int i = 0; i < n; i++)
        {
            nextLine(br);
            int start = nextInt();
            int finish = nextInt();
            double diff = finish - start;
            double ans = solve(diff, v, r);
            sb.append(String.valueOf(ans) + "\n");
        }
        System.out.println(sb.toString());

    }

    public static double test(double in)
    {
        double left = 0;
        double right = 1;
        double rem = in;
        for (int i = 0; i < 100; i++)
        {
            double mid = (left + right) / 2;
            double temp = Math.PI * mid;
            double k = temp + Math.sin(temp);
            //if (in > 3.14) System.out.println("M" + mid + " " + k);
            if (k > rem)
            {
                right = mid;
            }
            else
            {
                left = mid;
            }
        }
        return (left + right) / 2;
    }

    public static double solve(double d, double v, double r)
    {
        d = d / r;
        v = v / r;
        double circ = 2 * Math.PI;
        double rounds = Math.floor(d / circ);
        double rem = (d - rounds * circ) / 2;
        double left = 0;
        double right = 1;
        for (int i = 0; i < 100; i++)
        {
            double mid = (left + right) / 2;
            double temp = Math.PI * mid;
            double k = temp + Math.sin(temp);
            if (k > rem)
            {
                right = mid;
            }
            else
            {
                left = mid;
            }
        }
        //System.out.println(rounds + " " + rem + " " + left);

        double ans = ((left + rounds) * circ) / v;
        return ans;
    }

}

