    static class AntiPalindrome {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int N = in.nextInt();
            int[] cnt = new int[26];
            int move = 0;
            char[] str = in.next().toCharArray();
            int[] b = new int[N];
            int res = 0;
            for (int i = 0; i < b.length; i++) {
                b[i] = in.nextInt();
                res += b[i];
            }
            for (int i = 0; i < N / 2; i++) {
                if (str[i] == str[N - i - 1]) {
                    cnt[str[i] - 'a']++;
                    move++;
                    res -= Math.min(b[i], b[N - i - 1]);
                }
            }
            for (int i = 0; i < 26; i++) {
                if (cnt[i] > move / 2) {
                    int left = cnt[i] * 2 - move;
                    ArrayList<Integer> pos = new ArrayList<>();
                    for (int j = 0; j < N / 2; j++) {
                        if (str[j] != str[N - j - 1]) {
                            if (str[N - j - 1] - 'a' == i || str[j] - 'a' == i) {
//                            if (str[j] -'a' == i) {
//                                pos.add(b[j]);
//                            }
//                            else {
//                                pos.add(b[N-j-1]);
//                            }
                            } else {
                                pos.add(Math.min(b[N - j - 1], b[j]));
                            }
                        }
                    }
                    Collections.sort(pos);
                    for (int j = 0; j < left; j++) {
                        res -= pos.get(j);
                    }
                }
            }
            out.println(res);
        }

    }

