public class Ada extends PrintWriter {
    Ada() { super(System.out, true); }
    Scanner sc = new Scanner(System.in);
    public static void main(String[] $) {
        Ada o = new Ada(); o.main(); o.flush();
    }

    int compress(int[] aa, int n) {
        Random rand = new Random();
        for (int i = 0; i < n; i++) {
            int j = rand.nextInt(i + 1);
            int tmp = aa[i]; aa[i] = aa[j]; aa[j] = tmp;
        }
        Arrays.sort(aa, 0, n);
        int m = 1;
        for (int i = 1; i < n; i++)
            if (aa[i] != aa[i - 1])
                aa[m++] = aa[i];
        return m;
    }
    void main() {
        int a = sc.nextInt();
        int b = sc.nextInt();
        int n = a + b;
        int s = (int) Math.sqrt(n) + 1;
        int[] gg = new int[s + s];
        int m = 0;
        for (int g = 1; g <= s; g++)
            gg[m++] = g;
        for (int k = 1; k <= s; k++) {
            int g = n / k;
	    gg[m++] = g;
        }
        m = compress(gg, m);
        int ans = 0;
        for (int h = 0; h < m; h++) {
            int g = gg[h];
            int al = (int) ((a + (long) g) / (g + 1));
            int bl = (int) ((b + (long) g) / (g + 1));
            int ar = a / g;
            int br = b / g;
            if (al <= ar && bl <= br) {
                int l = Math.max(n / (g + 1) + 1, al + bl);
                int r = Math.min(n / g, ar + br);
                if (l <= r)
                    ans += r - l + 1;
            }
        }
        println(ans);
    }
}

