public class Solution {

    public static void main(String[] args) throws IOException {
        new Solution().run();
    }

    int divs[] = new int[100];
    int divcnt = 0;

    public void solve() throws IOException {
        int n = nextInt();
        int x = nextInt();

        int npp = n + 1;
        for(int i = 2; i * i <= npp; ++i) {
            if(npp % i == 0) {
                out.println(-1);
                return;
            }
        }

        for(int i = 2; i * i <= n; ++i) {
            if(n % i == 0) {
                divs[divcnt++] = n / i;
            }
        }

        int stop = Math.max(2, x - n - 2);
        for(int b = x - 1; b >= stop; --b) {
            if(binpow(b, n, npp) == 1) {
                boolean ok = true;
                for(int d = 0; d < divcnt && ok; ++d) {
                    ok = binpow(b, divs[d], npp) != 1;
                }
                if(ok) {
                    out.println(b);
                    return;
                }
            }
        }

        out.println(-1);
    }

    int binpow(long a, int n, int mod) {
        long res = 1 % mod;
        while(n != 0) {
            if((n & 1) != 0) {
                res = res * a % mod;
            }
            a = a * a % mod;
            n >>= 1;
        }
        return (int)res;
    }

    BufferedReader br;
    StringTokenizer in;
    PrintWriter out;

    String nextToken() throws IOException {
        while( in == null || !in.hasMoreTokens() ) {
            in = new StringTokenizer(br.readLine());
        }

        return in.nextToken();
    }

    public int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
