import java.io.*;
import java.util.*;

public class Solution {
    private static int MOD = (1000000000+7);

    public static void main(String[] args) {
        FastReader sc = new FastReader();
        int n = sc.nextInt();
        int k = sc.nextInt();

        long ans = pow_mod(2,n);
        long pascalTriangle = 1;
        long m = pow_mod(2,n-k);
        for(int i = 0; i < n-k; i++){
            ans = sub(ans, mul(pascalTriangle,(m-1)));
            m = m * pow_mod(2, MOD-2) % MOD;
            long temp  = mul(pascalTriangle, (k+i));
            pascalTriangle = temp * pow_mod(i+1, MOD-2) % MOD;
        }

        System.out.println(ans);
    }

    public static long mul(long a, long b) {
        return (long) a * b % MOD;
    }

    private static long sub(long a, long b) {
        return a >= b ? a - b : a - b + MOD;
    }

    private static long pow_mod (long x, long n) {
        long y = 1;
        while (n > 0) {
            if (n%2 != 0)
                y = y * x % MOD;
            n = n/2;
            x = x * x % MOD;
        }
        return y;
    }

    private static int max(int a, int b){
        return Math.max(a, b);
    }

    private static int min(int a, int b){
        return Math.min(a, b);
    }

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader()
        {
            br = new BufferedReader(
                    new InputStreamReader(System.in));
        }

        String next()
        {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                }
                catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() { return Integer.parseInt(next()); }

        long nextLong() { return Long.parseLong(next()); }

        double nextDouble()
        {
            return Double.parseDouble(next());
        }

        String nextLine()
        {
            String str = "";
            try {
                if(st.hasMoreTokens()){
                    str = st.nextToken("\n");
                }
                else{
                    str = br.readLine();
                }
            }
            catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }

        int[] intArray(int n){
            int[] arr = new int[n];
            for(int i =0; i < n; i ++){
                arr[i] = nextInt();
            }
            return arr;
        }
    }
}

