public class CodeforcesD268 {
	public static int[][][][][] memo;
	public static int n, h;
	public static int mod = 1000000009;
	public static void main(String[] args){
		Scanner br = new Scanner(System.in);
		n = br.nextInt();
		h = br.nextInt();

		memo = new int[2][h+1][h+1][h+1][n];
		for(int i = 0;i<2;i++){
			for(int j = 0;j<h+1;j++){
				for(int k = 0;k<h+1;k++){
					for(int l = 0;l<h+1;l++){
						Arrays.fill(memo[i][j][k][l], -1);
					}
				}
			}
		}
		System.out.println(go(0, new int[3], 0));
	}
	public static int go(int flag, int[] lasts, int pos){
		for(int i = 0;i<lasts.length;i++){
			lasts[i] = Math.min(lasts[i], h);
		}
		int last1 = (flag == 0 ? 0 : h);
		int last2 = lasts[0];
		int last3 = lasts[1];
		int last4 = lasts[2];
		if(last1 < h || last2 < h || last3 < h || last4 < h){

		}
		else{
			return 0;
		}
		if(pos == n){

			if(last1 < h || last2 < h || last3 < h || last4 < h){
				return 1;
			}
			return 0;
		}

		if(memo[flag][last2][last3][last4][pos] != -1){
			return memo[flag][last2][last3][last4][pos];
		}

		int ans = 0;
		ans+=go(flag, new int[]{last2+1, last3+1, last4+1}, pos+1);
		ans%=mod;

		//Place second
		ans+=go((last2 == h) ? 1 : 0, new int[]{last1+1, last3+1, last4+1}, pos+1);
		ans%=mod;

		//Place third
		ans+=go((last3 == h) ? 1 : 0, new int[]{last1+1, last2+1, last4+1}, pos+1);
		ans%=mod;


		//Place fourth
		ans+=go((last4 == h) ? 1 : 0, new int[]{last1+1, last2+1, last3+1}, pos+1);
		ans%=mod;

		return memo[flag][last2][last3][last4][pos] = ans;
	}
