class Matrix {
    final int[][] a;
    public final int n;
    public final int m;

    public Matrix(int n, int m) {
        this.n = n;
        this.m = m;
        a = new int[n][m];
    }

    public Matrix(int n) {
        this(n, n);
    }

    public Matrix(int[][] a) {
        n = a.length;
        if (n == 0) {
            throw new AssertionError();
        }
        m = a[0].length;
        this.a = new int[n][];
        for (int i = 0; i < n; i++) {
            if (m != a[i].length) {
                throw new AssertionError();
            }
            this.a[i] = a[i].clone();
        }
    }

    public int get(int x, int y) {
        return a[x][y];
    }

    public static Matrix getOne(int n) {
        Matrix ret = new Matrix(n);
        for (int i = 0; i < n; i++) {
            ret.a[i][i] = 1;
        }
        return ret;
    }

    public Matrix multiplyMod(Matrix b, int mod) {
        if (m != b.n) {
            throw new AssertionError();
        }
        Matrix ret = new Matrix(n, b.m);
        long modmod = (long) mod * mod;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < b.m; j++) {
                long d = 0;
                for (int k = 0; k < m; k++) {
                    d = (d + (long) a[i][k] * b.a[k][j]);
                    if (d >= modmod) {
                        d -= modmod;
                    }
                }
                ret.a[i][j] = (int) (d % mod);
            }
        }
        return ret;
    }

    public static Matrix powMod(Matrix a, long b, int mod) {
        if (a.n != a.m) {
            throw new AssertionError();
        }
        Matrix ret = getOne(a.n);
        while (b > 0) {
            if ((b & 1) == 1) {
                ret = ret.multiplyMod(a, mod);
            }
            a = a.multiplyMod(a, mod);
            b >>= 1;
        }
        return ret;
    }

    }

