public class E {
    static int mod;

    public static long[][] identity() {
        long[][] a = new long[6][6];
        for (int i = 0; i < 6; i++)
            a[i][i] = 1;
        return a;
    }

    public static long[][] modMul(long[][] A, long[][] B) {
        long[][] C = new long[6][6];
        for (int i = 0; i < 6; i++)
            for (int j = 0; j < 6; j++)
                for (int k = 0; k < 6; k++)
                    C[i][j] = (C[i][j] + (A[i][k] * B[k][j]) % mod) % mod;
        return C;
    }

    public static long[][] modPow(long[][] M, long p) {
        if (p == 0)
            return identity();
        long[][] temp = modPow(M, p >> 1);
        temp = modMul(temp, temp);
        if ((p & 1) != 0)
            temp = modMul(M, temp);
        return temp;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        mod = in.nextInt();
        long x = in.nextLong() - 1;
        long y = in.nextLong() - 1;
