import java.util.Scanner;

public class Main {

    public static final double EPS = 1e-8;
    private static StreamTokenizer in;
    private static Scanner ins;
    private static PrintWriter out;
    private double p;

    public static void main(String[] args) {
        try {
            in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
            ins = new Scanner(System.in);
            out = new PrintWriter(System.out);
            try {
                if (System.getProperty("xDx") != null) {
                    in = new StreamTokenizer(new BufferedReader(new FileReader("input.txt")));
                    ins = new Scanner(new FileReader("input.txt"));
                    out = new PrintWriter(new FileWriter("output.txt"));
                }
            } catch (Exception e) {
                in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
                ins = new Scanner(System.in);
                out = new PrintWriter(System.out);
            }
            new Main().run();
            out.close();
        } catch (IOException e) {
            throw new RuntimeException(e.getMessage(), e);
        }
    }

    private double[][] dp;

    private void run() throws IOException {
        int n = nextInt();
        p = nextDouble();
        int t = nextInt();

        dp = new double[n + 1][t + 1];
        for (int i = 0; i <= n; i++) {
            Arrays.fill(dp[i], -1.0);
        }

        out.printf("%.6f", calcDp(n, t));
    }

    private double calcDp(int n, int t) {
        if (n == 0 || t == 0) {
            return 0;
        }

        if (dp[n][t] >= 0) {
            return dp[n][t];
        }

        return dp[n][t] = p * (1.0 + calcDp(n - 1, t - 1)) + (1.0 - p) * calcDp(n, t - 1);
    }


    private int nextInt() throws IOException {
        in.nextToken();
        return (int) in.nval;
    }

    private long nextLong() throws IOException {
        in.nextToken();
        return (long) in.nval;
    }

    private double nextDouble() throws IOException {
        in.nextToken();
        return in.nval;
    }

    private String nextString() throws IOException {
        in.nextToken();
        return in.sval;
    }

}

