public class Main {

    static int n, t;
    static double p;
    static double memo[][];

    static double dp (int time, int soFar) {
        if (time == t) return soFar;
        if (memo[time][soFar] != -1) {
            return memo[time][soFar];
        }

        if (soFar == n) {
           return memo[time][soFar] = dp(time + 1, soFar);
        } else {
            return memo[time][soFar] = dp(time + 1, soFar) * (1 - p) + (soFar == n ? 0 : dp(time + 1, soFar + 1) * p);
        }
    }
