/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author svilen.marchev@gmail.com
 */
public class Main {
  public static void main(String[] args) {
    InputStream inputStream = System.in;
    OutputStream outputStream = System.out;
    InputStreamReader in = new InputStreamReader(inputStream);
    PrintWriter out = new PrintWriter(outputStream);
    TaskG solver = new TaskG();
    solver.solve(1, in, out);
    out.close();
  }

  static class TaskG {
    final int MOD = 1_000_000_007;
    int n;
    int k;
    byte[] moebius;
    int[] powN;
    long[] val;

    public void solve(int testNumber, InputStreamReader in, PrintWriter out) {
      SvScanner sc = new SvScanner(in);
      n = sc.nextInt();
      k = sc.nextInt();

//    moebius = SvNumberTheoryUtils.genMoebiusFuncForIntsUpTo(k);
      int[] lowestPrimeFactors = SvPrimalityUtils.genLowestPrimeFactorOfIntsUpTo(k);
      moebius = SvNumberTheoryUtils.genMoebiusFuncOfIntsUpTo(k, lowestPrimeFactors);

      powN = new int[k + 1];
      for (int i = 1; i <= k; ++i) {
        powN[i] = SvCommonMathUtils.pow(i, n, MOD);
      }

      val = new long[k + 1];
      for (int g = 1; g <= k; ++g) {
        for (int i = g; i <= k; i += g) {
          val[i] += moebius[g] * powN[i / g];
          val[i] -= moebius[g] * powN[(i - 1) / g];
        }
      }
      for (int i = 2; i <= k; ++i) {
        val[i] = (val[i] + val[i - 1]) % MOD;
      }

      long ans = 0;
      for (int i = 1; i <= k; ++i) {
        long v = (val[i] % MOD + MOD) % MOD;
        ans = (ans + (v ^ i)) % MOD;
      }
      out.println(ans);
    }

  }

  static class SvScanner {
    private BufferedReader reader;
    private StringTokenizer tokenizer = new StringTokenizer("");

    public SvScanner(InputStreamReader in) {
      reader = new BufferedReader(in);
    }

    public String next() {
      try {
        while (!tokenizer.hasMoreTokens()) {
          String nextLine = reader.readLine();
          if (nextLine == null) {
            throw new IllegalStateException("next line is null");
          }
          tokenizer = new StringTokenizer(nextLine);
        }
        return tokenizer.nextToken();
      } catch (IOException e) {
        throw new IllegalStateException(e);
      }
    }

    public int nextInt() {
      return Integer.parseInt(next());
    }

  }

  static class SvNumberTheoryUtils {
    public static byte[] genMoebiusFuncOfIntsUpTo(int n, int[] lowestPrimeFactorOf) {
      byte[] moebius = new byte[n + 1];
      moebius[1] = 1;
      for (int i = 2; i <= n; i++) {
        int j = i / lowestPrimeFactorOf[i];
        if (lowestPrimeFactorOf[j] == lowestPrimeFactorOf[i]) {
          moebius[i] = 0;
        } else {
          moebius[i] = (byte) -moebius[j];
        }
      }
      return moebius;
    }

  }

  static class InputReader {
    private InputStream stream;

    public InputReader(InputStream stream) {
      this.stream = stream;
    }

  }

  static class SvPrimalityUtils {
    public static int[] genLowestPrimeFactorOfIntsUpTo(int n) {
      // Allocate enough memory for the primes up to n.
      int u = n + 32;
      double lu = Math.log(u);
      int[] primes = new int[(int) (u / lu + u / lu / lu * 1.5)];
      int numPrimes = 0;

      int[] lowestPrimeFactorOf = new int[n + 1];
      for (int i = 2; i <= n; i++) {
        lowestPrimeFactorOf[i] = i;
      }

      for (int p = 2; p <= n; ++p) {
        if (lowestPrimeFactorOf[p] == p) {
          primes[numPrimes++] = p;
        }
        for (int i = 0; i < numPrimes && primes[i] <= lowestPrimeFactorOf[p]; ++i) {
          int tmp = primes[i] * p;
          if (tmp > n) break;
          lowestPrimeFactorOf[tmp] = primes[i];
        }
      }
      return lowestPrimeFactorOf;
    }

  }

  static class SvCommonMathUtils {
    public static int pow(int n, long deg, int mod) {
      if (n < 0 || deg < 0 || mod <= 0) {
        throw new IllegalArgumentException();
      }
      if (deg == 0) {
        return 1;
      } else if (deg % 2 == 0) {
        long tmp = pow(n, deg / 2, mod);
        return (int) ((tmp * tmp) % mod);
      } else {
        return (int) (((n % mod) * (long) pow(n, deg - 1, mod)) % mod);
      }
    }

  }
}

