                System.out.println(0);
            }

            return;
        }

        int[] dp = new int[N];
        Arrays.fill(dp, 1);
        dp[0] = 0;
        int sum = N - 1;

        for (int i = 1; i < K; i++) {
            int nsum = 0;
            for (int j = 0; j < N; j++) {
                dp[j] = (sum - dp[j] + MOD) % MOD;
                nsum += dp[j];
                if (nsum >= MOD) nsum -= MOD;
