    }

    static class GLuckyTickets {
        public int mod = 998244353;
        int[] d;

        public void solve(int testNumber, ScanReader in, PrintWriter out) {
            int n = in.scanInt();
            int k = in.scanInt();
            d = new int[k];
            in.scanInt(d, k);
            long[] way = new long[10];
            for (int i : d) way[i]++;
            long ans = 0;
            long[] dp = null;
            n /= 2;
            while (n > 0) {
                if ((n & 1) == 1) {
                    if (dp == null) dp = Arrays.copyOf(way, way.length);
                    else {
                        long[] dp1 = Arrays.copyOf(dp, dp.length);
                        dp = FFT.convoluteSimply(dp1, way, mod, 3);
                    }
                }
                n >>= 1;
                way = FFT.convoluteSimply(way, way, mod, 3);
            }
            for (int i = 0; i < dp.length; i++) ans = (ans + dp[i] * dp[i]) % mod;
            out.println(ans);
        }

    }

    static class CodeHash {
        public static long pow(long a, long b, long m) {
            long res = 1;
            a %= m;
            while (b > 0) {
                if ((b & 1) == 1) res = (res * a) % m;
                a = (a * a) % m;
                b >>= 1;
            }
            return res;
        }

    }

    static class FFT {
        public static long[] convoluteSimply(long[] a, long[] b, int P, int g) {
            int m = Math.max(2, Integer.highestOneBit(Math.max(a.length, b.length) - 1) << 2);
            long[] fa = nttmb(a, m, false, P, g);
            long[] fb = a == b ? fa : nttmb(b, m, false, P, g);
            for (int i = 0; i < m; i++) {
                fa[i] = fa[i] * fb[i] % P;
            }
            return nttmb(fa, m, true, P, g);
        }

        private static long invl(long a, long mod) {
            long b = mod;
            long p = 1, q = 0;
            while (b > 0) {
                long c = a / b;
                long d;
                d = a;
                a = b;
                b = d % b;
                d = p;
                p = q;
                q = d - c * q;
            }
            return p < 0 ? p + mod : p;
        }

        private static long[] nttmb(long[] src, int n, boolean inverse, int P, int g) {
            long[] dst = Arrays.copyOf(src, n);

            int h = Integer.numberOfTrailingZeros(n);
            long K = Integer.highestOneBit(P) << 1;
            int H = Long.numberOfTrailingZeros(K) * 2;
            long M = K * K / P;

            int[] wws = new int[1 << h - 1];
            long dw = inverse ? CodeHash.pow(g, P - 1 - (P - 1) / n, P) : CodeHash.pow(g, (P - 1) / n, P);
            long w = (1L << 32) % P;
            for (int k = 0; k < 1 << h - 1; k++) {
                wws[k] = (int) w;
                w = modh(w * dw, M, H, P);
            }
            long J = invl(P, 1L << 32);
            for (int i = 0; i < h; i++) {
                for (int j = 0; j < 1 << i; j++) {
                    for (int k = 0, s = j << h - i, t = s | 1 << h - i - 1; k < 1 << h - i - 1; k++, s++, t++) {
                        long u = (dst[s] - dst[t] + 2 * P) * wws[k];
                        dst[s] += dst[t];
                        if (dst[s] >= 2 * P) dst[s] -= 2 * P;
//					long Q = (u&(1L<<32)-1)*J&(1L<<32)-1;
                        long Q = (u << 32) * J >>> 32;
                        dst[t] = (u >>> 32) - (Q * P >>> 32) + P;
                    }
                }
                if (i < h - 1) {
                    for (int k = 0; k < 1 << h - i - 2; k++) wws[k] = wws[k * 2];
                }
            }
            for (int i = 0; i < n; i++) {
                if (dst[i] >= P) dst[i] -= P;
            }
            for (int i = 0; i < n; i++) {
                int rev = Integer.reverse(i) >>> -h;
                if (i < rev) {
                    long d = dst[i];
                    dst[i] = dst[rev];
                    dst[rev] = d;
                }
            }

            if (inverse) {
                long in = invl(n, P);
                for (int i = 0; i < n; i++) dst[i] = modh(dst[i] * in, M, H, P);
            }

            return dst;
        }

        public static long modh(long a, long M, int h, int mod) {
            long r = a - ((M * (a & ((1L << 31) - 1)) >>> 31) + M * (a >>> 31) >>> h - 31) * mod;
            return r < mod ? r : r - mod;
        }

    }

    static class ScanReader {
        private byte[] buf = new byte[4 * 1024];
        private int index;
        private BufferedInputStream in;
        private int total;

        public ScanReader(InputStream inputStream) {
            in = new BufferedInputStream(inputStream);
        }

        private int scan() {
            if (index >= total) {
                index = 0;
                try {
                    total = in.read(buf);
                } catch (Exception e) {
                    e.printStackTrace();
                }
                if (total <= 0) return -1;
            }
            return buf[index++];
        }

        public int scanInt() {
            int integer = 0;
            int n = scan();
            while (isWhiteSpace(n)) n = scan();
            int neg = 1;
            if (n == '-') {
                neg = -1;
                n = scan();
            }
            while (!isWhiteSpace(n)) {
                if (n >= '0' && n <= '9') {
                    integer *= 10;
                    integer += n - '0';
                    n = scan();
                }
            }
            return neg * integer;
        }

        private boolean isWhiteSpace(int n) {
            if (n == ' ' || n == '\n' || n == '\r' || n == '\t' || n == -1) return true;
            else return false;
        }

        public void scanInt(int[] A, int size) {
            for (int i = 0; i < size; i++) A[i] = scanInt();
        }

    }
}

