        nx = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
            pr[i] = i - 1;
            nx[i] = i + 1;
        }

        Q = new ArrayList<>();
        used = new boolean[n];
        for (int i = 1; i <= n-2; i++) {
            try_add(i);
        }
        long ans = 0;

        while( !Q.isEmpty() ){
            int i = Q.get(Q.size()-1);
            Q.remove( Q.size() - 1 );
            nx[pr[i]] = nx[i];
            pr[nx[i]] = pr[i];
            ans += min( a[pr[i]], a[nx[i]] );
            try_add( pr[i] );
            try_add( nx[i] );
        }

        if( 3 <= n ){
            int i = nx[0];
            while( nx[i] != n ){
                ans += min( a[pr[i]], a[nx[i]] );
                i = nx[i];
            }
        }

        out.println( ans );
    }

