        if( used[i] )return;

        if( 1<=i && i <=n-2 && a[pr[i]] >= a[i] && a[i] <= a[nx[i]] ){
            Q.add( i );
            used[i] = true;
        }
    }


}

import java.io.PrintWriter;
import java.util.Scanner;

public class CF1384E extends PrintWriter {
	// https://codeforces.com/contest/1384/problem/E
	public Scanner sc = new Scanner(System.in);

	public CF1384E() {
		super(System.out);
	}

	public static void main(String[] args) {
		CF1384E o = new CF1384E();
		o.main();
		o.flush();
	}

	public static final int SZ = 20;
	public int[] ds = new int[SZ];

	public void main() {
		int t = sc.nextInt();
		while (t-- > 0) {
			int n = sc.nextInt();
			byte[] sa = sc.next().getBytes();
			byte[] sb = sc.next().getBytes();
			for (int id = 0; id < SZ; id++) {
				ds[id] = id;
			}
			int[] es = new int[SZ];
			for (int i = 0; i < n; i++) {
				if (sa[i] != sb[i]) {
					int u = sa[i] - 'a';
					int v = sb[i] - 'a';
					join(u, v);
					es[u] |= (1 << v);
				}
			}
			int ans = SZ * 2;
			for (int id = 0; id < SZ; id++) {
				if (ds[id] == id) {
					ans = ans - 1;
				}
			}
			boolean[] dags = new boolean[1 << SZ];
			dags[0] = true;
			int cnt_ = 0;
			for (int state = 1; state < (1 << SZ); state++) {
				int cnt = 0;
				for (int tmp = state; tmp > 0; tmp &= (tmp - 1)) {
					cnt++;
				}
				for (int id = 0; id < SZ; id++) {
					if ((state & (1 << id)) > 0) {
						int a = state ^ (1 << id);
						// chu y thu tu duyet cua cac bai toan
						if (dags[a]) {
							if ((a & es[id]) == 0) {
								dags[state] = true;
								cnt_ = Math.max(cnt_, cnt);
								break;
							}
						}
					}
				}
			}
			ans -= cnt_;
			println(ans);
		}
	}

	private void join(int u, int v) {
		u = find(u);
		v = find(v);
		if (u != v) {
			ds[u] = v;
		}

	}

	private int find(int u) {
		if (ds[u] == u) {
			return u;
		}
		ds[u] = find(ds[u]);
		return ds[u];
	}
}

