	public static void main(String[] $) {
		CF1384E o = new CF1384E(); o.main(); o.flush();
	}

	static final int A = 20;
	int[] ds = new int[A];
	int find(int i) {
		return ds[i] < 0 ? i : (ds[i] = find(ds[i]));
	}
	void join(int i, int j) {
		i = find(i);
		j = find(j);
		if (i == j)
			return;
		if (ds[i] > ds[j])
			ds[i] = j;
		else {
			if (ds[i] == ds[j])
				ds[i]--;
			ds[j] = i;
		}
	}
	void main() {
		int t = sc.nextInt();
		while (t-- > 0) {
			int n = sc.nextInt();
			byte[] sa = sc.next().getBytes();
			byte[] sb = sc.next().getBytes();
			Arrays.fill(ds, -1);
			int[] aa = new int[A];
			for (int i = 0; i < n; i++)
				if (sa[i] != sb[i]) {
					int u = sa[i] - 'a';
					int v = sb[i] - 'a';
					join(u, v);
					aa[u] |= 1 << v;
				}
			int ans = A * 2;
			for (int u = 0; u < A; u++)
				if (ds[u] < 0)
					ans--;
			boolean[] dag = new boolean[1 << A]; dag[0] = true;
			int cnt_ = 0;
			for (int a, b = 1; b < 1 << A; b++) {
				int cnt = 0;
				for (a = b; a > 0; a &= a - 1)
					cnt++;
				for (int u = 0; u < A; u++)
					if ((a = b ^ 1 << u) != b && dag[a] && (a & aa[u]) == 0) {
						dag[b] = true;
						cnt_ = Math.max(cnt_, cnt);
						break;
					}
			}
			ans -= cnt_;
			println(ans);
		}
	}
}

