public class C {

	static final int P = 1_000_000_007;

	static boolean nextPermutation(int[] a) {
		int n = a.length;
		int ptr = n - 1;
		while (ptr > 0 && a[ptr - 1] >= a[ptr]) {
			ptr--;
		}

		for (int i = ptr, j = n - 1; i < j; i++, j--) {
			int tmp = a[i];
			a[i] = a[j];
			a[j] = tmp;
		}

		if (ptr == 0) {
			return false;
		}

		for (int i = ptr;; i++) {
			if (a[ptr - 1] < a[i]) {
				int tmp = a[ptr - 1];
				a[ptr - 1] = a[i];
				a[i] = tmp;
				return true;
			}
		}
	}

	int slow(int n, int k) {
		int[] p = new int[n];
		for (int i = 0; i < n; i++) {
			p[i] = i;
		}
		int ans = 0;
		do {
			int m = 0;
			int offset = 0;
			for (int i = 0; i < n; ++i)
				if (m < p[i]) {
					m = p[i];
					offset = 0;
				} else {
					offset = offset + 1;
					if (offset == k)
						break;
				}
			ans += m == n - 1 ? 1 : 0;
		} while (nextPermutation(p));
		return ans;
	}

	void submit() {
		int n = nextInt();
		int k = nextInt();
		int[] a = new int[n + 1];
		a[0] = 1;
		for (int i = 1; i <= k && i <= n; i++) {
			a[i] = (int) ((long) (i + 1) * a[i - 1] % P);
		}

		if (n <= k) {
			out.println(0);
			return;
		}

		int mult = a[k - 1];

		for (int i = k + 1; i <= n; i++) {
			a[i] = (int) ((long) (i + 1) * a[i - 1] % P);
			a[i] -= (int) ((long) mult * a[i - k - 1] % P);
			if (a[i] < 0) {
				a[i] += P;
			}

			mult = (int) ((long) mult * i % P * inv(i - k) % P);
		}

		int fact = 1;
		for (int i = 1; i <= n; i++) {
			fact = (int) ((long) fact * i % P);
		}

		n--;

		fact -= a[n];
		if (fact < 0) {
			fact += P;
		}

		out.println(fact);
	}

	int inv(int x) {
		return x == 1 ? 1 : (P - (int) ((long) (P / x) * inv(P % x) % P));
	}

