        int n = nextInt();
        for (int i = 0; i < n; i++) {
            String s = nextString();
            s = s.split("'", 2)[1];
            System.out.println(check(s));;
        }
    }

    public String check(String s) {
        switch (s.length()) {
            case 1:
                if (s.equals("9")) {
                    return "1989";
                } else {
                    return "199" + s;
                }
            case 2:
                if (s.equals("99")) {
                    return "1999";
                } else {
                    return "20" + s;
                }
            case 3:
                String s1 = check(s.substring(2));
                String s2 = check(s.substring(1));
                for (int i = 1; i < 100; i++) {
                    String ans = i + s;
                    if (!ans.equals(s1) && !ans.equals(s2) && Integer.parseInt(ans) >= 1989) {
                        return ans;
                    }
                }
                break;
            default:

                ArrayList<String> list = new ArrayList<>();
                for (int i = 1; i < s.length(); i++) {
                    list.add(check(s.substring(i)));
                }
                if (!list.contains(s) && !s.startsWith("0") && Integer.parseInt(s) >= 1989) {
                    return s;
                }
                int i = 1;
                while (true) {
                    String ans = i++ + s;
                    if (!list.contains(ans)) {
                        return ans;
                    }
                }
        }
        return s;
    }

    //End !!!
    void run() throws Exception {
        is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
        out = new PrintWriter(System.out);
        long s = System.currentTimeMillis();
