    boolean isset(int x){

        x >>= 1;
        int ind = x >> 3;
        int sh = x & 7;
        return (bits[ind] & (1 << sh)) != 0;
    }

    void setbit(int x){
        x >>= 1;
        int ind = x >> 3;
        int sh = x & 7;
        bits[ind] |= (1 << sh);
    }
    void seive(){

