					int ti = g[i][j] - '1';
					treasure[ti] = new Point(i, j);
				} else if (g[i][j] == 'B') {
					boom[bi++] = new Point(i, j);
				}
			}
		for (int ti = 0; ti < t; ti++)
			value[ti] = in.nextInt();
		int[][][][] cost = new int[n][m][1 << t][1 << b];
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				for (int k = 0; k < (1 << t); k++) {
					for (int l = 0; l < (1 << b); l++) {
						cost[i][j][k][l] = 19930309;
					}
				}
			}
		}
		Queue<State> queue = new LinkedList<State>();
		State state = new State(start, 0, 0);
		cost[state.p.x][state.p.y][state.ts][state.bs] = 0;
		queue.add(state);
		while (!queue.isEmpty()) {
			state = queue.remove();
			final int[] dx = new int[] { 0, 0, 1, -1 };
			final int[] dy = new int[] { -1, 1, 0, 0 };
			for (int d = 0; d < 4; d++) {
				State nstate = new State(new Point(state.p.x + dx[d], state.p.y
						+ dy[d]), state.ts, state.bs);
				if (nstate.p.x >= 0 && nstate.p.x < n && nstate.p.y >= 0
						&& nstate.p.y < m
						&& !Character.isDigit(g[nstate.p.x][nstate.p.y])
						&& g[nstate.p.x][nstate.p.y] != '#'
						&& g[nstate.p.x][nstate.p.y] != 'B') {
					for (int i = 0; i < t; i++) {
						if (cross(treasure[i], state.p, nstate.p)) {
							nstate.ts ^= 1 << i;
						}
					}
					for (int i = 0; i < b; i++) {
						if (cross(boom[i], state.p, nstate.p)) {
							nstate.bs ^= 1 << i;
						}
					}
					if (cost[nstate.p.x][nstate.p.y][nstate.ts][nstate.bs] > cost[state.p.x][state.p.y][state.ts][state.bs] + 1) {
						cost[nstate.p.x][nstate.p.y][nstate.ts][nstate.bs] = cost[state.p.x][state.p.y][state.ts][state.bs] + 1;
						queue.add(nstate);
					}
				}
			}
		}
		int answer = 0;
		for (int ts = 0; ts < (1 << t); ts++) {
			int get = 0;
			for (int i = 0; i < t; i++)
				if ((ts & (1 << i)) != 0) {
					get += value[i];
				}
			get -= cost[start.x][start.y][ts][0];
			answer = Math.max(answer, get);
		}
		System.out.println(answer);
	}

	private static boolean cross(Point p, Point l1, Point l2) {
		return (l1.y > p.y) != (l2.y > p.y)
				&& p.x * (l2.y - l1.y) * (l2.y - l1.y) < (l2.x - l1.x)
						* (p.y - l1.y) * (l2.y - l1.y) + l1.x * (l2.y - l1.y)
						* (l2.y - l1.y);
	}
}

