public class Main {

	BufferedReader in;
	StringTokenizer str = null;
	PrintWriter out;

	private String next() throws Exception{
		if (str == null || !str.hasMoreElements())
			str = new StringTokenizer(in.readLine());
		return str.nextToken();
	}

	private int nextInt() throws Exception{
		return Integer.parseInt(next());
	}

	private long nextLong() throws Exception{
		return Long.parseLong(next());
	}

	private double nextDouble() throws Exception{
		return Double.parseDouble(next());
	}

	int dx[] = new int[]{1, 0, -1, 0};
	int dy[] = new int[]{0, -1, 0, 1};

	int n,m;
	char maze[][];
	int state[][];

	boolean used[][][];
	int d[][][];

	public void run() throws Exception{
		in =  new BufferedReader(new InputStreamReader(System.in));
		out = new PrintWriter(System.out);

		n = nextInt();
		m = nextInt();

		int sx = -1;
		int sy = -1;

		state = new int[n][m];

		int treasure = 0;
		maze = new char[n][m];
		for(int i=0;i<n;i++){
			maze[i] = next().toCharArray();
			for(int j=0;j<m;j++){
				if (maze[i][j] == 'S') {
					sx = i;
					sy = j;
					maze[i][j] = '.';
				}else if ('0' <= maze[i][j] && maze[i][j] <= '9') {
					int idx = maze[i][j] - '1';
					for(int k=j+1;k<m;k++){
						state[i][k]|=1<<idx;
					}
					treasure++;
				}
			}
		}

		int []a = new int[treasure];
		for(int i=0;i<treasure;i++) a[i] = nextInt();

		int sum[] = new int[1<<10];
		for(int i=0;i<1<<treasure;i++) {
			for(int j=0;j<treasure;j++) {
				if ((i & (1<<j)) > 0) {
					sum[i]+=a[j];
				}
			}
		}

		int bomb = treasure;
		for(int i=0;i<n;i++){
			for(int j=0;j<m;j++){
				if (maze[i][j] == 'B') {
					for(int k=j+1;k<m;k++){
						state[i][k]|=1<<bomb;
					}
					bomb++;
				}
			}
		}

		used = new boolean[n][m][1<<bomb];
		d = new int[n][m][1<<bomb];

		bfs(sx, sy);
		int ans = 0;
		for(int i=0;i<1<<treasure;i++){
			if (used[sx][sy][i]) {
				ans = Math.max(ans, sum[i] - d[sx][sy][i]);
			}
		}

		out.println(ans);
		out.close();
	}

	Queue<int[]> q;

	private void bfs(int sx, int sy) {
		q = new LinkedList<int[]>();
		q.add(new int[]{sx, sy, 0});
		used[sx][sy][0] = true;
		d[sx][sy][0] = 0;

		while(q.size() > 0){
			int cur[] = q.poll();
			int x = cur[0], y = cur[1], nst = cur[2];

			for(int i=0;i<4;i++){
				int nx = x + dx[i], ny = y + dy[i], nstate = nst;
				if (!can(nx, ny)) continue;
				if (dx[i] == 1) {
					nstate^=state[nx][ny];
				}else if (dx[i] == -1) {
					nstate^=state[x][y];
				}

				if (used[nx][ny][nstate]) continue;
				used[nx][ny][nstate] = true;
				d[nx][ny][nstate] = d[x][y][nst] + 1;
				q.add(new int[]{nx, ny, nstate});
			}
		}
	}

	private boolean can(int x, int y) {
		if (x < 0 || y < 0) return false;
		if (x >=n || y >= m) return false;
		if (maze[x][y] != '.') return false;
		return true;
	}

	public static void main(String[] args) throws Exception{
		new Main().run();
	}
}

