class Solver {
    BufferedReader in;
    StringTokenizer tok;

    public void solve() throws IOException {
        in = new BufferedReader(new InputStreamReader(System.in));

        int n = nextInt();
        int m = nextInt();
        String[] st = new String[n];
        int tr = 0, bomb = 0, sx = 0, sy = 0;
        int[] tx = new int [10];
        int[] ty = new int [10];
        int[] bx = new int [10];
        int[] by = new int [10];
        for(int i = 0; i < n; ++i) {
            st[i] = next();
            for(int j = 0; j < m; ++j) {
                char ch = st[i].charAt(j);
                if (ch >= '0' && ch <= '9') {
                    tx[ch - '0' - 1] = i;
                    ty[ch - '0' - 1] = j;
                    ++tr;
                }
                if (ch == 'B') {
                    bx[bomb] = i;
                    by[bomb] = j;
                    ++bomb;
                }
                if (ch == 'S') {
                    sx = i;
                    sy = j;
                }
            }
        }
        int[] cost = new int [tr];
        for(int i = 0; i < tr; ++i) {
            cost[i] = nextInt();
        }
        final int INF = Integer.MAX_VALUE;
        int[][][][] dist = new int [n][m][1 << tr][1 << bomb];
        for(int i = 0; i < n; ++i) {
            for(int j = 0; j < m; ++j) {
                for(int t = 0; t < 1 << tr; ++t) {
                    for(int b = 0; b < 1 << bomb; ++b) {
                        dist[i][j][t][b] = INF;
                    }
                }
            }
        }
        dist[sx][sy][0][0] = 0;
        int[] Q = new int[20 * 20 * (1 << tr) * (1 << bomb) * 4];
        int l = 0,r = 0;
        Q[r++] = sx;
        Q[r++] = sy;
        Q[r++] = 0;
        Q[r++] = 0;

        final int[] dx = {1, 0, -1, 0};
        final int[] dy = {0, 1, 0, -1};

        while(l < r) {
            int x = Q[l++];
            int y = Q[l++];
            int t = Q[l++];
            int b = Q[l++];


            for(int d = 0; d < 4; ++d) {
                int nx = x + dx[d];
                int ny = y + dy[d];
                if (nx < 0 || ny < 0 || nx >= n || ny >= m) {
                    continue;
                }
                if (st[nx].charAt(ny) == '.' || st[nx].charAt(ny) == 'S') {
                    int nt = t;
                    int nb = b;
                    for(int i = 0; i < tr; ++i) {
                        if (intersects(tx[i], ty[i], x, y, nx, ny)) {
                            nt ^= (1 << i);
                        }
                    }
                    for(int i = 0; i < bomb; ++i) {
                        if (intersects(bx[i], by[i], x, y, nx, ny)) {
                            nb ^= (1 << i);
                        }
                    }
                    if (dist[nx][ny][nt][nb] == INF) {
                        dist[nx][ny][nt][nb] = dist[x][y][t][b] + 1;
                        Q[r++] = nx;
                        Q[r++] = ny;
                        Q[r++] = nt;
                        Q[r++] = nb;
                    }
                }
            }
        }

        int ans = 0;

        for(int t = 0; t < 1 << tr; ++t) {
            int d = dist[sx][sy][t][0];
            if (d == INF) {
                continue;
            }
            int cur = 0;
            for(int j = 0; j < tr; ++j) {
                if (((t >> j) & 1) == 1) {
                    cur += cost[j];
                }
            }
            ans = Math.max(ans, cur - d);
        }

        System.out.println(ans);
    }

    final double eps = 1e-7;

    boolean intersects(int sx, int sy, int ax, int ay, int bx, int by) {
        // (42, 43) ray from (sx, sy)

        int a1 = 43;
        int b1 = -42;
        int c1 = (sx + 42) * sy - sx * (sy + 43);

        int a2 = by - ay;
        int b2 = ax - bx;
        int c2 = bx * ay - ax * by;

        double det = a1 * b2 - a2 * b1;
        double detx = b1 * c2 - b2 * c1;
        double dety = a2 * c1 - c2 * a1;
        detx /= det;
        dety /= det;
        return detx > Math.min(ax, bx) - eps && detx < Math.max(ax, bx) + eps
                && dety > Math.min(ay, by) - eps && dety < Math.max(ay, by) + eps
                && detx > sx;
    }

    String next() throws IOException {
        if (tok == null || !tok.hasMoreTokens()) {
            tok = new StringTokenizer(in.readLine());
        }
        return tok.nextToken();
    }

    int nextInt() throws IOException {
        return parseInt(next());
    }

    long nextLong() throws IOException {
        return parseLong(next());
    }

    double nextDouble() throws IOException {
        return parseDouble(next());
    }
}

