import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.*;

public class C {
    BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
    PrintWriter writer = new PrintWriter(System.out);
    StringTokenizer stringTokenizer;

    String next() throws IOException {
        while (stringTokenizer == null || !stringTokenizer.hasMoreTokens()) {
            stringTokenizer = new StringTokenizer(reader.readLine());
        }
        return stringTokenizer.nextToken();
    }

    int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    long nextLong() throws IOException {
        return Long.parseLong(next());
    }

    void solve() throws IOException {
        int n = nextInt();
        int m = nextInt();
        char[][] map = new char[n][];
        int bombs = 0;
        int treasures = 0;
        for (int i = 0; i < n; i++) {
            map[i] = next().toCharArray();
            for (int j = 0; j < m; j++) {
                if (map[i][j] == 'B') bombs++;
                if (map[i][j] >= '0' && map[i][j] <= '9') {
                    treasures++;
                    map[i][j]--;
                }
            }
        }
        int[] treasureCosts = new int[treasures];
        for (int i = 0; i < treasures; i++) {
            treasureCosts[i] = nextInt();
        }
        class Point {
            int x, y;

            Point(int x, int y) {
                this.x = x;
                this.y = y;
            }

            Point subtract(Point other) {
                return new Point(x - other.x, y - other.y);
            }

            int vectorProduct(Point other) {
                return x * other.y - y * other.x;
            }

            Point add(Point other) {
                return new Point(x + other.x, y + other.y);
            }
        }
        class GeomUtils {
            Point cellCenter(int row, int column) {
                return new Point(2 * row + 1, 2 * column + 1);
            }

            Point ray = new Point(40, 41);

            double getT(Point o, Point v, Point s1, Point s2) {
                Point vs = s2.subtract(s1);
                int r = vs.vectorProduct(s2) - vs.vectorProduct(o);
                int l = vs.vectorProduct(v);
                return 1.0 * r / l;
            }

            boolean intersects(Point o, Point s1, Point s2) {
                if (getT(o, ray, s1, s2) < 0.0) return false;
                double t = getT(s1, s2.subtract(s1), o, o.add(ray));
                return t >= 0.0 && t <= 1.0;
            }
        }
        Point[] treasureCoords = new Point[treasures];
        Point[] bombCoords = new Point[bombs];
        bombs = 0;
        int si = 0, sj = 0;
        GeomUtils geomUtils = new GeomUtils();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (map[i][j] == 'B') {
                    bombCoords[bombs++] = geomUtils.cellCenter(i, j);
                }
                if (map[i][j] >= '0' && map[i][j] <= '9') {
                    treasureCoords[map[i][j] - '0'] = geomUtils.cellCenter(i, j);
                }
                if (map[i][j] == 'S') {
                    si = i;
                    sj = j;
                }
            }
        }
        int[][][][] dist = new int[n][m][1 << treasures][1 << bombs];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
                for (int k = 0; k < 1 << treasures; k++)
                    for (int l = 0; l < 1 << bombs; l++) dist[i][j][k][l] = Integer.MAX_VALUE;
        dist[si][sj][0][0] = 0;
        Queue<Integer> qi = new LinkedList<>(), qj = new LinkedList<>(), qt = new LinkedList<>(), qb = new LinkedList<>();
        qi.add(si);
        qj.add(sj);
        qt.add(0);
        qb.add(0);
        int[] di = {0, -1, 0, 1};
        int[] dj = {-1, 0, 1, 0};
        while (!qi.isEmpty()) {
            int i = qi.poll();
            int j = qj.poll();
            int tmask = qt.poll();
            int bmask = qb.poll();
            Point s1 = geomUtils.cellCenter(i, j);
            for (int k = 0; k < 4; k++) {
                int ii = i + di[k];
                int jj = j + dj[k];
                if (ii < 0 || ii >= n || jj < 0 || jj >= m || map[ii][jj] != '.' && map[ii][jj] != 'S') continue;
                int tm = 0;
                for (int ti = 0; ti < treasures; ti++) {
                    if (geomUtils.intersects(treasureCoords[ti], s1, geomUtils.cellCenter(ii, jj))) {
                        tm |= 1 << ti;
                    }
                }
                int bm = 0;
                for (int bi = 0; bi < bombs; bi++) {
                    if (geomUtils.intersects(bombCoords[bi], s1, geomUtils.cellCenter(ii, jj))) {
                        bm |= 1 << bi;
                    }
                }
                if (dist[ii][jj][tmask ^ tm][bmask ^ bm] == Integer.MAX_VALUE) {
                    dist[ii][jj][tmask ^ tm][bmask ^ bm] = dist[i][j][tmask][bmask] + 1;
                    qi.add(ii);
                    qj.add(jj);
                    qt.add(tmask ^ tm);
                    qb.add(bmask ^ bm);
                }
            }
        }
        int ans = 0;
        for (int i = 0; i < 1 << treasures; i++) {
            if(dist[si][sj][i][0] == Integer.MAX_VALUE) continue;
            int tCost = 0;
            for (int j = 0; j < treasures; j++) {
                if (((i >> j) & 1) == 1) tCost += treasureCosts[j];
            }
            ans = Math.max(ans, tCost - dist[si][sj][i][0]);
        }
        writer.println(ans);
        writer.close();
    }

    public static void main(String[] args) throws IOException {
        new C().solve();
    }
}

