public class Main implements Runnable {

	public void _main() throws IOException {
		final int infinity = 1000000000;
		// A ray that is not collinear with any of the (dx, dy)`s
		final int RAY_R = 31;
		final int RAY_C = 37;
		int height = nextInt();
		int width = nextInt();
		char[][] s = new char[height][];
		int sr = -1;
		int sc = -1;
		int numTreasures = 0;
		int numBombs = 0;
		int[][] treasureId = new int[height][width];
		int[][] bombId = new int[height][width];		
		for (int r = 0; r < height; r++) {
			s[r] = next().toCharArray();
			for (int c = 0; c < width; c++) {
				if (s[r][c] == 'S') {
					sr = r;
					sc = c;
					s[r][c] = '.';
				}
				treasureId[r][c] = -1;
				if (Character.isDigit(s[r][c])) {
					treasureId[r][c] = s[r][c] - '1';
					++numTreasures;
				}
				bombId[r][c] = -1;
				if (s[r][c] == 'B') {
					bombId[r][c] = numBombs;
					++numBombs;
				}
			}
		}
		int[] treasureR = new int[numTreasures];
		int[] treasureC = new int[numTreasures];
		int[] bombR = new int[numBombs];
		int[] bombC = new int[numBombs];
		for (int r = 0; r < height; r++) {
			for (int c = 0; c < width; c++) {
				if (treasureId[r][c] >= 0) {
					int id = treasureId[r][c];
					treasureR[id] = r;
					treasureC[id] = c;
				}
				if (bombId[r][c] >= 0) {
					int id = bombId[r][c];
					bombR[id] = r;
					bombC[id] = c;
				}
			}
		}
		int[] cost = new int[numTreasures];
		for (int i = 0; i < numTreasures; i++) {
			cost[i] = nextInt();
		}
		int[] value = new int[1 << (numTreasures + numBombs)];
		for (int i = 1; i < value.length; i++) {
			int j = Integer.numberOfTrailingZeros(i);
			if (j < numTreasures) {
				value[i] = cost[j] + value[i ^ (1 << j)];
			} else {
				value[i] = -infinity;
			}
		}
		int qsize = height * width * (1 << (numTreasures + numBombs));
		int[] qr = new int[qsize];
		int[] qc = new int[qsize];
		int[] qmask = new int[qsize];
		int[][][] dist = new int[height][width][1 << (numTreasures + numBombs)];
		for (int r = 0; r < height; r++) {
			for (int c = 0; c < width; c++) {
				Arrays.fill(dist[r][c], infinity);
			}
		}
		dist[sr][sc][0] = 0;
		qr[0] = sr;
		qc[0] = sc;
		qmask[0] = 0;
		int qt = 0;
		int qh = 1;
		int ans = 0;
		while (qt < qh) {
			int r = qr[qt];
			int c = qc[qt];
			int mask = qmask[qt];
			++qt;
			if (r == sr && c == sc) {
				ans = Math.max(ans, value[mask] - dist[r][c][mask]);
			}
			for (int dr = -1; dr <= 1; dr++) {
				for (int dc = -1; dc <= 1; dc++) {
					if (dr == 0 ^ dc == 0) {
						int nr = r + dr;
						int nc = c + dc;
						if (nr < 0 || nr >= height || nc < 0 || nc >= width) continue;
						if (s[nr][nc] != '.') continue;
						int nmask = mask;
						for (int i = 0; i < numTreasures + numBombs; i++) {
							int or, oc;
							if (i < numTreasures) {
								or = treasureR[i];
								oc = treasureC[i];
							} else {
								or = bombR[i - numTreasures];
								oc = bombC[i - numTreasures];
							}
							int r1 = r - or;
							int c1 = c - oc;
							int r2 = nr - or;
							int c2 = nc - oc;
							if (r1 < 0 || r2 < 0 || c1 < 0 || c2 < 0) continue;
							if (Integer.signum(cross(r1, c1, RAY_R, RAY_C)) == Integer.signum(cross(RAY_R, RAY_C, r2, c2))) {
								nmask ^= 1 << i;
							}
						}
						if (dist[nr][nc][nmask] > 1 + dist[r][c][mask]) {
							dist[nr][nc][nmask] = 1 + dist[r][c][mask];
							qr[qh] = nr;
							qc[qh] = nc;
							qmask[qh] = nmask;
							++qh;
						}
					}
				}
			}
		}
		out.println(ans);
	}

	private int cross(int x1, int y1, int x2, int y2) {
		return x1*y2 - x2*y1;
	}


