            mem = new int[2][n + 1][n + 1];
            visit = new boolean[2][n + 1][n + 1];
            int meetCount = find(n, n, 1);

            int factorial = 1;
            for (int i = 2, until = 2 * n + 1; i <= until; i++) {
                factorial = mul(factorial, i);
            }
            int total = mul(factorial, Mathematics.inverse(Mathematics.pow(2, n, mod), mod));
            int probability = mul(meetCount, Mathematics.inverse(total, mod));
            int expectLength = mul(l, probability);
