        public int find(int i, int j, int x) {
            time++;
            if (i < 0 || i > n || j < 0 || j > n) {
                return 0;
            }
            if (i == 0 && j == 0 && x == 0) {
                return 1;
            }
            if (visit[x][i][j]) {
                return mem[x][i][j];
            }
            visit[x][i][j] = true;
            mem[x][i][j] = 0;
            if (i < j) {
