import java.io.*;
import java.util.*;

import static java.lang.Math.*;

public class CF1447F1 {
    public static void main(String[] args) throws Exception {
        Scanner in = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        int n = in.nextInt();
        int[] arr = new int[n + 1];
        int[] freq = new int[101];
        int mostFreq = 0;
        for (int i = 1; i <= n; i++) {
            arr[i] = in.nextInt();
            freq[arr[i]]++;
            if (freq[arr[i]] > freq[mostFreq]) {
                mostFreq = arr[i];
            }
        }

        int res = 0;
        for (int i = 1; i <= 100; i++) {
            if (i != mostFreq) {
                int tmp = maxSumArrayWithZeroSum(n, mostFreq, i, arr);
                res = max(res, tmp);
            }
        }

        pw.println(res);
        pw.close();
    }

    static int maxSumArrayWithZeroSum(int n, int x, int y, int[] arr) {
        int offset = n + 5;
        int[] idx = new int[offset + offset + 10];
        int invalid = -n - n - n;
        Arrays.fill(idx, invalid);
        int sum = 0, res = 0;
        idx[offset + sum] = 0;
        for (int i = 1; i <= n; i++) {
            if (arr[i] == x) sum++;
            else if (arr[i] == y) sum--;
            if (idx[offset + sum] != invalid) res = max(res, i - idx[offset + sum]);
            else idx[offset + sum] = i;
        }
        return res;
    }

    static void debug(Object... obj) {
        System.err.println(Arrays.deepToString(obj));
    }
}

