    static class SequenceUtils {
        public static void swap(int[] data, int i, int j) {
            int tmp = data[i];
            data[i] = data[j];
            data[j] = tmp;
        }

        public static void reverse(int[] data, int l, int r) {
            while (l < r) {
                swap(data, l, r);
                l++;
                r--;
            }
        }

        public static void reverse(int[] data) {
            reverse(data, 0, data.length - 1);
        }

    }

    static class FastInput {
        private final InputStream is;
        private byte[] buf = new byte[1 << 13];
        private int bufLen;
        private int bufOffset;
        private int next;

        public FastInput(InputStream is) {
            this.is = is;
        }

        public void populate(int[] data) {
            for (int i = 0; i < data.length; i++) {
                data[i] = readInt();
            }
        }

        private int read() {
            while (bufLen == bufOffset) {
                bufOffset = 0;
                try {
                    bufLen = is.read(buf);
                } catch (IOException e) {
                    bufLen = -1;
                }
                if (bufLen == -1) {
                    return -1;
                }
            }
            return buf[bufOffset++];
        }

        public void skipBlank() {
            while (next >= 0 && next <= 32) {
                next = read();
            }
        }

        public int readInt() {
            int sign = 1;

            skipBlank();
            if (next == '+' || next == '-') {
                sign = next == '+' ? 1 : -1;
                next = read();
            }

            int val = 0;
            if (sign == 1) {
                while (next >= '0' && next <= '9') {
                    val = val * 10 + next - '0';
                    next = read();
                }
            } else {
                while (next >= '0' && next <= '9') {
                    val = val * 10 - next + '0';
                    next = read();
                }
            }

            return val;
        }

    }

    static interface IntegerIterator {
        boolean hasNext();

        int next();

    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.NoSuchElementException;

public class C {

  private void solve(FastScanner in, PrintWriter out) {
    int MAX = 50;

    // count[i] := 2^i の数
    int[] count = new int[MAX + 1];

    // garbage[i] := 2^(i+1) 以下の garbage の数
    int[] garbage = new int[MAX + 1];

    int N = in.nextInt();
    for (int i = 0; i < N; i++) {
      long z = in.nextLong();
      if (Long.bitCount(z) == 1) {
        //2べきのものはカウントする
        count[Long.numberOfTrailingZeros(z)]++;
      } else {
        long floor = Long.highestOneBit(z);
        garbage[Long.numberOfTrailingZeros(floor)]++;
      }
    }

    for (int bit = 0; bit < MAX; bit++) {
      if (count[bit] < count[bit + 1]) {
        garbage[bit] += count[bit + 1] - count[bit];
        count[bit + 1] = count[bit];
      }
    }

    ArrayList<Integer> answers = new ArrayList<>();
    for (int ans = 1; ans <= N; ans++) {
      if (count[0] < ans) {
        continue;
      }

      int currentGarbage = 0;
      for (int bit = 0; bit < MAX; bit++) {
        //今建っている整数
        int now = Math.min(count[bit], ans);
        //まだ高さがある整数
        int next = Math.min(count[bit + 1], ans);

        // ここで garbageを吸着できる整数
        int catching = now - next;

        //新たに生まれた garbage
        int newGarbage = Math.max(0, count[bit] - ans);

        currentGarbage += garbage[bit] + newGarbage - catching;
        if (currentGarbage < 0) {
          currentGarbage = 0;
        }
      }

      if (currentGarbage == 0) {
        answers.add(ans);
      }
    }

    if (answers.isEmpty()) {
      out.println(-1);
      return;
    }
    for (int a : answers) {
      out.print(a + " ");
    }
    out.println();
  }

  public static void main(String[] args) {
    PrintWriter out = new PrintWriter(System.out);
    new C().solve(new FastScanner(), out);
    out.close();
  }

  private static class FastScanner {

    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int bufferLength = 0;

    private boolean hasNextByte() {
      if (ptr < bufferLength) {
        return true;
      } else {
        ptr = 0;
        try {
          bufferLength = in.read(buffer);
        } catch (IOException e) {
          e.printStackTrace();
        }
        if (bufferLength <= 0) {
          return false;
        }
      }
      return true;
    }

    private int readByte() {
      if (hasNextByte()) {
        return buffer[ptr++];
      } else {
        return -1;
      }
    }

    private static boolean isPrintableChar(int c) {
      return 33 <= c && c <= 126;
    }

    private void skipUnprintable() {
      while (hasNextByte() && !isPrintableChar(buffer[ptr])) {
        ptr++;
      }
    }

    boolean hasNext() {
      skipUnprintable();
      return hasNextByte();
    }

    public String next() {
      if (!hasNext()) {
        throw new NoSuchElementException();
      }
      StringBuilder sb = new StringBuilder();
      int b = readByte();
      while (isPrintableChar(b)) {
        sb.appendCodePoint(b);
        b = readByte();
      }
      return sb.toString();
    }

    long nextLong() {
      if (!hasNext()) {
        throw new NoSuchElementException();
      }
      long n = 0;
      boolean minus = false;
      int b = readByte();
      if (b == '-') {
        minus = true;
        b = readByte();
      }
      if (b < '0' || '9' < b) {
        throw new NumberFormatException();
      }
      while (true) {
        if ('0' <= b && b <= '9') {
          n *= 10;
          n += b - '0';
        } else if (b == -1 || !isPrintableChar(b)) {
          return minus ? -n : n;
        } else {
          throw new NumberFormatException();
        }
        b = readByte();
      }
    }

    double nextDouble() {
      return Double.parseDouble(next());
    }

    double[] nextDoubleArray(int n) {
      double[] array = new double[n];
      for (int i = 0; i < n; i++) {
        array[i] = nextDouble();
      }
      return array;
    }

    double[][] nextDoubleMap(int n, int m) {
      double[][] map = new double[n][];
      for (int i = 0; i < n; i++) {
        map[i] = nextDoubleArray(m);
      }
      return map;
    }

    public int nextInt() {
      return (int) nextLong();
    }

    public int[] nextIntArray(int n) {
      int[] array = new int[n];
      for (int i = 0; i < n; i++) {
        array[i] = nextInt();
      }
      return array;
    }

    public long[] nextLongArray(int n) {
      long[] array = new long[n];
      for (int i = 0; i < n; i++) {
        array[i] = nextLong();
      }
      return array;
    }

    public String[] nextStringArray(int n) {
      String[] array = new String[n];
      for (int i = 0; i < n; i++) {
        array[i] = next();
      }
      return array;
    }

    public char[][] nextCharMap(int n) {
      char[][] array = new char[n][];
      for (int i = 0; i < n; i++) {
        array[i] = next().toCharArray();
      }
      return array;
    }

    public int[][] nextIntMap(int n, int m) {
      int[][] map = new int[n][];
      for (int i = 0; i < n; i++) {
        map[i] = nextIntArray(m);
      }
      return map;
    }
  }
}

import java.util.*;
import java.io.*;

public class C {
  FastScanner in;
  PrintWriter out;

  public void solve() throws IOException {
    int[] powCnt = new int[63];
    int[] other = new int[63];
    long[] pows = new long[63];
    pows[0] = 1L;
    for (int i = 1; i < 63; i++) {
      pows[i] = pows[i - 1] * 2;
    }

    int n = in.nextInt();
    long[] a = new long[n];

    for (int i = 0; i < n; i++) {
      a[i] = in.nextLong();
      boolean isPow = false;
      for (int j = 0; j < 63; j++) {
        if (a[i] == pows[j]) {
          powCnt[j]++;
          isPow = true;
        }
        if (!isPow && j != 0 && a[i] > pows[j - 1] && a[i] < pows[j]) {
          other[j]++;
        }
      }
    }

    int min = Arrays.stream(other).sum();
    int max = powCnt[0];
    boolean exists = false;
    for (int len = min; len <= max; len++) {
      int tails = 0;
      int cur = len;
      for (int i = 0; i < 62; i++) {
        int oldCur = cur;
        if (powCnt[i] < cur) {
          cur = powCnt[i];
        }
        int ended = oldCur - cur;
        if (tails < ended) {
          tails = 0;
        } else {
          tails -= ended;
        }
        tails += powCnt[i] - cur;
        tails += other[i + 1];
      }
      if (tails == 0) {
        out.print(len + " ");
        exists = true;
      }
    }
    if (!exists) {
      out.println(-1);
    } else {
      out.println();
    }
  }

  public void run() {
    try {
      in = new FastScanner(System.in);
      out = new PrintWriter(System.out);
      solve();

      out.close();
    } catch (IOException e) {
      e.printStackTrace();
    }
  }

  class FastScanner {
    BufferedReader br;
    StringTokenizer st;

    FastScanner(InputStream is) {
      br = new BufferedReader(new InputStreamReader(is));
    }

    String next() {
      while (st == null || !st.hasMoreTokens()) {
        try {
          st = new StringTokenizer(br.readLine());
        } catch (IOException e) {
          e.printStackTrace();
        }
      }
      return st.nextToken();
    }

    int nextInt() {
      return Integer.parseInt(next());
    }

    long nextLong() {
      return Long.parseLong(next());
    }
  }

  public static void main(String[] arg) {
    new C().run();
  }
}

