public class Main {

    public static void main(String[] args) throws IOException {

        Scanner sc = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = sc .nextInt();
        long[] a = new long[n];
        for(int i = 0; i < n; ++i)
            a[i] = sc.nextLong();
        ArrayList<Long> b = new ArrayList<>();
        ArrayList<Long> c = new ArrayList<>();
        ArrayList<Integer> d = new ArrayList<>();
        int idx = 0;
        long curPower = 1;
        boolean possible = true;
        for(long x: a)
            if (x == 1) {
                b.add(1l);
                d.add(1);
            } else if ((x & x - 1) == 0) {
                if (x != curPower) {
                    if (curPower * 2 != x) {
                        possible = false;
                        break;
                    }
                    curPower = x;
                    idx = 0;
                }
                if (idx < b.size() && b.get(idx) * 2 == x) {
                    b.set(idx, x);
                    d.set(idx, d.get(idx) + 1);
                    ++idx;
                }
                else
                    c.add(x);
            } else {
                c.add(x);
            }
        int open = b.size();
        possible &= b.size() >= c.size();
        if(possible) for(int i = c.size() - 1, j = 0; i >= 0; --i, ++j) {
            if(c.get(i) <= 2 * b.get(j)) --open;
            else {
                possible = false;
                break;
            }
        }
        ArrayList<Integer> ans = new ArrayList<>();
        if (possible) {
            ans.add(b.size());
            int free = 0;
            for(int i = b.size() - 1; i >= 0; --i) {
                open--;
                free += d.get(i);
                if (open >= free)
                    ans.add(i);
                else
                    break;
            }
            Collections.reverse(ans);
            for(int x: ans)
                out.print(x + " ");
        } else {
            out.println(-1);
        }
        out.close();
    }

