class matrix{
    int [] [] A;
    int n;
    public matrix(int dim){
        A = new int[dim][dim];
        n = dim;
    }
    public void makeEye(){
        for (int i = 0;i < n;i++)
            for (int j = 0;j < n;j++)
                A[i][j] = (i == j) ? 1 : 0;
    }
    public matrix mul(matrix O) {
        matrix C = new matrix(n);
        for (int i = 0;i < n;i++)
            for (int j = 0;j < n;j++)
                for (int k = 0;k < n;k++)
                    C.A[i][j] = Main.add(C.A[i][j],Main.mul(A[i][k],O.A[k][j]));
        return C;
    }
    public int [] [] exp(long p) {
        matrix B = new matrix(n);
        matrix C = new matrix(n);
        C.makeEye();
        for (int i = 0;i < n;i++)
            for (int j = 0;j < n;j++)
                B.A[i][j] = A[i][j];

        if (p == 0) {
            B.makeEye();
            return B.A;
        }
        for (;p > 1;p >>= 1) {
            if (p%2 == 1) C = C.mul(B);
            B = B.mul(B);
        }
        return B.mul(C).A;
    }
}

