	final int RADIX = 10;
	private long solve2(int[] u, int[] v, int n) {
		
		// 50000*2^10 = 5*10^7 = 50*10^6 = 100MB
		// why exceed?
		// dp[i][set] = # representatives in a[n-i..n-1] where elements in the set can move forward
		// long[][] dp = new long[n][1<<RADIX];
		long[] dp = new long[1<<RADIX];
		
		for(int j=0; j<RADIX; j++) {
			dp[1<<j] = 1;
		}
		
		int[][] cmp = new int[RADIX][RADIX];
		int m = u.length;
		for(int i=0; i<m; i++) {
			int small = Math.min(u[i], v[i]);
			int larger = Math.max(u[i], v[i]);
			cmp[small][larger] = -1;
			cmp[larger][small] = 1;
		}
		
		boolean[][] isValid = new boolean[1<<RADIX][RADIX];
		int[][] map = new int[1<<RADIX][RADIX];
		
		for(int mask=0; mask< 1<<RADIX; mask++) {
			for(int j=0; j<RADIX; j++) {
				boolean ok = true;
				int next = 1<<j;
				for(int k=0; k<RADIX; k++) {
					if( (1<<k & mask) == 0)
						continue;
					// k can come forward
					// case 1: j is incomparable to k
					// -> remove k from the set
					if(cmp[j][k] == 0) {
					}
					// case 2: j, k can be swapped and j is smaller
					else if(cmp[j][k] == -1) {
						next |= 1<<k;
					}
					// case 3: j, k can be swapped and j is larger -> not a representative
					else {
						ok = false;
					}
				}
				isValid[mask][j] = ok;
				map[mask][j] = next;
			}
		}
		
		// n*2^RADIX*RADIX = 5*10^4*10^3*10 = 5*10^8
		for(int i=n-2; i>=0; i--) {
			long[] next = new long[1<<RADIX];
			for(int mask=0; mask < 1<<RADIX; mask++) {
				for(int j=0; j<RADIX; j++) {
					if(!isValid[mask][j])
						continue;
					int mask2 = map[mask][j];
					long val = next[mask2] + dp[mask];
					next[mask2] = val < MOD? val: val-MOD;
				}
			}
			dp = next;
		}
		
		long sum = 0;
		for(int mask=0; mask < 1<<RADIX; mask++)
			sum += dp[mask]; // < Integer.MAX_VALUE * 10^3
		return sum%MOD;
	}
	
	
	private long solve(int[] u, int[] v, int n) {
		int m = u.length;
		// S = [0, 10^n]
		// find # of equivalance classes S/~
		// base: swap uj and vj if they are adjacent digits
		
		// 10^n
		// (0, 1)
		
		// num[i] = # nums ending in i
		long[] num = new long[RADIX];
		for(int i=0; i<RADIX; i++)
			num[i] = 1;
		
		// multipliers[i][j] = contributions from num[i] when j is appended
		long[][] multipliers = new long[RADIX][RADIX];
		for(int i=0; i<RADIX; i++) {
			for(int j=0; j<RADIX; j++) {
				multipliers[i][j] = 1;
			}
		}
		
		for(int i=0; i<m; i++) {
			int min = Math.min(u[i], v[i]);
			int max = Math.max(u[i], v[i]);
			multipliers[max][min] = 0;
		}
		
		// xxxx0 + 1 -> xxxx01 * (1/2) + xxxx10 * (1/2)
		// yyyy1
		
		// (1/2) + (1/2) = 1
		// 2* + 2* = 1
		
		// string made of (0, 1)
		// -> different iff it has diff # of 0 or diff # of 1
		
		// (0, 1) (1, 2)
		// 0000000022222222
		// 0 and 2 can't swap
		// 021
		
		// xxxx0 + 0 -> k
		// xxxx0 + 1 -> k
		
		// xxxx1 + 0 -> X
		// 
		
		int temp  =1;
		
		for(int i=1; i<n; i++) {
			long[] num2 = new long[RADIX];
			for(int j=0; j<RADIX; j++) {
				for(int k=0; k<RADIX; k++) {
					num2[j] += num[k]*multipliers[j][k] % MOD;
				}
				num2[j] %= MOD;
			}
			num = num2;
		}
		
		long sum = 0;
		for(int i=0; i<RADIX; i++)
			sum += num[i];
		
		return sum%MOD;
	}
	
	static long pow(int a, int k, long p) {
		long m = k;
		long ans = 1;

		// curr = k^(2^i)
		long curr = a;

		// k^(2x+1) = (k^x)^2 * k
		while(m > 0) {
			if( (m&1) == 1 ) {
				ans *= curr;
				ans %= p;
			}
			m >>= 1;
			curr *= curr;
			curr %= p;
		}
		return ans;		
	}

	// computes a^(p-2)
	static long inverse(int a, long p) {
		return pow(a, (int)(p-2), p);
	}
	
