public class E {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int m = sc.nextInt();
		int k = sc.nextInt();
		int[][]a = new int[n][n];
		int[][]dp = new int[1 << n][1 << n];
		for (int i = 1; i <= m; i++) {
			int v1 = sc.nextInt();
			int v2 = sc.nextInt();
			v1--;
			v2--;
			a[v1][v2] = a[v2][v1] = 1;
			dp[(1 << v1) | (1 << v2)][(1 << v1) | (1 << v2)] = 1;
		}
		for (int mask = 0; mask < (1 << n); mask++) {
			for (int subm = mask; subm != 0; subm = ((subm-1) & mask)) {
				if (dp[mask][subm]==0)
					continue;
				for (int i = 0; i < n; i++) {
					if ((mask & (1 << i)) != 0) {
						for (int j = 0; j < n; j++) {
							if ((mask & (1 << j))==0 && a[i][j]==1) {
								int new_subm = (subm | (1 << j));
								if ((subm & (1 << i)) != 0)
									new_subm ^= (1 << i);
								int q = (1 << n)-(1 << (j+1));
								if ((new_subm & q) != 0)
										continue;
								dp[mask | (1 << j)][new_subm] += dp[mask][subm];
							}
						}
					}
				}
			}
		}
		int ans = 0;
		for (int mask = 0; mask < (1 << n); mask++) {
			if (Integer.bitCount(mask)==k)
				ans += dp[(1 << n)-1][mask];
		}
		System.out.println(ans);
	}

}

import java.util.*;

public class E {
	public static void main(String[] args) {
		Scanner s = new Scanner(System.in);
		int n = s.nextInt(), m = s.nextInt(), k = s.nextInt();
		int[][] a = new int[m][];
		int[][] count = new int[1 << n][1 << n];
		for (int i = 0; i < m; ++i) {
			int u = s.nextInt() - 1, v = s.nextInt() - 1;
			a[i] = new int[] { u, v };
			count[bit(u) | bit(v)][bit(u) | bit(v)] = 1;
		}
		int result = 0;
		for (int used = 0; used < bit(n); ++used) {
			for (int deadends = 0; deadends < bit(n); ++deadends) {
				int c = Integer.bitCount(deadends);
				if (c > 1 && count[used][deadends] > 1) {
					count[used][deadends] /= c;
				}
				if (used == bit(n) - 1 && c == k) {
					result += count[used][deadends];
				}
				for (int i = 0; i < m; ++i) {
					int u = a[i][0], v = a[i][1];
					int ut = used, dt = deadends;
					if (isUsed(u, used) ^ isUsed(v, used)) {
						if (isUsed(u, used)) {
							ut = add(v, ut);
							if (isUsed(u, dt)) {
								dt = remove(u, dt);
							}
							dt = add(v, dt);
						} else {
							ut = add(u, ut);
							if (isUsed(v, dt)) {
								dt = remove(v, dt);
							}
							dt = add(u, dt);
						}
						count[ut][dt] += count[used][deadends];
					}
				}
			}
		}
		System.out.println(result);
	}

	private static int remove(int v, int dt) {
		return dt ^ bit(v);
	}

	private static int add(int u, int dt) {
		return dt | bit(u);
	}

	private static boolean isUsed(int u, int dt) {
		return (dt & bit(u)) > 0;
	}

	private static int bit(int v) {
		return 1 << v;
	}

}

