import java.util.*;
import java.math.*;

public class cfD implements Runnable {
	private final boolean useStandardIO = true;
	private final String inFile = "segments.in";
	private final String outFile = "segments.out";

	int n, m, k;
	int[][] c, aa;

	int dp[][][];
	boolean[][][] was;

	int go(int m1, int m2, int need) {
		if (was[need][m1][m2])
			return dp[need][m1][m2];
		int res = 0;
		int have = Integer.bitCount(m1);
		int cur = Integer.bitCount(m2);
		if (m2 == 0) {
			if (have == need)
				res = 1;
		} else {
			int[] a1 = new int[have], a2 = new int[cur];
			int j = 0;
			for (int i = 0; i < n; ++i)
				if ((m1 & (1 << i)) != 0)
					a1[j++] = i;
			j = 0;
			for (int i = 0; i < n; ++i)
				if ((m2 & (1 << i)) != 0)
					a2[j++] = i;
			int tot = 1;
			for (int i = 0; i < cur; ++i)
				tot *= (have + 1);
			for (int mask = 1; mask < tot; ++mask) {
				int x = mask;
				int taken = 0, takenMask = 0, newLeaves = 0, newMask = 0;
				boolean ok = true;
				for (j = 0; j < cur; ++j) {
					int y = x % (have + 1);
					x /= (have + 1);
					if (y == 0)
						continue;
					--y;
					if (c[a1[y]][a2[j]] == 0) {
						ok = false;
						break;
					}
					if ((takenMask & (1 << y)) == 0) {
						++taken;
						takenMask |= (1 << y);
					}
					++newLeaves;
					newMask |= (1 << a2[j]);
				}
				if (!ok || newMask == 0)
					continue;
				int old = have - taken;
				if (m1 == 1 && newLeaves < 2)
					++old;
				if (need - old >= 0)
					res += go(newMask, m2 ^ newMask, need - old);
			}
		}

		was[need][m1][m2] = true;
		return dp[need][m1][m2] = res;
	}

	private void solve() throws IOException {
		n = nextInt();
		m = nextInt();
		k = nextInt();
		c = new int[n][n];
		for (int i = 0; i < m; ++i) {
			int x = nextInt() - 1, y = nextInt() - 1;
			c[x][y] = c[y][x] = 1;
		}

		dp = new int[k + 1][1 << n][1 << n];
		was = new boolean[k + 1][1 << n][1 << n];
		writer.print(go(1, (1 << n) - 2, k));
	}

	public static void main(String[] args) {
		new cfD().run();
	}

	BufferedReader reader;
	StringTokenizer tokenizer;
	PrintWriter writer;

	public void run() {
		try {
			Locale.setDefault(Locale.US);
			if (useStandardIO)
				reader = new BufferedReader(new InputStreamReader(System.in));
			else
				reader = new BufferedReader(new FileReader(inFile));
			tokenizer = null;
			if (useStandardIO)
				writer = new PrintWriter(System.out);
			else
				writer = new PrintWriter(new FileWriter(outFile));
			solve();
			reader.close();
			writer.close();
		} catch (Exception e) {
			e.printStackTrace();
			System.exit(1);
		}
	}

	int nextInt() throws IOException {
		return Integer.parseInt(nextToken());
	}

	long nextLong() throws IOException {
		return Long.parseLong(nextToken());
	}

	double nextDouble() throws IOException {
		return Double.parseDouble(nextToken());
	}

	BigInteger nextBigInteger() throws IOException {
		return new BigInteger(nextToken());
	}

	String nextToken() throws IOException {
		while (tokenizer == null || !tokenizer.hasMoreTokens()) {
			tokenizer = new StringTokenizer(reader.readLine());
		}
		return tokenizer.nextToken();
	}
}

