public class DeadEnds {

	int N, M, K;
	int[][] graph;
	long[][] res;

	long solve(int mask, int leaf, int n, int k){
		if(k < 2) return 0;
		if(res[mask][leaf] != -1) return res[mask][leaf];

		if(n == 2){

			int x = -1, y = -1;
			for(int i = 0; i < N; i++) if((mask & (1<<i)) > 0){
				if(x == -1) x = i; else y = i;
			}

			return res[mask][leaf] = graph[x][y];
		}

		long ans = 0;
		for(int i = 0; i < N; i++){
			if((leaf & (1<<i)) > 0){
				for(int j = 0; j < N; j++){
					if((mask & (1<<j)) > 0 && (leaf & (1<<j)) == 0 && graph[i][j] == 1){
						ans += solve(mask - (1<<i), leaf - (1<<i), n - 1, k - 1);
						ans += solve(mask - (1<<i), leaf - (1<<i) + (1<<j), n - 1, k);
				   	}
			   	}
				break;
			}
		}

		return res[mask][leaf] = ans;
	}

    void run(){
		N = nextInt(); M = nextInt(); K = nextInt();
		graph = new int[N][N];

		int x, y;
		for(int i = 0; i < M; i++){
			x = nextInt() - 1; y = nextInt() - 1;
			graph[x][y] = graph[y][x] = 1;
		}

		int[] bitCount = new int[1<<N];
		for(int i = 0; i < bitCount.length; i++){
			bitCount[i] = bitCount[i>>1];
			if(i % 2 == 1) bitCount[i]++;
		}

		long ret = 0;
		res = new long[1<<N][1<<N];
		for(long[] f : res) Arrays.fill(f, -1);
		for(int i = 0; i < (1<<N); i++){
			if(bitCount[i] == K){
				ret += solve((1<<N) - 1, i, N, K);
			}
		}

		System.out.println(ret);
    }

