import java.util.Arrays;
import java.util.StringTokenizer;

public class TaskE extends Thread {
    public TaskE() {
        this.input = new BufferedReader(new InputStreamReader(System.in));
        this.output = new PrintWriter(System.out);
        this.setPriority(Thread.MAX_PRIORITY);
    }


    static final long doit(int mask, int dead, int n) {
        if ((mask & dead) == 0) {
            cache[mask][dead] = 0;
            return 0;
        }
        if (cache[mask][dead] != -1) {
            return cache[mask][dead];
        }
        long result = 0;
        for (int a = 0; a < n; ++a) {
            if (((mask & (1 << a)) != 0) && ((dead & (1 << a)) != 0)) {
                for (int b = 0; b < n; ++b) {
                    if (g[a][b] && (mask & (1 << b)) != 0) {
                        if (mask == ((1 << a) | (1 << b))) {
                            cache[mask][dead] = ((dead & mask) == mask) ? 1 : 0;
                            return cache[mask][dead];
                        }
                        if ((dead & (1 << b)) == 0) {
                            result += doit(mask ^ (1 << a), dead, n) + doit(mask ^ (1 << a), dead ^ (1 << b), n);
                        }
                    }
                }
                break;
            }
        }
        cache[mask][dead] = result;
        return result;
    }

    private void solve() throws Throwable {
        int n = nextInt(), m = nextInt(), k = nextInt();
        g = new boolean[n][n];
        cache = new long[1 << n][1 << n];
        for (long[] current : cache) {
            Arrays.fill(current, -1);
        }
        Arrays.fill(cache[0], 1);
        for (int i = 0; i < m; ++i) {
            int a = nextInt() - 1, b = nextInt() - 1;
            g[a][b] = g[b][a] = true;
        }
        long ans = 0;
        for (int dead = 0; dead < (1 << n); ++dead) {
            if (Integer.bitCount(dead) == k) {
                ans += doit((1 << n) - 1, dead, n);
            }
        }
        output.println(ans);

    }

    public void run() {
        try {
            solve();
        } catch (Throwable e) {
            System.err.println(e.getMessage());
            e.printStackTrace();
            System.exit(666);
        } finally {
            output.flush();
            output.close();
        }
    }

    public static void main(String[] args) {
        new TaskE().start();
    }

    private int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    private long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }

    private double nextDouble() throws IOException {
        return Double.parseDouble(nextToken());
    }

    private String nextToken() throws IOException {
        while (tokens == null || !tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(input.readLine());
        }
        return tokens.nextToken();
    }

    static long[][] cache;
    static boolean[][] g;
    private BufferedReader input;
    private PrintWriter output;
    private StringTokenizer tokens = null;
}

