public class Main {

	/**
	 * @param args
	 */
	static int N, M, K;
	static int[] G, log;
	static long[][] DP;
	public static void main(String[] args) {
		DP = new long[1 << 17][13];

		log = new int[1 << 15];
		for(int i = 0; i < 15; i++)
			log[1 << i] = i;

		InputReader r = new InputReader(System.in);

		N = r.nextInt();
		M = r.nextInt();
		K = r.nextInt();

		G = new int[N];

		int id = 1;
		for(int k = 0; k < M; k++){
			int i = r.nextInt() - 1;
			int j = r.nextInt() - 1;

//			G[Math.min(i, j)] |= 1 << Math.max(i, j);
			G[i] |= 1 << j;
			G[j] |= 1 << i;
		}

		for(long[] i : DP)
			Arrays.fill(i, -1);

		long ret = 0;
		for(int next = G[0]; next > 0; next = (next - 1) & G[0]){
//			System.out.println(Integer.toBinaryString(next));
			ret += go(1, next | 1, Integer.bitCount(next) == 1 ? 1 : 0);
		}

		System.out.println(ret);
	}

	private static long go(int done, int reached, int c) {
		if(done == (1 << N) - 1){
			return c == K ? 1 : 0;
		}else{
			if(DP[gen(done, reached)][c] != -1)return DP[gen(done, reached)][c];

			int can = reached & ~done;
			int curr = can & -can;

//			System.out.println(curr + ", " + currI);
			if(curr == 0)return DP[gen(done, reached)][c] = 0;

			int currI = log[curr];

			long ret = 0;

			ret += go(done | 1 << currI, reached, c + 1);
			for(int next = G[currI] & ~reached; next > 0; next = (next - 1) & G[currI] & ~reached){
//				System.out.println(currI + ", " + next);
				ret += go(done | 1 << currI, reached | next, c);
			}

			return DP[gen(done, reached)][c] = ret;
		}
	}

	private static int gen(int done, int reached) {
		int ret = 0;
		for(int itr = 0; itr < N; itr++){
			ret *= 3; 
			if((reached & 1) == 0){
//				if((done & 1) == 1)System.out.println("error");
				ret += 0;
			}else{
				if((done & 1) == 0)ret += 1;
				else ret += 2;
			}

			done /= 2;
			reached /= 2;
		}

		return ret;
	}

	private static String print(int m) {
		String ret = Integer.toBinaryString(m);
		while(ret.length() < N)ret = "0" + ret;
		return ret;
	}

	static class InputReader {
		private BufferedReader reader;
		private StringTokenizer tokenizer;

		public InputReader(InputStream stream) {
			reader = new BufferedReader(new InputStreamReader(stream));
			tokenizer = null;
		}

		public String nextLine() {
			try {
				return reader.readLine();
			} catch (IOException e) {
				// TODO Auto-generated catch block
				e.printStackTrace();
				return null;
			}
		}

		public String next() {
			while (tokenizer == null || !tokenizer.hasMoreTokens()) {
				try {
					tokenizer = new StringTokenizer(reader.readLine());
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return tokenizer.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

		public long nextLong() {
			return Long.parseLong(next());
		}

		public double nextDouble() {
			return Double.parseDouble(next());
		}
	}
}

