		v=new int[m];
		for(int i=0; i<m; i++){
			u[i]=(int)(random()*n);
			v[i]=(int)(random()*n);
			for(; v[i]==u[i];){
				v[i]=(int)(random()*n);
			}
			boolean ok=true;
			for(int j=0; j<i; j++){
				ok&=u[i]!=u[j]||v[i]!=v[j];
				ok&=u[i]!=v[j]||v[i]!=u[j];
			}
			if(!ok){
				i--;
				continue;
			}
		}
		solve();
	}

	void solve(){
		long[][] dp=new long[1<<n][1<<n];
		// [s][t]:=sが連結，tが葉，の個数

		for(int i=0; i<n; i++){
			// dp[1<<i][1<<i]=1;
		}
		for(int i=0; i<m; i++){
			dp[(1<<u[i])|(1<<v[i])][(1<<u[i])|(1<<v[i])]=2;
		}
		// dp[1][1]=1;
		for(int s=1; s<1<<n; s++){
			int t=s;
			do{
				if(Integer.bitCount(t)>0){
					dp[s][t]/=Integer.bitCount(t);
				}
				for(int i=0; i<m; i++){
					boolean ub=(s>>u[i]&1)==1;
					boolean vb=(s>>v[i]&1)==1;
					if(ub&!vb){
						dp[s|(1<<v[i])][t&~(1<<u[i])|(1<<v[i])]+=dp[s][t];
					}
					if(!ub&vb){
						dp[s|(1<<u[i])][t&~(1<<v[i])|(1<<u[i])]+=dp[s][t];
					}
				}
				t=(t-1)&s;
			}while(t!=s);
		}
		long ans=0;
		int comb=(1<<k)-1;
		for(; comb<1<<n;){
			ans+=dp[(1<<n)-1][comb];
			int x=comb&-comb, y=comb+x;
			comb=((comb&~y)/x>>>1)|y;
		}
		println(ans+"");
	}

	void println(String s){
		System.out.println(s);
	}

	void print(String s){
		System.out.print(s);
	}

	void debug(Object... os){
		System.err.println(Arrays.deepToString(os));
	}

	public static void main(String[] args){
		Locale.setDefault(Locale.US);
		new P053E().run();
	}
}

