class Solver {
    int N, K;
    long[][][] big, small; 
    static long[][] comb;
    static final int Mod = 1000000000 + 7;
    static {
        comb = new long[13][13];
        for (int i = 0; i <= 12; ++i) {
            for (int j = 0; j <= i; ++j) {
                if (j == 0 || j == i) {
                    comb[i][j] = 1;
                }
                else {
                    comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % Mod;
                }
            }
        }
    }
    Solver(int N, int K) {
        this.N = N;
        this.K = K;
        big = new long[N + 1][K + 1][1 << 4];
        small = new long[N + 1][K + 1][1 << 4];
        for (int i = 0; i <= N; ++i) {
            for (int j = 0; j <= K; ++j) {
                for (int k = 0; k < 16; ++k) {
                    big[i][j][k] = small[i][j][k] = -1;
                }
            }
        }
    }
    long solve() {
        long res = calcBig(N, K, 15);
        for (int i = K; i >= 1; --i) {
            res = res * i % Mod;
        }
        return res;
    }
    long calcBig(int size, int count, int mask) {
        if (count < 0) {
            return 0;
        }
        if (big[size][count][mask] != -1) {
            return big[size][count][mask];
        }
        long res = 0;
        if (mask == 15) {
            res += 2 * calcBig(0, count - 2, 0);
        }
        for (int i = 0; i < 4; ++i) {
            int j = (i + 1) & 3;
            if ((mask >> i & 1) == 1 && (mask >> j & 1) == 1) {
                int nxt = mask ^ (1 << i) ^ (1 << j);
                for (int k = nxt; ; k = (k - 1) & nxt) {
                    res += calcSmall(size, count - 1 - Integer.bitCount(k), nxt - k);
                    if (k == 0) {
                        break;
                    }
                }
            }
        }
        int nxt = mask;
        for (int k = nxt; ; k = (k - 1) & nxt) {
            res += calcSmall(size, count - Integer.bitCount(k), nxt - k);
            if (k == 0) {
                break;
            }
        }
        return big[size][count][mask] = res % Mod;
    }
    long calcSmall(int size, int count, int mask) {
        if (count < 0) {
            return 0;
        }
        if (small[size][count][mask] != -1) {
            return small[size][count][mask];
        }
        if (size == 0) {
            return count == 0 ? 1 : 0;
        }
        long res = 0;
        int maxCount = Integer.bitCount(mask) * 3;
        int pairCount = 0;
        for (int i = 0; i < 4; ++i) {
            int j = (i + 1) & 3;
            if ((mask >> i & 1) == 1 && (mask >> j & 1) == 1) {
                pairCount++;
            }
        }
        for (int i = 0; i <= pairCount; ++i) {
            for (int j = 0; j <= maxCount - i * 2; ++j) {
                res += calcBig(size - 1, count - i - j, mask) * comb[pairCount][i] % Mod * comb[maxCount - i * 2][j] % Mod;
            }
        }
        return small[size][count][mask] = res % Mod;
    }
}

