	static int solveKO(int[] a,int[] b,int[][] c) {
		int n=a.length;
		int m=b.length;
		int MX=1<<m;

		int[][] cost=new int[n][MX];
		int[] bill=new int[MX];

		for (int w=0;w<MX;w++)
			for (int j=0;j<m;j++)
				if (((1<<j)&w)!=0) {
					bill[w]+=b[j];
					for (int i=0;i<n;i++)
						cost[i][w]+=c[i][j];
				}


		int VX=m*4+1;
		int[][] spend=new int[MX][VX];

		for (int w=0;w<MX;w++) {
			Arrays.fill(spend[w], FX);
			if (bill[w]>=a[0]) {
				// ok for me
				// now we look at the previous
				spend[w][bill[w]-a[0]]=cost[0][w];
				//log("adding:"+w);
			}
		}



		// this is taking some shortcut...

		for (int i=1;i<n;i++) {
			int[][] nxt=new int[MX][VX];
			for (int w=0;w<MX;w++)
				Arrays.fill(nxt[w],FX);
			for (int w=0;w<MX;w++) {
				if (bill[w]>=a[i]) {
					//log("considering:"+w);
					// ok for me
					// now we look at the previous
					for (int u=0;u<MX;u++)
						for (int v=0;v<VX;v++) {
							if (spend[u][v]<FX) {
								//log("----interested by u:"+u);
								int nu=u|w;
								int nv=v+bill[w]-bill[w&u]-a[i];
								//log("nv:"+nv);
								if (nv>=0) {
									//log("----merging");
									nxt[nu][nv]=Math.min(spend[u][v]+cost[i][w], nxt[nu][nv]);
								}
							}
						}
				}

			}
			spend=nxt;
		}
		int ans=FX;
		for (int w=0;w<MX;w++)
			for (int v=0;v<VX;v++)
				ans=Math.min(ans, spend[w][v]);

		if (ans==FX)
			ans=-1;
		return ans;
	}

