	static class Point extends Vertex<Point, EdgeDefault<Point>>
	{
		public static final Comparator<Point> COMPARATOR_X = Comparator.comparing(Point::getX);
		public static final Comparator<Point> COMPARATOR_Y = Comparator.comparing(Point::getX);
		public final int x;
		public final int y;

		public Point(int index, int x, int y)
		{
			super(index);
			this.x = x;
			this.y = y;
		}

