	public static long BIG = 1000000007;

	public static int countLines(Set<Point> points)
	{
		Set<Integer> xs = new SortedSetAVL<>(Comparator.naturalOrder());
		Set<Integer> ys = new SortedSetAVL<>(Comparator.naturalOrder());
		for (Point point : points)
		{
			xs.add(point.getX());
			ys.add(point.getY());
		}
		return xs.size() + ys.size();
	}

	public static long modMultiply(long a, long b)
	{
		return (a * b) % BIG;
	}

	public static long modAdd(long a, long b)
	{
		return (a + b) % BIG;
	}

	public static long modSubtract(long a, long b)
	{
		return (a - b + BIG) % BIG;
	}

	public static long modPower2(int a)
	{
		long result = 1;
		for (int index = 0; index < a; index++)
		{
			result = modMultiply(result, 2);
		}
		return result;
	}

	public static void solve() throws IOException
	{
		int n = nextInt();
		Array<Point> points = new Array<>(n);
		MapSet<Integer, Point> y2Points = new MapSet<>(Comparator.naturalOrder(), Point.COMPARATOR_X);
		for (int index = 0; index < n; index++)
		{
			Point point = new Point(index, nextInt(), nextInt());
			points.set(index, point);
			y2Points.add(point.getY(), point);
		}
		Map<Integer, Point> x2LastY = new SortedMapAVL<>(Comparator.naturalOrder());
		for (Set<Point> set : y2Points.values())
		{
			Point lastX = null;
			for (Point point : set)
			{
				if (lastX != null)
				{
					new EdgeDefault<>(point, lastX, true);
				}
				lastX = point;
				Point lastY = x2LastY.get(point.getX());
				if (lastY != null)
				{
					new EdgeDefault<>(point, lastY, true);
				}
				x2LastY.put(point.getX(), point);
			}
		}
		Map<Point, Set<Point>> pointsCycleFalse = new SortedMapAVL<>(Comparator.naturalOrder());
		Map<Point, Set<Point>> pointsCycleTrue = new SortedMapAVL<>(Comparator.naturalOrder());
		Set<Point> pointsProcessed = new SortedSetAVL<>(Comparator.naturalOrder());
		for (Point point : points)
		{
			if (!pointsProcessed.contains(point))
			{
				SortedSet<Point> structure = new SortedSetAVL<>(Comparator.naturalOrder());
				if (Vertex.cycle(point, structure))
				{
					pointsCycleTrue.put(point, structure);
				}
				else
				{
					pointsCycleFalse.put(point, structure);
				}
				pointsProcessed.addAll(structure);
			}
		}
		long result = 1;
		for (Set<Point> set : pointsCycleFalse.values())
		{
			result = modMultiply(result, modSubtract(modPower2(countLines(set)), 1));
		}
		for (Set<Point> set : pointsCycleTrue.values())
		{
			result = modMultiply(result, modPower2(countLines(set)));
		}
		out.println(result);
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.*;

import static java.lang.Math.random;

/**
 * @author Don Li
 */
public class PointsLinesTitles {

    int N = (int) 1e5 + 10;
    int MOD = (int) 1e9 + 7;

    int n;
    int[][] p;
    List<Integer>[] G;

    boolean[] used = new boolean[N];
    Set<Integer> uniqueX = new HashSet<>(), uniqueY = new HashSet<>();
    long sumDegree = 0, numNode = 0;

    void solve() {
        n = in.nextInt();

        p = new int[n][2];
        for (int i = 0; i < n; i++) {
            p[i][0] = in.nextInt();
            p[i][1] = in.nextInt();
        }

        int[] x = new int[n], y = new int[n];
        for (int i = 0; i < n; i++) {
            x[i] = p[i][0];
            y[i] = p[i][1];
        }
        sort(x);
        sort(y);
        for (int i = 0; i < n; i++) {
            p[i][0] = lowerBound(x, p[i][0]);
            p[i][1] = lowerBound(y, p[i][1]);
        }

        G = new List[n];
        for (int i = 0; i < n; i++) G[i] = new ArrayList<>();

        List<Integer>[] ver = new List[n], hor = new List[n];
        for (int i = 0; i < n; i++) {
            ver[i] = new ArrayList<>();
            hor[i] = new ArrayList<>();
        }
        for (int i = 0; i < n; i++) {
            ver[p[i][0]].add(i);
            hor[p[i][1]].add(i);
        }
        for (int i = 0; i < n; i++) {
            ver[i].sort(Comparator.comparingInt(a -> p[a][1]));
            for (int j = 1; j < ver[i].size(); j++) {
                int u = ver[i].get(j - 1), v = ver[i].get(j);
                addNeighbors(u, v);
            }
            hor[i].sort(Comparator.comparingInt(a -> p[a][0]));
            for (int j = 1; j < hor[i].size(); j++) {
                int u = hor[i].get(j - 1), v = hor[i].get(j);
                addNeighbors(u, v);
            }
        }

        long ans = 1;
        for (int i = 0; i < n; i++) {
            if (!used[i]) {
                uniqueX.clear();
                uniqueY.clear();
                sumDegree = 0; numNode = 0;
                dfs(i);
                long ways = mpow(2, uniqueX.size() + uniqueY.size());
                if (sumDegree / 2 == numNode - 1) ways = (ways - 1 + MOD) % MOD;
                ans = ans * ways % MOD;
            }
        }
        out.println(ans);
    }

    void dfs(int u) {
        used[u] = true;
        uniqueX.add(p[u][0]);
        uniqueY.add(p[u][1]);
        numNode++;
        sumDegree += G[u].size();
        for (int v : G[u]) {
            if (!used[v]) dfs(v);
        }
    }

    long mpow(long a, long n) {
        long res = 1;
        while (n > 0) {
            if ((n & 1) > 0) res = res * a % MOD;
            a = a * a % MOD;
            n >>= 1;
        }
        return res;
    }

    void addNeighbors(int u, int v) {
        G[u].add(v);
        G[v].add(u);
    }

    void sort(int[] a) {
        int n = a.length;
        for (int i = 0; i < n; i++) {
            int j = (int) (i + random() * (n - i));
            int tmp = a[i];
            a[i] = a[j];
            a[j] = tmp;
        }
        Arrays.sort(a);
    }

    int lowerBound(int[] a, int k) {
        int lb = -1, ub = a.length;
        while (ub - lb > 1) {
            int m = (lb + ub) >> 1;
            if (a[m] >= k) ub = m;
            else lb = m;
        }
        return ub;
    }

    public static void main(String[] args) {
        in = new FastScanner(new BufferedReader(new InputStreamReader(System.in)));
        out = new PrintWriter(System.out);
        new PointsLinesTitles().solve();
        out.close();
    }

    static FastScanner in;
    static PrintWriter out;

    static class FastScanner {
        BufferedReader in;
        StringTokenizer st;

        public FastScanner(BufferedReader in) {
            this.in = in;
        }

        public String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(in.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextToken());
        }

        public long nextLong() {
            return Long.parseLong(nextToken());
        }

        public double nextDouble() {
            return Double.parseDouble(nextToken());
        }
    }
}

