public class Main implements Runnable{
	public int TC = 0;
	public static void main(String[] args) {
		new Thread(null, new Main(), ":)", 1L << 26).start();
	}
	static final int MODULO = (int)(1e9 + 7);
	@SuppressWarnings("Unchecked")
	public void solve() throws IOException {
	    int n = ni();
	    HashSet<Integer> x = new HashSet<>();
	    HashSet<Integer> y = new HashSet<>();
	    HashMap<Integer, Integer> mapX = new HashMap<>();
	    HashMap<Integer, Integer> mapY = new HashMap<>();
	    int[][] pp = new int[2][n];
	    for (int i = 0; i < n;  ++i) {
	    	for(int j = 0;j < 2; ++j) {
	    		pp[j][i] = ni();
	    		if(j == 0) x.add(pp[j][i]);
	    		else y.add(pp[j][i]);
	    	}
	    }

	    int mapIdx = 0;
	    for(int xx : x) 
	    	if(!mapX.containsKey(xx)) 
	    		mapX.put(xx, mapIdx++);

	    for(int yy : y) 
	    	if(!mapY.containsKey(yy)) 
	    		mapY.put(yy, mapIdx++);

	    DJSet ds = new DJSet(mapIdx);
	    for(int i = 0;i < n; ++i) {
	    	ds.union(mapX.get(pp[0][i]), mapY.get(pp[1][i]));
	    }

	    long res = 1;
	    factorial();
	    for (int i = 0; i < mapIdx; i++)
            if (ds.upper[i] < 0) {
                int numPoints = ds.pointsNum[i], lines = -ds.upper[i];
                long ways = 0;
                for (int j = 0; j <= Math.min(numPoints, lines); j++) {
                    ways += ncr(lines, j);
                    if (ways >= MODULO) ways -= MODULO;
                }
                res *= ways;
                res %= MODULO;
            }
	    out.println(res);
	}
	// O(1) nCr
    static int MAX = 5 * 100000 + 1;
    static int fact[] = new int[MAX];

    static int ncr(int n, int r) {
        return (int) ((long) fact[n] * ((inv(fact[r], MODULO) * inv(fact[n - r], MODULO)) % MODULO) % MODULO) % MODULO;
    }

    static long inv(long x, long mod) {
        long r, y;
        for (r = 1, y = mod - 2; y != 0; x = x * x % mod, y >>= 1)
            if ((y & 1) == 1)
                r = r * x % mod;
        return r;
    }

    static void factorial() {
        fact[0] = fact[1] = 1;
        for (int i = 2; i < MAX; i++)
            fact[i] = (int) ((long) i * fact[i - 1] % MODULO);
    }

    public static long powMod(long a, long n) {
    	long res = 1;
    	long t = a;
    	for(int i = 0;i < 63; ++i) {
    		if((n & (1L << i)) != 0)
    			res = (res + t) % MODULO;
    		t = t * t % MODULO;
    	}
        return res;
    }
	public class DJSet {
	    public int[] upper;
	    public int[] pointsNum;
	    public int count;
	    public DJSet(int n) {
	        upper = new int[n];
	        count = n;
	        pointsNum = new int[n];
	        Arrays.fill(upper, -1);
	    }


	    public int root(int x) {
	        return upper[x] < 0 ? x : (upper[x] = root(upper[x]));
	    }

	    public boolean equiv(int x, int y) {
	        return root(x) == root(y);
	    }

	    public boolean union(int x, int y) {
	        x = root(x);
	        y = root(y);
	        if (x != y) {
	            if (upper[y] < upper[x]) {
	                int d = x;
	                x = y;
	                y = d;
	            }
	            upper[x] += upper[y];
	            upper[y] = x;
	            pointsNum[x] += 1 + pointsNum[y];
	            --count;
	            return true;
	        } else {
	        	++pointsNum[x];
	        }
	        return false;
	    }

	    public int getCount() {
	        return count;
	    }

	    public long size(int u) {
	        return -upper[root(u)];
	    }

	    public void clear() {
	        Arrays.fill(upper, -1);
	    }
	}
	BufferedReader br;
