	pair(long x,int y){ this.x=x ; this.y=y ;}
	public int compareTo(pair p){
		return (this.x<p.x ? -1 : (this.x>p.x ? 1 : (this.y<p.y ? -1 : (this.y>p.y ? 1 : 0)))) ;
	}
}
class Solver{	
	FasterScanner ip = new FasterScanner(System.in) ;	  
	PrintWriter op = new PrintWriter(System.out) ;
	long offset = 2000000001l ;
	void Solve() throws IOException{
		int m = ip.i() ;
		long edges[][] = new long[m][] ;
		for(int i=0 ; i<m ; i++){
			long tmp[] = {ip.l(),ip.l()+offset} ;
			edges[i] = tmp ;
		}
		myset set = new myset() ;
		for(int i=0 ; i<m ; i++){
			set.add(edges[i][0]) ;
			set.add(edges[i][1]) ;
		}
		mymap map = new mymap() ;
		int n=0 ;
		for(long elem : set) map.put(elem,n++) ;
		for(int i=0 ; i<m ; i++){
			long tmp[] = {map.get(edges[i][0]),map.get(edges[i][1])} ;
			edges[i] = tmp ;
		}
		mylist adj[] = new mylist[n] ;
		for(int i=0 ; i<n ; i++) adj[i] = new mylist() ;
		for(int i=0 ; i<m ; i++){
			int x = (int) edges[i][0] ;
			int y = (int) edges[i][1] ;
			adj[x].add(y) ; adj[y].add(x) ;
		}
		int comp[] = new int[n] ;
		Arrays.fill(comp,-1) ;
		int clr=0 ;
		for(int i=0 ; i<n ; i++){
			if(comp[i]==-1){
				mystack S = new mystack() ;
				S.add(i) ;
				comp[i]=clr ;
				while(!S.isEmpty()){
					int nd = S.pop() ;
					for(int nnd : adj[nd])
						if(comp[nnd]==-1){
							S.push(nnd) ;
							comp[nnd]=clr ;
						}
				}
				clr++ ;
			}
		}
		int cntn[] = new int[clr] ;
		int cntm[] = new int[clr] ;
		for(int i=0 ; i<n ; i++) cntn[comp[i]]++ ;
		for(int i=0 ; i<m ; i++) cntm[comp[(int) edges[i][0]]]++ ;
		long res=1 ;
		for(int i=0 ; i<clr ; i++){
			if(cntm[i]>=cntn[i]) 
				res = Mod.m(res,Mod.pow(2,cntn[i])) ;
			else
				res = Mod.m(res,Mod.pow(2,cntn[i])+(Mod.mod-1)) ;
		}
		pln(res) ;
	}
	void p(Object o){
		op.print(o) ;
	}
	void pln(Object o){
		op.println(o) ;
	}
	void pArr(String name,Object arr,char type){
		p(name+": [") ;
		if(type=='i'){ 
			int arr1[] = (int[]) arr ;
			for(int i=0 ; i<arr1.length ; i++) p(arr1[i]+(i+1==arr1.length ? "" : ",")) ;		 
		}else if(type=='l'){ 
			long arr1[] = (long[]) arr ;
			for(int i=0 ; i<arr1.length ; i++) p(arr1[i]+(i+1==arr1.length ? "" : ",")) ;
		}else if(type=='b'){
			boolean arr1[] = (boolean[]) arr ;
			for(int i=0 ; i<arr1.length ; i++) p((arr1[i] ? 1 : 0)+(i+1==arr1.length ? "" : ",")) ;
		}
		pln("]") ;
	}	
	void Finish(){
		op.flush();
		op.close();
	}	
}
