    long getAnswer(int n, long c0, long c1) {
        long c01 = c0 + c1;

        if (n == 2) {
            return c01;
        }

        long answer = c1;
        n -= 2;

        long x = (c0 == 0 ? Integer.MAX_VALUE : c1 / c0);
        x = Math.min(x, n);

        answer += x * c1 + (x + 1) * (x + 2) / 2 * c0;
        n -= x;

        NavigableMap<Long, Integer> costs = new TreeMap<>();

//        costs.put(c1, 1);
        for (int count = 0; count <= Math.min(MAX_SIZE, x); ++count) {
            inc(costs, count * c0 + c1, 1);
        }
        inc(costs, (x + 1) * c0, 1);

        while (n > 0) {
            Map.Entry<Long, Integer> minCostEntry = costs.pollFirstEntry();

            long cost = minCostEntry.getKey();
            int count = minCostEntry.getValue();
            count = Math.min(count, n);

            n -= count;
            answer += (cost + c01) * count;

            inc(costs, cost + c0, count);
            inc(costs, cost + c1, count);
        }

        return answer;
    }

    void inc(NavigableMap<Long, Integer> counts, long cost, int count) {
        Integer curCount = counts.get(cost);
        if (curCount == null) {
            curCount = 0;
        }

        counts.put(cost, curCount + count);

        while (counts.size() > MAX_SIZE) {
            counts.pollLastEntry();
        }
    }

