public class Main {
    FastScanner in;
    PrintWriter out;

    int area(long ax, long ay, long bx, long by, long cx, long cy) {
        // удвоеная знаковая площадь треугольник abc; векторное произведение ab и ac
        long s = (bx - ax) * (cy - ay) - (by - ay) * (cx - ax);
        return s < 0 ? -1 : s > 0 ? 1 : 0;
    }

    private void solve() throws IOException {
        int n = in.nextInt();
        long[] x = new long[n], y = new long[n];
        for (int i = 0; i < n; i++) {
            x[i] = in.nextLong();
            y[i] = in.nextLong();
        }
        char[] s = in.next().toCharArray();
        boolean[] used = new boolean[n];

        int cur = 0;
        for (int i = 1; i < n; i++)
            if (y[i] < y[cur] || (y[i] == y[cur] && x[i] < x[cur]))
                cur = i;
        used[cur] = true;
        out.print(cur + 1 + " ");

        for (int i = 0; i < n - 1; i++) {
            int next = -1;
            for (int j = 0; j < n; j++)
                if (!used[j] && (next == -1 || (s[i] == 'L' && area(x[cur], y[cur], x[next], y[next], x[j], y[j]) < 0) ||
                        (s[i] == 'R' && area(x[cur], y[cur], x[next], y[next], x[j], y[j]) > 0)))
                    next = j;
            cur = next;
            used[cur] = true;
            out.print(cur + 1 + " ");
        }

        out.println();
    }

    class FastScanner {
        StringTokenizer st;
        BufferedReader br;

        FastScanner(InputStream s) {
            br = new BufferedReader(new InputStreamReader(s));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens())
                st = new StringTokenizer(br.readLine());
            return st.nextToken();
        }

        boolean hasNext() throws IOException {
            return br.ready() || (st != null && st.hasMoreTokens());
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        String nextLine() throws IOException {
            return br.readLine();
        }

        boolean hasNextLine() throws IOException {
            return br.ready();
        }
    }

    private void run() throws IOException {
        in = new FastScanner(System.in); // new FastScanner(new FileInputStream(".in"));
        out = new PrintWriter(System.out); // new PrintWriter(new FileOutputStream(".out"));

        for (int t = 1; t-- > 0; )
            solve();

        out.flush();
        out.close();
    }

    public static void main(String[] args) throws IOException {
        new Main().run();
    }
}

import java.io.*;
