        long prob = 1;
        for(int i = k; i > 0; i--){
            val*=(n-(k-i));
            val%=MOD;
            prob*=p;
            prob%=MOD;
            ans += (((val*prob)%MOD)*stirling[k][k-i+1])%MOD;
            ans%=MOD;
        }
        System.out.println(ans);


    }

    public static long modInverse(long x, long p){
        return power(x, p-2, p);
    }

    public static long power(long x, long y, long p){
        long res = 1;
        x = x % p;

        while (y > 0) {

            if (y % 2 == 1)
                res = (res * x) % p;

            y = y >> 1;
            x = (x * x) % p;
        }

        return res;
    }

}

