							&& when[i] % period == 0) {
						// out.println(i + 1);
						return i;
					}
				}

				throw new AssertionError();

			}
			when[s] = left;

			for (int i = n - 1; i > 0; i--) {
				if (s < k) {
					s += i;
					if (s >= n) {
						s -= n;
					}
				} else {
					s -= i;
					if (s < 0) {
						s += n;
					}
				}
			}

		}

		// out.println(s + 1);
		return s;

	}

	int go(int n, int m) {
		int[] a = IntStream.range(0, n).toArray();
		for (int i = n - 1; i > 0; i--) {
			for (int j = 0; j < n; j++) {
				int delta = a[j] < m ? 1 : -1;
				a[j] = (a[j] + n + i * delta) % n;
			}
		}
		// System.err.println(Arrays.toString(a));
		// out.println("digraph G {");
		// for (int i = 0; i < n; i++) {
		// out.println(i + " -> " + a[i] + ";");
		// }
		// out.println("}");

		return maxDepth(a);
	}

	int maxDepth(int[] p) {
		int n = p.length;
		int[] used = new int[n];
		int ret = 0;
		Arrays.fill(used, -1);
		for (int i = 0; i < n; i++) {
			int cur = 0;
			int v = i;
			while (used[v] != i) {
				used[v] = i;
				cur++;
				v = p[v];
			}
			ret = Math.max(ret, cur);
		}
		return ret;
	}

