public class backforth implements Runnable {
	public StringTokenizer strtok;
	public BufferedReader inr;
	public PrintWriter out;

	public static void main(String[] args) {
		new Thread(new backforth()).start();
	}

	public static final String taskname = "backforth";

	public void run() {
		Locale.setDefault(Locale.US);
		boolean oj = System.getProperty("ONLINE_JUDGE") != null;
		try {
			inr = new BufferedReader(oj ? new InputStreamReader(System.in, "ISO-8859-1") : new FileReader(taskname + ".in"));
			out = new PrintWriter(oj ? new OutputStreamWriter(System.out, "ISO-8859-1") : new FileWriter(taskname + ".out"));
			solve();
		} catch (Exception e) {
			if (!oj)
				e.printStackTrace();
			System.exit(9000);
		} finally {
			out.flush();
			out.close();
		}
	}

	public String nextToken() throws IOException {
		while (strtok == null || !strtok.hasMoreTokens()) {
			strtok = new StringTokenizer(inr.readLine());
		}
		return strtok.nextToken();
	}

	public int nextInt() throws NumberFormatException, IOException {
		return Integer.parseInt(nextToken());
	}

	// Solution

	byte[] action;
	ArrayList<HashSet<Integer>> g;
	ArrayList<HashSet<Integer>> revg;

	boolean[] visited_from_write;
	boolean[] visited_from_read;

	public void dfs_from_write(int start) {
		Stack<Integer> stack = new Stack<Integer>();
		stack.add(start);
		while(!stack.isEmpty()) {
			int node = stack.pop();
			visited_from_write[node] = true;
			HashSet<Integer> neighbours = g.get(node);
			for (int neigh : neighbours) {
				if (visited_from_write[neigh]) {
					continue;
				}
				stack.add(neigh);
			}
		}
	}

	public void dfs_from_read(int start) {
		Stack<Integer> stack = new Stack<Integer>();
		stack.add(start);
		while(!stack.isEmpty()) {
			int node = stack.pop();
			visited_from_read[node] = true;
			if (action[node] == 1) {
				continue;
			}
			HashSet<Integer> neighbours = revg.get(node);
			for (int neigh : neighbours) {
				if (visited_from_read[neigh]) {
					continue;
				}
				stack.add(neigh);
			}
		}
	}

	public void solve() throws NumberFormatException, IOException {
		int n = nextInt(), m = nextInt();
		action = new byte[n];
		g = new ArrayList<HashSet<Integer>>(n);
		for (int i = 0; i < n; i++) {
			g.add(new HashSet<Integer>());
		}
		revg = new ArrayList<HashSet<Integer>>(n);
		for (int i = 0; i < n; i++) {
			revg.add(new HashSet<Integer>());
		}
		visited_from_write = new boolean[n];
		visited_from_read = new boolean[n];
		for (int i = 0; i < n; i++) {
			action[i] = (byte)nextInt();
		}
		for (int i = 0; i < m; i++) {
			int a = nextInt() - 1;
			int b = nextInt() - 1;
			g.get(a).add(b);
			revg.get(b).add(a);
		}
		for (int i = 0; i < n; i++) {
			if (action[i] == 1 && !visited_from_write[i]) {
				dfs_from_write(i);
			}
		}
		for (int i = 0; i < n; i++) {
			if (action[i] == 2 && !visited_from_read[i]) {
				dfs_from_read(i);
			}
		}
		for (int i = 0; i < n; i++) {
			if (visited_from_write[i] && visited_from_read[i]) {
				out.println(1);
			}
			else {
				out.println(0);
			}
		}
	}
}

