    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1000];
        private int curChar, numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1)
                throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public long readLong() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String readString() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            StringBuffer res = new StringBuffer();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private String readLine0() {
            StringBuffer buf = new StringBuffer();
            int c = read();
            while (c != '\n' && c != -1) {
                buf.appendCodePoint(c);
                c = read();
            }
            return buf.toString();
        }

        public String readLine() {
            String s = readLine0();
            while (s.trim().length() == 0)
                s = readLine0();
            return s;
        }

        public String readLine(boolean ignoreEmptyLines) {
            if (ignoreEmptyLines)
                return readLine();
            else
                return readLine0();
        }

        public char readCharacter() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            return (char) c;
        }

        public double readDouble() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            double res = 0;
            while (!isSpaceChar(c) && c != '.') {
                if (c == 'e' || c == 'E')
                    return res * Math.pow(10, readInt());
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            }
            if (c == '.') {
                c = read();
                double m = 1;
                while (!isSpaceChar(c)) {
                    if (c == 'e' || c == 'E')
                        return res * Math.pow(10, readInt());
                    if (c < '0' || c > '9')
                        throw new InputMismatchException();
                    m /= 10;
                    res += (c - '0') * m;
                    c = read();
                }
            }
            return res * sgn;
        }
    }

}

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Scanner;
import java.util.Stack;


public class CF_164D {

	public static void main(String[] args) {
		new CF_164D().solve();
	}

	private void solve() {
		Scanner in = new Scanner(System.in);
		int numNodes = in.nextInt();
		int numEdges = in.nextInt();

		boolean[] rfs = new boolean[numNodes];
		boolean[] rfe = new boolean[numNodes];
		int[] type = new int[numNodes];

		HashMap<Integer, List<Integer>> fwdEdges = new HashMap<Integer, List<Integer>>();
		HashMap<Integer, List<Integer>> revEdges = new HashMap<Integer, List<Integer>>();

		Stack<Integer> startNodes = new Stack<Integer>();
		Stack<Integer> endNodes   = new Stack<Integer>();

		// read nodes
		for(int i = 0; i < numNodes; i++) {
			type[i] = in.nextInt();
			fwdEdges.put(i, new ArrayList<Integer>());
			revEdges.put(i, new ArrayList<Integer>());

			if(type[i] == 1) {
				startNodes.push(i);
			} else if (type[i] == 2) {
				endNodes.push(i);
			}
		}

		// read edges
		for(int i = 0; i < numEdges; i++) {
			int a = in.nextInt() - 1;
			int b = in.nextInt() - 1;
			fwdEdges.get(a).add(b);
			revEdges.get(b).add(a);
		}

		// find all nodes reachable from start nodes without visiting an end node
		// (traverse forward edges)
		while(!startNodes.empty()) {
			int node = startNodes.pop();
			if(rfs[node]) {
				continue;
			}

			rfs[node] = true;
			//if(type[node] == 2) {
			//	continue;
			//}
			for(int next : fwdEdges.get(node)) {
				startNodes.push(next);
			}
		}

		// find all nodes reachable from end nodes without visiting a start node
		// (traverse reverse edges)
		while(!endNodes.empty()) {
			int node = endNodes.pop();
			if(rfe[node]) {
				continue;
			}

			rfe[node] = true;
			if(type[node] == 1) {
				continue;
			}
			for(int next : revEdges.get(node)) {
				endNodes.push(next);
			}
		}		

		for(int i = 0; i < numNodes; i++) {
			System.out.println(rfs[i] && rfe[i] ? "1" : "0");
		}
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.StringTokenizer;

public class Solver {

    StringTokenizer st;
    BufferedReader in;
    PrintWriter out;

    public static void main(String[] args) throws NumberFormatException, IOException {
        Solver solver = new Solver();
        solver.open();
        solver.solve();
        solver.close();
    }

    public void open() throws IOException {
        in = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(System.out);
    }

    public String nextToken() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            st = new StringTokenizer(in.readLine());
        }
        return st.nextToken();
    }

    public int nextInt() throws NumberFormatException, IOException {
        return Integer.parseInt(nextToken());
    }

    public long nextLong() throws NumberFormatException, IOException {
        return Long.parseLong(nextToken());
    }

    public double nextDouble() throws NumberFormatException, IOException {
        return Double.parseDouble(nextToken());
    }

    enum State{
        IGNORE,ASSIGN,USE;

        public static State getState(int v){
            switch(v){
                case 0:
                    return IGNORE;
                case 1:
                    return ASSIGN;
                case 2:
                    return USE;
                default:
                        return null;
            }
        }
    }

    public void solve() throws NumberFormatException, IOException {
        int n = nextInt();
        int m = nextInt();

        State[] states = new State[n];
        List<List<Integer>> child = new ArrayList<List<Integer>>(n);
        List<List<Integer>> rev = new ArrayList<List<Integer>>(n);
        List<Integer> whenUsed = new ArrayList<Integer>();
        List<Integer> whenAssi = new ArrayList<Integer>();
        boolean[] forward = new boolean[n];
        boolean[] back = new boolean[n];

        for (int i=0;i<n;i++){
            child.add(new ArrayList<Integer>());
            rev.add(new ArrayList<Integer>());
            int vertex = nextInt();
            State state = State.getState(vertex);
            states[i] = state;
            if (state==State.USE){
                whenUsed.add(i);
            }else if(state==State.ASSIGN){
                whenAssi.add(i);
            }
        }

        for (int i=0;i<m;i++){
            int from = nextInt()-1;
            int to = nextInt()-1;

            child.get(from).add(to);
            rev.get(to).add(from);
        }

        while (whenAssi.size()>0){
            List<Integer> tmp = new ArrayList<Integer>();
            for (int vert:whenAssi){
                if (!forward[vert]){
                    forward[vert] = true;
                    tmp.addAll(child.get(vert));
                }
            }
            whenAssi = tmp;
        }

        while (whenUsed.size()>0){
            List<Integer> tmp = new ArrayList<Integer>();
            for (int vert:whenUsed){
                if (!back[vert]){
                    back[vert] = true;
                    if (states[vert]!=State.ASSIGN){
                        tmp.addAll(rev.get(vert));
                    }
                }
            }
            whenUsed = tmp;
        }

        for (int i=0;i<n;i++){
            if (forward[i] && back[i]){
                out.println(1);
            }else{
                out.println(0);
            }
        }
    }

    public void close() {
        out.flush();
        out.close();
    }

}

import static java.lang.Integer.parseInt;
import static java.lang.Long.parseLong;
import static java.lang.Math.max;
import static java.lang.System.exit;
import static java.util.Arrays.fill;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class G {

	static final long inf = Long.MAX_VALUE / 2;

	static void solve() throws Exception {
		int k = scanInt();
		long f[] = new long[6];
		for (int i = 0; i < 6; i++) {
			f[i] = scanLong();
		}
		long dyn[] = new long[1000000], ndyn[] = new long[1000000];
		fill(dyn, 1, 1000000, -inf);
		int p10 = 1;
		int smpos[] = new int[1000000];
		for (int p = 0; p < 6; p++) {
			fill(ndyn, -inf);
			long cf = f[p];
			int s = 3 * p10;
			for (int i = 0; i < 1000000; i++) {
				dyn[i] -= i / s * cf;
			}
			for (int m = 0; m < s; m++) {
				int smhead = 0, smtail = 0;
				for (int i = m; i < 1000000; i += s) {
					while (smtail > smhead && dyn[i] >= dyn[smpos[smtail - 1]]) {
						--smtail;
					}
					smpos[smtail++] = i;
					long v = dyn[smpos[smhead]] + i / s * cf;
					ndyn[i] = max(ndyn[i], v);
					if (i + p10 < 1000000) {
						ndyn[i + p10] = max(ndyn[i + p10], v);
					}
					if (i + 2 * p10 < 1000000) {
						ndyn[i + 2 * p10] = max(ndyn[i + 2 * p10], v);
					}
					if (smpos[smhead] == i - (long) (9 * k - 9) * p10) {
						++smhead;
					}
				}
			}
			for (int i = 0; i < 1000000; i++) {
				for (int ss = 9 * k - 6; ss <= 9 * k; ss++) {
					if (i - (long) ss * p10 >= 0) {
						ndyn[i] = max(ndyn[i], dyn[i - ss * p10] + ((i - ss * p10) / s + (ss % 3 == 0 ? ss / 3 : 3 * k - 3)) * cf);
					}
				}
			}
			p10 *= 10;
			long t[] = dyn;
			dyn = ndyn;
			ndyn = t;
		}
		int q = scanInt();
		for (int qq = 0; qq < q; qq++) {
			out.println(dyn[scanInt()]);
		}
	}

	static int scanInt() throws IOException {
		return parseInt(scanString());
	}

	static long scanLong() throws IOException {
		return parseLong(scanString());
	}

	static String scanString() throws IOException {
		while (tok == null || !tok.hasMoreTokens()) {
			tok = new StringTokenizer(in.readLine());
		}
		return tok.nextToken();
	}

	static BufferedReader in;
	static PrintWriter out;
	static StringTokenizer tok;

	public static void main(String[] args) {
		try {
			in = new BufferedReader(new InputStreamReader(System.in));
			out = new PrintWriter(System.out);
			solve();
			in.close();
			out.close();
		} catch (Throwable e) {
			e.printStackTrace();
			exit(1);
		}
	}
}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;
import java.math.BigInteger;
import java.io.IOException;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskE1 solver = new TaskE1();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskE1 {
        static final int DENOM = 100;
        static final long MODULO = (long) 1e9 + 7;
        private static final long INVDENOM = BigInteger.valueOf(DENOM).modInverse(BigInteger.valueOf(MODULO)).longValue();
        int n;
        long[][] p;
        int[][] s;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            n = in.nextInt();
            p = new long[n][n];
            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < n; ++j) {
                    p[i][j] = in.nextInt() * INVDENOM % MODULO;
                }
            }
            int[] match = new int[n];
            Arrays.fill(match, -1);
            s = new int[n][n];
            int[] stack = new int[n];
            int[] via = new int[n];
            int[] ptr = new int[n];
            long res = rec(match, stack, via, ptr, -1, 0);
            out.println(res);
        }

        private long rec(int[] match, int[] stack, int[] via, int[] ptr, int sp, int next) {
            for (int i = 0; i < sp; ++i)
                if (via[stack[i]] == -1) {
                    throw new RuntimeException();
                }
            if (sp == 0) return 0;
            if (sp == -1) {
                if (next >= n) {
                    return 1;
                }
                Arrays.fill(via, -1);
                Arrays.fill(ptr, 0);
                Arrays.fill(stack, -1);
                stack[0] = next;
                via[next] = -2;
                return rec(match, stack, via, ptr, 1, next);
            } else {
                int cur = stack[sp - 1];
                int dest = ptr[cur];
                if (dest < n && match[dest] < 0) {
                    if (s[cur][dest] == 0) {
                        s[cur][dest] = 1;
                        long res = p[cur][dest] * rec(match, stack, via, ptr, sp, next);
                        s[cur][dest] = 2;
                        res += (1 - p[cur][dest]) * rec(match, stack, via, ptr, sp, next);
                        res %= MODULO;
                        if (res < 0) res += MODULO;
                        s[cur][dest] = 0;
                        return res;
                    }
                    if (s[cur][dest] == 1) {
                        int[] nmatch = match.clone();
                        int[] nstack = new int[n];
                        int[] nvia = new int[n];
                        int[] nptr = new int[n];
                        for (int i = 1; i < sp; ++i) {
                            nmatch[via[stack[i]]] = stack[i - 1];
                        }
                        nmatch[dest] = cur;
                        return rec(nmatch, nstack, nvia, nptr, -1, next + 1);
                    }
                }
                int ndest = dest - n;
                if (ndest >= 0 && ndest < n && match[ndest] >= 0 && via[match[ndest]] == -1) {
                    if (s[cur][ndest] == 0) {
                        s[cur][ndest] = 1;
                        long res = p[cur][ndest] * rec(match, stack, via, ptr, sp, next);
                        s[cur][ndest] = 2;
                        res += (1 - p[cur][ndest]) * rec(match, stack, via, ptr, sp, next);
                        res %= MODULO;
                        if (res < 0) res += MODULO;
                        s[cur][ndest] = 0;
                        return res;
                    }
                    if (s[cur][ndest] == 1) {
                        int md = match[ndest];
                        via[md] = ndest;
                        stack[sp] = md;
                        long res = rec(match, stack, via, ptr, sp + 1, next);
                        stack[sp] = -1;
                        via[md] = -1;
                        return res;
                    }
                }
                if (dest >= 2 * n) {
                    long res = rec(match, stack, via, ptr, sp - 1, next);
                    stack[sp - 1] = cur;
                    return res;
                } else {
                    ptr[cur] = dest + 1;
                    long res = rec(match, stack, via, ptr, sp, next);
                    ptr[cur] = dest;
                    return res;
                }
            }
        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

