    static class TaskC {
        public String get(long x) {
            String res = "";
            while (x >= 9) {
                res += '9';
                x -= 9;
            }
            if (x > 0)
                res += (char) ('0' + x);
            return res;
        }

        int get_length(long x) {
            if (x == 0)
                return 1;
            int cnt = 0;
            while (x > 0) {
                cnt++;
                x /= 10;
            }
            return cnt;
        }

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            long a = in.nextLong();
            if (a < 45) {
                for (int i = 0; i < a; i++)
                    out.print(1);
                out.print(' ');
                for (int i = 0; i < a; i++)
                    out.print(1);
                out.println();
                return;
            }
            long len = 0;
            for (long x = 1; x <= 16; x++) {
                long cnt = x * 45;
                for (int i = 0; i < x - 1; i++)
                    cnt *= 10;
                if (cnt <= a)
                    len = x;
            }
            long sum = len * 45, cnt = 10;
            for (int i = 0; i < len - 1; i++) {
                sum *= 10;
                cnt *= 10;
            }
            a -= sum;
            long l = 0, r = cnt - 1;
            l += a % cnt;
            r += a % cnt;
            String add = get(a / cnt);
            if (a / cnt == 0 && l == 0)
                l++;
            out.print(add);
            if (a / cnt != 0)
                for (int i = 0; i < get_length(r) - get_length(l); i++)
                    out.print(0);
            out.print(l + " ");
            out.print(add);
            out.println(r);
        }

    }

