	int isType2(int b, int d)
	{
		int[][] fb = factor(b, primes);
		int emax = 0;
		for(int[] f : fb){
			int e = 0;
			while(d % f[0] == 0){
				d /= f[0];
				e++;
			}
			emax = Math.max(emax, (e+f[1]-1)/f[1]);
		}
		return d != 1 ? 0 : emax;
	}

	boolean isType3(int b, int d)
	{
		if(b == 2)return false;
		return (b-1) % d == 0;
	}

	boolean isType11(int b, int d)
	{
		return (b+1) % d == 0;
	}

	boolean isType6(int b, int d)
	{
		int[][] fd = factor(d, primes);
		for(int[] f : fd){
			int mul = 1;
			for(int i = 0;i < f[1];i++){
				mul *= f[0];
			}
			if(isType2(b, mul) > 0 || isType3(b, mul) || isType11(b, mul)){
			}else{
				return false;
			}
		}
		return true;
	}

	public static int[][] factor(int n, int[] primes)
	{
		int[][] ret = new int[9][2];
		int rp = 0;
		for(int p : primes){
			if(p * p > n)break;
			int i;
			for(i = 0;n % p == 0;n /= p, i++);
			if(i > 0){
				ret[rp][0] = p;
				ret[rp][1] = i;
				rp++;
			}
		}
		if(n != 1){
			ret[rp][0] = n;
			ret[rp][1] = 1;
			rp++;
		}
		return Arrays.copyOf(ret, rp);
	}

