    static class DINOIFinalContests {
        int mod;
        Factorial fact;
        Combination comb;
        long[] f;
        long[] g;
        Debug debug = new Debug(true);

        public long g(int n) {
            if (n == 0) {
                return 0;
            }
            if (g[n] == -1) {
                long sum = 0;
                for (int i = 0; i < n; i++) {
                    int left = i;
                    int right = n - 1 - i;
                    //0.. left
                    //0.. right
                    long contrib = (g(left) * f(right) + g(right) * f(left)) % mod * (n - 1 + 2) % mod + f(left) * f(right) % mod * ((IntMath.sumOfInterval(0, left) +
                            IntMath.sumOfInterval(0, right)) % mod) % mod;
                    contrib = contrib % mod * comb.combination(n - 1, left) % mod;
                    sum += contrib;
                }
                g[n] = sum % mod;
            }
            return g[n];
        }

        public long f(int n) {
            if (n == 0) {
                return 1;
            }
            if (f[n] == -1) {
                long sum = 0;
                for (int i = 0; i < n; i++) {
                    int left = i;
                    int right = n - 1 - i;
                    sum += f(left) * comb.combination(n - 1, left) % mod * f(right) % mod * (n - 1 + 2) % mod;
                }
                f[n] = sum % mod;
            }
            return f[n];
        }

        public void solve(int testNumber, FastInput in, FastOutput out) {
            int n = in.readInt();
            int m = in.readInt();
            int p = in.readInt();
            mod = p;
            fact = new Factorial((int) 1e4, p);
            comb = new Combination(fact);

            f = new long[m + 1];
            g = new long[m + 1];
            Arrays.fill(f, -1L);
            Arrays.fill(g, -1L);

            long[][] dpWay = new long[n + 1][m + 1];
            long[][] dpSum = new long[n + 1][m + 1];
            dpWay[0][0] = 1;
            for (int i = 1; i <= n; i++) {
                for (int j = 0; j <= m && j <= i; j++) {
                    dpWay[i][j] = dpWay[i - 1][j];
                    dpSum[i][j] = dpSum[i - 1][j];
                    for (int k = 1; k <= j; k++) {
                        int prev = Math.max(i - k - 1, 0);
                        dpWay[i][j] += dpWay[prev][j - k] * comb.combination(j, k) % mod * f(k) % mod;
                        long local = dpSum[prev][j - k] * f(k) +
                                dpWay[prev][j - k] * g(k);
                        local = local % mod * comb.combination(j, k) % mod;
                        dpSum[i][j] += local;
                    }
                    dpWay[i][j] %= mod;
                    dpSum[i][j] %= mod;
                }
            }

            long ans = dpSum[n][m];
            debug.debug("f", f);
            debug.debug("g", g);
            debug.debug("dpWay", dpWay);
            debug.debug("dpSum", dpSum);
            out.println(ans);
        }

    }

    static class Combination implements IntCombination {
        final Factorial factorial;
        int modVal;

        public Combination(Factorial factorial) {
            this.factorial = factorial;
            this.modVal = factorial.getMod();
        }

        public Combination(int limit, int mod) {
            this(new Factorial(limit, mod));
        }

        public int combination(int m, int n) {
            if (n > m || n < 0) {
                return 0;
            }
            return (int) ((long) factorial.fact(m) * factorial.invFact(n) % modVal * factorial.invFact(m - n) % modVal);
        }

    }

    static class FastOutput implements AutoCloseable, Closeable, Appendable {
        private static final int THRESHOLD = 1 << 13;
        private final Writer os;
        private StringBuilder cache = new StringBuilder(THRESHOLD * 2);

        public FastOutput append(CharSequence csq) {
            cache.append(csq);
            return this;
        }

        public FastOutput append(CharSequence csq, int start, int end) {
            cache.append(csq, start, end);
            return this;
        }

        private void afterWrite() {
            if (cache.length() < THRESHOLD) {
                return;
            }
            flush();
        }

        public FastOutput(Writer os) {
            this.os = os;
        }

        public FastOutput(OutputStream os) {
            this(new OutputStreamWriter(os));
        }

        public FastOutput append(char c) {
            cache.append(c);
            afterWrite();
            return this;
        }

        public FastOutput append(long c) {
            cache.append(c);
            afterWrite();
            return this;
        }

        public FastOutput append(String c) {
            cache.append(c);
            afterWrite();
            return this;
        }

        public FastOutput println(long c) {
            return append(c).println();
        }

        public FastOutput println() {
            return append(System.lineSeparator());
        }

        public FastOutput flush() {
            try {
                os.append(cache);
                os.flush();
                cache.setLength(0);
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
            return this;
        }

        public void close() {
            flush();
            try {
                os.close();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        public String toString() {
            return cache.toString();
        }

    }

    static interface IntCombination {
    }

    static class Factorial {
        int[] fact;
        int[] inv;
        int mod;

        public int getMod() {
            return mod;
        }

        public Factorial(int[] fact, int[] inv, int mod) {
            this.mod = mod;
            this.fact = fact;
            this.inv = inv;
            fact[0] = inv[0] = 1;
            int n = Math.min(fact.length, mod);
            for (int i = 1; i < n; i++) {
                fact[i] = i;
                fact[i] = (int) ((long) fact[i] * fact[i - 1] % mod);
            }
            inv[n - 1] = BigInteger.valueOf(fact[n - 1]).modInverse(BigInteger.valueOf(mod)).intValue();
            for (int i = n - 2; i >= 1; i--) {
                inv[i] = (int) ((long) inv[i + 1] * (i + 1) % mod);
            }
        }

        public Factorial(int limit, int mod) {
            this(new int[limit + 1], new int[limit + 1], mod);
        }

        public int fact(int n) {
            return fact[n];
        }

        public int invFact(int n) {
            return inv[n];
        }

    }

