class TaskD {
	private int sign(double x) {
		if (Math.abs(x) < 1e-8) return 0;
		return (x > 0) ? 1 : -1;
	}
	public void solve(int testNumber, InputReader in, OutputWriter out) {
		double a = in.readDouble();
		double b = in.readDouble();
		double m = in.readDouble();
		double vx = in.readDouble();
		double vy = in.readDouble();
		double vz = in.readDouble();
		double x = a / 2, y = m, z = 0;
		while (true) {
			double minT = -y / vy;
			int flag = 0;
			if (sign(vx) > 0) {
				double t = (a - x) / vx;
				if (sign(t - minT) < 0) {
					minT = t;
					flag = 1;
				}
			}
			if (sign(vx) < 0) {
				double t = -x / vx;
				if (sign(t - minT) < 0) {
					minT = t;
					flag = 2;
				}
			}
			if (sign(vz) > 0) {
				double t = (b - z) / vz;
				if (sign(t - minT) < 0) {
					minT = t;
					flag = 3;
				}
			}
			if (sign(vz) < 0) {
				double t = -z / vz;
				if (sign(t - minT) < 0) {
					minT = t;
					flag = 4;
				}
			}
			x += minT * vx;
			y += minT * vy;
			z += minT * vz;
			if (flag == 0) break;
			if (flag == 1 || flag == 2) vx *= -1;
			if (flag == 3 || flag == 4) vz *= -1;
		}
		out.printDouble(x, 10);
		out.print(" ");
		out.printDouble(z, 10);
		out.printLine();
	}
}

class InputReader {
	private InputStream stream;
	private byte[] buf = new byte[1000];
	private int curChar;
	private int numChars;

	public InputReader(InputStream stream) {
		this.stream = stream;
	}

	private int read() {
		if (numChars == -1)
			throw new InputMismatchException();
		if (curChar >= numChars) {
			curChar = 0;
			try {
				numChars = stream.read(buf);
			} catch (IOException e) {
				throw new InputMismatchException();
			}
			if (numChars <= 0)
				return -1;
		}
		return buf[curChar++];
	}

	public double readDouble() {
		int c = read();
		while (isSpaceChar(c))
			c = read();
		int sgn = 1;
		if (c == '-') {
			sgn = -1;
			c = read();
		}
		double res = 0;
		while (!isSpaceChar(c) && c != '.') {
			if (c < '0' || c > '9')
				throw new InputMismatchException();
			res *= 10;
			res += c - '0';
			c = read();
		}
		if (c == '.') {
			c = read();
			double m = 1;
			while (!isSpaceChar(c)) {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				m /= 10;
				res += (c - '0') * m;
				c = read();
			}
		}
		return res * sgn;
	}

	private boolean isSpaceChar(int c) {
		return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
	}
}

class OutputWriter {
	private final PrintWriter writer;

	public OutputWriter(OutputStream outputStream) {
		writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
	}

	public OutputWriter(Writer writer) {
		this.writer = new PrintWriter(writer);
	}

	public void print(Object...objects) {
		for (int i = 0; i < objects.length; i++) {
			if (i != 0)
				writer.print(' ');
			writer.print(objects[i]);
		}
	}

	public void printDouble(double x, int precision) {
		writer.printf("%." + precision + "f", x);
	}

	public void printLine(Object...objects) {
		print(objects);
		writer.println();
	}

	public void close() {
		writer.close();
	}
}

