public class Main {
  BufferedReader br;
  int a, b, m, vx, vy, vz;
  BigDecimal t, x, z, x0, z0;

  public void go() throws Exception {
    br = new BufferedReader(new InputStreamReader(System.in));
    String[] ss = br.readLine().split(" ");
    a = Integer.parseInt(ss[0]);
    b = Integer.parseInt(ss[1]);
    m = Integer.parseInt(ss[2]);
    ss = br.readLine().split(" ");
    vx = Integer.parseInt(ss[0]);
    vy = Integer.parseInt(ss[1]);
    vz = Integer.parseInt(ss[2]);

    t = new BigDecimal(-m).divide(new BigDecimal(vy), 50, RoundingMode.UP);
    x = new BigDecimal(a).divide(new BigDecimal(2), 50, RoundingMode.UP).add(new BigDecimal(vx).multiply(t));
    z = new BigDecimal(vz).multiply(t);

    if (x.compareTo(BigDecimal.ZERO) != -1) {
      x0 = x.divideAndRemainder(new BigDecimal(2*a))[1];
      if (x0.intValue() >= a)
        x0 = new BigDecimal(2*a).subtract(x0);
    }
    else {
      x = x.negate();
      x0 = x.divideAndRemainder(new BigDecimal(2*a))[1];
      if (x0.intValue() >= a)
        x0 = new BigDecimal(2*a).subtract(x0);
    }

    z0 = z.divideAndRemainder(new BigDecimal(2*b))[1];
    if (z0.intValue() > b)
      z0 = new BigDecimal(2*b).subtract(z0);

    System.out.format("%.10f %.10f%n", x0.doubleValue(), z0.doubleValue());
  }

  public static void main(String[] args) throws Exception {
    new Main().go();
  }
}

