            for(; scan.hasNext();) {
                long a, b, c;
                a = scan.nextLong();
                b = scan.nextLong();
                c = scan.nextLong();
                long res = calc(a, b, c);
                long r = calc(b, a, c);
                if(r < res) res = r;
                r = calc(c, a, b);
                if(r < res) res = r;
