        } */
        finally {
            print.close();
        }       
    }

    private long calc(long a, long b, long c) {
        long d = Math.min(b, c);
        a += d;
        b -= d;
        c -= d;
        if(b == 0) {
            b = c;
            c = 0;
        }
        if((b & 1) == 1) return d + a + b - 1;
        else if(a > 0) return d + b;
        else return d + a + b - 1;
    }

}

