import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * @author Don Li
 */
public class FindACar2 {

    int N = 31;
    int MOD = (int) 1e9 + 7;

    void solve() {
        int q = in.nextInt();
        while (q-- > 0) {
            int x1 = in.nextInt() - 1, y1 = in.nextInt() - 1, x2 = in.nextInt() - 1, y2 = in.nextInt() - 1, k = in.nextInt() - 1;

            long ans = 0;
            ans = add(ans, calc(x2, y2, k));
            ans = sub(ans, calc(x1 - 1, y2, k));
            ans = sub(ans, calc(x2, y1 - 1, k));
            ans = add(ans, calc(x1 - 1, y1 - 1, k));

            out.println(ans);
        }
    }

    int calc(int x, int y, int k) {
        if (x < 0 || y < 0) return 0;

        int[][][][] cnt = new int[N + 1][2][2][2];
        int[][][][] sum = new int[N + 1][2][2][2];

        int[] a = new int[N], b = new int[N], c = new int[N];
        for (int i = 0; i < N; i++) {
            a[i] = (x >> i) & 1;
            b[i] = (y >> i) & 1;
            c[i] = (k >> i) & 1;
        }
        reverse(a);
        reverse(b);
        reverse(c);

        cnt[0][1][1][1] = 1;
        for (int i = 0; i < N; i++) {
            for (int p = 0; p < 2; p++) for (int q = 0; q < 2; q++) for (int r = 0; r < 2; r++) {
                for (int u = 0; u < 2; u++) for (int v = 0; v < 2; v++) {
                    int w = u ^ v;
                    if (p == 1 && u == 1 && a[i] == 0) continue;
                    if (q == 1 && v == 1 && b[i] == 0) continue;
                    if (r == 1 && w == 1 && c[i] == 0) continue;
                    int np = p == 1 && a[i] == u ? 1 : 0;
                    int nq = q == 1 && b[i] == v ? 1 : 0;
                    int nr = r == 1 && c[i] == w ? 1 : 0;
                    cnt[i + 1][np][nq][nr] = add(cnt[i + 1][np][nq][nr], cnt[i][p][q][r]);
                    sum[i + 1][np][nq][nr] = add(sum[i + 1][np][nq][nr], sum[i][p][q][r]);
                    sum[i + 1][np][nq][nr] = add(sum[i + 1][np][nq][nr], mul(w << (30 - i), cnt[i][p][q][r]));
                }
            }
        }

        long res = 0;
        for (int p = 0; p < 2; p++) for (int q = 0; q < 2; q++) for (int r = 0; r < 2; r++) {
            res = add(res, sum[N][p][q][r]);
            res = add(res, cnt[N][p][q][r]);
        }
        return (int) res;
    }

    void reverse(int[] a) {
        int l = 0, r = a.length - 1;
        while (l < r) {
            int tmp = a[l];
            a[l] = a[r];
            a[r] = tmp;
            l++;
            r--;
        }
    }

    int add(long a, long b) {
        return (int) ((a + b) % MOD);
    }

    int sub(long a, long b) {
        return (int) ((a - b + MOD) % MOD);
    }

    int mul(long a, long b) {
        return (int) (a * b % MOD);
    }

    public static void main(String[] args) {
        in = new FastScanner(new BufferedReader(new InputStreamReader(System.in)));
        out = new PrintWriter(System.out);
        new FindACar2().solve();
        out.close();
    }

    static FastScanner in;
    static PrintWriter out;

    static class FastScanner {
        BufferedReader in;
        StringTokenizer st;

        public FastScanner(BufferedReader in) {
            this.in = in;
        }

        public String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(in.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextToken());
        }

        public long nextLong() {
            return Long.parseLong(nextToken());
        }

        public double nextDouble() {
            return Double.parseDouble(nextToken());
        }
    }
}

