public class Main {

	private static final String NO = "NO";
	private static final String YES = "YES";
	InputStream is;
	PrintWriter out;
	String INPUT = "";

	private static final long MOD = 1000000007;

	void solve() {
		int T = 1;
		for (int i = 0; i < T; i++)
			solve(i);
	}

	long p[];

	void solve(int T) {
		int n = ni();
		p = new long[64];
		p[0] = 1;
		for (int i = 1; i < 60; i++)
			p[i] = p[i - 1] * 2;

		for (int i = 0; i < n; i++) {
			int a[] = na(5);
			long ans = work(a[2], a[3], a[4], 0) - work(a[0] - 1, a[3], a[4], 0) - work(a[2], a[1] - 1, a[4], 0)
					+ work(a[0] - 1, a[1] - 1, a[4], 0);
			ans %= MOD;
			out.println((ans + MOD) % MOD);
		}
	}

	long work(long x, long y, long k, long lazy) {
		if (x <= 0 || y <= 0)
			return 0;
		if (k <= 0)
			return 0;
		if (x > y) {
			long tmp = x;
			x = y;
			y = tmp;
		}
		int t = 0;
		while (p[t] <= y)
			t++;

		long ans;
		if (y == p[t - 1]) {
			long tmpa, tmpb;
			if (p[t - 1] < k)// all numbers is within [1..k], count them all
			{
				tmpa = p[t - 1];
				tmpa = tmpa * (tmpa + 1) / 2;
				tmpa %= MOD;
				tmpa *= x;
				tmpa %= MOD;
				tmpb = (lazy * y) % MOD;
				tmpb *= x;
				tmpb %= MOD;
				ans = (tmpa + tmpb) % MOD;
			} else// p[t-1]>=k only less or equal to k is needed
			{
				tmpa = k;
				tmpa = tmpa * (tmpa + 1) / 2;
				tmpa %= MOD;
				tmpa *= x;
				tmpa %= MOD;
				tmpb = (lazy * k) % MOD;
				tmpb *= x;
				tmpb %= MOD;
				ans = (tmpa + tmpb) % MOD;
			}
		} else// y > p[t-1]
		{
			if (x < p[t - 1]) {
				ans = work(x, p[t - 1], k, lazy);
				ans = (ans + work(x, y - p[t - 1], k - p[t - 1], lazy + p[t - 1])) % MOD;
			} else {
				ans = work(p[t - 1], p[t - 1], k, lazy);
				ans = (ans + work(x - p[t - 1], p[t - 1], k - p[t - 1], lazy + p[t - 1])) % MOD;
				ans = (ans + work(p[t - 1], y - p[t - 1], k - p[t - 1], lazy + p[t - 1])) % MOD;
				ans = (ans + work(x - p[t - 1], y - p[t - 1], k, lazy)) % MOD;
			}
		}
//		tr(x, y, k, lazy, ans);

		return ans;
	}

	// a^b
	long power(long a, long b) {
		long x = 1, y = a;
		while (b > 0) {
			if (b % 2 != 0) {
				x = (x * y) % MOD;
			}
			y = (y * y) % MOD;
			b /= 2;
		}
		return x % MOD;
	}

	private long gcd(long a, long b) {
		while (a != 0) {
			long tmp = b % a;
			b = a;
			a = tmp;
		}
		return b;
	}

	void run() throws Exception {
		is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
		out = new PrintWriter(System.out);

		long s = System.currentTimeMillis();
		solve();
		out.flush();
		if (!INPUT.isEmpty())
			tr(System.currentTimeMillis() - s + "ms");
	}

