			}
			else {
				answer = answer(x2, y2, k) - answer(x1-1, y2, k) - answer(x2, y1-1, k) + answer(x1-1, y1-1, k);
			}
			answer %= 1000000007;
			if (answer < 0)
				answer += 1000000007;
			pw.println(answer);
		}
		pw.close();
	}

	public static int answer(int m, int n, int k) {
		int tmp = m;
		int counter = 0;
		int counter2 = 0;
		while (tmp > 0) {
			if (tmp%2 == 1)
				counter++;
			counter2++;
			tmp = tmp/2;
		}
		int[][] mlist = new int[counter][2];
		counter--;
		for (int i = counter2-1; i >= 0; i--) {
			if ((m >> i)%2 == 1) {
				mlist[counter][0] = (m >> i)-1;
				mlist[counter][1] = i;
				counter--;
			}
		}

		tmp = n;
		counter = 0;
		counter2 = 0;
		while (tmp > 0) {
			if (tmp%2 == 1)
				counter++;
			counter2++;
			tmp = tmp/2;
		}
		int[][] nlist = new int[counter][2];
		counter--;
		for (int i = counter2-1; i >= 0; i--) {
			if ((n >> i)%2 == 1) {
				nlist[counter][0] = (n >> i)-1;
				nlist[counter][1] = i;
				counter--;
			}
		}

		int answer = 0;

		for (int i = 0; i < mlist.length; i++) {
			for (int j = 0; j < nlist.length; j++) {
				answer = (answer + sum(mlist[i][1], nlist[j][1], mlist[i][0], nlist[j][0], k))%1000000007;
			}
		}

		return answer;
	}

	public static int sum(int m, int n, int r, int s, int k) {
		if (m < n) {
			int temp = m;
			m = n;
			n = temp;
			temp = r;
			r = s;
			s = temp;
		}
		int t = s >> (m-n);
		int u = r^t;
		long val = 0;
		if (k > u*global[m]) {
			int min = u*global[m];
			int max = Math.min(k, (u+1)*global[m]);
			val = (((long) max)*((long) max+1))/2 - (((long) min)*((long)min+1))/2;
		}
		val %= 1000000007;
		val *= global[n];
		val %= 1000000007;
		return (int) val;
	}

}

