public class FindACar {

    int N = 30;
    int MOD = (int) 1e9 + 7;

    int a, b, c;

    int[][][][] dp = new int[N + 1][2][2][2];
    int[][][][] cnt = new int[N + 1][2][2][2];

    void solve() {
        int q = in.nextInt();
        while (q-- > 0) {
            int x1 = in.nextInt() - 1, y1 = in.nextInt() - 1, x2 = in.nextInt() - 1, y2 = in.nextInt() - 1, k = in.nextInt() - 1;

            long ans = 0;
            ans = (ans + calc(x2, y2, k)) % MOD;
            ans = (ans - calc(x1 - 1, y2, k) + MOD) % MOD;
            ans = (ans - calc(x2, y1 - 1, k) + MOD) % MOD;
            ans = (ans + calc(x1 - 1, y1 - 1, k)) % MOD;

            out.println(ans);
        }
    }

    int calc(int x, int y, int k) {
        if (x < 0 || y < 0) return 0;

        for (int i = 0; i <= N; i++)
            for (int j = 0; j < 2; j++)
                for (int u = 0; u < 2; u++) 
                    for (int v = 0; v < 2; v++) 
                        dp[i][j][u][v] = cnt[i][j][u][v] = -1;

        a = x;
        b = y;
        c = k;
        return dfs1(N, 1, 1, 1);
    }

    int dfs1(int i, int ea, int eb, int ec) {
        if (i < 0) return 1;
        if (dp[i][ea][eb][ec] >= 0) return dp[i][ea][eb][ec];

        int bit_a = (a >> i) & 1;
        int bit_b = (b >> i) & 1;
        int bit_c = (c >> i) & 1;

        long res = 0;

        int nec = ec == 1 && bit_c == 0 ? 1 : 0;
        int nea = ea == 1 && bit_a == 0 ? 1 : 0;
        int neb = eb == 1 && bit_b == 0 ? 1 : 0;
        res = (res + dfs1(i - 1, nea, neb, nec)) % MOD;

        if ((eb == 0 || bit_b == 1) && (ec == 0 || bit_c == 1)) {
            nec = ec == 1 && bit_c == 1 ? 1 : 0;
            nea = ea == 1 && bit_a == 0 ? 1 : 0;
            neb = eb == 1 && bit_b == 1 ? 1 : 0;
            res = (res + (1L << i) * dfs2(i - 1, nea, neb, nec) % MOD + dfs1(i - 1, nea, neb, nec)) % MOD;
        }

        if ((ea == 0 || bit_a == 1) && (ec == 0 || bit_c == 1)) {
            nec = ec == 1 && bit_c == 1 ? 1 : 0;
            nea = ea == 1 && bit_a == 1 ? 1 : 0;
            neb = eb == 1 && bit_b == 0 ? 1 : 0;
            res = (res + (1L << i) * dfs2(i - 1, nea, neb, nec) % MOD + dfs1(i - 1, nea, neb, nec)) % MOD;
        }

        if ((ea == 0 || bit_a == 1) && (eb == 0 || bit_b == 1)) {
            nec = ec == 1 && bit_c == 0 ? 1 : 0;
            nea = ea == 1 && bit_a == 1 ? 1 : 0;
            neb = eb == 1 && bit_b == 1 ? 1 : 0;
            res = (res + dfs1(i - 1, nea, neb, nec)) % MOD;
        }

        return dp[i][ea][eb][ec] = (int) res;
    }

    int dfs2(int i, int ea, int eb, int ec) {
        if (i < 0) return 1;
        if (cnt[i][ea][eb][ec] >= 0) return cnt[i][ea][eb][ec];

        int bit_a = (a >> i) & 1;
        int bit_b = (b >> i) & 1;
        int bit_c = (c >> i) & 1;

        long res = 0;

        int nec = ec == 1 && bit_c == 0 ? 1 : 0;
        int nea = ea == 1 && bit_a == 0 ? 1 : 0;
        int neb = eb == 1 && bit_b == 0 ? 1 : 0;
        res = (res + dfs2(i - 1, nea, neb, nec)) % MOD;

        if ((eb == 0 || bit_b == 1) && (ec == 0 || bit_c == 1)) {
            nec = ec == 1 && bit_c == 1 ? 1 : 0;
            nea = ea == 1 && bit_a == 0 ? 1 : 0;
            neb = eb == 1 && bit_b == 1 ? 1 : 0;
            res = (res + dfs2(i - 1, nea, neb, nec)) % MOD;
        }

        if ((ea == 0 || bit_a == 1) && (ec == 0 || bit_c == 1)) {
            nec = ec == 1 && bit_c == 1 ? 1 : 0;
            nea = ea == 1 && bit_a == 1 ? 1 : 0;
            neb = eb == 1 && bit_b == 0 ? 1 : 0;
            res = (res + dfs2(i - 1, nea, neb, nec)) % MOD;
        }

        if ((ea == 0 || bit_a == 1) && (eb == 0 || bit_b == 1)) {
            nec = ec == 1 && bit_c == 0 ? 1 : 0;
            nea = ea == 1 && bit_a == 1 ? 1 : 0;
            neb = eb == 1 && bit_b == 1 ? 1 : 0;
            res = (res + dfs2(i - 1, nea, neb, nec)) % MOD;
        }

        return cnt[i][ea][eb][ec] = (int) res;
    }

    public static void main(String[] args) {
        in = new FastScanner(new BufferedReader(new InputStreamReader(System.in)));
        out = new PrintWriter(System.out);
        new FindACar().solve();
        out.close();
    }

    static FastScanner in;
    static PrintWriter out;

    static class FastScanner {
        BufferedReader in;
        StringTokenizer st;

        public FastScanner(BufferedReader in) {
            this.in = in;
        }

        public String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(in.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
