import static java.util.Arrays.fill;

/**
 * @author Don Li
 */
public class WrapAround2 {

    int N = 41;

    int n, m;
    char[] s;

    int[] f;
    long[][][][] dp = new long[N][N][N][2];

    void solve() {
        n = in.nextInt();
        s = in.nextToken().toCharArray();
        m = s.length;

        f = fail(s);

        for (int i = 0; i < N; i++) for (int j = 0; j < N; j++) for (int k = 0; k < N; k++) fill(dp[i][j][k], -1);

        long ans = 0;
        for (int i = 0; i <= m; i++) {
            ans += dfs(n, i, i, 0);
        }
        out.println(ans);
    }

    long dfs(int rem, int cur, int tar, int has) {
        if (cur == m) has = 1;

        if (rem == 0) {
            return cur == tar && has > 0 ? 1 : 0;
        }

        if (dp[rem][cur][tar][has] >= 0) return dp[rem][cur][tar][has];

        long ans = 0;
        for (char x = '0'; x <= '1'; x++) {
            int nxt = next(cur, x);
            ans += dfs(rem - 1, nxt, tar, has);
        }
        return dp[rem][cur][tar][has] = ans;
    }

    int next(int now, char x) {
        if (now == m) now = f[now];
        while (now > 0 && s[now] != x) now = f[now];
        return s[now] == x ? now + 1 : 0;
    }

    int[] fail(char[] s) {
        int n = s.length;
        int[] f = new int[n + 1];
        f[0] = f[1] = 0;
        for (int i = 2; i <= n; i++) {
            int j = f[i - 1];
            while (j > 0 && s[j] != s[i - 1]) j = f[j];
            f[i] = s[j] == s[i - 1] ? j + 1 : 0;
        }
        return f;
    }

    public static void main(String[] args) {
        in = new FastScanner(new BufferedReader(new InputStreamReader(System.in)));
        out = new PrintWriter(System.out);
        new WrapAround2().solve();
        out.close();
    }

    static FastScanner in;
    static PrintWriter out;

    static class FastScanner {
        BufferedReader in;
        StringTokenizer st;

        public FastScanner(BufferedReader in) {
            this.in = in;
        }

        public String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(in.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextToken());
        }

        public long nextLong() {
            return Long.parseLong(nextToken());
        }

        public double nextDouble() {
            return Double.parseDouble(nextToken());
        }
    }
}

