            for (int j = i; j < m; j++) {
                String sub = s.substring(i, j + 1);
                if (!str_to_idx.containsKey(sub)) {
                    str_to_idx.put(sub, str_to_idx.size());
                    subs.add(sub);
                }
                if (i == 0) pref.add(sub);
            }
        }

        dp[0][0][0][0] = 1;
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j < 2; j++) {
                for (int k = 0; k <= n; k++) {
                    for (int l = 0; l < subs.size(); l++) {
                        dfs(i, j, k, l);
                    }
                }
            }
        }
        out.println(ans);
    }

    void dfs(int len, int has, int pre, int suf) {
        if (dp[len][has][pre][suf] == 0) return;
        if (len == n) {
            if (has > 0) {
                ans += dp[len][has][pre][suf];
            } else {
                String cur = s.substring(0, pre) + subs.get(suf);
                if (cur.contains(s)) ans += dp[len][has][pre][suf];
            }
            return;
        }
        add(len, has, pre, suf, 0);
        add(len, has, pre, suf, 1);
    }

    void add(int len, int has, int pre, int suf, int x) {
        String cur = s.substring(0, pre) + x;
        while (!pref.contains(cur)) cur = cur.substring(1);
        int nhas = has;
        if (cur.length() == s.length()) nhas = 1;
        int npre = cur.length();
        cur = subs.get(suf) + x;
        int nsuf = suf;
        if (cur.length() == len + 1 && str_to_idx.containsKey(cur)) nsuf = str_to_idx.get(cur);
        dp[len + 1][nhas][npre][nsuf] += dp[len][has][pre][suf];
    }

    public static void main(String[] args) {
        in = new FastScanner(new BufferedReader(new InputStreamReader(System.in)));
        out = new PrintWriter(System.out);
        new WrapAround().solve();
        out.close();
    }

    static FastScanner in;
    static PrintWriter out;

    static class FastScanner {
        BufferedReader in;
        StringTokenizer st;

        public FastScanner(BufferedReader in) {
            this.in = in;
        }

