	public class DSU1 {
		int[] p;
		int[] sz;
		Stack less;
		Stack more;
		PriorityQueue<Integer>[] q;
		boolean[] used;

		@SuppressWarnings("unchecked")
		public DSU1(int[] v, int m) {
			int n = v.length;
			p = new int[n];
			sz = new int[n];
			q = new PriorityQueue[n];
			less = new Stack(m);
			more = new Stack(m);
			used = new boolean[n + 1];
			for (int i = 0; i < v.length; i++) {
				p[i] = i;
				sz[i] = 1;
				q[i] = new PriorityQueue<>();
				q[i].add(-v[i]);
			}
		}

		public int get(int x) {
			while (x != p[x]) {
				x = p[x];
			}
			return x;
		}

		public boolean unite(int a, int b) {
			int pa = get(a);
			int pb = get(b);
			if (pa == pb) {
				less.add(-1);
				more.add(-1);
				return false;
			}
			if (sz[pa] < sz[pb]) {
				p[pa] = pb;
				sz[pb] += sz[pa];

				less.add(pa);
				more.add(pb);
				for (int i : q[pa]) {
					q[pb].add(i);
				}
			} else {
				p[pb] = pa;
				sz[pa] += sz[pb];

				less.add(pb);
				more.add(pa);
				for (int i : q[pb]) {
					q[pa].add(i);
				}
			}
			return true;
		}

		public void popEdge() {
			int pa = less.pop();
			int pb = more.pop();
			if (pa < 0) {
				return;
			}
			p[pa] = pa;
			sz[pb] -= sz[pa];
		}

		public int poll(int x) {
			int px = get(x);
			while (!q[px].isEmpty()) {
				int v = -q[px].poll();
				if (!used[v] && get(inv[v - 1]) == px) {
					used[v] = true;
					return v;
				}
			}
			return 0;
		}
	}

	int[] inv;

	public void solve() {
		int n = in.nextInt();
		int m = in.nextInt();
		int q = in.nextInt();
		int[] v = new int[n];
		inv = new int[n];
		for (int i = 0; i < v.length; i++) {
			v[i] = in.nextInt();
			inv[v[i] - 1] = i;
		}
		int[] a = new int[m];
		int[] b = new int[m];
		for (int i = 0; i < b.length; i++) {
			a[i] = in.nextInt() - 1;
			b[i] = in.nextInt() - 1;
		}
		boolean[] type = new boolean[q];
		int[] x = new int[q];
		boolean[] removed = new boolean[m];
		for (int i = 0; i < q; i++) {
			if (in.nextInt() == 1) {
				x[i] = in.nextInt() - 1;
				type[i] = true;
			} else {
				x[i] = in.nextInt() - 1;
				removed[x[i]] = true;
			}
		}
		DSU1 dsu = new DSU1(v, m);
		for (int i = 0; i < removed.length; i++) {
			if (!removed[i]) {
				dsu.unite(a[i], b[i]);
			}
		}
		for (int i = q - 1; i >= 0; i--) {
			if (!type[i]) {
				dsu.unite(a[x[i]], b[x[i]]);
			}
		}
		for (int i = 0; i < q; i++) {
			if (type[i]) {
				out.println(dsu.poll(x[i]));
			} else {
				dsu.popEdge();
			}
		}
	}

