            Node(int max, Pair lr) {
                this.max = max;
                this.lr = lr;
            }
        }
        Node[] t;
        int size;

        void push(int u) {
            if (t[u].lr.l != -1) {
                t[u * 2 + 1].lr.l = t[u].lr.l;
                t[u * 2 + 1].lr.r = t[u].lr.r;
                t[u * 2 + 2].lr.l = t[u].lr.l;
                t[u * 2 + 2].lr.r = t[u].lr.r;
                t[u].lr.l = t[u].lr.r = -1;
            }
        }
        void pull(int u) {
            t[u].max = p[t[u * 2 + 1].max] > p[t[u * 2 + 2].max] ? t[u * 2 + 1].max : t[u * 2 + 2].max;
        }
        void build(int u, int tl, int tr, int[][] initial) {
            if (tl == tr) {
                t[u] = new Node(initial[tl][0], new Pair(initial[tl][1], initial[tl][2]));
            } else {
                int tm = (tl + tr) / 2;
                build(u * 2 + 1, tl, tm, initial);
                build(u * 2 + 2, tm + 1, tr, initial);
                t[u] = new Node(-1, new Pair(-1, -1));
                pull(u);
            }
        }
        int maxPOn(int u, int tl, int tr, int l, int r) {
