            int tm = (tl + tr) / 2;
            push(u);
            int v1 = maxPOn(u * 2 + 1, tl, tm, l, r);
            int v2 = maxPOn(u * 2 + 2, tm + 1, tr, l, r);
            return p[v1] > p[v2] ? v1 : v2;
