            setLROn(u * 2 + 2, tm + 1, tr, l, r, newL, newR);
            pull(u);
        }
        Pair LRIn(int u, int tl, int tr, int i) {
            if (tl == tr) {
                return t[u].lr;
            }
            int tm = (tl + tr) / 2;
            push(u);
            if (i <= tm) {
                return LRIn(u * 2 + 1, tl, tm, i);
            } else {
                return LRIn(u * 2 + 2, tm + 1, tr, i);
            }
        }

