class TaskD_EgorAndCaves {
    public static final int MOD = (int)1e9 + 7;

    public void solve(int testNumber, InputReader in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();

        if (m < 2) {
            out.println(0);
            return;
        }
        long[][] dp = new long[n+1][m+1];
        long[][] lastRow = new long[n+1][m+1];

        for (int width = 2; width <= m; ++width) {
            dp[0][width] = 1;
        }
        long[] sum = new long[m+1];
        long[] sum2 = new long[m+1];
        for (int row = 1; row < n; ++row) {
            sum[0] = sum[1] = 0;
            sum2[0] = sum2[1] = 0;
            for (int i = 2; i <= m; ++i) {
                sum[i] = sum[i-1] + dp[row-1][i];
                if (sum[i] >= MOD) sum[i] -= MOD;
                sum2[i] = sum2[i-1] + (dp[row-1][i] * i) % MOD;
                if (sum2[i] >= MOD) sum2[i] -= MOD;
            }
            for (int width = 2; width <= m; ++width) {
                dp[row][width] = 1;
                lastRow[row][width] = 0;
                dp[row][width] += ((width + 1) * sum[width]) % MOD;
                if (dp[row][width] >= MOD) {
                    dp[row][width] -= MOD;
                }
                dp[row][width] -= sum2[width];
                if (dp[row][width] < 0) {
                    dp[row][width] += MOD;
                }
                lastRow[row][width] += ((width + 1) * sum[width-1]) % MOD;
                if (lastRow[row][width] >= MOD) {
                    lastRow[row][width] -= MOD;
                }
                lastRow[row][width] -= sum2[width-1];
                if (lastRow[row][width] < 0) {
                    lastRow[row][width] += MOD;
                }
            }
        }

        long res = 0;
        for (int t = 0; t < n; ++t) {
            for (int width = 2; width <= m; ++width) {
                res += ((dp[t][width]) % MOD) * (m - width + 1) % MOD;
                if (res >= MOD) {
                    res -= MOD;
                }
                res += ((dp[t][width] * lastRow[n - t - 1][width]) % MOD) * (m - width + 1) % MOD;
                if (res >= MOD) {
                    res -= MOD;
                }
            }
        }
        out.println(res);
    }
}

