						l=mid+1;
					}
				}

				if (t+sz*t1<=T)
					cost=Math.min(cost, k2*p2+((sz+a1-1)/a1)*p1);

				if (result!=-1)
				{
					cost=Math.min(cost, k2*p2+result*p1);
				}

			}

			if (f*t2<=T)
				cost=Math.min(cost, ((f+a2-1)/a2)*p2);
		}

		if (cost==MAX)
			out.println(-1);
		else
