import java.util.StringTokenizer;
import java.io.IOException;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskC {
        final long infinity = Long.MAX_VALUE / 3;
        FastScanner in;

        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            this.in = in;
            long bytesLeft0 = assertedNextInt();
            long timeLeft0 = assertedNextInt();
            long t0 = assertedNextInt();

            long a1 = assertedNextInt();
            long t1 = assertedNextInt();
            long p1 = assertedNextInt();

            long a2 = assertedNextInt();
            long t2 = assertedNextInt();
            long p2 = assertedNextInt();
            long u = solve(bytesLeft0, timeLeft0, t0, a1, t1, p1, a2, t2, p2);
            long v = solve(bytesLeft0, timeLeft0, t0, a2, t2, p2, a1, t1, p1);
            long ans = Math.min(u, v);
            if (ans >= infinity) {
                ans = -1;
            }
            out.println(ans);
        }

        private long solve(long bytesLeft0, long timeLeft0, long t0, long a1, long t1, long p1, long a2, long t2, long p2) {
            final int N = (int) 1e7 + 20;
            long ans = infinity;
            for (int k1 = 0; k1 <= N; k1++) {
                long cost1 = k1 * p1;
                long bytesDownloaded1 = Math.min(bytesLeft0, k1 * a1);
                long time1 = bytesDownloaded1 * t1;
                long bytesLeft1 = bytesLeft0 - bytesDownloaded1;
                long timeLeft1 = timeLeft0 - time1;
                if (timeLeft1 < 0) {
                    continue;
                }
                if (bytesLeft1 == 0) {
                    ans = Math.min(ans, cost1);
                    continue;
                }
                if (t0 * bytesLeft1 <= timeLeft1) {
                    ans = Math.min(ans, cost1);
                    continue;
                }
                if (t0 <= t2) {
                    continue;
                }
                if (bytesLeft1 * t2 > timeLeft1) {
                    continue;
                }
                long bytes0 = Math.min(bytesLeft1, (timeLeft1 - bytesLeft1 * t2) / (t0 - t2));
                long bytes2 = bytesLeft1 - bytes0;
                long k2 = (bytes2 + a2 - 1) / a2;

                long cost2 = k2 * p2;
                ans = Math.min(ans, cost1 + cost2);
            }
            return ans;
        }

        private long assertedNextInt() {
            long x = in.nextLong();
            if (x < 1 || x > (int) 1e7) {
                throw new AssertionError();
            }
            return x;
        }

    }

    static class FastScanner {
        private BufferedReader in;
        private StringTokenizer st;

        public FastScanner(InputStream stream) {
            in = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(in.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

    }
}

import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Scanner;

public class Main {
	private static Scanner in;
	private static PrintWriter out;
	private static final int MOD = (int)1e9 + 7;

	private static int n;
	private static int[] a, degIn;
	private static ArrayList<Integer> s, t;
	private static boolean[] visited;
	private static ArrayList<Integer>[] graph;

	private static boolean isSubset(int a, int b) {
		return (a & b) == a;
	}

	private static boolean isIntersect(int a, int b) {
		return (a & b) != 0;
	}

	// Solve for each weakly connected component (WCC)
	private static int cntOrder(ArrayList<Integer> s, ArrayList<Integer> t) {
		int p = s.size(), m = t.size();

		int[] inMask = new int[m];
		for(int x = 0; x < p; ++x)
			for(int i = 0; i < m; ++i)
				if (t.get(i) % s.get(x) == 0)
					inMask[i] |= 1 << x;

		int[] cnt = new int[1<<p];
		for(int mask = 0; mask < (1<<p); ++mask)
			for(int i = 0; i < m; ++i)
				if (isSubset(inMask[i], mask))
					++cnt[mask];

		int[][] dp = new int[m+1][1<<p];
		for(int i = 0; i < m; ++i)
			dp[1][inMask[i]] += 1;
		for(int k = 1; k < m; ++k) {
			for(int mask = 0; mask < (1<<p); ++mask) {
				for(int i = 0; i < m; ++i)
					if (!isSubset(inMask[i], mask) && isIntersect(inMask[i], mask))
						dp[k+1][mask | inMask[i]] = (int)((dp[k+1][mask | inMask[i]] + dp[k][mask]) % MOD);
				dp[k+1][mask] = (int)((dp[k+1][mask] + (long)dp[k][mask] * (cnt[mask] - k)) % MOD);
			}
		}

		return dp[m][(1<<p)-1];
	}

	private static void dfs(int u) {
		visited[u] = true;
		if (degIn[u] == 0)
			s.add(a[u]);
		else
			t.add(a[u]);

		for(int v: graph[u])
			if (!visited[v])
				dfs(v);
	}

	private static void input() {
		n = in.nextInt();
		a = new int[n];
		for(int u = 0; u < n; ++u)
			a[u] = in.nextInt();
	}

	private static void solve() {
		// Pre-calculate C(n, k)
		int[][] c = new int[n][n];
		for(int i = 0; i < n; ++i) {
			c[i][0] = 1;
			for(int j = 1; j <= i; ++j)
				c[i][j] = (c[i-1][j-1] + c[i-1][j]) % MOD;
		}

		// Building divisibility graph
		degIn = new int[n];
		graph = new ArrayList[n];
		for(int u = 0; u < n; ++u)
			graph[u] = new ArrayList<>();
		for(int u = 0; u < n; ++u) {
			for(int v = 0; v < n; ++v) {
				if (u != v && a[v] % a[u] == 0) {
					graph[u].add(v);
					graph[v].add(u);
					++degIn[v];
				}
			}
		}

		// Solve for each WCC of divisibility graph and combine result
		int ans = 1;
		int curLen = 0;
		visited = new boolean[n];
		for(int u = 0; u < n; ++u) {
			if (!visited[u]) {
				s = new ArrayList<>();
				t = new ArrayList<>();
				dfs(u);

				if (!t.isEmpty()) {
					int sz = t.size() - 1;
					int cnt = cntOrder(s, t);

					// Number of orders for current WCC
					ans = (int)(((long)ans * cnt) % MOD);
					// Number of ways to insert <sz> number to array of <curLen> elements
					ans = (int)(((long)ans * c[curLen + sz][sz]) % MOD);
					curLen += sz;
				}
			}
		}

		out.println(ans);
	}

	public static void main(String[] args) {
		in = new Scanner(System.in);
		out = new PrintWriter(System.out);

		input();
		solve();

		out.close();
	}
}

