        int log_n = (int) (Math.log(n)/Math.log(2))+1;
        if (b > log_n) {
            System.out.println("Missing");
            return;
        }
        if (a > sqrt_n) {
            if ((n-a) % 2==0)
                System.out.println("Masha");
            else
                System.out.println("Stas");
            return;
        }
        int[][]dp = new int[sqrt_n+1][log_n+1];
        if ((n-sqrt_n) % 2==0)
            dp[sqrt_n][1] = 1;
        for (int i = 2; i <= log_n; i++) {
            dp[sqrt_n][i] = 1;
        }
        for (int i = sqrt_n-1; i >= 2; i--) {
            long pow = i;
            int h = 1;
            while (pow < n) {
                pow *= i;
                h++;
            }
            h--;
            for (int j = h+1; j <= log_n; j++) {
                dp[i][j] = 1;
            }
            for (int j = h; j >= 1; j--) {
                if (dp[i+1][j]==0 || dp[i][j+1]==0)
                    dp[i][j] = 1;
            }
        }
        for (int i = log_n; i >= 1; i--) {
            if ((1 << (long)i) >= n)
                dp[1][i] = 2;
            else {
                if (dp[2][i]==1 && dp[1][i+1]==2)
                    dp[1][i] = 2;
                else
                    if (dp[2][i]==0 || dp[1][i+1]==0)
                        dp[1][i] = 1;
            }
        }
        if (dp[a][b]==1)
            System.out.println("Masha");
        else {
            if (dp[a][b]==0)
                System.out.println("Stas");
            else
                System.out.println("Missing");
        }
    }
}

