import java.io.*;
import java.util.*;

public class E implements Runnable {
	public static void main (String[] args) {new Thread(null, new E(), "_cf", 1 << 28).start();}

	int n;
	int MAX = 51;
	HashMap<Integer, Integer>[] dp;

	public void run() {
		FastScanner fs = new FastScanner();
		PrintWriter out = new PrintWriter(System.out);
		System.err.println("Go!");


		int a = fs.nextInt(), b = fs.nextInt();
		n = fs.nextInt();

		dp = new HashMap[MAX];
		for(int i = 0; i < MAX; i++) dp[i] = new HashMap<Integer, Integer>();

		int ret = solve(b, a);
		if(ret == 1) System.out.println("Masha");
		else if(ret == 0) System.out.println("Missing");
		else System.out.println("Stas");

		out.close();
	}

	//returns -1 if whoever is playing here loses
	//returns 1 otherwise
	int solve(int a, int b) {
		if(a >= MAX) { //draw
			return 0;
		}
		if(b >= 32000) {
			int moves = (n-1)-b;
			if(moves % 2 == 1) {
				return 1;
			}

			return -1;
		}
		if(dp[a].containsKey(b)) return dp[a].get(b);
//		System.out.printf("Items %d Boxes: %d\n", a, b);

		boolean canDraw = false;
		if(!isBad(a, b + 1)) { //increase number of boxes
			int ret = solve(a, b + 1);
			if(ret == -1) { //i win
				dp[a].put(b, 1);
				return 1;
			}
			canDraw |= ret == 0;
		}

		if(!isBad(a + 1, b)) { //increase number of items
			int ret = solve(a + 1, b);
			if(ret == -1) {
				dp[a].put(b, 1);
				return 1;
			}
			canDraw |= ret == 0;
		}

		int ret = -1;
		if(canDraw) ret = 0;

		dp[a].put(b, ret);
		return ret;
	}

	boolean isBad(int a, int b) {
		double one = a * Math.log(b);
		double two = Math.log(n);
		return one > two || Math.abs(one-two) < 1e-9;
	}

	class FastScanner {
		public int BS = 1<<16;
		public char NC = (char)0;
		byte[] buf = new byte[BS];
		int bId = 0, size = 0;
		char c = NC;
		double num = 1;
		BufferedInputStream in;

		public FastScanner() {
			in = new BufferedInputStream(System.in, BS);
		}

		public FastScanner(String s) throws FileNotFoundException {
			in = new BufferedInputStream(new FileInputStream(new File(s)), BS);
		}

		public char nextChar(){
			while(bId==size) {
				try {
					size = in.read(buf);
				}catch(Exception e) {
					return NC;
				}                
				if(size==-1)return NC;
				bId=0;
			}
			return (char)buf[bId++];
		}

		public int nextInt() {
			return (int)nextLong();
		}

		public long nextLong() {
			num=1;
			boolean neg = false;
			if(c==NC)c=nextChar();
			for(;(c<'0' || c>'9'); c = nextChar()) {
				if(c=='-')neg=true;
			}
			long res = 0;
			for(; c>='0' && c <='9'; c=nextChar()) {
				res = (res<<3)+(res<<1)+c-'0';
				num*=10;
			}
			return neg?-res:res;
		}

		public double nextDouble() {
			double cur = nextLong();
			return c!='.' ? cur:cur+nextLong()/num;
		}

		public String next() {
			StringBuilder res = new StringBuilder();
			while(c<=32)c=nextChar();
			while(c>32) {
				res.append(c);
				c=nextChar();
			}
			return res.toString();
		}

		public String nextLine() {
			StringBuilder res = new StringBuilder();
			while(c<=32)c=nextChar();
			while(c!='\n') {
				res.append(c);
				c=nextChar();
			}
			return res.toString();
		}

		public boolean hasNext() {
			if(c>32)return true;
			while(true) {
				c=nextChar();
				if(c==NC)return false;
				else if(c>32)return true;
			}
		}

		public int[] nextIntArray(int n) {
			int[] res = new int[n];
			for(int i = 0; i < n; i++) res[i] = nextInt();
			return res;
		}

	}


}

