public class E {

	static StreamTokenizer in =
		new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));

	static int nextInt() throws IOException{
		in.nextToken();
		return (int)in.nval;
	}

	static PrintWriter out = new PrintWriter(System.out);

	public static void main(String[] args) throws IOException{
		int a = nextInt(),
			b = nextInt(),
			n = nextInt();

		if (a==1 && Math.pow(2, b)>=n){
			out.println("Missing");
			out.flush();
			return;
		}

		int B[] = new int[100];
		B[1] = n-1;
		int p = (int)Math.sqrt(n);
		if (p*p == n)
			p--;
		B[2] = p;
		for (int i=3; i<=30; i++)
			for (int j=p; j>=2; j--)
				if (Math.pow(j, i) < n){
					B[i] = j;
					p = j;
					break;
				}

		int x = 1000000000,
			y = 1000000000;
		for (int i=b; i<=30; i++)
			if (B[i]!=B[i+1] && B[i]>=a){
				if (i-b == B[i]-a){
					out.println("Stas");
					out.flush();
					return;
				}
				else{
					if (i-b > B[i]-a)
						x = Math.min(x, i-b-(B[i]-a));
					else
						y = Math.min(y, B[i]-a-(i-b));
				}
			}

		if (x%2==0 && y%2==0){
			out.println("Stas");
			out.flush();
			return;
		}
		else if (x%2==1 && y%2==1){
			out.println("Masha");
			out.flush();
			return;
		}

		int u = a, v = b;
		while (Math.pow(u, v) < n){
			u++;
			v++;
		}

		u--;
		v--;
		if (x%2==1 && Math.pow(u, v+1)<n || y%2==1 && Math.pow(u+1, v)<n){
			out.println("Masha");
			out.flush();
			return;
		}
		else{
			out.println("Stas");
			out.flush();
			return;
		}
	}

}

