	static long pow(int a, int k, long p) {
		long m = k;
		long ans = 1;

		// curr = k^(2^i)
		long curr = a;

		// k^(2x+1) = (k^x)^2 * k
		while(m > 0) {
			if( (m&1) == 1 ) {
				ans *= curr;
				ans %= p;
			}
			m >>= 1;
			curr *= curr;
			curr %= p;
		}
		return ans;		
	}
	
	// computes a^(p-2)
	static long inverse(int a, long p) {
		return pow(a, (int)(p-2), p);
	}
	
	// static final long MOD = 998_244_353; // = 1 + 7*17*2^23
	// primitive root is 3, i.e., the order of 3 is MOD-1
	// we have to find the 1<<23-th root
	static final int ROOT = (int) pow(3, 7*17, MOD);
	static final int ROOT_INV = (int) pow(ROOT, (int)MOD - 2, MOD);
	static final int ORDER = 1 << 23;
	static final long W4 = pow(ROOT, (int)(MOD-1)/4, MOD);
	static final long W4_INV = pow(ROOT, (int)(MOD-1)/4*3, MOD);

	static void swap(long[] a, int i, int j) {
		long temp = a[i];
		a[i] = a[j];
		a[j] = temp;
	}
	static void fft(long[] a, boolean isInvertedFFT) {
	    int n = a.length;

	    for (int i = 1, j = 0; i < n; i++) {
	        int bit = n >> 1;
	        for (; (j & bit) > 0; bit >>= 1)
	            j ^= bit;
	        j ^= bit;

	        if (i < j) {
	        	swap(a, i, j);
	        }
	    }

	    for (int len = 2; len <= n; len <<= 1) {
	        long wlen = isInvertedFFT ? ROOT_INV : ROOT;
	        for (int i = len; i < ORDER; i <<= 1)
	            wlen = wlen * wlen % MOD;

	        for (int i = 0; i < n; i += len) {
	        	long w = 1;
	            for (int j = 0; j < len / 2; j++) {
	                long u = a[i+j];
	                long v = a[i+j+len/2] * w % MOD;
	                a[i+j] =  u + v < MOD ? u + v : u + v - MOD;
	                a[i+j+len/2] = u - v >= 0 ? u - v : u - v + MOD;
	                w = w * wlen % MOD;
	            }
	        }
	    }

	    if (isInvertedFFT) {
	        long inv = inverse(n, MOD);
	        for(int i=0; i<a.length; i++)
	        	a[i] = a[i]*inv%MOD;
	    }
	}
	
	static void fft4(long[] a, boolean isInvertedFFT) {
		int n = a.length;
		
	    for (int i = 1, j = 0; i < n; i++) {
	        int bit = n >> 1;
	        for (; (j & bit) > 0; bit >>= 1)
	            j ^= bit;
	        j ^= bit;

	        if (i < j) {
	        	swap(a, i, j);
	        }
	    }
		
		int parity = 0;
	    for (int len = 2; len <= n; len <<= 1)
	    	parity++;
	    
	    int len;
	    if(parity % 2 == 1) {
	    	len = 2;
		    if(len <= n) {
		        long wlen = isInvertedFFT ? ROOT_INV : ROOT;
		        for (int i = len; i < ORDER; i <<= 1)
		            wlen = wlen * wlen % MOD;

		        for (int i = 0; i < n; i += len) {
		        	long w = 1;
		            for (int j = 0; j < len / 2; j++) {
		                long u = a[i+j];
		                long v = a[i+j+len/2] * w % MOD;
		                a[i+j] =  u + v < MOD ? u + v : u + v - MOD;
		                a[i+j+len/2] = u - v >= 0 ? u - v : u - v + MOD;
		                w = w * wlen % MOD;
		            }
		        }
		        len *= 4;
		    }
	    }
	    else
	    	len = 4;

	    
	    for (; len <= n; len <<= 2) {
	        long wlen = isInvertedFFT ? ROOT_INV : ROOT;
	        long w4 = isInvertedFFT? W4_INV: W4;
	        for (int i = len; i < ORDER; i <<= 1)
	            wlen = wlen * wlen % MOD;

	        for (int i = 0; i < n; i += len) {
	        	long w = 1;
	            for (int j = 0; j < len / 4; j++) {
	            	long x0 = a[i+j];
	            	long x1 = a[i+j+len/2] * w % MOD;
	            	long x2 = a[i+j+len/4] * w % MOD;
	            	x2 = x2 * w % MOD;
	            	long x3 = a[i+j+len*3/4] * w % MOD;
	            	x3 = x3 * w % MOD;
	            	x3 = x3 * w % MOD;
	            	
	            	long y0 = x0 + x1 + x2 + x3;
	            	a[i+j] = y0 % MOD;
	            	long y1 = x0 + x1*w4 - x2 - x3*w4;
	            	y1 %= MOD;
	            	a[i+j+len*3/4] = y1 < 0? y1 + MOD: y1;
	            	long y2 = x0 - x1 + x2 - x3;
	            	y2 %= MOD;
	            	a[i+j+len/2] = y2 < 0? y2 + MOD: y2;
	            	long y3 = x0 - x1*w4 - x2 + x3*w4;
	            	y3 %= MOD;
	            	a[i+j+len/4] = y3 < 0? y3 + MOD: y3;
	            	
	            	w = w * wlen % MOD;
	            }
	        }
	    }

	    if (isInvertedFFT) {
	        long inv = inverse(n, MOD);
	        for(int i=0; i<a.length; i++)
	        	a[i] = a[i]*inv%MOD;
	    }
	}
	
	static void square(long[] a) {
	    fft4(a, false);
	    for (int i = 0; i < a.length; i++)
	        a[i] = a[i]*a[i] % MOD;
	    fft4(a, true);
	}
	
	static long[] multiplyPolynomial(long[] a, long[] b) {
	    int n = 1;
	    while (n < a.length + b.length) 
	        n <<= 1;
		long[] fa = Arrays.copyOf(a, n);
		long[] fb = Arrays.copyOf(b, n);

	    fft(fa, false);
	    fft(fb, false);
	    for (int i = 0; i < n; i++)
	        fa[i] = fa[i]*fb[i] % MOD;
	    fft(fa, true);
	    
	    return fa;
	}
	
