public class TaskD {
    public static void main(String[] args) {
        new TaskD().solve();
    }

    TaskD() {
    }

    int b, d, lenA, lenC;
    String a, c;
    int[][] next, delta;

    public void solve() {
        Scanner in = new Scanner(System.in);
        b = in.nextInt();
        d = in.nextInt();
        a = in.next();
        c = in.next();

        lenA = a.length();
        lenC = c.length();

        next = new int[lenA][lenC];
        delta = new int[lenA][lenC];
        for (int i = 0; i < lenA; ++i) {
            Arrays.fill(next[i], -1);
            Arrays.fill(delta[i], -1);

            for (int j = 0; j < lenC; ++j) {
                if (a.charAt(i) != c.charAt(j)) continue;

                int l = 1, dd = 0, lastL = 0;
                while (l <= lenA) {
                    int ii = (i + l) % lenA;
                    int jj = (j + dd + 1) % lenC;
                    if (a.charAt(ii) == c.charAt(jj)) {
                        ++dd;
                        lastL = l;
                    }
                    ++l;
                }

                if (lastL > 0) {
                    next[i][j] = lastL;
                    delta[i][j] = dd;
                }
            }
        }

        int cnt = 0, i = 0, j = 0;
        while (i < lenA && next[i][j] == -1) ++i;
        if (i >= lenA || next[i][j] == -1) {
            System.out.println(0);
            return;
        }

        while (next[i % lenA][j] != -1 && i + next[i % lenA][j] < lenA * b) {
            assert a.charAt(i % lenA) == c.charAt(j);
            int ii = i % lenA;
            int jj = j;
            cnt += delta[ii][jj];
            i += next[ii][jj];
            j = (j + delta[ii][jj]) % lenC;
        }

        if (next[i % lenA][j] != -1) {
            while (i < lenA * b) {
                if (a.charAt(i % lenA) == c.charAt(j)) {
                    ++cnt;
                    j = (j + 1) % lenC;
                }
                ++i;
            }
        }

        System.out.println(cnt / (d * lenC));
    }
}

