public class F {
 
    static int N = 250;
    static int M = 28;
    static int INF = (int) 1e9;
    static int[][][][] dp = new int[2][M * 2 + 1][N][N];
 
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder(br.readLine());
        String s = sb.reverse().append("0").toString();        
 
        for (int carry = 0; carry < M * 2 + 1; carry++) {
            for (int cp = 0; cp < N; cp++) {
                for (int cn = 0; cn < N; cn++) {
                    dp[0][carry][cp][cn] = INF;
                }
            }
        }
        dp[0][M][N - 1][N - 1] = 0;
 
        for (int i = 0; i < s.length(); i++) {
            for (int carry = 0; carry < M * 2 + 1; carry++) {
                for (int cp = 0; cp < N; cp++) {
                    for (int cn = 0; cn < N; cn++) {
                        dp[1][carry][cp][cn] = INF;
                    }
                }
            }
            for (int carry = 0; carry < M * 2 + 1; carry++) {
                for (int cp = N - 1; cp >= 0; cp--) {
                    for (int cn = N - 1; cn >= 0; cn--) {
                        if (dp[0][carry][cp][cn] != INF) {
                            if (cp > 0) {
                                dp[0][carry][cp - 1][cn] = Math.min(dp[0][carry][cp - 1][cn], dp[0][carry][cp][cn]);
                            }
                            if (cn > 0) {
                                dp[0][carry][cp][cn - 1] = Math.min(dp[0][carry][cp][cn - 1], dp[0][carry][cp][cn]);
                            }
                            int rcarry = carry - M;
                            int val = rcarry + cp - cn;
                            int digit = val % 10;
                            if (digit < 0) {
                                digit += 10;
                            }
                            int ncarry = val / 10;
                            if (val < 0 && digit != 0) {
                                --ncarry;
                            }
                            if (digit == s.charAt(i) - '0') {
                                dp[1][ncarry + M][cp][cn] = Math.min(dp[1][ncarry + M][cp][cn],
                                        dp[0][carry][cp][cn] + cp + cn);
                            }
                        }
                    }
                }
            }
            int[][][] tmp = dp[0];
            dp[0] = dp[1];
            dp[1] = tmp;
        }
 
        int ans = INF;
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                ans = Math.min(ans, dp[0][M][i][j]);
            }
        }
        System.out.println(ans);
    }
 
}

