                else if(i == 0)
                    res[i][j] = 0;
                else
                    res[i][j] = (res[i-1][j-1] + res[i-1][j]) % mod;
            }
        }
        
        long ans2 = 0;
        
        for(int rows = 1 ; rows < n ; rows++){
            long ans1 = 0;
            for(int col = m-1 ; col >= 1 ; col--){
                ans1 = (ans1 + res[n - rows + m - col -1][n - rows]*(res[n - rows + col - 1][n - rows - 1])) % mod;
                ans2 = (ans2 + res[rows + col -1][rows] * ((res[rows + m - col - 1][rows - 1] * ans1) % mod)) % mod;
            }
        }
        
        n= swap(m , m = n);
        //System.out.println(n+" "+m);
        for(int rows = 1 ; rows < n ; rows++){
            long ans1 = 0;
            for(int col = m-1 ; col >= 1 ; col--){
                ans2 = (ans2 + res[rows + col -1][rows] * ((res[rows + m - col - 1][rows - 1] * ans1) % mod)) % mod;
                ans1 = (ans1 + res[n - rows + m - col -1][n - rows]*(res[n - rows + col - 1][n - rows - 1])) % mod;
            }
        }
        
        ans2 = (ans2 * 2) % mod;
        System.out.println(ans2);
        
    }
    
    public static int swap(int...args){
        return args[0];
    }
}

