	final int mod = 998244353;
	long[][] C;
	
	void solve()
	{
		C = new long[4052 + 1][4052 + 1];
		for (int i = 0; i <= 4052; i++) {
			C[i][0] = 1;
			for (int j = 1; j <= i; j++) {
				C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
				if (C[i][j] >= mod) C[i][j] -= mod;
			}
		}

		int H = ni(), W = ni();

		long T = 0;
		// O(wh^4)
		for(int w = 1;w < W;w++) {
			long R = 0;
			for (int hl = 1; hl <= H; hl++) {
				// 0 <= hr <= H-1-hl
				// d(hl, w-1) * d(hr, w-1)
				// C[dr+w-1][w-1] * d(hl, w-1)
				int hll = H+1 - hl;
				R += d(hll, W-w-1) * C[H-1-hll+W-w][W-w];
				R %= mod;
				T += d(hl, w-1) * C[H-1-hl+w][w] % mod * R;
				T %= mod;
//				for (int hll = 0; hll <= H; hll++) {
//					if (hl + hll > H) {
//						T += d(hl, w-1) * C[H-1-hl+w][w] * d(hll, W-w-1) * C[H-1-hll+W-w][W-w];
//						T %= mod;
//					}
//				}
			}
		}
		T = T * 2;

		long IT = 0;
		// O(hw^4)
		for(int h = 1;h <= H-1;h++){
			// C[h-1+l][l]
			// C[h-1+r][r-1]
			long R = 0;
			for(int r = W-1;r >= 1;r--){
				R += d(H-h-1, r) * C[H-h+W-(r+1)][W-(r+1)];
				R %= mod;
				IT += C[h-1+r][r-1] * d(h-1, W-r) % mod * R;
				IT %= mod;
			}
		}
		IT *= 2;
		out.println((T+IT)%mod);
	}

	long d(int h, int w)
	{
		// begin:h, dec
		return C[h+w][h];
	}
	
