public class E {


    static int find(fenwik_tree t, int y, int lo, int hi) {
        while(lo<=hi) {
            int mid=(lo+hi)>>1;
            long cnt=t.query(0, mid);

            if(cnt<y) {
                lo=mid+1;
            } else {
                hi=mid-1;
            }
        }
        return hi+1;
    }

    static void run_stream(InputStream ins) throws IOException {
        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
        String[] nm=br.readLine().split(" ");
        int n=Integer.parseInt(nm[0]);
        int m=Integer.parseInt(nm[1]);

        int[] i2c=new int[n+m+1];
        fenwik_tree t=new fenwik_tree(n+m+1);
        for (int i=1; i<=n; i++) {
            t.update(m+i, 1);
            i2c[m+i]=i;
        }

        int[] out=new int[n+1];
        for (int i=0; i<m; i++) {
            String[] xy=br.readLine().split(" ");
            int x=Integer.parseInt(xy[0]);
            int y=Integer.parseInt(xy[1]);

            int j=find(t, y, m-i, n+m), k=i2c[j];
            if(out[k]>0&&out[k]!=x) {
                System.out.println("-1");
                return;
            } else {
                out[k]=x;
            }
            t.update(j,-1);  i2c[j]=-1; 
            t.update(m-i,1); i2c[m-i]=k;
        }

        boolean[] b=new boolean[n+1]; int j=1;
        for (int i=1; i<=n; i++) {
            if(out[i]!=0) {
                if(b[out[i]]) {
                    System.out.println("-1");
                    return;
                }
                b[out[i]]=true;
            }
        }

        for (int i=1; i<=n; i++) {
            if(out[i]==0) {
                while(b[j]) {
                    j++;
                }
                out[i]=j;
            }
            b[out[i]]=true;
        }

        StringBuilder sb=new StringBuilder();
        for (int i=1; i<=n; i++) {
            sb.append(out[i]+" ");
        }
        System.out.println(sb.toString());
    }

