        long[] fadd;

        fenwik_tree(int n) {
            this.n=n; fadd=new long[n];
        }

        void update(int i, long add) {
            while (i<n) {
                fadd[i]+=add;
                i|=(i+1);
            }
        }

        long query(int i) {
            long ret=0;
            while (i>=0) {
                ret+=fadd[i];
                i=(i&(i+1))-1;
            }
            return ret;
        }

        long query(int l, int r) {
            return query(r)-query(l-1);
        }
    }

}

import java.util.*;
import java.io.*;

public class PuttingBoxesTogether {
    static final long MOD = 1000000007L;
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);
        int N = scanner.nextInt();
        int Q = scanner.nextInt();
        long[] pos = new long[N];
        long[] weights = new long[N];
        BIT bit1 = new BIT(N);
        BIT bit2 = new BIT(N);
        for(int i = 0; i < N; i++) {
            pos[i] = scanner.nextInt();
        }
        for(int i  = 0; i < N; i++) weights[i] = scanner.nextInt();
        for(int i = 0; i < N; i++) {
            pos[i] -= i;
            bit1.update(i, weights[i]);
            bit2.update(i, (weights[i] * pos[i])%MOD);
        }
        while(Q-->0) {
            int x = scanner.nextInt();
            int y = scanner.nextInt();
            if (x < 0) {
                //update event
                x = -x -1;
                bit1.update(x, -weights[x]);
                bit2.update(x, -((weights[x]*pos[x])%MOD));
                weights[x] = y;
                bit1.update(x, weights[x]);
                bit2.update(x, (weights[x]*pos[x])%MOD);
            }
            else {
                x--;
                long s = bit1.rangeSum(x, y);
                int lo = x, hi = y;
                while (hi - lo > 1) {
                    int mid = (lo + hi)/2;
                    if (bit1.rangeSum(x, mid) * 2 <= s) lo = mid;
                    else hi = mid;
                }
                long ret = norm(mul(pos[lo], norm(bit1.rangeSum(x, lo))) - norm(bit2.rangeSum(x, lo)));
                ret = norm(ret + norm(norm(bit2.rangeSum( lo + 1, y)) - mul(pos[lo], norm(bit1.rangeSum(lo + 1, y)))));
                out.println(ret );

            }
        }
        out.flush();
    }
    static long mul(long a, long b) {
        return a * b % MOD;
    }

    static long norm(long a) {
        a %= MOD;
        if (a > MOD) a -= MOD;
        if (a < 0) a += MOD;
        return a;
    }
    public static class BIT {
        long[] table;
        int size;
        public BIT(int ss) {
            size = ss;
            table = new long[ss];
        }
        private void update(int loc, long amt) {
            for (int x = loc; x < size; x = x | x + 1) table[x] += amt;
        }
        private long prefixSum(int loc) {
            long res = 0;
            for (int x = loc; x >= 0; x = (x & x + 1) - 1) res += table[x];
            return res;
        }
        private long rangeSum(int l, int r) {
            return prefixSum(r-1) - prefixSum(l-1);
        }
    }
    public static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(Reader in) {
            br = new BufferedReader(in);
        }

        public FastScanner() {
            this(new InputStreamReader(System.in));
        }

