import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * @author Don Li
 */
public class PuttingBoxesTogether2 {

    int N = (int) 2e5 + 10;
    int MOD = (int) 1e9 + 7;
    int INF = (int) 2e9;

    int n;
    long[] t1 = new long[N << 2];
    long[] t2 = new long[N << 2];

    void solve() {
        n = in.nextInt(); int Q = in.nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = in.nextInt();
        long[] w = new long[n];
        for (int i = 0; i < n; i++) w[i] = in.nextInt();

        for (int i = 0; i < n; i++) a[i] -= i;

        long[] aw = new long[n];
        for (int i = 0; i < n; i++) aw[i] = mul(a[i], w[i]);

        build(t1, 0, 0, n, w);
        build(t2, 0, 0, n, aw);

        while (Q-- > 0) {
            int x = in.nextInt();
            if (x < 0) {
                int i = -x - 1, nw = in.nextInt();
                update(t1, 0, 0, n, i, nw);
                update(t2, 0, 0, n, i, mul(a[i], nw));
            } else {
                int l = x - 1, r = in.nextInt();
                long tot = query(t1, 0, 0, n, l, r);
                int k = (int) find(t1, 0, 0, n, l, r, tot / 2)[0];
                long ans = norm(mul(a[k], norm(query(t1, 0, 0, n, l, k))) - norm(query(t2, 0, 0, n, l, k)));
                ans = norm(ans + norm(norm(query(t2, 0, 0, n, k + 1, r)) - mul(a[k], norm(query(t1, 0, 0, n, k + 1, r)))));
                out.println(ans);
            }
        }
    }

    long[] find(long[] t, int k, int l, int r, int a, int b, long val) {
        if (l == a && r == b) {
            if (t[k] <= val) return new long[]{INF, t[k]};
            if (r - l == 1) return new long[]{l, t[l]};
        }
        int m = (l + r) >> 1;
        long pos = INF, sum = 0;
        if (a < m) {
            long[] ret = find(t, 2 * k + 1, l, m, a, Math.min(m, b), val);
            pos = Math.min(pos, ret[0]);
            sum += ret[1];
        }
        if (pos == INF && b >= m) {
            long[] ret = find(t, 2 * k + 2, m, r, Math.max(m, a), b, val - sum);
            pos = Math.min(pos, ret[0]);
            sum += ret[1];
        }
        return new long[]{pos, sum};
    }

    long query(long[] t, int k, int l, int r, int a, int b) {
        if (a <= l && r <= b) return t[k];
        if (a >= r || b <= l) return 0;
        int m = (l + r) >> 1;
        return query(t, 2 * k + 1, l, m, a, b) + query(t, 2 * k + 2, m, r, a, b);
    }

    void update(long[] t, int k, int l, int r, int i, long val) {
        if (r - l == 1) {
            t[k] = val;
            return;
        }
        int m = (l + r) >> 1;
        if (i < m) update(t, 2 * k + 1, l, m, i, val);
        else update(t, 2 * k + 2, m, r, i, val);
        t[k] = t[2 * k + 1] + t[2 * k + 2];
    }

    void build(long[] t, int k, int l, int r, long[] x) {
        if (r - l == 1) {
            t[k] = x[l];
            return;
        }
        int m = (l + r) >> 1;
        build(t, 2 * k + 1, l, m, x);
        build(t, 2 * k + 2, m, r, x);
        t[k] = t[2 * k + 1] + t[2 * k + 2];
    }

    long mul(long a, long b) {
        return a * b % MOD;
    }

    long norm(long a) {
        a %= MOD;
        if (a > MOD) a -= MOD;
        if (a < 0) a += MOD;
        return a;
    }

    public static void main(String[] args) {
        in = new FastScanner(new BufferedReader(new InputStreamReader(System.in)));
        out = new PrintWriter(System.out);
        new PuttingBoxesTogether2().solve();
        out.close();
    }

    static FastScanner in;
    static PrintWriter out;

    static class FastScanner {
        BufferedReader in;
        StringTokenizer st;

        public FastScanner(BufferedReader in) {
            this.in = in;
        }

        public String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(in.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextToken());
        }

        public long nextLong() {
            return Long.parseLong(nextToken());
        }

        public double nextDouble() {
            return Double.parseDouble(nextToken());
        }
    }
}

