public class p1173e {
    static int MOD = 998244353;
    static int n;
    static int m;
    static long[] invert;
    static long[][] f;
    static long[][] g;
    static boolean[][] df;
    static boolean[][] dg;
    static int[] sum;
    public static void main(String[] args) {
        FS in = new FS(System.in);
        PrintWriter out = new PrintWriter(System.out);
        n = in.nextInt();
        m = in.nextInt();
        invert = new long[2*m];
        int[] like = new int[n];
        sum = new int[2];
        int[] weight = new int[n];
        for(int i = 0; i < n; i++) like[i] = in.nextInt();
        for(int i = 0; i < n; i++) {
            weight[i] = in.nextInt();
            sum[1-like[i]] += weight[i];
        }
        for(int i = -(m-1); i < m; i++) invert[i+m-1] = modInv(sum[0]+sum[1]+i, MOD);
        f = new long[m][m];
        g = new long[m][m];
        df = new boolean[m][m];
        dg = new boolean[m][m];
        for(int i = 0; i < n; i++) if(like[i] == 0) out.println((g(0, 0)*weight[i])%MOD); else out.println((f(0, 0)*weight[i])%MOD);
        out.close();
    }

    static long f(int i, int j) {
        if(i+j == m) return 1;
        if(df[i][j]) return f[i][j];
        df[i][j] = true;
        return f[i][j] = (((((sum[0]+i+1)*invert[i-j+m-1])%MOD)*f(i+1, j))%MOD+((((sum[1]-j)*invert[i-j+m-1])%MOD)*f(i, j+1))%MOD)%MOD;
    }


    static long g(int i, int j) {
        if(i+j == m) return 1;
        if(dg[i][j]) return g[i][j];
        dg[i][j] = true;
        return g[i][j] = (((((sum[0]+i)*invert[i-j+m-1])%MOD)*g(i+1, j))%MOD+((((sum[1]-j-1)*invert[i-j+m-1])%MOD)*g(i, j+1))%MOD)%MOD;
    }

    //@
    static long gcd(long a, long b) { return b == 0 ? a : gcd(b, a % b); }
    static long lcm(long a, long b) { return a / gcd(a, b) * b; }


    //@
    // Computes the modular inverse of x
    // Returns 0 if the GCD of x and mod is not 1
    // O(log n)  :  Can be converted to use BigIntegers
    static long modInv(long x, long mod) {
            if(x == 1) return 1;
            if(gcd(x, mod) != 1) return 0;
            long r = mod % x;
            return (modInv(r, x % r, 0, 1, mod / x, x / r)+mod)%mod;
    }

    static long modInv(long a, long b, long y0, long y1, long q0, long q1) {
            long y2 = y0 - y1*q0;
            return b == 0 ? y2 : modInv(b, a % b, y1, y2, q1, a / b);
    }
    static class FS {
        BufferedReader in;
        StringTokenizer t;

        public FS(InputStream i) {
            in = new BufferedReader(new InputStreamReader(i));
        }

        public String next() {
            try {
                while(t == null || !t.hasMoreElements()) {
                    t = new StringTokenizer(in.readLine());
                }
            } catch(Exception e) {}
            return t.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}
